window.BAHR_DATA=window.BAHR_DATA||{};window.BAHR_DATA["notes"]=[{"id":"XVI-N001","title":"The named Taftāzānī source and its variants","content":"The quotation is directly attested in al-Taftāzānī, Sharḥ al-ʿAqāʾid, Maktabat al-Madīna, 2nd ed. (1433/2012), p. 349. That printing has daqāʾiq (subtleties) and ʿalā arbāb where Cairo has ḥaqāʾiq (realities) and li-arbāb; it confirms the closing “perfection of faith and pure gnosis.”","source":"Cairo I:50.","revision_status":"","limitations":"The printed source establishes the philosophical and theological quotation. It does not identify which edition or intermediary Ibn ʿAjība used, or provide an independent witness to the wording of al-Baḥr al-madīd.","scope":[{"record_id":"preface","segment_index":2,"quran_context":"preface","printed_pages":[50],"anchor_text":"pure gnosis.”","segment_title":"The inward sense does not abolish the outward sense","anchor_paragraph":"Saʿd al-Dīn says in his commentary upon al-Nasafī’s Creed , after refuting impious distortion ( الإلحاد ): “As for the view of certain realized authorities that scriptural texts retain their outward meanings, while also containing hidden allusions to realities unveiled to the people of wayfaring, which can be reconciled with the intended outward senses, this is of the perfection of faith and pure gnosis.” [XVI-N001] His words “can be reconciled,” and what follows, mean that these realities may be indicated within the inward dimension of the discourse in such a way that the discourse’s secret sense does not reject them, and the wording is not wholly remote from them, which would amount to distortion ( تحريف ).","anchor_basis":"Exact active annotation call in current HTML"}],"evidence":[{"source_id":"XVI-PS-TAFTAZANI-349","title":"Sharḥ al-ʿAqāʾid al-Nasafiyya","author":"Saʿd al-Dīn Masʿūd b. ʿUmar al-Taftāzānī","edition":"With Jamʿ al-farāʾid bi-inārat Sharḥ al-ʿAqāʾid by Ṣadr al-Warā al-Qādirī al-Miṣbāḥī; Karachi: Maktabat al-Madīna, 2nd ed., 1433/2012.","locator":"Printed p. 349; PDF p. 350; main Taftāzānī text above the footnote rule.","url":"https://data2.dawateislami.net/Data/Books/Download/ar/pdf/2012/664-1.pdf","web_ref":"turn542view0","inspection":"Named work, title and imprint directly read; printed p. 349 visually inspected in a locally rendered facsimile. Full PDF not retained.","exact_arabic":"مصروفة على ظواهرها … إلى دقائق تنكشف على أرباب السلوك … فهو من كمال الإيمان ومحض العرفان","evidence_files":["evidence/Taftazani_2012_Title.png","evidence/Taftazani_2012_Imprint.png","evidence/Taftazani_2012_p349.png"],"provenance_file":"Taftazani_Facsimile_Provenance_XVI.json"}],"source_review_id":"XVI-SR-001","print_number":1,"print_label":"T1","linked_occurrences":[{"record_id":"preface","segment_index":2,"q":"preface","source":"Cairo print · Volume I, pp. 49–51"}]},{"id":"CP11","content":"al-Baqara, introduction · Cairo I:71. Ibn ʿAjība explicitly attributes the statement to ʿAlī. Al-Suyūṭī reports the “first revealed in Medina” form from ʿIkrima and a separate “revealed in Medina” statement from Ibn ʿAbbās. Neither supplies an isnād to ʿAlī. The attribution to ʿAlī remains unverified; the Cairo editor’s objection and the separately transmitted al-Suyūṭī reports have distinct evidential scopes.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:71; Ruslān’s editorial footnote.","revision_status":"","print_number":2,"print_label":"T2","linked_occurrences":[{"record_id":"intro2","segment_index":0,"q":"intro2","source":"Cairo print · Volume I, pp. 71–71"}]},{"id":"R07-02","content":"Cairo I:89 · Poetic attribution. The Cairo footnote points to al-Khaṭīb al-Baghdādī’s Tārīkh Baghdād for a verse associated with a narrative about Abū al-Ḥasan al-Nūrī. It does not establish authorship of every line in the surrounding passage. This is a poetic-literary source reference; the original cited narrative and its pagination have not been independently verified.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:89; Ruslān’s editorial footnote.","revision_status":"","print_number":3,"print_label":"T3","linked_occurrences":[{"record_id":"q2-23-25","segment_index":0,"q":"2:23–25","source":"Cairo print · Volume I, pp. 87–90"}]},{"id":"R07-03","content":"Cairo I:102 · Poetry in the discussion of the guide. Ruslān supplies a further explanation from al-Khafājī’s gloss on al-Bayḍāwī; the footnotes also record the nearby verse of poetry. This is the Cairo editor’s quotation of a later commentator’s explanatory material, distinct from Ibn ʿAjība’s own text. The quotation has not been independently verified in al-Khafājī’s gloss.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:102; Ruslān’s editorial footnote.","revision_status":"","print_number":4,"print_label":"T4","linked_occurrences":[{"record_id":"q2-45-46","segment_index":0,"q":"2:45–46","source":"Cairo print · Volume I, pp. 101–103"}]},{"id":"R07-01","content":"Cairo I:124 · Composite report. Ruslān explicitly states that the words in square brackets are not part of the cited Prophetic report. He links that description to ʿAṭāʾ b. Yasār through al-Ṭabarī and al-Wāḥidī, or to Companion wording in al-Baghawī. Al-Ṭabarī transmits the ʿAṭāʾ wording separately at Q2:79. The Prophetic report about the valley also circulates in a different form, mentioning forty years of descent. These are distinct transmissions: the melting-mountains clause is not thereby established as part of the Prophetic quotation.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:124; Ruslān’s editorial footnote.","revision_status":"","print_number":5,"print_label":"T5","linked_occurrences":[{"record_id":"q2-79","segment_index":0,"q":"2:79","source":"Cairo print · Volume I, pp. 124–125"}]},{"id":"R07-04","content":"Cairo I:143 · Spiritual training and the shaykh’s fallibility. Ruslān interprets the story to mean that a disciple must not presume the shaykh’s infallibility, although a shaykh may be highly accomplished. This interpretation belongs to the Cairo editor’s footnote, not to another passage from Ibn ʿAjība.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:143; Ruslān’s editorial footnote.","revision_status":"","print_number":6,"print_label":"T6","linked_occurrences":[{"record_id":"q2-100","segment_index":3,"q":"2:100","source":"Cairo print · Volume I, pp. 141–143"}]},{"id":"R07-05","content":"Cairo I:156 · The qibla commentary. Ruslān comments on the story behind direction in prayer and supplies his own explanation of the sequence of the qibla verses. This is the Cairo editor’s legal-historical interpretation, not an additional manuscript reading. Other explanations occur in the traditional tafsīr literature.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:156; Ruslān’s editorial footnote.","revision_status":"","print_number":7,"print_label":"T7","linked_occurrences":[{"record_id":"q2-115","segment_index":0,"q":"2:115","source":"Cairo print · Volume I, pp. 155–157"}]},{"id":"R07-06","content":"Cairo I:182 · The verse ascribed to Labīd. The Cairo footnote cites Ibn Ḥajar’s Fatḥ al-Bārī on the poem about the impermanence of delight. The poetic line and the reported reply of ʿUthmān require separate attribution control. The Qurʾānic teaching about the permanence of the next life does not settle their provenance. Ibn Ḥajar is the Cairo editor’s cited source; the precise Fatḥ passage has not been independently verified.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:182; Ruslān’s editorial footnote.","revision_status":"","print_number":8,"print_label":"T8","linked_occurrences":[{"record_id":"q2-150","segment_index":0,"q":"2:150","source":"Cairo print · Volume I, pp. 181–183"}]},{"id":"R07-07","content":"Cairo I:191 · Report-source reference. The Cairo footnote supplies an additional report locator in the discussion of the signs of divine unity. A printed source reference is a finding aid, not an examination of the chain. The reference is reported by Ruslān; the exact report wording and chain have not been independently assessed, so the locator alone does not establish a ṣaḥīḥ report.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:191; Ruslān’s editorial footnote.","revision_status":"","print_number":9,"print_label":"T9","linked_occurrences":[{"record_id":"q2-163-164","segment_index":0,"q":"2:163–164","source":"Cairo print · Volume I, pp. 190–193"}]},{"id":"CP16","content":"al-Baqara 2:187 · Cairo I:216. The Arabic commentary introduces a long report involving al-Ḥawlāʾ and ʿĀʾisha, but the transmission in Ibn al-Jawzī’s al-Mawḍūʿāt passes through Anas b. Mālik and includes Ziyād b. Maymūn. Ibn al-Jawzī criticizes Ziyād and other narrators; the named critics treat this as a fabricated transmission. The story’s interlocutor and the chain’s narrator are distinct. The sound account of ʿAdī b. Ḥātim concerning the two threads, printed on the same page, is an unrelated report and does not authenticate the al-Ḥawlāʾ story or its extravagant rewards.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:216; Ruslān’s editorial footnote.","revision_status":"","print_number":10,"print_label":"T10","linked_occurrences":[{"record_id":"q2-187","segment_index":1,"q":"2:187","source":"Cairo print · Volume I, pp. 215–218"}]},{"id":"XVI-N002","title":"The scope of al-Suyūṭī’s narrator-wording comment","content":"Al-Suyūṭī’s al-Tawshīḥ, ed. Riḍwān Jāmiʿ Riḍwān (1419/1998), p. 1427 (on al-Bukhārī 1916–1917), distinguishes ʿAdī’s later experience from Sahl’s account of the earlier men. His remark about narrators’ wording falls under ʿAdī’s “when it was revealed”; Cairo’s abridgment attaches it to “then God revealed ‘of dawn’.” Ibn ʿAjība’s following inference depends on this arrangement. Al-Suyūṭī does not draw that inference in this passage.","source":"Cairo I:217.","revision_status":"","limitations":"This is a comparison of the scope and arrangement of the quotation in a printed earlier source. It does not establish whether the discrepancy originated with Ibn ʿAjība, an intermediary, or a later Baḥr witness. It does not independently adjudicate the hadith routes or the legal-theory question of delayed clarification.","scope":[{"record_id":"q2-187","segment_index":2,"quran_context":"2:187","printed_pages":[217],"anchor_text":"Here ends the abridged quotation.","segment_title":"The two threads and the timing of clarification","anchor_paragraph":"Yet al-Suyūṭī states otherwise in the Tawshīḥ : someone said ʿAdī apparently had not heard this part of the verse, which descended long before his conversion in year nine or ten. He said: “The Messenger taught me prayer and fasting: ‘Pray thus and fast thus; when the sun sets, eat until the white thread becomes distinct from the black.’ I took the two threads …” The Prophet asked him, “Did I not say, ‘of dawn’?” This shows that “then God revealed ‘of dawn’” in the report results from the narrators’ handling of it. Here ends the abridged quotation. [XVI-N002] This explicitly makes the verse clear and complete upon revelation, with no delay. And God Most High knows best. [B123]","anchor_basis":"Exact active annotation call in current HTML"}],"evidence":[{"source_id":"XVI-PS-TAWSHIH-1427","title":"Al-Tawshīḥ sharḥ al-Jāmiʿ al-ṣaḥīḥ","author":"Jalāl al-Dīn ʿAbd al-Raḥmān al-Suyūṭī","edition":"Ed. Riḍwān Jāmiʿ Riḍwān; Riyadh: Maktabat al-Rushd / Sharikat al-Riyāḍ, 1st ed., 1419/1998. Continuous printed pagination.","locator":"Printed pp. 1426–1427; especially p. 1427, comments on al-Bukhārī 1916 and 1917. PDF pages 1426–1427.","url":"https://archive.org/download/fp36067_202503/36067.pdf","web_ref":"turn558view1 (observed public download link; local facsimile read)","inspection":"Cover/editor and imprint visually verified, then complete pp. 1426–1427 read from locally rendered facsimiles. Full PDF not retained.","exact_arabic":"لما تليت عليّ بعد نزولها … فعرف أن الذي هنا من تصرف الرواة … ليس فيهم عدي، لأن قصته متأخرة عنهم","evidence_files":["evidence/Tawshih_Title.png","evidence/Tawshih_Imprint.png","evidence/Tawshih_p1426.png","evidence/Tawshih_p1427.png"],"provenance_file":"Tawshih_Facsimile_Provenance_XVI.json"},{"source_id":"XVI-PS-TAWSHIH-TEXT-1427","title":"Electronic transcription/OCR of al-Tawshīḥ, pages 1421–1440","author":"Al-Suyūṭī; OCR supplied by ScribeTools","edition":"Running text identifies al-Tawshīḥ; the containing ScribeTools collection has an inconsistent displayed title and must not determine the bibliography.","locator":"Printed p. 1427, lines 179–202 in retrieved view.","url":"https://scribetools.com/en/library/six-books/شروحات/التوشيح-f9b90f1d/text/0072","web_ref":"turn566view3","inspection":"Complete pertinent comment read electronically and checked against the facsimile above; OCR is a navigation aid, not an independent witness.","exact_arabic":"فأنزل الله بعد من الفجر"}],"source_review_id":"XVI-SR-002","print_number":11,"print_label":"T11","linked_occurrences":[{"record_id":"q2-187","segment_index":2,"q":"2:187","source":"Cairo print · Volume I, pp. 215–218"}]},{"id":"R07-08","content":"Cairo I:238 · Occupations and mindfulness. Ruslān quotes and contextualises a maxim from Abū Sulaymān al-Dārānī through al-Sarrāj’s al-Lumaʿ on combining proper worldly occupations with remembrance. The quotation, Ruslān’s explanatory paraphrase and Ibn ʿAjība’s spiritual allusion are distinct. The precise al-Lumaʿ passage has not been independently verified in full.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:238; Ruslān’s editorial footnote.","revision_status":"","print_number":12,"print_label":"T12","linked_occurrences":[{"record_id":"q2-212","segment_index":0,"q":"2:212","source":"Cairo print · Volume I, pp. 237–238"}]},{"id":"R07-09","content":"Cairo I:243 · Fighting and the Sacred Months. The Cairo editor supplies an evaluation of the Sufis’ role in struggle and the context of a verse on fighting. This is his own interpretation, neither a manuscript variant nor Ibn ʿAjība’s direct statement.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:243; Ruslān’s editorial footnote.","revision_status":"","print_number":13,"print_label":"T13","linked_occurrences":[{"record_id":"q2-217-218","segment_index":0,"q":"2:217–218","source":"Cairo print · Volume I, pp. 243–245"}]},{"id":"R07-10","content":"Cairo I:246 · The wine metaphor. Ruslān explains figurative intoxication, spiritual capacity and disclosure according to Sufi usage. This is the Cairo editor’s contextual interpretation; the metaphor is distinct from a juristic judgment about drinking.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:246; Ruslān’s editorial footnote.","revision_status":"","print_number":14,"print_label":"T14","linked_occurrences":[{"record_id":"q2-219","segment_index":0,"q":"2:219","source":"Cairo print · Volume I, pp. 245–248"}]},{"id":"R07-11","content":"Cairo I:280 · The Goliath narratives. Ruslān calls a group of supplementary narratives “legends” and cites both Ibn ʿAṭiyya and a twentieth-century critic. His note does not automatically apply to every version of the David and Goliath story. The Qurʾānic statement, later narrative expansion, Ibn ʿAṭiyya’s criticism as reported and Ruslān’s judgment have distinct scopes. Ibn ʿAṭiyya’s precise passage has not been independently verified, so Ruslān’s conclusion cannot simply be assigned to him.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:280; Ruslān’s editorial footnote.","revision_status":"","print_number":15,"print_label":"T15","linked_occurrences":[{"record_id":"q2-250-252","segment_index":0,"q":"2:250–252","source":"Cairo print · Volume I, pp. 279–282"}]},{"id":"XVI-N003","title":"Placement after the first 280 verses","content":"The placement formula means the boundary after the preceding two hundred and eighty verses. Al-Qārī, Jamʿ al-wasāʾil, I:14, quotes al-Ṭībī’s gloss of raʾs al-āya as a verse’s end. Al-Qurṭubī, III:341–342, and al-Bursawī on Q2:281 place this verse between the usury and debt passages; Aṭfayyish explicitly numbers it 281. This explains the placement language; it does not establish the report’s revelation chronology or the interval before the Prophet’s death.","source":"Cairo I:312.","revision_status":"","limitations":"The earlier commentaries clarify the placement formula. The chain of the reported Gabriel instruction, the claim that this was the last verse revealed and the interval of twenty-one days before the Prophet’s death remain unverified. The argument concerns the standard verse numbering; regional enumeration systems are a separate question.","scope":[{"record_id":"q2-280-281","segment_index":2,"quran_context":"2:280–281","printed_pages":[312],"anchor_text":"Other accounts give eighty-one days or other intervals. And God Most High knows best.","segment_title":"The final accounting","anchor_paragraph":"Ibn ʿAbbās said: “This was the last verse Gabriel brought down. He said, ‘Place it after the first two hundred and eighty verses of al-Baqara.’ The Messenger of God lived twenty-one days after it.” Other accounts give eighty-one days or other intervals. And God Most High knows best. [XVI-N003] [B237]","anchor_basis":"Exact active annotation call in current HTML"}],"evidence":[{"source_id":"XVI-PS-QARI-I14","title":"Jamʿ al-wasāʾil fī sharḥ al-Shamāʾil","author":"ʿAlī al-Qārī, here explicitly quoting al-Ṭībī","edition":"Islamweb electronic text with volume/page markers; no facsimile of this work newly inspected.","locator":"I:14, opening chapter on the Prophet’s physical description, gloss on “ʿalā raʾs arbaʿīn sana”; before the displayed page-15 break.","url":"https://www.islamweb.net/ar/library/content/117/3/باب-ما-جاء-في-خلق-رسول-الله-صلى-الله-عليه-وسلم","web_ref":"turn567view2","inspection":"Full pertinent paragraph and adjacent distinction between the completed forty-year span and the ordinal fortieth year directly read.","exact_arabic":"رأس الآية أي آخرها","evidence_role":"New XVI lexical control: raʾs of a verse can explicitly denote its end. This is al-Qārī’s quotation of al-Ṭībī, not a newly inspected al-Ṭībī original."},{"source_id":"XVI-PS-QURTUBI-III341","title":"Al-Jāmiʿ li-aḥkām al-Qurʾān","author":"Abū ʿAbd Allāh al-Qurṭubī","edition":"Islamweb electronic text with volume/page markers.","locator":"III:341–342, Q2:281; the placement reports precede the displayed p. 342 break.","url":"https://www.islamweb.net/ar/library/index.php?ID=876&ayano=281&bk_no=48&flag=1&page=bookcontents&surano=2","web_ref":"turn566view1","inspection":"Full Q2:281 context read; includes several chronological alternatives and two versions of the 280-verse placement formula.","exact_arabic":"اجعلوها بين آية الربا وآية الدين … اجعلها على رأس مائتين وثمانين آية","evidence_role":"New XVI early contextual control connecting the numerical placement expression with the boundary between the usury and debt passages. Makkī and Abū Bakr al-Anbārī are transmitted here; their own works were not newly inspected."},{"source_id":"XVI-PS-BURSAWI-Q281","title":"Rūḥ al-bayān","author":"Ismāʿīl Ḥaqqī al-Bursawī","edition":"Great Tafsirs electronic text; no new printed-page locator claimed.","locator":"Q2:281, opening commentary paragraph.","url":"https://www.greattafsirs.com/Tafsir_Library.aspx?AyahNo=281&LanguageID=1&MadhabNo=3&QuranAyat_Home=1&SoraNo=2&TafsirNo=36","web_ref":"turn566view2","inspection":"Complete pertinent paragraph directly read, including alternatives for the interval before the Prophet’s death.","exact_arabic":"ضعها على رأس مائتين وثمانين آية من سورة البقرة فجعلت بين آية الدين وآية الربا","evidence_role":"New XVI contextual control: the numeric formula and the resulting position are joined in one sentence."},{"source_id":"XV-XVI-PS-ATFAYYISH-Q281","title":"Taysīr al-tafsīr","author":"Muḥammad b. Yūsuf Aṭfayyish","edition":"Great Tafsirs electronic text.","locator":"Q2:281, final numbered sequence of the sura’s last verse endings.","url":"https://www.greattafsirs.com/Tafsir_Library.aspx?AyahNo=281&LanguageID=1&MadhabNo=9&QuranAyat_Home=1&SoraNo=2&TafsirNo=50","web_ref":"turn568view1","inspection":"Previously read in XV; re-read in XVI as inherited contextual evidence. Not counted as a newly discovered source.","exact_arabic":"فآخر المائتين وإحدى والثمانين لا يظلمون","evidence_role":"Explicitly identifies the verse ending lā yuẓlamūn as the end of verse 281 while retaining the placement formula referring to 280. A later commentator, not an independent Baḥr witness."}],"source_review_id":"XVI-SR-003","print_number":16,"print_label":"T16","linked_occurrences":[{"record_id":"q2-280-281","segment_index":2,"q":"2:280–281","source":"Cairo print · Volume I, pp. 311–313"}]},{"id":"XV-N004","title":"The direction of love in the Dhū l-Nūn account","content":"Cairo I:320 leaves the direction of love open: “love of God” and “love of created beings” may refer to love felt by them or directed towards them. The Turkish translation (I:751) takes the contrast as God’s love and the creatures’ love for Him. An earlier account in al-Thaʿlabī, al-Kashf wa-l-bayān, II:309 (electronic text), repeats these expressions. Ibn ʿAjība then applies the description to worshippers and ascetics. The Arabic expression remains ambiguous.","source":"Cairo I:320; primary-source comparison recorded below.","revision_status":"","scope":[{"record_id":"q2-285-286","segment_index":5,"quran_context":"2:285–286","printed_pages":[320],"anchor_text":"speak now of the love of created beings.’","segment_title":"Love, overwhelming states and settled realization","anchor_paragraph":"Regarding His words, “Our Lord, do not make us bear what we have no strength to bear,” it has been said that what is meant is love for God. A servant should therefore ask his Master for no more of His love than he can bear. Consider the story of the man who asked our master Moses, peace be upon him, to ask God to bestow His love upon him. When Moses asked his Lord, the man wandered distraught, rent his clothes, and his limbs were torn apart until he died. Moses privately addressed his Lord concerning him, and He said: “Moses, a thousand men all asked Me what this man asked. I divided a portion of My love among them, and that share fell to him”—or words to that effect from Him, exalted is He. [B252] One of the righteous said: “I attended Dhū l-Nūn’s gathering in Fusṭāṭ, Egypt. I estimated those present at seventy thousand. That day he spoke of love of God, and eleven men died in the gathering. A disciple cried, ‘Abū l-Fayḍ, you have spoken of love of God; speak now of the love of created beings.’ [XV-N004] Dhū l-Nūn gave a deep groan, reached towards his shirt, tore it in two, and said: ‘Ah! Their pledges are forfeit, their eyes overflow. They have allied themselves with sleeplessness and parted company with slumber. Their nights are long, their sleep little. Their sorrows do not run out, their cares do not depart. Their affairs are hard, their tears abundant, their eyes weeping, their eyelids sore. Time, family and neighbours have become their enemies.’” [B252] I say: this is the condition of worshippers and ascetics, people of strenuous effort and exertion, overcome by disturbing fear or unsettling longing. As for the gnostics who have arrived ( العارفون الواصلون ), this weariness has left them, and after toil they have passed into repose. They have reached the witnessing of the Beloved and intimate converse with the Near. Their worship is of the heart, their works inward: now contemplation, now vision, while abiding in the Presence. Their longing has grown still and their disquiet departed. They have drunk and been quenched, become intoxicated and returned to sobriety. States no longer move them, nor do words excite them; rather, they are like firmly rooted mountains. May God benefit us through their remembrance and make us of their company. Amen. On His words, “Pardon us,” al-Wartajbī says: “‘Pardon us’ our slight knowledge of You; ‘forgive us’ our shortcoming in worshipping You; and ‘have mercy on us’ through communion with You and witnessing You.” And success is through God. He guides to the even path. Peace be upon the messengers, and praise belongs to God, Lord of the worlds.","anchor_basis":"Exact active annotation call in current HTML"}],"evidence":[{"source":"Cairo copytext","locator":"I:320; PDF page 320","file":"audit_work/baseline_XII/recovered_translation/Translations/ba7r-madid-01_text.pdf","image":"evidence/Cairo_I_320.png","inspection":"Full page image inspected; local wording agrees with the quoted transcription. No Arabic wording variant established."},{"source":"Turkish translation","locator":"I:751; PDF page 751","file":"upload/Bahrül Medid-1.pdf","image":"evidence/Turkish_I_751.png","inspection":"Full page image inspected.","text":"Ey Ebü’l-Feyz, Allah Teâlâ’nın muhabbetinden bahsettin; biraz da kulların O’na muhabbetinden bahset","interpretation":"Takes the contrast as God’s love and creatures’ love for Him. This is a translator’s interpretation, not evidence of different Baḥr wording."},{"source":"al-Thaʿlabī, al-Kashf wa-l-bayān","locator":"II:309, beginning of page; book metadata identifies Dār Iḥyāʾ al-Turāth al-ʿArabī, Beirut, review by Naẓīr al-Sāʿidī","url":"https://ablibrary.net/book_content/b/18296/309?lang=ar","web_ref":"turn534view0","exact_relevant_text":"ذكرت محبّة اللّه فاذكر محبّة المخلوقين","context":"Dhū l-Nūn’s gathering, eleven deaths, ecstatic lament. The following saying attributed to Yaḥyā concerns lovers whose sins are involuntary; this is contextual evidence, not a definitive explanation of the genitives in Ibn ʿAjība.","inspection":"Entire public electronic page read. The site contains conspicuous transcription corruption nearby; no corresponding printed facsimile inspected. Used only to establish the earlier parallel and repeated genitives."},{"source":"al-Thaʿlabī, preceding context","locator":"II:308, last commentary before page turn","url":"https://ablibrary.net/book_content/b/18296/308?lang=ar","web_ref":"turn534view1","exact_relevant_text":"يعني العشق","context":"The petition not to bear what one cannot endure is interpreted as passionate love before the Dhū l-Nūn account.","inspection":"Entire public electronic page read; not a Baḥr witness."}],"provenance":{"revision":"XV","proposal_id":"XV-BAQARA-TAIL-E006","source_proposal_file":"crux_late/Turkish_Baqara_Tail_Proposed_Operations_XV.json","adopted_edit_id":"XV-016","independent_Bahr_manuscript_evidence":false},"limitations":"Source comparison and copytext interpretation; no independent Baḥr manuscript reading is asserted.","word_count":71,"print_number":17,"print_label":"T17","linked_occurrences":[{"record_id":"q2-285-286","segment_index":5,"q":"2:285–286","source":"Cairo print · Volume I, pp. 317–320"}]},{"id":"R07-12","content":"Cairo I:329–330 · The saying attributed to ʿAlī. Ruslān challenges the attribution to ʿAlī of the sharply disparaging saying about women and notes historical examples of women excelling in righteousness. The saying is attributed speech, not a Prophetic hadith; its attribution remains unverified. Ruslān’s challenge belongs to the Cairo editor’s footnote.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:329–330; Ruslān’s editorial footnote.","revision_status":"","print_number":18,"print_label":"T18","linked_occurrences":[{"record_id":"q3-14","segment_index":0,"q":"3:14","source":"Cairo print · Volume I, pp. 328–331"}]},{"id":"R07-13","content":"Cairo I:334 · The merit report about the testimony to divine unity. The Cairo editor supplies source attributions and a classical objection to a report promising exceptional rewards for reciting “God bears witness that there is no god but He.” His cited version is distinct from other reports on the verse. The transmitted objection concerns a particular chain, not every report about the verse; a complete comparison of the chains has not been established.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:334; Ruslān’s editorial footnote.","revision_status":"","print_number":19,"print_label":"T19","linked_occurrences":[{"record_id":"q3-18","segment_index":0,"q":"3:18","source":"Cairo print · Volume I, pp. 332–334"}]},{"id":"XIV-N001","historical_note_id":"T058","title":"“Offspring” and the meaning of dedication","content":"The parenthesis is “God knows best what she/I have borne,” together with the intervening comparison of male and female; it is not the statement “I have named her Mary.” Waḍaʿtu, with the first-person ending, makes the mother acknowledge that God knows the significance of her child better than she does. Waḍaʿat, with the feminine third-person ending, allows a divine comment correcting the mother’s estimate. Al-Bayḍāwī explicitly distinguishes these voices at Q3:36 (Anwār, II:14). The change of speaker therefore follows a recitational distinction; it must not be flattened into a single uninterrupted speech by Mary’s mother.","evidence":[{"source_id":"CAIRO-I-345","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 345; Q3:33–37","exact_arabic":"وما بينهما اعتراض، من كلامها على قراءة التكلم، أو من كلام الله على قراءة التأنيث.","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-baydawi","title":"baydawi","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0685NasirDinBaydawi/0685NasirDinBaydawi.AnwarTanzil/0685NasirDinBaydawi.AnwarTanzil.Shamela0023588-ara1","locator":"Anwār al-tanzīl II:14, Q3:36; PageV02P014","exact_arabic":"هو استئناف من الله تعالى ... على أنه من كلامها تسلية لنفسها","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The grammatical discussion distinguishes divine parenthesis and maternal speech according to the reading.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"6bc14b72dc468030f939690ce4307a3a9e617d866198b2b9d19857fba684def6"}],"scope":[{"record_id":"q3-33-37","segment_index":0,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"“Offspring” and the meaning of dedication","anchor_paragraph":"I say: “Offspring” ( ذُرِّيَّةً ) is an accusative of state ( حال ), or a substitute ( بدل ) for the two families, or for Noah: that is, they are one offspring, branching forth, some from others. “When the wife [of ʿImrān] said” ( إذ قالت ) is an adverbial expression ( ظرف ) governed by “Knowing” ( عليم ), or by an understood “remember” ( اذكر ). “Consecrated” ( محرَّرًا ) is an accusative of state ( حال ). Taḥrīr ( التحرير ) means setting free or purifying. One says “I freed the slave” when I released him from bondage; and “I revised [or purified] the writing” when I corrected it and made it sound, leaving nothing that still required amendment. A free man ( حُرّ ) is one unencumbered by another’s claim; pure clay is clay free of black mud. Her saying “I have named her Mary” ( وإني سميتها مريم ) is coordinated ( عطف ) with “I have given birth to her” ( إني وضعتها ); what intervenes is a parenthesis ( اعتراض ). On the reading in the first person, this is part of her speech; on the reading in the third-person feminine, it is speech from God. [XIV-N001]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 345; Q3:33–37; baydawi: Anwār al-tanzīl II:14, Q3:36; PageV02P014","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-33-37","segment_index":0,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"[“Offspring” and the meaning of dedication]","anchor_paragraph":"I say: “Offspring” ( ذُرِّيَّةً ) is an accusative of state ( حال ), or a substitute ( بدل ) for the two families, or for Noah: that is, they are one offspring, branching forth, some from others. “When the wife [of ʿImrān] said” ( إذ قالت ) is an adverbial expression ( ظرف ) governed by “Knowing” ( عليم ), or by an understood “remember” ( اذكر ). “Consecrated” ( محرَّرًا ) is an accusative of state ( حال ). Taḥrīr ( التحرير ) means setting free or purifying. One says “I freed the slave” when I released him from bondage; and “I revised [or purified] the writing” when I corrected it and made it sound, leaving nothing that still required amendment. A free man ( حُرّ ) is one unencumbered by another’s claim; pure clay is clay free of black mud. Her saying “I have named her Mary” ( وإني سميتها مريم ) is coordinated ( عطف ) with “I have given birth to her” ( إني وضعتها ); what intervenes is a parenthesis ( اعتراض ). On the reading in the first person, this is part of her speech; on the reading in the third-person feminine, it is speech from God. [T058]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T058; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T058","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T058","original_body_sha256":"ffe2503999a89ea79ef1eb3e52285dc9eb4b54132c767e4cccb8c8b8288240d4","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":20,"print_label":"T20","linked_occurrences":[{"record_id":"q3-33-37","segment_index":0,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349"}]},{"id":"XIV-N002","historical_note_id":"T059","title":"Ḥanna’s vow and Mary’s birth","content":"Three voices should be distinguished here. The report attributed to the Prophet singles out Mary and her son; al-Bukhārī transmits that exception and Abū Hurayra’s ensuing citation of Q3:36 (Ṣaḥīḥ, no. 3431). The explanation in terms of Satan’s attempt at temptation is exegetical interpretation. “I say: likewise with all the prophets” is Ibn ʿAjība’s own theological extension, introduced by qultu, and is not part of the quoted hadith. Thus “protection from sin” renders the author’s appeal to ʿiṣma; it should not make the report appear to enumerate an exception for every prophet.","evidence":[{"source_id":"CAIRO-I-347","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 347; Q3:33–37","exact_arabic":"قلت: وكذا الأنبياء كلهم، لا يمسهم لمكان العصمة.","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-bukhari","title":"bukhari","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","locator":"Ṣaḥīḥ al-Bukhārī, no.3431, Book of Prophets","exact_arabic":"غير مريم وابنها ثم يقول أبو هريرة وإني أعيذها بك وذريتها من الشيطان الرجيم","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The reported exception and the companion’s Qurʾānic citation were read; Ibn ʿAjība’s extension is not in this report.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"16f95173b9ea1927b577ff85dc7e2a8351b8287e4ea9863782c4c5fc87ac8132"}],"scope":[{"record_id":"q3-33-37","segment_index":2,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"Ḥanna’s vow and Mary’s birth","anchor_paragraph":"Ḥanna, Mary’s mother, continued: “I seek Your protection for her”—that is, I shelter her with You—“and her offspring from Satan the accursed,” either stoned with shooting stars or driven away. The Prophet is reported to have said: “No child is born without Satan touching him at birth, causing him to cry out by his touch, except Mary and her son.” Its meaning is that Satan seeks to mislead every newborn, so that the child is affected by him; Mary and her son are excepted by virtue of this invocation for protection. I say: likewise with all the prophets: he does not touch them on account of their protection from sin ( العصمة ). And God knows best. [XIV-N002]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 347; Q3:33–37; bukhari: Ṣaḥīḥ al-Bukhārī, no.3431, Book of Prophets","revision_status":"","word_count":92,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-33-37","segment_index":2,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"[Ḥanna’s vow and Mary’s birth]","anchor_paragraph":"Ḥanna, Mary’s mother, continued: “I seek Your protection for her”—that is, I shelter her with You—“and her offspring from Satan the accursed,” either stoned with shooting stars or driven away. The Prophet is reported to have said: “No child is born without Satan touching him at birth, causing him to cry out by his touch, except Mary and her son.” Its meaning is that Satan seeks to mislead every newborn, so that the child is affected by him; Mary and her son are excepted by virtue of this invocation for protection. I say: likewise with all the prophets: he does not touch them on account of their protection from sin ( العصمة ). And God knows best. [T059]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T059; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T059","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T059","original_body_sha256":"e40a90b8b118b45e08af98458932163a0f24159cdd113b16c1fd2d0626bac229","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":21,"print_label":"T21","linked_occurrences":[{"record_id":"q3-33-37","segment_index":2,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349"}]},{"id":"XIV-N003","historical_note_id":"T060","title":"Acceptance, growth and Zachariah’s guardianship","content":"The guardianship narrative expands details that the Qurʾān states more briefly. Q3:37 names Zachariah’s care of Mary, while Q3:44 refers to the disputants casting their pens to determine her guardian. The number twenty-seven, the river, and the contrasting movement of the pens belong to the account introduced here by “it is related” (ruwiya). They are not words of the Qurʾānic verses. “Pens” preserves aqlām and its connection to the learned custodians; the passage presents the casting as a lot, not a writing exercise. The report’s narrative form does not by itself authenticate the event.","evidence":[{"source_id":"CAIRO-I-347","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 347; Q3:33–37","exact_arabic":"وكانوا سبعة وعشرين، فانطلقوا إلى نهر، فألقوا فيه أقلامهم","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-33-37","segment_index":3,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"Acceptance, growth and Zachariah’s guardianship","anchor_paragraph":"“Her Lord accepted her with a gracious acceptance”: He was satisfied to receive her in the fulfilment of the vow in place of a boy. The manner of this acceptance was beautiful: He put her in the boy’s position and received her into service immediately after her birth, before she had grown fit for custodianship ( السدانة ). It is related that Ḥanna wrapped the child in a cloth, carried her to the sanctuary, placed her before the learned custodians, and said: “Here is the child I have dedicated.” They vied to take charge of her, for she was the daughter of their leader and the man who presided over their offerings. The family of Māthān were leaders and kings among the Children of Israel. Zachariah said, “I have the strongest claim to her, for her maternal aunt is in my house.” They refused except by lot. All twenty-seven of them went to a river and cast their pens into it; Zachariah’s pen remained afloat on the water, while the others sank. So he took charge of her. [XIV-N003]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 347; Q3:33–37","revision_status":"","word_count":98,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-33-37","segment_index":3,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"[Acceptance, growth and Zachariah’s guardianship]","anchor_paragraph":"“Her Lord accepted her with a gracious acceptance”: He was satisfied to receive her in the fulfilment of the vow in place of a boy. The manner of this acceptance was beautiful: He put her in the boy’s position and received her into service immediately after her birth, before she had grown fit for custodianship ( السدانة ). It is related that Ḥanna wrapped the child in a cloth, carried her to the sanctuary, placed her before the learned custodians, and said: “Here is the child I have dedicated.” They vied to take charge of her, for she was the daughter of their leader and the man who presided over their offerings. The family of Māthān were leaders and kings among the Children of Israel. Zachariah said, “I have the strongest claim to her, for her maternal aunt is in my house.” They refused except by lot. All twenty-seven of them went to a river and cast their pens into it; Zachariah’s pen remained afloat on the water, while the others sank. So he took charge of her. [T060]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T060; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T060","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T060","original_body_sha256":"9df285911b250619cb31ffb2e4f38cc4505dd57cdb834063eaab84124d790c2d","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":22,"print_label":"T22","linked_occurrences":[{"record_id":"q3-33-37","segment_index":3,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349"}]},{"id":"XIV-N004","historical_note_id":"T061","title":"Acceptance, growth and Zachariah’s guardianship","content":"Al-Qushayrī draws a practical inference from kullamā, “whenever”: Zachariah repeatedly attends to Mary even after finding extraordinary provision. His Laṭāʾif (I:239, Q3:37) contains the same argument and the concluding statement that nothing is incumbent upon God. The point is that a karāma is a freely bestowed divine favour whose recurrence cannot be demanded. Earlier provision therefore does not cancel the guardian’s continuing care or justify assuming that today’s circumstances match yesterday’s. “Without reckoning” is correspondingly explained through divine generosity, not as a contractual reward earned by Mary’s worship.","evidence":[{"source_id":"CAIRO-I-347","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 347; Q3:33–37","exact_arabic":"لأن الكرامات للأولياء ليس مما يجب أن تدوم قطعاً","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-qushayri_tafsir","title":"qushayri_tafsir","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0465IbnHawazinQushayri/0465IbnHawazinQushayri.LataifIsharat/0465IbnHawazinQushayri.LataifIsharat.Shamela0023629-ara1","locator":"Laṭāʾif al-ishārāt I:239, Q3:37; PageV01P239","exact_arabic":"فلفظة كلما للتكرار ... لأن كرامات الأولياء ليست مما يجب أن يدوم ذلك قطعا","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"Direct parallel for repeated guardianship and the non-obligatory recurrence of karāma.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"afbcaeb1209d6436504cb78b70d0b6b8a036b9be499bcc69543436feb264cd8a"}],"scope":[{"record_id":"q3-33-37","segment_index":3,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"Acceptance, growth and Zachariah’s guardianship","anchor_paragraph":"“God provides for whomsoever He wills without reckoning” ( بغير حساب ): without measure or without anything being owed, solely through His grace. The expression “whenever” ( كلما ) implies repetition. It also indicates that Zachariah never abandoned his care of her or relied upon what he found: he continually inspected her circumstances. Extraordinary graces granted to God’s friends ( كرامات الأولياء ) are not bound to continue; they may be manifested constantly or may cease. Zachariah therefore did not cease looking after her. He kept asking “Mary, whence is this for you?” because what arrived today might have come in a different fashion from yesterday. Nothing is incumbent upon God—exalted is He. Thus al-Qushayrī. [XIV-N004]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 347; Q3:33–37; qushayri_tafsir: Laṭāʾif al-ishārāt I:239, Q3:37; PageV01P239","revision_status":"","word_count":88,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-33-37","segment_index":3,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"[Acceptance, growth and Zachariah’s guardianship]","anchor_paragraph":"“God provides for whomsoever He wills without reckoning” ( بغير حساب ): without measure or without anything being owed, solely through His grace. The expression “whenever” ( كلما ) implies repetition. It also indicates that Zachariah never abandoned his care of her or relied upon what he found: he continually inspected her circumstances. Extraordinary graces granted to God’s friends ( كرامات الأولياء ) are not bound to continue; they may be manifested constantly or may cease. Zachariah therefore did not cease looking after her. He kept asking “Mary, whence is this for you?” because what arrived today might have come in a different fashion from yesterday. Nothing is incumbent upon God—exalted is He. Thus al-Qushayrī. [T061]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T061; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T061","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T061","original_body_sha256":"a8520efb1625f635082216c8c35260398eb9ccca7ebc21560683d3d5405772ec","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":23,"print_label":"T23","linked_occurrences":[{"record_id":"q3-33-37","segment_index":3,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349"}]},{"id":"XIV-N005","historical_note_id":"T062","title":"Fāṭima’s provision","content":"The episode is constructed as a parallel between Mary’s provision and Fāṭima’s household: the same question “Whence is this for you?” receives the same answer from Q3:37. A longer version occurs in al-Thaʿlabī’s al-Kashf wa-l-bayān (III:57–58), introduced as a report from Jābir and including the two loaves, meat, full dish, and distribution to neighbours. This establishes an earlier textual parallel for Ibn ʿAjība’s account. It does not, by itself, authenticate the transmission chain or prove that the event occurred. The Qurʾānic wording within the narrative remains a quotation placed on Fāṭima’s lips by the report.","evidence":[{"source_id":"CAIRO-I-348","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 348; Q3:33–37","exact_arabic":"رَوى جابر بنُ عبد الله أن النبي صلى الله عليه وسلم أقام أياماً لم يطعم الطعام","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-thalabi","title":"thalabi","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0427AbuIshaqThaclabi/0427AbuIshaqThaclabi.KashfWaBayan/0427AbuIshaqThaclabi.KashfWaBayan.Shamela0023578-ara1.mARkdown","locator":"al-Kashf wa-l-bayān III:57–58, Q3:37; PageV03P057–058","exact_arabic":"بعثت إليها جارة لها برغيفين وبضعة لحم ... وبقيت الجفنة كما هي فأوسعت منها على جميع جيراني","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The extended earlier narrative agrees in the named participants and sequence; no hadith grading inferred.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"d9aa1ab28e951322ad88e1b8d7fb8d9a0915498174fcc474cac405fa91afa856"}],"scope":[{"record_id":"q3-33-37","segment_index":4,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"Fāṭima’s provision","anchor_paragraph":"Jābir son of ʿAbd Allāh relates that the Prophet, blessings and peace be upon him, went without food for several days. He visited the homes of his wives and found nothing, then went to Fāṭima and asked, “My daughter, do you have anything?” She replied, “No, by God—may my father and mother be your ransom.” After he left, a neighbour sent her two loaves and a piece of meat. She sent Ḥasan and Ḥusayn to fetch the Prophet. He arrived, and she uncovered the dish: it was full of bread and meat. She was astonished and knew it to be a blessing from God. He asked, “Whence is this for you, my daughter?” She answered, “It is from God. God provides for whomsoever He wills without reckoning.” He praised God and said, “Praise belongs to God who has made you like the foremost lady of the Children of Israel. Whenever God provided her with something, she said, ‘It is from God. God provides for whomsoever He wills without reckoning.’” The Prophet then sent for ʿAlī. The whole household and all the Prophet’s wives ate, yet the dish remained as before; she shared with the neighbours, and God bestowed abundant goodness and blessing in it. End of report. [XIV-N005]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 348; Q3:33–37; thalabi: al-Kashf wa-l-bayān III:57–58, Q3:37; PageV03P057–058","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-33-37","segment_index":4,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"[Fāṭima’s provision]","anchor_paragraph":"Jābir son of ʿAbd Allāh relates that the Prophet, blessings and peace be upon him, went without food for several days. He visited the homes of his wives and found nothing, then went to Fāṭima and asked, “My daughter, do you have anything?” She replied, “No, by God—may my father and mother be your ransom.” After he left, a neighbour sent her two loaves and a piece of meat. She sent Ḥasan and Ḥusayn to fetch the Prophet. He arrived, and she uncovered the dish: it was full of bread and meat. She was astonished and knew it to be a blessing from God. He asked, “Whence is this for you, my daughter?” She answered, “It is from God. God provides for whomsoever He wills without reckoning.” He praised God and said, “Praise belongs to God who has made you like the foremost lady of the Children of Israel. Whenever God provided her with something, she said, ‘It is from God. God provides for whomsoever He wills without reckoning.’” The Prophet then sent for ʿAlī. The whole household and all the Prophet’s wives ate, yet the dish remained as before; she shared with the neighbours, and God bestowed abundant goodness and blessing in it. End of report. [T062]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T062; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T062","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T062","original_body_sha256":"02c902b58c918d19710cda8d7fd404da9414e31c4e3985f80605e305e89c145d","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":24,"print_label":"T24","linked_occurrences":[{"record_id":"q3-33-37","segment_index":4,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349"}]},{"id":"XIV-N006","historical_note_id":"T063","title":"The chosen renewers and consecration of the self","content":"The renewal saying is transmitted in Abū Dāwūd’s Sunan (no. 4291); its wording identifies whoever renews the community’s religion, without naming al-Ḥasan al-Baṣrī. The funeral proclamation and Ibn ʿAjība’s designation of al-Ḥasan as a renewer are separate applications. Abū Ṭālib al-Makkī does call al-Ḥasan “our imam in this science” in Qūt al-qulūb (I:223), within a discussion of divine decree, command, and responsibility. That located phrase supports the quoted attribution. It should not be enlarged into primary evidence that al-Ḥasan founded every feature of later organized Sufism; that broader historical characterization belongs to Ibn ʿAjība’s presentation.","evidence":[{"source_id":"CAIRO-I-348","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 348; Q3:33–37","exact_arabic":"قال في القوت: وهو إمامنا في هذا العلم","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-abu_dawud","title":"abu_dawud","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0275AbuDawudSijistani/0275AbuDawudSijistani.Sunan/0275AbuDawudSijistani.Sunan.Shamela0001726-ara1","locator":"Sunan Abī Dāwūd, no.4291, Kitāb al-Malāḥim","exact_arabic":"إن الله يبعث لهذه الأمة على رأس كل مائة سنة من يجدد لها دينها","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The renewal report was directly read, including Abū Dāwūd’s ensuing transmission remark.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"f153a439d58e7fbeded321cd6ba9cba3b5402c5d3b3286ca3dde9b620d6feef6"},{"source_id":"XIV-OT-qut","title":"qut","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0386AbuTalibMakki/0386AbuTalibMakki.QutQulub/0386AbuTalibMakki.QutQulub.Shamela0000482-ara1","locator":"Qūt al-qulūb I:223; PageV01P223","exact_arabic":"وقد فرق الحسن البصري رحمه الله قبله وهو إمامنا في هذا العلم بين التعذيب على جريان العلم ومخالفة الأمر","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The phrase occurs in a doctrinal discussion, establishing the scope of the located quotation.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"6e4fc19c2120f7c66753067b10f0dd61e5f4bfe9eeb2232212ee0dbccec6680f"}],"scope":[{"record_id":"q3-33-37","segment_index":5,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"The chosen renewers and consecration of the self","anchor_paragraph":"The hadith states: “At the head of every hundred years God sends one who renews this community’s religion.” Al-Ḥarīrī relates: “Al-Ḥasan al-Baṣrī died on a Friday afternoon—that is, after the sun had passed its zenith. After the Friday prayer people carried him [to burial], and for the first time since Islam came to Basra, the congregational ʿaṣr prayer was not held in its mosque: all had followed his funeral procession. I heard a caller proclaiming, ‘God chose Adam and Noah and the family of Abraham and the family of ʿImrān above the worlds, and chose al-Ḥasan above the people of his age.’” I say: al-Ḥasan al-Baṣrī was the one who made the science of Sufism ( علم التصوف ) manifest, spoke of it, and refined it. The Qūt says of him: “He is our imam in this science,” meaning Sufism. [XIV-N006]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 348; Q3:33–37; abu_dawud: Sunan Abī Dāwūd, no.4291, Kitāb al-Malāḥim; qut: Qūt al-qulūb I:223; PageV01P223","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-33-37","segment_index":5,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349","segment_title":"Spiritual allusion — الإشارة The chosen renewers and consecration of the self","anchor_paragraph":"The hadith states: “At the head of every hundred years God sends one who renews this community’s religion.” Al-Ḥarīrī relates: “Al-Ḥasan al-Baṣrī died on a Friday afternoon—that is, after the sun had passed its zenith. After the Friday prayer people carried him [to burial], and for the first time since Islam came to Basra, the congregational ʿaṣr prayer was not held in its mosque: all had followed his funeral procession. I heard a caller proclaiming, ‘God chose Adam and Noah and the family of Abraham and the family of ʿImrān above the worlds, and chose al-Ḥasan above the people of his age.’” I say: al-Ḥasan al-Baṣrī was the one who made the science of Sufism ( علم التصوف ) manifest, spoke of it, and refined it. The Qūt says of him: “He is our imam in this science,” meaning Sufism. [T063]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T063; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T063","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T063","original_body_sha256":"a40597e0a84c525c0d2df8a45496bf5faf0d28bf684a0fcc914cf1cb932e0bc4","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":25,"print_label":"T25","linked_occurrences":[{"record_id":"q3-33-37","segment_index":5,"q":"3:33–37","source":"Cairo print · Volume I, pp. 345–349"}]},{"id":"XIV-N007","historical_note_id":"T064","title":"“There,” the sanctuary, and the angelic announcement","content":"The masculine and feminine forms discussed here belong to grammatical agreement with a broken plural. They do not assign biological sex to the angels. Ibn ʿAjība’s own example, “the men arose,” permits either verb form, which makes this distinction explicit. Fanādat-hu and fanādā-hu both describe the call to Zachariah; the final -hu refers to him. Identifying the speaker as Gabriel is the author’s interpretation of the plural, not a translation of malāʾika as a singular noun. Likewise, bashara and bashshara are two Arabic verbal forms for giving glad tidings, not two different announcements.","evidence":[{"source_id":"CAIRO-I-349","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 349; Q3:38–41","exact_arabic":"جمع تكسير، يجوز في فعله التذكير والتأنيث","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-38-41","segment_index":0,"q":"3:38–41","source":"Cairo print · Volume I, pp. 349–351","segment_title":"“There,” the sanctuary, and the angelic announcement","anchor_paragraph":"“The angels” ( الملائكة ) is a broken plural ( جمع تكسير ). Its verb may be masculine or feminine, though the latter is preferable; thus one may say qāma al-rijāl or qāmat al-rijāl , “the men arose.” The reading “the angels called to him” with a feminine verb construes them as a group ( الجماعة ); the masculine reading, “he [or they] called,” is intended to keep the angels free from feminine description, in reply to the unbelievers. What is intended here is Gabriel, as in “He sends down the angels with the Spirit” [16:2] and “When the angels said, O Mary ...” [3:42]. In bashshara , “he gave glad tidings,” two forms occur: the light, ungeminated form, the idiom of Tihāma, bashara yabshuru (with ḍamma on the shīn of the imperfect), and the geminated form bashshara yubashshiru , which is more eloquent. [XIV-N007]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 349; Q3:38–41","revision_status":"","word_count":93,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-38-41","segment_index":0,"q":"3:38–41","source":"Cairo print · Volume I, pp. 349–351","segment_title":"[“There,” the sanctuary, and the angelic announcement]","anchor_paragraph":"“The angels” ( الملائكة ) is a broken plural ( جمع تكسير ). Its verb may be masculine or feminine, though the latter is preferable; thus one may say qāma al-rijāl or qāmat al-rijāl , “the men arose.” The reading “the angels called to him” with a feminine verb construes them as a group ( الجماعة ); the masculine reading, “he [or they] called,” is intended to keep the angels free from feminine description, in reply to the unbelievers. What is intended here is Gabriel, as in “He sends down the angels with the Spirit” [16:2] and “When the angels said, O Mary ...” [3:42]. In bashshara , “he gave glad tidings,” two forms occur: the light, ungeminated form, the idiom of Tihāma, bashara yabshuru (with ḍamma on the shīn of the imperfect), and the geminated form bashshara yubashshiru , which is more eloquent. [T064]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T064; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T064","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T064","original_body_sha256":"ebc1b01f91a3308384329e11c7ed09a3fc47e093425b4b07c7e76f169bee3bea","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":26,"print_label":"T26","linked_occurrences":[{"record_id":"q3-38-41","segment_index":0,"q":"3:38–41","source":"Cairo print · Volume I, pp. 349–351"}]},{"id":"XIV-N008","historical_note_id":"T065","title":"A child from the barren and the aged","content":"Ḥaṣūr is first explained through disciplined restraint, then through a reported physiological interpretation. The conjunction “or” keeps those explanations alternative; they should not become a single settled biography of John. The bodily report is transmitted here with an attribution to Ibn ʿAbbās, without an evaluated chain. Al-Qushayrī’s directly corresponding comment (Laṭāʾif, I:241, Q3:39) interprets the word as freedom from passions while remaining human. That supports the ascetic sense emphasized here. It does not verify the anatomical report or require “restrained” to mean incapable of sexual intercourse.","evidence":[{"source_id":"CAIRO-I-350","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 350; Q3:38–41","exact_arabic":"وَحَصُوراً، أي: مبالغاً في حبس النفس عن الشهوات والملاهي.","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-qushayri_tafsir","title":"qushayri_tafsir","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0465IbnHawazinQushayri/0465IbnHawazinQushayri.LataifIsharat/0465IbnHawazinQushayri.LataifIsharat.Shamela0023629-ara1","locator":"Laṭāʾif al-ishārāt I:241, Q3:39; PageV01P241","exact_arabic":"وقوله وحصورا أي معتقا من الشهوات، مكفيا أحكام البشرية مع كونه من جملة البشر","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"Direct source for the author’s quoted spiritual interpretation of ḥaṣūr.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"afbcaeb1209d6436504cb78b70d0b6b8a036b9be499bcc69543436feb264cd8a"}],"scope":[{"record_id":"q3-38-41","segment_index":1,"q":"3:38–41","source":"Cairo print · Volume I, pp. 349–351","segment_title":"A child from the barren and the aged","anchor_paragraph":"“Confirming a Word from God”: the Word is Jesus, who came to be by the divine command “Be!” ( كُنْ ), without the customary natural cause. “A lordly leader” ( سيّدًا ): he will surpass and preside over his people. “Restrained” ( حصورًا ): one who exercises exceptional restraint over the self’s desires and diversions. It is reported that children invited him to play in his youth, and he replied: “I was not created for play.” Or it has been interpreted as a man incapable of sexual intercourse. It is related that “he had a male organ like a mote”; Ibn ʿAbbās transmits this. The Asās defines a ḥaṣūr as “a man who has no desire for women.” It is said that this was an excellence under his religious law, unlike the law of our Prophet Muḥammad, blessings and peace be upon him. Al-Wartajbī explains: the ḥaṣūr is one who rules [his impulses] without being ruled by them. Al-Qushayrī says: “Restrained” means set free from passions, spared the compulsion of ordinary human appetites even while remaining human. “A prophet among the righteous”: those fitted for prophecy and worthy of the [divine] Presence. [XIV-N008]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 350; Q3:38–41; qushayri_tafsir: Laṭāʾif al-ishārāt I:241, Q3:39; PageV01P241","revision_status":"","word_count":88,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-38-41","segment_index":1,"q":"3:38–41","source":"Cairo print · Volume I, pp. 349–351","segment_title":"[A child from the barren and the aged]","anchor_paragraph":"“Confirming a Word from God”: the Word is Jesus, who came to be by the divine command “Be!” ( كُنْ ), without the customary natural cause. “A lordly leader” ( سيّدًا ): he will surpass and preside over his people. “Restrained” ( حصورًا ): one who exercises exceptional restraint over the self’s desires and diversions. It is reported that children invited him to play in his youth, and he replied: “I was not created for play.” Or it has been interpreted as a man incapable of sexual intercourse. It is related that “he had a male organ like a mote”; Ibn ʿAbbās transmits this. The Asās defines a ḥaṣūr as “a man who has no desire for women.” It is said that this was an excellence under his religious law, unlike the law of our Prophet Muḥammad, blessings and peace be upon him. Al-Wartajbī explains: the ḥaṣūr is one who rules [his impulses] without being ruled by them. Al-Qushayrī says: “Restrained” means set free from passions, spared the compulsion of ordinary human appetites even while remaining human. “A prophet among the righteous”: those fitted for prophecy and worthy of the [divine] Presence. [T065]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T065; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T065","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T065","original_body_sha256":"3516b6edfe381065bc8a22027397e752310cb2eab7d6f77bcbaa206d8ed64170","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":27,"print_label":"T27","linked_occurrences":[{"record_id":"q3-38-41","segment_index":1,"q":"3:38–41","source":"Cairo print · Volume I, pp. 349–351"}]},{"id":"XIV-N009","historical_note_id":"T066","title":"Spiritual children and the transmission of the Path","content":"Muslim’s Ṣaḥīḥ (no. 1631) transmits the three continuing benefits: ongoing charity, beneficial knowledge, and a righteous child who prays for the deceased. Ibn ʿAjība then explicitly includes spiritual as well as bodily offspring. The extension to disciples belongs to his interpretation of the report and to his analogy between bodily and spiritual lineages. It is not an additional phrase in Muslim’s hadith. The preceding acknowledgement that a perfected saint may have no spiritual offspring also matters: the number of disciples is not presented as a necessary measure of the saint’s personal realization.","evidence":[{"source_id":"CAIRO-I-351","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 351; Q3:38–41","exact_arabic":"وشمل الولد البشري والروحاني","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-muslim","title":"muslim","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0261Muslim/0261Muslim.Sahih/0261Muslim.Sahih.Shamela0001727-ara1.mARkdown","locator":"Ṣaḥīḥ Muslim, no.1631, Kitāb al-Waṣiyya","exact_arabic":"إذا مات الإنسان انقطع عنه عمله إلا من ثلاثة إلا من صدقة جارية أو علم ينتفع به أو ولد صالح يدعو له","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The three-part report was read; the explicit spiritual-child extension is absent from this hadith text.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"8126f063f53504b68d6e9e133cec049c10acf498c501f5f4897013efc1e56d9e"}],"scope":[{"record_id":"q3-38-41","segment_index":2,"q":"3:38–41","source":"Cairo print · Volume I, pp. 349–351","segment_title":"Spiritual children and the transmission of the Path","anchor_paragraph":"Spiritual lineages ( الأصلاب الروحانية ) resemble bodily lineages ( الأصلاب الجسمانية ). Some remain without offspring despite their own perfection; some have one or two, while some have many. Zachariah’s story teaches the appropriateness of seeking offspring when a friend of God ( وليّ ) fears that his knowledge or state may disappear with the interruption of his spiritual descent. There is unquestionably merit in the continuation of offspring, sensible or spiritual. The Prophet, blessings and peace be upon him, said: “When a servant dies, his work comes to an end except for three: ongoing charity, a righteous child praying for him, or knowledge from which people benefit.” [XIV-N009]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 351; Q3:38–41; muslim: Ṣaḥīḥ Muslim, no.1631, Kitāb al-Waṣiyya","revision_status":"","word_count":92,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-38-41","segment_index":2,"q":"3:38–41","source":"Cairo print · Volume I, pp. 349–351","segment_title":"Spiritual allusion — الإشارة Spiritual children and the transmission of the Path","anchor_paragraph":"Spiritual lineages ( الأصلاب الروحانية ) resemble bodily lineages ( الأصلاب الجسمانية ). Some remain without offspring despite their own perfection; some have one or two, while some have many. Zachariah’s story teaches the appropriateness of seeking offspring when a friend of God ( وليّ ) fears that his knowledge or state may disappear with the interruption of his spiritual descent. There is unquestionably merit in the continuation of offspring, sensible or spiritual. The Prophet, blessings and peace be upon him, said: “When a servant dies, his work comes to an end except for three: ongoing charity, a righteous child praying for him, or knowledge from which people benefit.” [T066]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T066; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T066","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T066","original_body_sha256":"dcb34c6d7c848fdc8711cf7eb5d2ae8e692d908611eb142196186291359c317a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":28,"print_label":"T28","linked_occurrences":[{"record_id":"q3-38-41","segment_index":2,"q":"3:38–41","source":"Cairo print · Volume I, pp. 349–351"}]},{"id":"XIV-N010","historical_note_id":"T067","title":"The two elections of Mary","content":"The repeated “has chosen you” is given two distinct applications. The first concerns Mary’s reception into sacred service and God’s provision for her; the second concerns her guidance, angelic address, and the extraordinary birth announced to her. The repetition distinguishes these two gifts. The passage places these gifts within the author’s category of karāma, a grace bestowed on a friend of God. His adjoining claim of consensus about women and prophecy remains an attributed doctrinal assertion; the two elections themselves do not independently establish that claim.","evidence":[{"source_id":"CAIRO-I-351","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 351; Q3:42–43","exact_arabic":"وَاصْطَفاكِ ثانياً بهدايته لك، وتخصيصك بتكليم الملائكة","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-42-43","segment_index":0,"q":"3:42–43","source":"Cairo print · Volume I, pp. 351–352","segment_title":"The two elections of Mary","anchor_paragraph":"The Real, exalted is His majesty, says: “Remember when the angels said”—Gabriel, or a company of angels, addressing Mary directly as a grace ( كرامة ) bestowed upon her. This establishes extraordinary graces for God’s friends ( كرامات الأولياء ). Mary was not a prophet, because of the consensus that God did not appoint a woman to prophecy, as indicated by “We sent before you only men to whom We revealed” [21:7]. [Translator’s note: The assertion of consensus is the author’s. The Cairo editor directs the reader to Fatḥ al-bārī , 6:542, on the question of Mary’s prophethood.] The angels said: “Mary, God has chosen you” for service in His House; before you He had not accepted a female for that service. He has freed you for His worship and sufficed you with His provision, without needing that of anyone else. “He has purified you” of blameworthy qualities and of what is considered impure in women; “and has chosen you” again through guidance, through addressing you by the angels, and through the annunciation of a son without a father. Thus He has chosen you above the women of the worlds. [XIV-N010]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 351; Q3:42–43","revision_status":"","word_count":102,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-42-43","segment_index":0,"q":"3:42–43","source":"Cairo print · Volume I, pp. 351–352","segment_title":"[The two elections of Mary]","anchor_paragraph":"The Real, exalted is His majesty, says: “Remember when the angels said”—Gabriel, or a company of angels, addressing Mary directly as a grace ( كرامة ) bestowed upon her. This establishes extraordinary graces for God’s friends ( كرامات الأولياء ). Mary was not a prophet, because of the consensus that God did not appoint a woman to prophecy, as indicated by “We sent before you only men to whom We revealed” [21:7]. [Translator’s note: The assertion of consensus is the author’s. The Cairo editor directs the reader to Fatḥ al-bārī , 6:542, on the question of Mary’s prophethood.] The angels said: “Mary, God has chosen you” for service in His House; before you He had not accepted a female for that service. He has freed you for His worship and sufficed you with His provision, without needing that of anyone else. “He has purified you” of blameworthy qualities and of what is considered impure in women; “and has chosen you” again through guidance, through addressing you by the angels, and through the annunciation of a son without a father. Thus He has chosen you above the women of the worlds. [T067]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T067; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T067","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T067","original_body_sha256":"8f6a472a979d84d5855dedd5b7114fb74b63874f57ce09638f0bc833ebba8a9a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":29,"print_label":"T29","linked_occurrences":[{"record_id":"q3-42-43","segment_index":0,"q":"3:42–43","source":"Cairo print · Volume I, pp. 351–352"}]},{"id":"XIV-N011","historical_note_id":"T068","title":"The two elections of Mary","content":"The reports about women’s distinction have different wording and should not be merged. Al-Bukhārī’s “many men attained perfection” report names Mary and Āsiya (Ṣaḥīḥ, no. 3433); the Cairo quotation here additionally names Khadīja. A different report in al-Tirmidhī (no. 3878) names Mary, Khadīja, Fāṭima, and Āsiya together. Its existence does not establish the added name as part of al-Bukhārī’s wording. The subsequent comparisons of “her world,” “her age,” and all women are exegetical efforts to relate distinct commendations. The difference between Ibn ʿAjība’s quotation and these hadith texts remains a separate textual issue.","evidence":[{"source_id":"CAIRO-I-352","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 352; Q3:42–43","exact_arabic":"كَمُلَ مِنَ الرِّجَالِ كَثِيرٌ ولَمْ يَكْمُلْ مِنَ النِّسَاءِ","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-bukhari","title":"bukhari","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","locator":"Ṣaḥīḥ al-Bukhārī, no.3433","exact_arabic":"ولم يكمل من النساء إلا مريم بنت عمران وآسية امرأة فرعون","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"This version of the perfection report does not include Khadīja.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"16f95173b9ea1927b577ff85dc7e2a8351b8287e4ea9863782c4c5fc87ac8132"},{"source_id":"XIV-OT-tirmidhi","title":"tirmidhi","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0279Tirmidhi/0279Tirmidhi.Sunan/0279Tirmidhi.Sunan.Shamela0001435-ara1","locator":"Jāmiʿ al-Tirmidhī, no.3878, V:703; PageV05P703","exact_arabic":"حسبك من نساء العالمين مريم ابنة عمران وخديجة بنت خويلد وفاطمة بنت محمد وآسية امرأة فرعون","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"A distinct four-women report, followed by al-Tirmidhī’s own grading; not a variant automatically interchangeable with the perfection report.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"965e8032d319ca639eebeac0f213a154acb379e3faaf49fd9a46b1f9289ec6e2"}],"scope":[{"record_id":"q3-42-43","segment_index":0,"q":"3:42–43","source":"Cairo print · Volume I, pp. 351–352","segment_title":"The two elections of Mary","anchor_paragraph":"The Prophet, blessings and peace be upon him, is reported to have said: “Many among men have attained perfection; among women only Mary daughter of ʿImrān, Āsiya daughter of Muzāḥim, and Khadīja daughter of Khuwaylid attained perfection ...” Ibn ʿAzīz says that “the worlds” means the people of her age, just as Khadīja and Fāṭima daughter of the Messenger, blessings and peace be upon him, were favoured above the women of Muḥammad’s community. Abū ʿUmar even maintained that Fāṭima was favoured above all women, pointing to the report that she is the foremost woman of Paradise; but another report excepts Mary. God knows best. In the Istīʿāb there is a report from ʿImrān ibn Ḥuṣayn that the Prophet visited Fāṭima when she was ill and asked how she was. She replied that she was in pain, made worse by having nothing to eat. He asked whether she would not be content to be the foremost woman of the worlds. She said, “Father, then where is Mary daughter of ʿImrān?” He replied that Mary was the foremost woman of her world, while Fāṭima was foremost in hers, and that he had married her to a master in this world and the next. End of note from the glossator. [XIV-N011]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 352; Q3:42–43; bukhari: Ṣaḥīḥ al-Bukhārī, no.3433; tirmidhi: Jāmiʿ al-Tirmidhī, no.3878, V:703; PageV05P703","revision_status":"","word_count":92,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-42-43","segment_index":0,"q":"3:42–43","source":"Cairo print · Volume I, pp. 351–352","segment_title":"[The two elections of Mary]","anchor_paragraph":"The Prophet, blessings and peace be upon him, is reported to have said: “Many among men have attained perfection; among women only Mary daughter of ʿImrān, Āsiya daughter of Muzāḥim, and Khadīja daughter of Khuwaylid attained perfection ...” Ibn ʿAzīz says that “the worlds” means the people of her age, just as Khadīja and Fāṭima daughter of the Messenger, blessings and peace be upon him, were favoured above the women of Muḥammad’s community. Abū ʿUmar even maintained that Fāṭima was favoured above all women, pointing to the report that she is the foremost woman of Paradise; but another report excepts Mary. God knows best. In the Istīʿāb there is a report from ʿImrān ibn Ḥuṣayn that the Prophet visited Fāṭima when she was ill and asked how she was. She replied that she was in pain, made worse by having nothing to eat. He asked whether she would not be content to be the foremost woman of the worlds. She said, “Father, then where is Mary daughter of ʿImrān?” He replied that Mary was the foremost woman of her world, while Fāṭima was foremost in hers, and that he had married her to a master in this world and the next. End of note from the glossator. [T068]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T068; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T068","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T068","original_body_sha256":"50b44ac0732d9da4a08687a4f454d85075630f9fcf9ec05b554a0df0bd978e67","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":30,"print_label":"T30","linked_occurrences":[{"record_id":"q3-42-43","segment_index":0,"q":"3:42–43","source":"Cairo print · Volume I, pp. 351–352"}]},{"id":"XIV-N012","historical_note_id":"T069","title":"Devotion, bowing and prostration","content":"The issue is the order of mention, not a prescription that Muslim prayer should place prostration before bowing. Arabic wa- joins the two commands without necessarily specifying their temporal sequence. Al-Bayḍāwī gives the same alternatives at Q3:43 (Anwār, II:16): a different earlier ritual order, the conjunction’s non-sequential force, or the rhetorical pairing of “bow” with “those who bow.” These are alternative explanations of the verse. His further interpretation of qunūt as sustained obedience and rukūʿ as humility is likewise a second account; the two accounts are alternatives, not one reconstructed ritual.","evidence":[{"source_id":"CAIRO-I-352","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 352; Q3:42–43","exact_arabic":"أو للتنبيه على أن الواو لا ترتب","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-baydawi","title":"baydawi","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0685NasirDinBaydawi/0685NasirDinBaydawi.AnwarTanzil/0685NasirDinBaydawi.AnwarTanzil.Shamela0023588-ara1","locator":"Anwār al-tanzīl II:16, Q3:43; PageV02P016","exact_arabic":"وقدم السجود على الركوع إما لكونه كذلك في شريعتهم أو للتنبيه على أن الواو لا توجب الترتيب","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The source directly presents alternative explanations of the ordering.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"6bc14b72dc468030f939690ce4307a3a9e617d866198b2b9d19857fba684def6"}],"scope":[{"record_id":"q3-42-43","segment_index":1,"q":"3:42–43","source":"Cairo print · Volume I, pp. 351–352","segment_title":"Devotion, bowing and prostration","anchor_paragraph":"“Mary, be devoutly obedient to your Lord” ( اقنتي ): prolong your prayer in gratitude for what He has singled you out to receive. “Prostrate and bow with those who bow”: pray with those who pray. The verse mentions prostration before bowing either because that was the sequence in their religious law, or to show that the conjunction wa- (و) does not itself impose an order, or so that “bow” may stand next to “those who bow,” indicating that those whose prayer does not include bowing are not among those who pray [in this sense]. It has also been said that qunūt is continual obedience, as in “one devout during the night, prostrating and standing” [39:9]; sujūd denotes prayer, as in “after prostrations” [50:40]; while rukūʿ signifies humility and lowliness. Thus al-Bayḍāwī. Al-Awzāʿī relates that when the angels had said this to Mary, she stood in prayer until her feet swelled and discharged blood and pus. [XIV-N012]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 352; Q3:42–43; baydawi: Anwār al-tanzīl II:16, Q3:43; PageV02P016","revision_status":"","word_count":97,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-42-43","segment_index":1,"q":"3:42–43","source":"Cairo print · Volume I, pp. 351–352","segment_title":"[Devotion, bowing and prostration]","anchor_paragraph":"“Mary, be devoutly obedient to your Lord” ( اقنتي ): prolong your prayer in gratitude for what He has singled you out to receive. “Prostrate and bow with those who bow”: pray with those who pray. The verse mentions prostration before bowing either because that was the sequence in their religious law, or to show that the conjunction wa- (و) does not itself impose an order, or so that “bow” may stand next to “those who bow,” indicating that those whose prayer does not include bowing are not among those who pray [in this sense]. It has also been said that qunūt is continual obedience, as in “one devout during the night, prostrating and standing” [39:9]; sujūd denotes prayer, as in “after prostrations” [50:40]; while rukūʿ signifies humility and lowliness. Thus al-Bayḍāwī. Al-Awzāʿī relates that when the angels had said this to Mary, she stood in prayer until her feet swelled and discharged blood and pus. [T069]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T069; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T069","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T069","original_body_sha256":"4fceb32a82ab7009696127c17394b7c139302d490f8b55c99547324fe50518fc","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":31,"print_label":"T31","linked_occurrences":[{"record_id":"q3-42-43","segment_index":1,"q":"3:42–43","source":"Cairo print · Volume I, pp. 351–352"}]},{"id":"XIV-N013","historical_note_id":"T070","title":"Dream, inspiration, legislation and disclosure","content":"Waḥy has a deliberately broad scope in this fourfold classification. The crucial distinction is between receiving an intimation and receiving binding religious rulings: waḥy al-aḥkām is reserved for prophets. Within this classification, he reserves waḥy al-iʿlām conveyed through an angel to prophets, while allowing inspiration, dreams, or direct understanding to saints. “Revelation” in these latter uses therefore should not imply a new scripture or authority to legislate. The closing qualification further limits what a purified spirit may receive: disclosure is partial and general, while exhaustive knowledge of unseen particulars belongs to God. This is Ibn ʿAjība’s local scheme, not an authentication of particular claimed experiences.","evidence":[{"source_id":"CAIRO-I-353","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 353; Q3:44","exact_arabic":"اعلم أن الوحي على أربعة أقسام: وحي منام، ووحي إلهام، ووحي أحكام، ووحي إعلام","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-44","segment_index":1,"q":"3:44","source":"Cairo print · Volume I, pp. 352–353","segment_title":"Dream, inspiration, legislation and disclosure","anchor_paragraph":"Know that waḥy ( الوحي ) is of four kinds: revelation in a dream ( وحي منام ), revelatory inspiration ( وحي إلهام ), revelation of rulings ( وحي أحكام ), and revelation conveying information ( وحي إعلام ). God’s friends share with the prophets in three of them: inspiration, dreams, and disclosure of information—provided that the last does not come through an angel. The meaning of waḥy al-iʿlām ( وحي إعلام ) is God’s acquainting a prophet with concealed matters. If it comes through an angel it belongs especially to prophets, just as revelation of rulings belongs especially to them. If, however, it comes by inspiration, dream or direct understanding from God ( الفهم عن الله ), it can also occur to God’s friends: once the spirit is clarified and cleansed of sensory defilement, God may disclose something of the unseen to it in a general way. Its particulars, however, none knows except the Knower of unseen things. And God knows best. [XIV-N013]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 353; Q3:44","revision_status":"","word_count":105,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-44","segment_index":1,"q":"3:44","source":"Cairo print · Volume I, pp. 352–353","segment_title":"Spiritual allusion — الإشارة Dream, inspiration, legislation and disclosure","anchor_paragraph":"Know that waḥy ( الوحي ) is of four kinds: revelation in a dream ( وحي منام ), revelatory inspiration ( وحي إلهام ), revelation of rulings ( وحي أحكام ), and revelation conveying information ( وحي إعلام ). God’s friends share with the prophets in three of them: inspiration, dreams, and disclosure of information—provided that the last does not come through an angel. The meaning of waḥy al-iʿlām ( وحي إعلام ) is God’s acquainting a prophet with concealed matters. If it comes through an angel it belongs especially to prophets, just as revelation of rulings belongs especially to them. If, however, it comes by inspiration, dream or direct understanding from God ( الفهم عن الله ), it can also occur to God’s friends: once the spirit is clarified and cleansed of sensory defilement, God may disclose something of the unseen to it in a general way. Its particulars, however, none knows except the Knower of unseen things. And God knows best. [T070]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T070; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T070","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T070","original_body_sha256":"b46376e5ee110e69998a65c9b63caa6c53795439f549420b9ff9383e37c3491a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":32,"print_label":"T32","linked_occurrences":[{"record_id":"q3-44","segment_index":1,"q":"3:44","source":"Cairo print · Volume I, pp. 352–353"}]},{"id":"XIV-N014","historical_note_id":"T071","title":"The Messiah, the Word, and the syntax of the annunciation","content":"These are alternative explanations of the Arabic epithet masīḥ. Under the root m-s-ḥ, its faʿīl form can be explained through a passive relation, “one wiped/anointed,” or an active relation, “one who wipes.” The proposed connection with travelling instead treats the initial mīm as additional and relates the word to another root. The alternatives are word-based exegetical explanations, not cumulative facts that must all hold at once. The final saying depends on the epithet’s application to both Jesus and the Dajjāl: “the Messiah will slay the messiah” contrasts its two referents and does not identify them as the same figure.","evidence":[{"source_id":"CAIRO-I-354","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 354; Q3:45–51","exact_arabic":"أن عيسى مسيح الخير، والدجال مسيح الشر","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-45-51","segment_index":0,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357","segment_title":"The Messiah, the Word, and the syntax of the annunciation","anchor_paragraph":"“Messiah” ( المسيح ) follows the pattern faʿīl with a passive sense ( mafʿūl ): he was wiped or cleansed of impurities and so purified; or he was anointed with blessing; or the sole of his foot was flat without an arch; or Gabriel wiped him with his wing to protect him from Satan. Or masīḥ has an active sense ( fāʿil ), because he passed his hand over the ill and they recovered, or over the blind person’s eyes and they saw; or because he travelled ( يسِيح ) through the earth, without settling in one place, in which case the initial mīm is additional. As for the Antichrist, al-masīḥ al-dajjāl , one of his eyes is effaced, or he traverses the earth save Mecca and Medina. In short, Jesus is the Messiah of good and the Antichrist the messiah of evil. It is therefore said, “The Messiah will slay the messiah.” [XIV-N014]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 354; Q3:45–51","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-45-51","segment_index":0,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357","segment_title":"[The Messiah, the Word, and the syntax of the annunciation]","anchor_paragraph":"“Messiah” ( المسيح ) follows the pattern faʿīl with a passive sense ( mafʿūl ): he was wiped or cleansed of impurities and so purified; or he was anointed with blessing; or the sole of his foot was flat without an arch; or Gabriel wiped him with his wing to protect him from Satan. Or masīḥ has an active sense ( fāʿil ), because he passed his hand over the ill and they recovered, or over the blind person’s eyes and they saw; or because he travelled ( يسِيح ) through the earth, without settling in one place, in which case the initial mīm is additional. As for the Antichrist, al-masīḥ al-dajjāl , one of his eyes is effaced, or he traverses the earth save Mecca and Medina. In short, Jesus is the Messiah of good and the Antichrist the messiah of evil. It is therefore said, “The Messiah will slay the messiah.” [T071]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T071; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T071","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T071","original_body_sha256":"fb78d0eb784d5357773f175a605b96e47a284d6911dec59569aa6c0bf252e0a3","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":33,"print_label":"T33","linked_occurrences":[{"record_id":"q3-45-51","segment_index":0,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357"}]},{"id":"XIV-N015","historical_note_id":"T072","title":"The signs granted to Jesus","content":"“I fashion” renders akhluqu in its local sense of forming a clay likeness. Al-Bayḍāwī makes that sense explicit at Q3:49: “I determine and shape for you” (Anwār, II:18). The subsequent life of the figure and the restoration of the dead are repeatedly qualified by “God’s leave.” Ibn ʿAjība expressly uses the qualification to distinguish the miracle’s ultimate divine agency from an independent power belonging to Jesus. The account of the bat is an additional reported explanation of the sign; its species identification and natural-history details are not specified by the Qurʾānic word “bird.”","evidence":[{"source_id":"CAIRO-I-355","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 355; Q3:45–51","exact_arabic":"وَأُحْيِ الْمَوْتى بِإِذْنِ اللَّهِ لا بقدرتي دفعاً لتوهم الألوهية","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-baydawi","title":"baydawi","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0685NasirDinBaydawi/0685NasirDinBaydawi.AnwarTanzil/0685NasirDinBaydawi.AnwarTanzil.Shamela0023588-ara1","locator":"Anwār al-tanzīl II:18, Q3:49; PageV02P018","exact_arabic":"والمعنى أقدر لكم وأصور شيئا مثل صورة الطير ... نبه به على أن إحياءه من الله تعالى لا منه","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"Direct lexical and agency explanation of the clay-bird sign.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"6bc14b72dc468030f939690ce4307a3a9e617d866198b2b9d19857fba684def6"}],"scope":[{"record_id":"q3-45-51","segment_index":2,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357","segment_title":"The signs granted to Jesus","anchor_paragraph":"“And [He will make him] a messenger to the Children of Israel.” Joseph was the first of the messengers among the Children of Israel, Jesus the last—upon them peace. A report attributed to the Prophet says: “I was sent after eight thousand prophets, four thousand of them from the Children of Israel.” When Jesus was sent to them, he said, “I have come to you with a sign from your Lord.” They asked what it was. He replied: “I fashion for you from clay something in the form of a bird; then I breathe into it and it becomes a bird, by God’s leave .” He used to form for them the shape of a bat, because it is the most complete of birds: it has breasts and teeth, menstruates and flies, making the miracle more striking. It flew while people looked at it and fell dead when out of their sight, to distinguish the act of the Real from that of the creature. [Translator’s note: These are transmitted exegetical descriptions; their claims about natural history have not been independently established.] [XIV-N015]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 355; Q3:45–51; baydawi: Anwār al-tanzīl II:18, Q3:49; PageV02P018","revision_status":"","word_count":93,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-45-51","segment_index":2,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357","segment_title":"[The signs granted to Jesus]","anchor_paragraph":"“And [He will make him] a messenger to the Children of Israel.” Joseph was the first of the messengers among the Children of Israel, Jesus the last—upon them peace. A report attributed to the Prophet says: “I was sent after eight thousand prophets, four thousand of them from the Children of Israel.” When Jesus was sent to them, he said, “I have come to you with a sign from your Lord.” They asked what it was. He replied: “I fashion for you from clay something in the form of a bird; then I breathe into it and it becomes a bird, by God’s leave .” He used to form for them the shape of a bat, because it is the most complete of birds: it has breasts and teeth, menstruates and flies, making the miracle more striking. It flew while people looked at it and fell dead when out of their sight, to distinguish the act of the Real from that of the creature. [Translator’s note: These are transmitted exegetical descriptions; their claims about natural history have not been independently established in this translation.] [T072]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T072; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T072","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T072","original_body_sha256":"32d75a34109a5475ed2953d5ebe70e17658babc5ca5ae981f7953f30c29cc678","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":34,"print_label":"T34","linked_occurrences":[{"record_id":"q3-45-51","segment_index":2,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357"}]},{"id":"XIV-N016","historical_note_id":"T073","title":"The signs granted to Jesus","content":"The four named resuscitations form an exegetical narrative attached to Q3:49. Al-Baghawī preserves the same sequence—ʿĀzir, the old woman’s son, the tithe-collector’s daughter, and Shem—and the account of Shem’s hair turning grey through fear of the Resurrection (Maʿālim, II:40). This locates an earlier narrative parallel, with some differences in detail. The Qurʾānic verse itself does not supply those names or episodes. The final “it is said” introduces a further identification of the invocation as “O Living, O Self-Subsisting”; it should not be read as an independently established quotation of the words used in every preceding episode.","evidence":[{"source_id":"CAIRO-I-355","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 355; Q3:45–51","exact_arabic":"دعا باسم الله الأعظم","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-baghawi","title":"baghawi","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0510IbnMascudBaghawi/0510IbnMascudBaghawi.Tafsir/0510IbnMascudBaghawi.Tafsir.Shamela0000041-ara1.completed","locator":"Maʿālim al-tanzīl II:40, Q3:49; PageV02P040","exact_arabic":"قد أحيا أربعة أنفس، عازر وابن العجوز، وابنة العاشر، وسام بن نوح ... فخرج من قبره وقد شاب نصف رأسه خوفا من قيام الساعة","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"Earlier four-person narrative and Shem episode read; matching narrative does not authenticate the attribution.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"2dee9364cc320628351e7057d2f593ae80323b0eebdbf97760ba73d1eaccbc6d"}],"scope":[{"record_id":"q3-45-51","segment_index":2,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357","segment_title":"The signs granted to Jesus","anchor_paragraph":"The fourth was Shem son of Noah. Jesus invoked God by His Greatest Name, and Shem came out of his grave, half his head white-haired. He asked, “Has the Hour come?” Jesus said, “No, but I invoked God and He gave you life. Why is your hair grey when it was not so in your time?” He answered that hearing the cry he supposed the Hour had come, and terror turned his hair grey. It is said Jesus raised the dead by the invocation “O Living, O Self-Subsisting” ( يا حي يا قيوم ). [XIV-N016]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 355; Q3:45–51; baghawi: Maʿālim al-tanzīl II:40, Q3:49; PageV02P040","revision_status":"","word_count":96,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-45-51","segment_index":2,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357","segment_title":"[The signs granted to Jesus]","anchor_paragraph":"The fourth was Shem son of Noah. Jesus invoked God by His Greatest Name, and Shem came out of his grave, half his head white-haired. He asked, “Has the Hour come?” Jesus said, “No, but I invoked God and He gave you life. Why is your hair grey when it was not so in your time?” He answered that hearing the cry he supposed the Hour had come, and terror turned his hair grey. It is said Jesus raised the dead by the invocation “O Living, O Self-Subsisting” ( يا حي يا قيوم ). [T073]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T073; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T073","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T073","original_body_sha256":"f979d19e919824cc269f4c1782b2fb45d124725b62797b67b51b5e6117a854a9","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":35,"print_label":"T35","linked_occurrences":[{"record_id":"q3-45-51","segment_index":2,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357"}]},{"id":"XIV-N017","historical_note_id":"T074","title":"The signs granted to Jesus","content":"The attribution to al-Suddī closes the childhood narrative, including the concealed food, the boys’ confinement, the transformation, and the flight to Egypt. Al-Baghawī transmits this same sequence under al-Suddī’s name at Q3:49 (Maʿālim, II:40–41). He then gives a different explanation from Qatāda involving the heavenly table; that separate account should not be combined with the schoolroom story. The parallel confirms the scope of the transmitted attribution in Ibn ʿAjība. It does not make the whole narrative Qurʾānic: the verse states Jesus’ knowledge of food eaten and stored, while the surrounding incidents come from exegetical reporting.","evidence":[{"source_id":"CAIRO-I-356","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 356; Q3:45–51","exact_arabic":"ففتحوا الباب، فإذاهم خنازير، فهموا بقتله، فهربت به أمه إلى مصر. قاله السُّدي.","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-baghawi","title":"baghawi","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0510IbnMascudBaghawi/0510IbnMascudBaghawi.Tafsir/0510IbnMascudBaghawi.Tafsir.Shamela0000041-ara1.completed","locator":"Maʿālim al-tanzīl II:40–41, Q3:49; PageV02P040–041","exact_arabic":"وقال السدي كان عيسى عليه السلام في الكتاب يحدث الغلمان ... ففتحوا عليهم فإذا هم خنازير ... إلى أهل مصر","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The al-Suddī attribution governs the complete schoolroom episode; a subsequent Qatāda account is distinct.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"2dee9364cc320628351e7057d2f593ae80323b0eebdbf97760ba73d1eaccbc6d"}],"scope":[{"record_id":"q3-45-51","segment_index":2,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357","segment_title":"The signs granted to Jesus","anchor_paragraph":"“And I tell you what you eat and what you store in your homes.” After witnessing his cures, some said that these were sorcery and demanded to know what they ate and saved. He would tell a man what he had eaten for his morning and evening meals. It is related that when he attended school, he told the boys what food their parents had prepared: “Go—your family’s meal today is such and such.” Asked how they knew, they said Jesus had informed them. Their parents confined them and warned them not to play with “this sorcerer.” When Jesus came looking for them, they denied the boys were there. He asked what the house contained. They said “Pigs.” Jesus said: “Then so shall they be.” When the door was opened, the boys were pigs. The people then intended to kill him, and his mother fled with him to Egypt. So relates al-Suddī. [XIV-N017]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 356; Q3:45–51; baghawi: Maʿālim al-tanzīl II:40–41, Q3:49; PageV02P040–041","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-45-51","segment_index":2,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357","segment_title":"[The signs granted to Jesus]","anchor_paragraph":"“And I tell you what you eat and what you store in your homes.” After witnessing his cures, some said that these were sorcery and demanded to know what they ate and saved. He would tell a man what he had eaten for his morning and evening meals. It is related that when he attended school, he told the boys what food their parents had prepared: “Go—your family’s meal today is such and such.” Asked how they knew, they said Jesus had informed them. Their parents confined them and warned them not to play with “this sorcerer.” When Jesus came looking for them, they denied the boys were there. He asked what the house contained. They said “Pigs.” Jesus said: “Then so shall they be.” When the door was opened, the boys were pigs. The people then intended to kill him, and his mother fled with him to Egypt. So relates al-Suddī. [T074]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T074; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T074","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T074","original_body_sha256":"23e99b2c5859f4118f2f56e526a4f9fe4a94ca947610763f08a71acb380af354","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":36,"print_label":"T36","linked_occurrences":[{"record_id":"q3-45-51","segment_index":2,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357"}]},{"id":"XIV-N018","historical_note_id":"T075","title":"Divine unity and the straight way","content":"The “theoretical” and “practical” powers are complementary human capacities: apprehending what is true and acting in accordance with it. Here the first reaches its fulfilment in acknowledging God’s unity; the second in worship and obedience. Al-Bayḍāwī’s corresponding passage (Anwār, II:19, Q3:51) makes the same pairing. “Theoretical” therefore should not suggest mere speculation or an optional hypothesis. The closing hadith condenses the two aspects into belief and upright conduct; Muslim transmits the instruction to Sufyān ibn ʿAbd Allāh as “Say: I believe in God; then remain upright” (Ṣaḥīḥ, no. 38).","evidence":[{"source_id":"CAIRO-I-356","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 356; Q3:45–51","exact_arabic":"استكمال القوة النظرية بالاعتقاد الحق الذي غايتُه التوحيد","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-baydawi","title":"baydawi","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0685NasirDinBaydawi/0685NasirDinBaydawi.AnwarTanzil/0685NasirDinBaydawi.AnwarTanzil.Shamela0023588-ara1","locator":"Anwār al-tanzīl II:19, Q3:51; PageV02P019","exact_arabic":"إشارة إلى استكمال القوة النظرية بالاعتقاد الحق الذي غايته التوحيد","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The knowing/acting structure of the argument is directly present in the named source.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"6bc14b72dc468030f939690ce4307a3a9e617d866198b2b9d19857fba684def6"},{"source_id":"XIV-OT-muslim","title":"muslim","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0261Muslim/0261Muslim.Sahih/0261Muslim.Sahih.Shamela0001727-ara1.mARkdown","locator":"Ṣaḥīḥ Muslim, no.38, Kitāb al-Īmān","exact_arabic":"قل آمنت بالله فاستقم","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"Direct prophetic-report parallel; the explanatory faculty terminology belongs to the commentary.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"8126f063f53504b68d6e9e133cec049c10acf498c501f5f4897013efc1e56d9e"}],"scope":[{"record_id":"q3-45-51","segment_index":3,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357","segment_title":"Divine unity and the straight way","anchor_paragraph":"He then calls them to divine unity ( التوحيد ) after establishing the evidence: “God is my Lord and your Lord; so worship Him,” and none besides Him. “This is a straight path,” without crookedness. Al-Bayḍāwī says: Having come with compelling miracles and manifest signs, “be mindful of God” by avoiding opposition “and obey me” in what I call you to. Jesus then begins his call, summed up in the words “God is my Lord and your Lord,” indicating the perfection of the theoretical power ( القوة النظرية ) through true belief, whose highest end is divine unity; and “so worship Him,” indicating the perfection of the practical power ( القوة العملية ) by persevering in obedience, performing commands and avoiding prohibitions. Uniting these two completes the path attested as straight. Its counterpart is the saying of the Prophet, blessings and peace be upon him: “Say, ‘I believe in God,’ and then remain upright.” [XIV-N018]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 356; Q3:45–51; baydawi: Anwār al-tanzīl II:19, Q3:51; PageV02P019; muslim: Ṣaḥīḥ Muslim, no.38, Kitāb al-Īmān","revision_status":"","word_count":89,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-45-51","segment_index":3,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357","segment_title":"[Divine unity and the straight way]","anchor_paragraph":"He then calls them to divine unity ( التوحيد ) after establishing the evidence: “God is my Lord and your Lord; so worship Him,” and none besides Him. “This is a straight path,” without crookedness. Al-Bayḍāwī says: Having come with compelling miracles and manifest signs, “be mindful of God” by avoiding opposition “and obey me” in what I call you to. Jesus then begins his call, summed up in the words “God is my Lord and your Lord,” indicating the perfection of the theoretical power ( القوة النظرية ) through true belief, whose highest end is divine unity; and “so worship Him,” indicating the perfection of the practical power ( القوة العملية ) by persevering in obedience, performing commands and avoiding prohibitions. Uniting these two completes the path attested as straight. Its counterpart is the saying of the Prophet, blessings and peace be upon him: “Say, ‘I believe in God,’ and then remain upright.” [T075]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T075; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T075","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T075","original_body_sha256":"e5c0213879afb11f6ce6ebaacafdbf0aa6c947faf88bb552d0c967c0eb234603","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":37,"print_label":"T37","linked_occurrences":[{"record_id":"q3-45-51","segment_index":3,"q":"3:45–51","source":"Cairo print · Volume I, pp. 353–357"}]},{"id":"XIV-N019","historical_note_id":"T076","title":"The disciples’ confession and the attempt upon Jesus","content":"Qaṣṣārūn are workers who cleanse or whiten cloth, while ṣabbāghūn are dyers; “cloth-finishers and dyers” preserves both crafts. The anecdote develops one of the explanations of ḥawāriyyūn given immediately before it (Cairo I:357): the disciples are associated with whitening cloth, beside interpretations through purity of intention or white clothing. In the story, different colours emerge from a single vat through Jesus’ instruction, prompting recognition of a divine sign. The report is introduced through ʿAṭāʾ. It illustrates an explanation of the disciples’ designation; it does not by itself settle the word’s historical derivation or authenticate their occupations.","evidence":[{"source_id":"CAIRO-I-358","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 358; Q3:52–54","exact_arabic":"وكانوا قصَّارين وصباغين","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-52-54","segment_index":1,"q":"3:52–54","source":"Cairo print · Volume I, pp. 357–359","segment_title":"The disciples’ confession and the attempt upon Jesus","anchor_paragraph":"ʿAṭāʾ relates that Mary handed Jesus over to learn various crafts, the last apprenticeship being with the disciples, who worked as cloth-finishers and dyers. When Jesus’ teacher was about to travel, he left him many garments of different colours to dye. Jesus heated a single vat, placed all the garments in it and bade them take the colours he wished. On the teacher’s return, the man feared that all had been ruined. Jesus took out yellow, red, green and other garments, each according to its intended colour. Amazed, the teacher knew that the act was from God, called people to him, and they believed and gave him support; hence they became disciples. [XIV-N019]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 358; Q3:52–54","revision_status":"","word_count":96,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-52-54","segment_index":1,"q":"3:52–54","source":"Cairo print · Volume I, pp. 357–359","segment_title":"[The disciples’ confession and the attempt upon Jesus]","anchor_paragraph":"ʿAṭāʾ relates that Mary handed Jesus over to learn various crafts, the last apprenticeship being with the disciples, who worked as cloth-finishers and dyers. When Jesus’ teacher was about to travel, he left him many garments of different colours to dye. Jesus heated a single vat, placed all the garments in it and bade them take the colours he wished. On the teacher’s return, the man feared that all had been ruined. Jesus took out yellow, red, green and other garments, each according to its intended colour. Amazed, the teacher knew that the act was from God, called people to him, and they believed and gave him support; hence they became disciples. [T076]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T076; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T076","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T076","original_body_sha256":"32a9f4aa767862ab43d192a576083efa0aae512d7a6d9fa943a992a4df57dd75","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":38,"print_label":"T38","linked_occurrences":[{"record_id":"q3-52-54","segment_index":1,"q":"3:52–54","source":"Cairo print · Volume I, pp. 357–359"}]},{"id":"XIV-N020","historical_note_id":"T077","title":"Why “planning” is predicated of God","content":"The argument distinguishes the opponents’ intention from the outcome of God’s allowing it to proceed. Al-Junayd’s reported answer calls that very allowance a divine makr; Ibn ʿAjība then explains the beneficial outcome as Jesus’ preservation and raising. The poetry supplies an analogy for judging an act in relation to its agent, and the “I say” explicitly marks Ibn ʿAjība’s subsequent explanation. The passage is consequently more specific than a general endorsement of deceit. Its earlier language of correspondence and requital (Cairo I:358) also explains why the same Arabic root is applied to the plotters and to God within Q3:54.","evidence":[{"source_id":"CAIRO-I-359","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 359; Q3:52–54","exact_arabic":"وتخليته تعالى إياهم مع المكر، تسبب عنه الرفع إلى السماء","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-52-54","segment_index":2,"q":"3:52–54","source":"Cairo print · Volume I, pp. 357–359","segment_title":"Why “planning” is predicated of God","anchor_paragraph":"His leaving them to their intrigue resulted in Jesus’ being raised to heaven and preserved alive until the last age, when he descends as the deputy of our Prophet, blessings and peace be upon him. This was an act of the highest perfection and wisdom, although only the people of gnosis ( أهل العرفان ) discern it. [XIV-N020]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 359; Q3:52–54","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-52-54","segment_index":2,"q":"3:52–54","source":"Cairo print · Volume I, pp. 357–359","segment_title":"[Why “planning” is predicated of God]","anchor_paragraph":"His leaving them to their intrigue resulted in Jesus’ being raised to heaven and preserved alive until the last age, when he descends as the deputy of our Prophet, blessings and peace be upon him. This was an act of the highest perfection and wisdom, although only the people of gnosis ( أهل العرفان ) discern it. [T077]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T077; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T077","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T077","original_body_sha256":"d2db5eddd1b8548f444229bad068fb78b04d28d627b9a9485660efbede326ba8","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":39,"print_label":"T39","linked_occurrences":[{"record_id":"q3-52-54","segment_index":2,"q":"3:52–54","source":"Cairo print · Volume I, pp. 357–359"}]},{"id":"XIV-N021","historical_note_id":"T078","title":"The meanings of tawaffī and the demonstrative","content":"Tawaffī can signify taking or receiving in full; its application to death or sleep depends on context. Ibn ʿAjība chooses explanations consistent with Jesus’ being raised alive. The assertion of consensus is his own: al-Ṭabarī explicitly records competing interpretations at Q3:55, including sleep, removal from the earth, and death, before preferring removal alive (Jāmiʿ al-bayān, VI:455–460). Recording those earlier interpretations does not authenticate each attributed report, but it prevents treating the history of exegesis as univocal. Q4:157’s denial of killing and crucifixion is the author’s cited argument; the lexical issue is discussed separately.","evidence":[{"source_id":"CAIRO-I-359","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 359; Q3:55–58","exact_arabic":"والإجماع على أنه لم يمت","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-tabari","title":"tabari","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0310Tabari/0310Tabari.JamicBayan/0310Tabari.JamicBayan.Shamela0000043-ara1","locator":"Jāmiʿ al-bayān VI:455–460, Q3:55; reports7133–7143 and ensuing preference","exact_arabic":"ثم اختلف أهل التأويل في معنى الوفاة ... وقال آخرون معنى ذلك إني متوفيك وفاة موت ... وأولى هذه الأقوال بالصحة عندنا ... إني قابضك من الأرض ورافعك إلي","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The source records actual exegetical disagreement and its own preference, qualifying a claim of unanimous interpretation.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"e5b4a303a1919072b06e6480e95133e7a54643d017ff13c68566ca8baf39cefd"}],"scope":[{"record_id":"q3-55-58","segment_index":0,"q":"3:55–58","source":"Cairo print · Volume I, pp. 359–361","segment_title":"The meanings of tawaffī and the demonstrative","anchor_paragraph":"I say: “When He said” ( إذ قال ) is governed by something understood: “remember”; or, “that took place when He said”; or it depends on “they plotted.” “I shall take you fully” ( مُتَوَفِّيكَ ) may mean “I shall raise you to Me complete and intact”: one says tawaffaytu or istawfaytu something when one receives it in full. Or it means “I shall cause you to die to the desires that impede ascent to the world of malakūt” ( عالم الملكوت ). Or it means “I shall cause you to sleep,” as indicated by “He it is who takes you [in sleep] by night” [6:60]. It is related that he was raised while sleeping. Ibn ʿAjība states a consensus that Jesus did not die, citing “They did not kill him or crucify him, but it was made to appear so to them” [4:157]. [XIV-N021]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 359; Q3:55–58; tabari: Jāmiʿ al-bayān VI:455–460, Q3:55; reports7133–7143 and ensuing preference","revision_status":"","word_count":96,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-55-58","segment_index":0,"q":"3:55–58","source":"Cairo print · Volume I, pp. 359–361","segment_title":"[The meanings of tawaffī and the demonstrative]","anchor_paragraph":"I say: “When He said” ( إذ قال ) is governed by something understood: “remember”; or, “that took place when He said”; or it depends on “they plotted.” “I shall take you fully” ( مُتَوَفِّيكَ ) may mean “I shall raise you to Me complete and intact”: one says tawaffaytu or istawfaytu something when one receives it in full. Or it means “I shall cause you to die to the desires that impede ascent to the world of malakūt” ( عالم الملكوت ). Or it means “I shall cause you to sleep,” as indicated by “He it is who takes you [in sleep] by night” [6:60]. It is related that he was raised while sleeping. Ibn ʿAjība states a consensus that Jesus did not die, citing “They did not kill him or crucify him, but it was made to appear so to them” [4:157]. [T078]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T078; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T078","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T078","original_body_sha256":"b27c2dfe273bdb7407b3cf4ed77b4af4977ce8916046541601d4eaced617f96d","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":40,"print_label":"T40","linked_occurrences":[{"record_id":"q3-55-58","segment_index":0,"q":"3:55–58","source":"Cairo print · Volume I, pp. 359–361"}]},{"id":"R07-14","content":"Cairo I:360 · The author’s historical horizon. Ibn ʿAjība’s statement is explicitly limited by “up to our time,” meaning his own time of writing. Ruslān adds a separate footnote about political developments in his own age. These are two historically situated claims, not one timeless theological judgment or an independently verified general history.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:360; Ruslān’s editorial footnote.","revision_status":"","print_number":41,"print_label":"T41","linked_occurrences":[{"record_id":"q3-55-58","segment_index":0,"q":"3:55–58","source":"Cairo print · Volume I, pp. 359–361"}]},{"id":"XIV-N022","historical_note_id":"T079","title":"The raising, judgment and recompense","content":"“Down to our own time” refers to the author’s time of writing. It is part of his historical generalization about the fulfilment of Q3:55, not a statement addressed to the present reader’s date. The preceding alternatives also need to remain visible: one account includes Christians and Muslims among Jesus’ followers, while another identifies the followers as the people of Islam. Ibn ʿAjība then defines true following through acceptance of Jesus’ prophethood and reads “above” in terms of argument and power. This historically situated polemic does not provide independent proof of the entire political generalization.","evidence":[{"source_id":"CAIRO-I-360","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 360; Q3:55–58","exact_arabic":"ولم يتفق لهم ملك ولا دولة إلى زمننا هذا","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-55-58","segment_index":1,"q":"3:55–58","source":"Cairo print · Volume I, pp. 359–361","segment_title":"The raising, judgment and recompense","anchor_paragraph":"The Real, exalted is His majesty, says: “Remember when God said” to Jesus, as He intended to raise him: “Jesus, I shall take you fully”—receive you to Myself, body and all, without diminution—“and raise you to Me,” to the place of My honour and the abode of My angels, “and purify you of those who disbelieve,” freeing you from companionship polluted by their unbelief. “I shall set those who follow you,” who believe in your prophethood, Christians and Muslims; though Qatāda, al-Shaʿbī and al-Rabīʿ say it means the Muslims. End of report. By God, whoever claims Jesus as Lord has not truly followed him. Those who really follow his religion are placed “above those who disbelieve” in him, the Jews, “until the Day of Resurrection,” overcoming them in argument and by the sword. He adds: This matter has been realised concerning them, for the Jews have not raised a standard, nor possessed kingship or a state, down to our own time. [XIV-N022]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 360; Q3:55–58","revision_status":"","word_count":100,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-55-58","segment_index":1,"q":"3:55–58","source":"Cairo print · Volume I, pp. 359–361","segment_title":"[The raising, judgment and recompense]","anchor_paragraph":"The Real, exalted is His majesty, says: “Remember when God said” to Jesus, as He intended to raise him: “Jesus, I shall take you fully”—receive you to Myself, body and all, without diminution—“and raise you to Me,” to the place of My honour and the abode of My angels, “and purify you of those who disbelieve,” freeing you from companionship polluted by their unbelief. “I shall set those who follow you,” who believe in your prophethood, Christians and Muslims; though Qatāda, al-Shaʿbī and al-Rabīʿ say it means the Muslims. End of report. By God, whoever claims Jesus as Lord has not truly followed him. Those who really follow his religion are placed “above those who disbelieve” in him, the Jews, “until the Day of Resurrection,” overcoming them in argument and by the sword. He adds: This matter has been realised concerning them, for the Jews have not raised a standard, nor possessed kingship or a state, down to our own time. [T079]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T079; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T079","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T079","original_body_sha256":"f399b6dc17f66ebdb4f87a3441d43d87cc0b9520ced183e65d114c18ea820d77","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":42,"print_label":"T42","linked_occurrences":[{"record_id":"q3-55-58","segment_index":1,"q":"3:55–58","source":"Cairo print · Volume I, pp. 359–361"}]},{"id":"XIV-N023","historical_note_id":"T080","title":"Ascending beyond desires and enduring through transmission","content":"The allusion moves from spatial ascent and migration to a change in attachment. The “homeland” left behind is explicitly the domain of personal appetites, self-interest, and habitual dependence; the ascent concerns the spirit and innermost secret. Malakūt and jabarūt function as technical terms in this spiritual account, rather than simply denoting geographical heavens. The continuing honour of disciples and descendants belongs to the author’s account of spiritual transmission. His prophetic attribution of “Emigrate, and you will gain honour for your children” is a separate reported saying; the inward interpretation does not establish its chain or turn the promise into a demonstrated rule of family history.","evidence":[{"source_id":"CAIRO-I-360","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 360; Q3:55–58","exact_arabic":"فمن هاجر وطن الحظوظ والشهوات، والركون إلى العوائد والمألوفات","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-55-58","segment_index":2,"q":"3:55–58","source":"Cairo print · Volume I, pp. 359–361","segment_title":"Ascending beyond desires and enduring through transmission","anchor_paragraph":"Whoever purifies the innermost secret ( السرّ ) of turbidity, sanctifies the spirit from the impurity of otherness ( الأغيار ), and lifts his aspiration beyond this abode, God causes his spirit to ascend to the heaven of malakūt and elevates his secret to the witnessing of the splendour of jabarūt ( مشاهدة سنا الجبروت ). His renown remains alive after death, and those attached to him enjoy care, reverence, dignity and honour. The Prophet is reported to have said: “Emigrate, and you will gain honour for your children.” Whoever leaves the homeland of personal portions and passions ( الحظوظ والشهوات ) and reliance upon habits and familiar comforts ascends in spirit to the heaven of holiness and the abode of intimacy; there he obtains honour that does not perish, extending to his offspring and associates until God inherits the earth and its inhabitants—He is the best of inheritors. [XIV-N023]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 360; Q3:55–58","revision_status":"","word_count":105,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-55-58","segment_index":2,"q":"3:55–58","source":"Cairo print · Volume I, pp. 359–361","segment_title":"Spiritual allusion — الإشارة Ascending beyond desires and enduring through transmission","anchor_paragraph":"Whoever purifies the innermost secret ( السرّ ) of turbidity, sanctifies the spirit from the impurity of otherness ( الأغيار ), and lifts his aspiration beyond this abode, God causes his spirit to ascend to the heaven of malakūt and elevates his secret to the witnessing of the splendour of jabarūt ( مشاهدة سنا الجبروت ). His renown remains alive after death, and those attached to him enjoy care, reverence, dignity and honour. The Prophet is reported to have said: “Emigrate, and you will gain honour for your children.” Whoever leaves the homeland of personal portions and passions ( الحظوظ والشهوات ) and reliance upon habits and familiar comforts ascends in spirit to the heaven of holiness and the abode of intimacy; there he obtains honour that does not perish, extending to his offspring and associates until God inherits the earth and its inhabitants—He is the best of inheritors. [T080]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T080; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T080","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T080","original_body_sha256":"7fddaac90a3cdcf8e4a51054cc637f58a875faa3e118643544658bec8677436a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":43,"print_label":"T43","linked_occurrences":[{"record_id":"q3-55-58","segment_index":2,"q":"3:55–58","source":"Cairo print · Volume I, pp. 359–361"}]},{"id":"XIV-N024","historical_note_id":"T081","title":"Adam without parents and Jesus without a father","content":"The comparison is an argument about divine creative power. On the author’s account, Adam’s creation without either parent is more unusual than Jesus’ birth without a father; unusual birth therefore supplies no sufficient ground for elevating Jesus beyond created servanthood. “Likeness” renders mathal in the sense of a comparable case or condition, rather than bodily resemblance between the two figures. The dialogue with the Najrān delegation is introduced as the occasion of revelation and expands the argument narratively. Q3:59 itself supplies the comparison and creative command; it does not contain the delegation’s questions or the quoted exchange.","evidence":[{"source_id":"CAIRO-I-361","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 361; Q3:59–60","exact_arabic":"فشأنه أغرب من شأن عيسى، لأنه وجد من غير أب ولا أم","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-59-60","segment_index":0,"q":"3:59–60","source":"Cairo print · Volume I, pp. 361–362","segment_title":"Adam without parents and Jesus without a father","anchor_paragraph":"As the occasion of revelation it is related that the delegation from Najrān said to the Prophet, “Why do you insult our master by calling him a servant?” He replied: “Yes, he is God’s servant and His Messenger, His Word cast to Mary, the Virgin.” They grew angry and asked: “Have you ever seen a human being without a father? If you speak truth, show us another.” Then the verse was revealed: “The likeness of Jesus with God is as the likeness of Adam.” Adam is more remarkable, having come to be with no parental intermediary whatever. [XIV-N024]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 361; Q3:59–60","revision_status":"","word_count":97,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-59-60","segment_index":0,"q":"3:59–60","source":"Cairo print · Volume I, pp. 361–362","segment_title":"[Adam without parents and Jesus without a father]","anchor_paragraph":"As the occasion of revelation it is related that the delegation from Najrān said to the Prophet, “Why do you insult our master by calling him a servant?” He replied: “Yes, he is God’s servant and His Messenger, His Word cast to Mary, the Virgin.” They grew angry and asked: “Have you ever seen a human being without a father? If you speak truth, show us another.” Then the verse was revealed: “The likeness of Jesus with God is as the likeness of Adam.” Adam is more remarkable, having come to be with no parental intermediary whatever. [T081]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T081; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T081","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T081","original_body_sha256":"e3556e8354445649e65b55bf98aafba863742284e79004deeb51a201a560fab2","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":44,"print_label":"T44","linked_occurrences":[{"record_id":"q3-59-60","segment_index":0,"q":"3:59–60","source":"Cairo print · Volume I, pp. 361–362"}]},{"id":"XIV-N025","historical_note_id":"T082","title":"Adam without parents and Jesus without a father","content":"This extended account combines material with separate textual witnesses. Abū Dāwūd (no. 4324) includes the bodily description, the Dajjāl, forty years, death and funeral prayer. Muslim (no. 1252) gives the pilgrimage through al-Rawḥāʾ; al-Ṭabarī (VI:459, report 7145) includes peace among animals. Al-Thaʿlabī (III:82) places marriage, offspring and burial in the Prophet’s chamber in a separate version attributed to Kaʿb, giving twenty-four years, after an Abū Hurayra narrative giving forty. Cairo combines these details under one prophetic quotation. The preceding ages of Mary and Jesus belong to another reporting frame. These parallels locate components and expose the composite structure; they do not authenticate the assembled narrative.","evidence":[{"source_id":"CAIRO-I-362","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 362; Q3:59–60","exact_arabic":"ويلبث في الأرض أربعين سنة، ثم يتزوج ويولد له ثم يتوفى","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-abu_dawud","title":"abu_dawud","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0275AbuDawudSijistani/0275AbuDawudSijistani.Sunan/0275AbuDawudSijistani.Sunan.Shamela0001726-ara1","locator":"Sunan Abī Dāwūd, no.4324, Kitāb al-Malāḥim","exact_arabic":"فيمكث في الأرض أربعين سنة ثم يتوفى فيصلي عليه المسلمون","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The actual complete numbered report was read; it does not state marriage, offspring, or the burial chamber.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"f153a439d58e7fbeded321cd6ba9cba3b5402c5d3b3286ca3dde9b620d6feef6"},{"source_id":"XIV-OT-muslim","title":"muslim","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0261Muslim/0261Muslim.Sahih/0261Muslim.Sahih.Shamela0001727-ara1.mARkdown","locator":"Ṣaḥīḥ Muslim, no.1252, Kitāb al-Ḥajj","exact_arabic":"ليهلن ابن مريم بفج الروحاء حاجا أو معتمرا أو ليثنينهما","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"Separate pilgrimage report, not the entire composite.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"8126f063f53504b68d6e9e133cec049c10acf498c501f5f4897013efc1e56d9e"},{"source_id":"XIV-OT-tabari","title":"tabari","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0310Tabari/0310Tabari.JamicBayan/0310Tabari.JamicBayan.Shamela0000043-ara1","locator":"Jāmiʿ al-bayān VI:459, report7145, on Q3:55; PageV06P459","exact_arabic":"وتقع في الأرض الأمنة حتى ترتع الأسود مع الإبل والنمر مع البقر والذئاب مع الغنم ... فيثبت في الأرض أربعين سنة ثم يتوفى","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"A wider earlier narrative parallel including the animals, but not all Cairo additions; no grading inferred from occurrence.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"e5b4a303a1919072b06e6480e95133e7a54643d017ff13c68566ca8baf39cefd"},{"source_id":"XIV-OT-thalabi","title":"al-Thaʿlabī, al-Kashf wa-l-bayān","locator":"III:82, on Q3:55; PageV03P082","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0427AbuIshaqThaclabi/0427AbuIshaqThaclabi.KashfWaBayan/0427AbuIshaqThaclabi.KashfWaBayan.Shamela0023578-ara1.mARkdown","exact_arabic":"وفي رواية كعب: أربعا وعشرين سنة، ثم يتزوج ويولد، ثم يتوفى ويصلي المسلمون عليه ويدفنونه في حجرة النبي","inspection":"Complete electronic page read directly by the researcher and primary editor, including the preceding Abū Hurayra report and the distinct Kaʿb introduction.","finding":"The three added details occur in a separately attributed version with a different duration.","limits":"Textual location and distinction of speakers; no authentication or Baḥr manuscript reading inferred."}],"scope":[{"record_id":"q3-59-60","segment_index":0,"q":"3:59–60","source":"Cairo print · Volume I, pp. 361–362","segment_title":"Adam without parents and Jesus without a father","anchor_paragraph":"It is related that Mary conceived Jesus when she was thirteen; God revealed to him when he reached thirty, and raised him from Jerusalem on the Night of Power when he was thirty-three; his mother lived six years after his being raised. A lengthy report attributed to the Prophet says: “I am the closest of people to Jesus son of Mary, for no prophet came between him and me. He will descend among my community and act as my deputy in it. When you see him, recognize him: he is a man of medium stature, reddish and white in complexion, with straight hair, as though water dripped from it even when it was not wet. He will break the cross and kill the pig, and wealth will become abundant. He will pass through al-Rawḥāʾ as a pilgrim or performer of ʿumra, perhaps combining both. He will fight people for Islam, until God brings all other religions to an end in his time and destroys in his time the false Messiah, the lying Dajjāl. Peace will spread upon the earth, so lions will graze with camels, leopards with cattle and wolves with sheep, and children will play with snakes. He will remain on earth forty years; then he will marry, have offspring and die, and the Muslims will pray over him.” The narration adds that they will bury him in the Prophet’s chamber. [Translator’s note: Such statements belong to the transmitted report, and individual details require their own authentication.] [XIV-N025]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 362; Q3:59–60; abu_dawud: Sunan Abī Dāwūd, no.4324, Kitāb al-Malāḥim; muslim: Ṣaḥīḥ Muslim, no.1252, Kitāb al-Ḥajj; tabari: Jāmiʿ al-bayān VI:459, report7145, on Q3:55; PageV06P459; al-Thaʿlabī, al-Kashf wa-l-bayān: III:82, on Q3:55; PageV03P082","revision_status":"","word_count":105,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-59-60","segment_index":0,"q":"3:59–60","source":"Cairo print · Volume I, pp. 361–362","segment_title":"[Adam without parents and Jesus without a father]","anchor_paragraph":"It is related that Mary conceived Jesus when she was thirteen; God revealed to him when he reached thirty, and raised him from Jerusalem on the Night of Power when he was thirty-three; his mother lived six years after his being raised. A lengthy report attributed to the Prophet says: “I am the closest of people to Jesus son of Mary, for no prophet came between him and me. He will descend among my community and act as my deputy in it. When you see him, recognize him: he is a man of medium stature, reddish and white in complexion, with straight hair, as though water dripped from it even when it was not wet. He will break the cross and kill the pig, and wealth will become abundant. He will pass through al-Rawḥāʾ as a pilgrim or performer of ʿumra, perhaps combining both. He will fight people for Islam, until God brings all other religions to an end in his time and destroys in his time the false Messiah, the lying Dajjāl. Peace will spread upon the earth, so lions will graze with camels, leopards with cattle and wolves with sheep, and children will play with snakes. He will remain on earth forty years; then he will marry, have offspring and die, and the Muslims will pray over him.” The narration adds that they will bury him in the Prophet’s chamber. [Translator’s note: Such statements belong to the transmitted report, and individual details require their own authentication.] [T082]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T082; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T082","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T082","original_body_sha256":"75434d1c05917428b8548971116a7adc75deee8fe62477d60b24fb7499c5bf5a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":45,"print_label":"T45","linked_occurrences":[{"record_id":"q3-59-60","segment_index":0,"q":"3:59–60","source":"Cairo print · Volume I, pp. 361–362"}]},{"id":"XIV-N026","historical_note_id":"T083","title":"Spirit and clay in the human being","content":"Lāhūtī and nāsūtī supply the last pair in a series of opposed attributes: divine-oriented and human, spiritual and bodily, inward and sensible. Their force should be read through the movement of the whole paragraph. The human being contains both tendencies; the decisive question is which governs aspiration. The following sentences define ascent through obedience and remembrance, and descent through absorption in appetite. Thus “divine spirit” belongs to the author’s spiritual anthropology, while the spirit remains directed towards its Master. His explanation of Jesus’ exceptional spiritual disposition likewise develops the virgin-birth narrative through this scheme, rather than presenting an independent physiological demonstration.","evidence":[{"source_id":"CAIRO-I-362","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 362; Q3:59–60","exact_arabic":"أودع فيه الروح نورانية لاهوتية في نطفة ناسوتية","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-59-60","segment_index":1,"q":"3:59–60","source":"Cairo print · Volume I, pp. 361–362","segment_title":"Spirit and clay in the human being","anchor_paragraph":"Know that the Real, exalted is His majesty, manifested this human being in a wondrous form and with an extraordinary mystery. He joined two opposites in him and entrusted to him the mystery of two worlds: luminous and dark, spiritual and bodily, heavenly and earthly, of malakūt and of mulk, intelligible and sensible. Into a human ( ناسوتية ) drop He placed a luminous, divine ( لاهوتية ) spirit. Thus a conflict arose between the opposites: the spirit yearns for its divine home, while the clay-formed drop yearns for its human home. [XIV-N026]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 362; Q3:59–60","revision_status":"","word_count":101,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-59-60","segment_index":1,"q":"3:59–60","source":"Cairo print · Volume I, pp. 361–362","segment_title":"Spiritual allusion — الإشارة Spirit and clay in the human being","anchor_paragraph":"Know that the Real, exalted is His majesty, manifested this human being in a wondrous form and with an extraordinary mystery. He joined two opposites in him and entrusted to him the mystery of two worlds: luminous and dark, spiritual and bodily, heavenly and earthly, of malakūt and of mulk, intelligible and sensible. Into a human ( ناسوتية ) drop He placed a luminous, divine ( لاهوتية ) spirit. Thus a conflict arose between the opposites: the spirit yearns for its divine home, while the clay-formed drop yearns for its human home. [T083]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T083; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T083","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T083","original_body_sha256":"3138545af94a02ddd185c9f1a9d2cbfa2d97f9e49c685cc85394ee57a3fc235d","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":46,"print_label":"T46","linked_occurrences":[{"record_id":"q3-59-60","segment_index":1,"q":"3:59–60","source":"Cairo print · Volume I, pp. 361–362"}]},{"id":"XIV-N027","historical_note_id":"T084","title":"Najrān and the challenge of mubāhala","content":"“Is subject to passing away” preserves the prospective or general force of yaʾtī ʿalayhi al-fanāʾ. It does not say that Jesus had already died, which would conflict with the interpretation the author adopted at Q3:55. The reported questions also echo the sūrah’s opening divine attributes: living and sustaining (Q3:2), knowledge from which nothing is hidden (3:5), and forming creatures in the womb (3:6). This explains the narrative’s final reference to revelation of the opening portion. The dialogue and its chronology are an exegetical report; the correspondences with those verses establish its argumentative design, not an independent record of the exchange.","evidence":[{"source_id":"CAIRO-I-363","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 363; Q3:61–63","exact_arabic":"وأن عيسى يأتي عليه الفناء","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-61-63","segment_index":1,"q":"3:61–63","source":"Cairo print · Volume I, pp. 362–364","segment_title":"Najrān and the challenge of mubāhala","anchor_paragraph":"The Prophet then asked whether a child does not resemble its father; whether God is living and never dies, while Jesus is subject to passing away; whether God sustains, protects and provides for all things, while Jesus cannot exercise such sovereignty; and whether nothing in earth or heaven escapes God’s knowledge, whereas Jesus knows only what he has been taught. They acknowledged each point. He continued: “God formed Jesus in the womb as He willed. God neither eats, drinks nor expels waste. Was Jesus not borne by his mother, delivered as other children are, fed and nourished, and himself subject to eating, drinking and the needs of the body?” When they assented, he asked how Jesus could be as they claimed. They fell silent. The narrative says that the opening of this sūrah was then revealed down to the present passage. [XIV-N027]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 363; Q3:61–63","revision_status":"","word_count":100,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-61-63","segment_index":1,"q":"3:61–63","source":"Cairo print · Volume I, pp. 362–364","segment_title":"[Najrān and the challenge of mubāhala]","anchor_paragraph":"The Prophet then asked whether a child does not resemble its father; whether God is living and never dies, while Jesus is subject to passing away; whether God sustains, protects and provides for all things, while Jesus cannot exercise such sovereignty; and whether nothing in earth or heaven escapes God’s knowledge, whereas Jesus knows only what he has been taught. They acknowledged each point. He continued: “God formed Jesus in the womb as He willed. God neither eats, drinks nor expels waste. Was Jesus not borne by his mother, delivered as other children are, fed and nourished, and himself subject to eating, drinking and the needs of the body?” When they assented, he asked how Jesus could be as they claimed. They fell silent. The narrative says that the opening of this sūrah was then revealed down to the present passage. [T084]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T084; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T084","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T084","original_body_sha256":"1c29e62070710907522de72d4187dd8e0c197615a6808f10474df0fe5817ed62","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":47,"print_label":"T47","linked_occurrences":[{"record_id":"q3-61-63","segment_index":1,"q":"3:61–63","source":"Cairo print · Volume I, pp. 362–364"}]},{"id":"XIV-N028","historical_note_id":"T085","title":"Najrān and the challenge of mubāhala","content":"Separate sources attest different parts of this narrative. Muslim’s report no. 2404 names ʿAlī, Fāṭima, al-Ḥasan, and al-Ḥusayn in connection with Q3:61, without supplying the whole negotiation. Abū Dāwūd’s no. 3041 reports the two thousand garments divided between Ṣafar and Rajab, but describes armour and other equipment as a guaranteed loan to be returned. This differs from Cairo’s compressed settlement. Neither parallel contains the entire preceding conversation and subsequent threatened transformations. The family’s participation, treaty terms, and warning therefore retain separate evidential scopes even though Ibn ʿAjība presents a continuous account.","evidence":[{"source_id":"CAIRO-I-363","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 363; Q3:61–63","exact_arabic":"في كل عام ألفَيْ حلة ألفاً في صَفَر، ألفا في رجب، وثلاثين درعاً من حديد","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-muslim","title":"muslim","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0261Muslim/0261Muslim.Sahih/0261Muslim.Sahih.Shamela0001727-ara1.mARkdown","locator":"Ṣaḥīḥ Muslim, no.2404, virtues of ʿAlī","exact_arabic":"دعا رسول الله صلى الله عليه وسلم عليا وفاطمة وحسنا وحسينا فقال اللهم هؤلاء أهلي","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The family’s participation is explicitly connected with Q3:61; broader treaty narrative absent.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"8126f063f53504b68d6e9e133cec049c10acf498c501f5f4897013efc1e56d9e"},{"source_id":"XIV-OT-abu_dawud","title":"abu_dawud","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0275AbuDawudSijistani/0275AbuDawudSijistani.Sunan/0275AbuDawudSijistani.Sunan.Shamela0001726-ara1","locator":"Sunan Abī Dāwūd, no.3041, Kitāb al-Kharāj","exact_arabic":"صالح رسول الله صلى الله عليه وسلم أهل نجران على ألفي حلة النصف في صفر والبقية في رجب ... والمسلمون ضامنون لها حتى يردوها عليهم","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The equipment is supplied on terms requiring its return; compare, rather than harmonize, the compressed Cairo formulation.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"f153a439d58e7fbeded321cd6ba9cba3b5402c5d3b3286ca3dde9b620d6feef6"}],"scope":[{"record_id":"q3-61-63","segment_index":1,"q":"3:61–63","source":"Cairo print · Volume I, pp. 362–364","segment_title":"Najrān and the challenge of mubāhala","anchor_paragraph":"The Prophet invited them again to enter Islam and receive the rights and responsibilities of Muslims. When they refused, he said that he would oppose them. They answered that they could not wage war against the Arabs, but sought terms by which he would not attack them or compel them to leave their religion. The reported settlement required two thousand garments each year, one thousand in Ṣafar and one thousand in Rajab, together with thirty iron coats of mail. The narrative adds the Prophet’s warning that, had they undertaken mubāhala , they would have been transformed into monkeys and pigs, their valley consumed in fire, Najrān and its people uprooted, and no year would have elapsed before all the Christians perished. [Translator’s note: All these details are presented as reports in the source, not as independent archival proof of the encounter or treaty.] [XIV-N028]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 363; Q3:61–63; muslim: Ṣaḥīḥ Muslim, no.2404, virtues of ʿAlī; abu_dawud: Sunan Abī Dāwūd, no.3041, Kitāb al-Kharāj","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-61-63","segment_index":1,"q":"3:61–63","source":"Cairo print · Volume I, pp. 362–364","segment_title":"[Najrān and the challenge of mubāhala]","anchor_paragraph":"The Prophet invited them again to enter Islam and receive the rights and responsibilities of Muslims. When they refused, he said that he would oppose them. They answered that they could not wage war against the Arabs, but sought terms by which he would not attack them or compel them to leave their religion. The reported settlement required two thousand garments each year, one thousand in Ṣafar and one thousand in Rajab, together with thirty iron coats of mail. The narrative adds the Prophet’s warning that, had they undertaken mubāhala , they would have been transformed into monkeys and pigs, their valley consumed in fire, Najrān and its people uprooted, and no year would have elapsed before all the Christians perished. [Translator’s note: All these details are presented as reports in the source, not as independent archival proof of the encounter or treaty.] [T085]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T085; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T085","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T085","original_body_sha256":"59afb025fc142e5c86853fbf18e4276be65bc79af68680a39498157c2e0f5d6c","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":48,"print_label":"T48","linked_occurrences":[{"record_id":"q3-61-63","segment_index":1,"q":"3:61–63","source":"Cairo print · Volume I, pp. 362–364"}]},{"id":"XIV-N029","historical_note_id":"T086","title":"Loyalty to one’s shaykh and the trial of denial","content":"Qultu, “I say,” introduces a first-person anecdote from Ibn ʿAjība. The claim that the scholars of Fez agreed is spoken by his unnamed visitor; the text neither lists those scholars nor presents their statements. Ibn ʿAjība’s answer then uses a deliberately comprehensive hypothetical—everyone in the seven heavens and earths—to express the force of his personal certainty. “Particular spiritual distinction” translates khuṣūṣiyya, the realization he claims to have witnessed in his shaykh. The exchange illustrates the author’s application of steadfastness to the relationship with a guide; it is not an independently documented institutional judgment or consensus.","evidence":[{"source_id":"CAIRO-I-364","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 364; Q3:61–63","exact_arabic":"قلت: وقد جاءني بعض من ينتسب إلى العلم من أهل فاس","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-61-63","segment_index":2,"q":"3:61–63","source":"Cairo print · Volume I, pp. 362–364","segment_title":"Loyalty to one’s shaykh and the trial of denial","anchor_paragraph":"I say: Someone associated with learning in Fez came to me and said, “The scholars of Fez have agreed that your shaykh is an innovator.” I replied: “If all the inhabitants of the seven heavens and the seven earths agreed that he was an innovator, I would still say he belonged to the Sunna. For I have realized his particular spiritual distinction as clearly as the sun in the sky, unobscured by any cloud.” May God grant us excellent comportment ( حسن الأدب ) towards them and reverence until the Day of Judgment. Amen. Whoever of the deniers turns away from God’s friends: “God knows the corrupters.” [XIV-N029]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 364; Q3:61–63","revision_status":"","word_count":97,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-61-63","segment_index":2,"q":"3:61–63","source":"Cairo print · Volume I, pp. 362–364","segment_title":"Spiritual allusion — الإشارة Loyalty to one’s shaykh and the trial of denial","anchor_paragraph":"I say: Someone associated with learning in Fez came to me and said, “The scholars of Fez have agreed that your shaykh is an innovator.” I replied: “If all the inhabitants of the seven heavens and the seven earths agreed that he was an innovator, I would still say he belonged to the Sunna. For I have realized his particular spiritual distinction as clearly as the sun in the sky, unobscured by any cloud.” May God grant us excellent comportment ( حسن الأدب ) towards them and reverence until the Day of Judgment. Amen. Whoever of the deniers turns away from God’s friends: “God knows the corrupters.” [T086]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T086; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T086","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T086","original_body_sha256":"e4709698f2db5a7a676d203c1f722a0224e35120db0d00d75132d5c49305a4ed","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":49,"print_label":"T49","linked_occurrences":[{"record_id":"q3-61-63","segment_index":2,"q":"3:61–63","source":"Cairo print · Volume I, pp. 362–364"}]},{"id":"XIV-N030","historical_note_id":"T087","title":"Worship, religious authority and the call to a common word","content":"The report is an interpretation of Q9:31 brought into the explanation of Q3:64. Its concern is accepting religious leaders’ unauthorized declarations of what is lawful and unlawful; “worship” here is explained through that obedience. Al-Tirmidhī transmits the substance from ʿAdī ibn Ḥātim (no. 3095), with different dialogue wording. He also calls this transmission gharīb and remarks that Ghuṭayf ibn Aʿyan is not well known in hadith. Those are the collector’s own qualifications, not a modern grading inferred from a verbal match. The parallel supports identification of the cited report while retaining a concrete transmission question.","evidence":[{"source_id":"CAIRO-I-364","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 364; Q3:64","exact_arabic":"قال عدي بن حاتم: ما كُنَّا نعبدهم يا رسول الله","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-tirmidhi","title":"tirmidhi","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0279Tirmidhi/0279Tirmidhi.Sunan/0279Tirmidhi.Sunan.Shamela0001435-ara1","locator":"Jāmiʿ al-Tirmidhī, no.3095, V:278; PageV05P278","exact_arabic":"إذا أحلوا لهم شيئا استحلوه وإذا حرموا عليهم شيئا حرموه ... هذا حديث غريب ... وغطيف بن أعين ليس بمعروف في الحديث","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The report and al-Tirmidhī’s express qualification were both read.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"965e8032d319ca639eebeac0f213a154acb379e3faaf49fd9a46b1f9289ec6e2"}],"scope":[{"record_id":"q3-64","segment_index":1,"q":"3:64","source":"Cairo print · Volume I, pp. 364–365","segment_title":"Worship, religious authority and the call to a common word","anchor_paragraph":"When the words of God Most High, “They have taken their rabbis and monks as lords apart from God” [9:31], were revealed, ʿAdī ibn Ḥātim said: “We did not worship them, Messenger of God.” He replied: “Did they not declare things lawful and unlawful for you, and you accepted what they said?” He answered: “Yes.” He said: “That is it.” [XIV-N030]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 364; Q3:64; tirmidhi: Jāmiʿ al-Tirmidhī, no.3095, V:278; PageV05P278","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-64","segment_index":1,"q":"3:64","source":"Cairo print · Volume I, pp. 364–365","segment_title":"[Worship, religious authority and the call to a common word]","anchor_paragraph":"When the words of God Most High, “They have taken their rabbis and monks as lords apart from God” [9:31], were revealed, ʿAdī ibn Ḥātim said: “We did not worship them, Messenger of God.” He replied: “Did they not declare things lawful and unlawful for you, and you accepted what they said?” He answered: “Yes.” He said: “That is it.” [T087]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T087; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T087","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T087","original_body_sha256":"0def810386f0d2c44d0e3621b97b70424789f33b93836fd0a235475ca9339664","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":50,"print_label":"T50","linked_occurrences":[{"record_id":"q3-64","segment_index":1,"q":"3:64","source":"Cairo print · Volume I, pp. 364–365"}]},{"id":"XIV-N031","historical_note_id":"T088","title":"Passage explanation","content":"This paragraph is a bridge into Q3:65–68: its concluding “God revealed” introduces the verses that follow. The dispute concerns who can claim Abraham as a religious predecessor. Ḥanīf and muslim here anticipate the explanation at Cairo I:366: turning from false beliefs and yielding to God. The author then expressly distinguishes that primordial submission from membership in a later historical religious community. Reading the transitional speech with its sequel prevents anachronistically assigning Abraham every later communal designation or treating the narrated dispute as part of the Qurʾānic wording.","evidence":[{"source_id":"CAIRO-I-365","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 365; Q3:64","exact_arabic":"بل كان إبراهيم حنيفاً مسلماً، وأنا على دينه","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-64","segment_index":4,"q":"3:64","source":"Cairo print · Volume I, pp. 364–365","segment_title":"","anchor_paragraph":"When the delegation from Najrān came to Medina, they met the Jews and disputed about Abraham, peace be upon him. The Prophet, blessings and peace be upon him, came to them. They said: “Muḥammad, we have disagreed about Abraham and his religion.” The Christians said he was Christian; the Jews said he was Jewish, and that they had the closest claim to him. The Prophet said: “Both parties are disassociated from Abraham. Rather, Abraham was a ḥanīf, one submitting to God, and I follow his religion. Follow, then, his religion: submission to God.” So God revealed: [XIV-N031]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 365; Q3:64","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-64","segment_index":4,"q":"3:64","source":"Cairo print · Volume I, pp. 364–365","segment_title":"[Transitional explanation]","anchor_paragraph":"When the delegation from Najrān came to Medina, they met the Jews and disputed about Abraham, peace be upon him. The Prophet, blessings and peace be upon him, came to them. They said: “Muḥammad, we have disagreed about Abraham and his religion.” The Christians said he was Christian; the Jews said he was Jewish, and that they had the closest claim to him. The Prophet said: “Both parties are disassociated from Abraham. Rather, Abraham was a ḥanīf, one submitting to God, and I follow his religion. Follow, then, his religion: submission to God.” So God revealed: [T088]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T088; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T088","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T088","original_body_sha256":"6daa40d62be06b92af8ee8b407507700e195c3284dd5f1116a4cc807ce6035b3","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":51,"print_label":"T51","linked_occurrences":[{"record_id":"q3-64","segment_index":4,"q":"3:64","source":"Cairo print · Volume I, pp. 364–365"}]},{"id":"XIV-N032","historical_note_id":"T089","title":"Abraham precedes the later communal designations","content":"The argument of Q3:65 rests on relative order: the Torah and Gospel came after Abraham, so later communal labels cannot simply be projected backwards onto him. Ibn ʿAjība expands that order with intervals of a thousand and two thousand years. These numbers are the commentator’s chronological assertions; they are not given by the verse. The logic of the passage does not depend on verifying those exact intervals. The numerical chronology and the more limited Qurʾānic premise have distinct scopes; the commentary’s chronology is not an independently established historical calculation.","evidence":[{"source_id":"CAIRO-I-366","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 366; Q3:65–68","exact_arabic":"ودينكم إنما حدث بعد إبراهيم بألف سنة","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-65-68","segment_index":1,"q":"3:65–68","source":"Cairo print · Volume I, pp. 365–367","segment_title":"Abraham precedes the later communal designations","anchor_paragraph":"The Real, exalted is His majesty, says: “O People of the Book, why do you dispute about Abraham,” each party claiming that he followed its religion, “when the Torah and the Gospel were sent down only after him?” How could he have been Jewish, when your religion arose only a thousand years after Abraham? How could he have been Christian, when Christianity appeared only two thousand years after Abraham? “Will you not reason,” instead of asserting what is impossible? [XIV-N032]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 366; Q3:65–68","revision_status":"","word_count":91,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-65-68","segment_index":1,"q":"3:65–68","source":"Cairo print · Volume I, pp. 365–367","segment_title":"[Abraham precedes the later communal designations]","anchor_paragraph":"The Real, exalted is His majesty, says: “O People of the Book, why do you dispute about Abraham,” each party claiming that he followed its religion, “when the Torah and the Gospel were sent down only after him?” How could he have been Jewish, when your religion arose only a thousand years after Abraham? How could he have been Christian, when Christianity appeared only two thousand years after Abraham? “Will you not reason,” instead of asserting what is impossible? [T089]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T089; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T089","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T089","original_body_sha256":"3d302619f8d771709e2ed9cecaa879425e73e2036f372ec2f4a47174a1d34492","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":52,"print_label":"T52","linked_occurrences":[{"record_id":"q3-65-68","segment_index":1,"q":"3:65–68","source":"Cairo print · Volume I, pp. 365–367"}]},{"id":"XIV-N033","historical_note_id":"T090","title":"Abraham precedes the later communal designations","content":"The author deliberately distinguishes two uses of Islam: submission to God and the historically later religious community with its particular ordinances. If muslim in Q3:67 meant membership in that later community in the same chronological sense as “Jew” or “Christian,” his preceding objection would apply to it as well. “The same objection” therefore refers to anachronism, not to denying Abraham’s submission to God. The next sentence calls Abraham the imam of those who affirm divine unity, while Q3:68 locates closeness to him in following his way. Keeping this distinction makes the otherwise surprising qualification intelligible.","evidence":[{"source_id":"CAIRO-I-366","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 366; Q3:65–68","exact_arabic":"وليس المراد أنه كان على ملة الإسلام، وإلا لكان مشترك الإلزام","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-65-68","segment_index":1,"q":"3:65–68","source":"Cairo print · Volume I, pp. 365–367","segment_title":"Abraham precedes the later communal designations","anchor_paragraph":"He then expressly declares both parties’ claims false: “Abraham was neither a Jew nor a Christian, but a ḥanīf,” turning away from false beliefs, “one submitting to God,” obedient to his Lord’s ordinances. It does not mean that he belonged to the [later] religious community of Islam ( ملّة الإسلام ); otherwise the same objection would apply, since the religion of Islam also came later. Abraham was the imam of those who affirm the One. “He was not one of those who associate partners with Him,” as do the Jews, Christians and polytheists. This indirectly rebukes them and refutes their claim to follow his religious way. [XIV-N033]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 366; Q3:65–68","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-65-68","segment_index":1,"q":"3:65–68","source":"Cairo print · Volume I, pp. 365–367","segment_title":"[Abraham precedes the later communal designations]","anchor_paragraph":"He then expressly declares both parties’ claims false: “Abraham was neither a Jew nor a Christian, but a ḥanīf,” turning away from false beliefs, “one submitting to God,” obedient to his Lord’s ordinances. It does not mean that he belonged to the [later] religious community of Islam ( ملّة الإسلام ); otherwise the same objection would apply, since the religion of Islam also came later. Abraham was the imam of those who affirm the One. “He was not one of those who associate partners with Him,” as do the Jews, Christians and polytheists. This indirectly rebukes them and refutes their claim to follow his religious way. [T090]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T090; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T090","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T090","original_body_sha256":"4be07743d24abbeab811c2bd3918155890bf5a74e0dc882ef1972ad478758339","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":53,"print_label":"T53","linked_occurrences":[{"record_id":"q3-65-68","segment_index":1,"q":"3:65–68","source":"Cairo print · Volume I, pp. 365–367"}]},{"id":"XIV-N034","historical_note_id":"T091","title":"The stratagem of professing belief and then withdrawing","content":"“At the beginning of the day” renders wajh al-nahār, literally the day’s face or front. The story explains a temporary outward profession followed by withdrawal intended to unsettle other believers. The number twelve, the identification with Khaybar, and the proposed appeal to learned authorities belong to the report attributed to al-Ḥasan and al-Suddī. Q3:72 itself identifies a group among the People of the Book without those particulars. The ensuing account about changing prayer direction is introduced separately by “it is said”; it is an alternative explanation of the stratagem, not an additional step established within the first report.","evidence":[{"source_id":"CAIRO-I-368","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 368; Q3:72","exact_arabic":"قال الحسن والسدي: تواطأ اثنا عشر رجلاً من يهود خيبر","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-72","segment_index":0,"q":"3:72","source":"Cairo print · Volume I, pp. 367–368","segment_title":"The stratagem of professing belief and then withdrawing","anchor_paragraph":"Al-Ḥasan and al-Suddī said: twelve men among the Jews of Khaybar—that is, their rabbis—conspired together, saying to one another: “Enter Muḥammad’s religion at the beginning of the day in speech, not in conviction; reject it at the end. Say: ‘We examined our books and consulted our learned men, and found that Muḥammad is not the one described; his falsehood became clear to us.’ We shall do this only to make his companions doubt.” End of the quotation. [XIV-N034]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 368; Q3:72","revision_status":"","word_count":98,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-72","segment_index":0,"q":"3:72","source":"Cairo print · Volume I, pp. 367–368","segment_title":"[The stratagem of professing belief and then withdrawing]","anchor_paragraph":"Al-Ḥasan and al-Suddī said: twelve men among the Jews of Khaybar—that is, their rabbis—conspired together, saying to one another: “Enter Muḥammad’s religion at the beginning of the day in speech, not in conviction; reject it at the end. Say: ‘We examined our books and consulted our learned men, and found that Muḥammad is not the one described; his falsehood became clear to us.’ We shall do this only to make his companions doubt.” End of the quotation. [T091]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T091; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T091","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T091","original_body_sha256":"7bef0ec17606cebc883f39699d5aa18c5a119f07d63dc63b129352be6adfa349","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":54,"print_label":"T54","linked_occurrences":[{"record_id":"q3-72","segment_index":0,"q":"3:72","source":"Cairo print · Volume I, pp. 367–368"}]},{"id":"XIV-N035","historical_note_id":"T092","title":"Entering the path without a settled commitment","content":"Al-Bukhārī transmits the warning about following predecessors, including the image of entering a lizard’s hole and the question about Jews and Christians (Ṣaḥīḥ, no. 3456). Ibn ʿAjība applies that general warning specifically to entering and abandoning a path of spiritual training. The application belongs to his allusive commentary; the hadith does not itself name Sufi disciples or guides. The preceding list also distinguishes motives: inability to bear the discipline, tentative experimentation, and deliberate manipulation. Preserving those alternatives prevents making every departure equivalent to the consciously deceptive scheme described in the verse.","evidence":[{"source_id":"CAIRO-I-368","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 368; Q3:72","exact_arabic":"لتَسْلُكن سَنَنَ مَنْ قَبْلكم","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-bukhari","title":"bukhari","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","locator":"Ṣaḥīḥ al-Bukhārī, no.3456","exact_arabic":"لتتبعن سنن من قبلكم شبرا بشبر وذراعا بذراع حتى لو سلكوا جحر ضب لسلكتموه","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"General warning directly read; the application to spiritual training is Ibn ʿAjība’s own.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"16f95173b9ea1927b577ff85dc7e2a8351b8287e4ea9863782c4c5fc87ac8132"}],"scope":[{"record_id":"q3-72","segment_index":1,"q":"3:72","source":"Cairo print · Volume I, pp. 367–368","segment_title":"Entering the path without a settled commitment","anchor_paragraph":"You see many people enter the path of the Folk ( طريق القوم ), only to find its burdens heavy and leave it: either because they lack the strength to bear them, or because they entered merely to test it, with a precarious commitment, or as a stratagem against others. When one of them withdraws, people say: “Had it been sound, so-and-so would not have left it.” They then deter people from entering it and persevering in it. This is an Israelite tendency: “Believe at the beginning of the day and reject it at its end, so that they may turn back.” The Prophet, blessings and peace be upon him, said: “You will follow the ways of those before you, span for span and cubit for cubit, until, were they to enter a lizard’s hole, you would enter it.” They asked: “The Jews and Christians?” He said: “Yes; who else, then?” Success comes through God. [XIV-N035]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 368; Q3:72; bukhari: Ṣaḥīḥ al-Bukhārī, no.3456","revision_status":"","word_count":91,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-72","segment_index":1,"q":"3:72","source":"Cairo print · Volume I, pp. 367–368","segment_title":"Spiritual allusion — الإشارة Entering the path without a settled commitment","anchor_paragraph":"You see many people enter the path of the Folk ( طريق القوم ), only to find its burdens heavy and leave it: either because they lack the strength to bear them, or because they entered merely to test it, with a precarious commitment, or as a stratagem against others. When one of them withdraws, people say: “Had it been sound, so-and-so would not have left it.” They then deter people from entering it and persevering in it. This is an Israelite tendency: “Believe at the beginning of the day and reject it at its end, so that they may turn back.” The Prophet, blessings and peace be upon him, said: “You will follow the ways of those before you, span for span and cubit for cubit, until, were they to enter a lizard’s hole, you would enter it.” They asked: “The Jews and Christians?” He said: “Yes; who else, then?” Success comes through God. [T092]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T092; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T092","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T092","original_body_sha256":"beba9f93211a04b4e873c93ea7bd2639814c22968ffbca3eeee39565dcdd8cc4","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":55,"print_label":"T55","linked_occurrences":[{"record_id":"q3-72","segment_index":1,"q":"3:72","source":"Cairo print · Volume I, pp. 367–368"}]},{"id":"XIV-N036","historical_note_id":"T093","title":"The disputed construction of an yuʾtā and the parenthetical reply","content":"This is the second of two syntactic reconstructions, not an extra sentence in the verse. In the first, “that anyone is given” supplies the content of “believe,” while God’s instruction to say that guidance belongs to Him interrupts the reported speech. In the second, the same infinitival phrase expresses a motive, with an understood act of devising or speaking: did they act from dislike of another receiving such favour? Taqdīr labels the explanatory wording supplied by the grammarian. Its clauses and changes of speaker must therefore remain distinguishable from the continuous Qurʾānic text of Q3:73.","evidence":[{"source_id":"CAIRO-I-368","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 368; Q3:73–74","exact_arabic":"ويحتمل أن يكون قوله: (أن يؤتى) مفعولاً لأجله، والعامل فيه محذوف","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-73-74","segment_index":0,"q":"3:73–74","source":"Cairo print · Volume I, pp. 368–370","segment_title":"The disputed construction of an yuʾtā and the parenthetical reply","anchor_paragraph":"Alternatively, “that anyone is given” is an expression of purpose or cause ( مفعول لأجله ), governed by an omitted expression ( عامل محذوف ). The reconstructed sense is: did you devise what you devised because you disliked anyone being given what you were given, and feared that they might dispute with you before your Lord? [XIV-N036]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 368; Q3:73–74","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-73-74","segment_index":0,"q":"3:73–74","source":"Cairo print · Volume I, pp. 368–370","segment_title":"[The disputed construction of an yuʾtā and the parenthetical reply]","anchor_paragraph":"Alternatively, “that anyone is given” is an expression of purpose or cause ( مفعول لأجله ), governed by an omitted expression ( عامل محذوف ). The reconstructed sense is: did you devise what you devised because you disliked anyone being given what you were given, and feared that they might dispute with you before your Lord? [T093]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T093; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T093","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T093","original_body_sha256":"e3627433e8b10d70d56c0d48a07c97b6852ee9b21e7f361f0f253618ba207ca7","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":56,"print_label":"T56","linked_occurrences":[{"record_id":"q3-73-74","segment_index":0,"q":"3:73–74","source":"Cairo print · Volume I, pp. 368–370"}]},{"id":"XIV-N037","historical_note_id":"T094","title":"Preparation, confidentiality and the danger of disclosure without realization","content":"The danger described concerns communicating realized experience to someone who receives only its verbal formulation. The preceding prose contrasts possessing khuṣūṣiyya with taking it merely “as knowledge,” then warns of doctrinal misunderstanding or accusations under the Law. The verse about al-Ḥallāj is introduced anonymously as poetry; mentioning him within it does not attribute the poem to him. Its language of guarding the Reality and being slain by a spear dramatizes the risk of disclosure. The following anonymous couplet makes the warning still sharper. These are poetic and disciplinary applications, not a hadith or a separately reasoned legal ruling on punishment.","evidence":[{"source_id":"CAIRO-I-369","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 369; Q3:73–74","exact_arabic":"ومن شَهِدَ الحَقِيقَةَ فَلْيَصُنْهَا","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-73-74","segment_index":2,"q":"3:73–74","source":"Cairo print · Volume I, pp. 368–370","segment_title":"Preparation, confidentiality and the danger of disclosure without realization","anchor_paragraph":"Whoever has witnessed the Reality, let him guard it, or he will be slain by the spear; like the Ḥallāj of love, when there appeared to him the sun of Reality through drawing near. [XIV-N037]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 369; Q3:73–74","revision_status":"","word_count":100,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-73-74","segment_index":2,"q":"3:73–74","source":"Cairo print · Volume I, pp. 368–370","segment_title":"Spiritual allusion — الإشارة Preparation, confidentiality and the danger of disclosure without realization","anchor_paragraph":"Whoever has witnessed the Reality, let him guard it, or he will be slain by the spear; like the Ḥallāj of love, when there appeared to him the sun of Reality through drawing near. [T094]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T094; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T094","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T094","original_body_sha256":"f472f6727ed38b3d1b6752153ed4bec0fd91d631bd3525db15d022a7958e6149","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":57,"print_label":"T57","linked_occurrences":[{"record_id":"q3-73-74","segment_index":2,"q":"3:73–74","source":"Cairo print · Volume I, pp. 368–370"}]},{"id":"XIV-N038","historical_note_id":"T095","title":"An entrusted deposit remains another person’s right","content":"The qinṭār and dinar form a rhetorical contrast between a large deposit and a small one. The author makes the extension explicit: a qinṭār “or more,” a dinar “or less.” The question is therefore reliability with entrusted property, not a precise exchange rate or fixed threshold for honesty. His grammatical note treats the preposition bi- with “entrust” as having the sense of ʿalā; the English idiom is “entrust someone with” the property. The named deposit stories and the promised heavenly reward are additional reports. The verse’s contrast itself concerns returning what belongs to another and the need for persistent demand when it is withheld.","evidence":[{"source_id":"CAIRO-I-370","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 370; Q3:75–76","exact_arabic":"إِنْ تَأْمَنْهُ على قنطار من المال أو أكثر أداه إليك","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-75-76","segment_index":1,"q":"3:75–76","source":"Cairo print · Volume I, pp. 370–371","segment_title":"An entrusted deposit remains another person’s right","anchor_paragraph":"The Real, exalted is His majesty, says: “Among the People of the Book” are those who have submitted and believed, becoming people of faith. If you entrust such a person with “a great sum” of money, or more, he returns it to you without betraying any part of it. A hadith states: “Whoever is entrusted with a trust and returns it, although he could have withheld it, God will marry him to as many of the wide-eyed maidens as he wishes.” Among them are also those who remain in their religion, people of treachery and loss: entrust such a person with “a single dinar,” or less, and “he will not return it to you unless you keep standing over him,” insistently demanding it. [XIV-N038]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 370; Q3:75–76","revision_status":"","word_count":104,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-75-76","segment_index":1,"q":"3:75–76","source":"Cairo print · Volume I, pp. 370–371","segment_title":"[An entrusted deposit remains another person’s right]","anchor_paragraph":"The Real, exalted is His majesty, says: “Among the People of the Book” are those who have submitted and believed, becoming people of faith. If you entrust such a person with “a great sum” of money, or more, he returns it to you without betraying any part of it. A hadith states: “Whoever is entrusted with a trust and returns it, although he could have withheld it, God will marry him to as many of the wide-eyed maidens as he wishes.” Among them are also those who remain in their religion, people of treachery and loss: entrust such a person with “a single dinar,” or less, and “he will not return it to you unless you keep standing over him,” insistently demanding it. [T095]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T095; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T095","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T095","original_body_sha256":"0a01a6b2b0b40ab24c213ef2f6f0e14beeaa48752df4e97f2a61b8db74169c5d","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":58,"print_label":"T58","linked_occurrences":[{"record_id":"q3-75-76","segment_index":1,"q":"3:75–76","source":"Cairo print · Volume I, pp. 370–371"}]},{"id":"XIV-N039","historical_note_id":"T096","title":"Realization does not cancel the Law or people’s rights","content":"The polemic turns the verse’s accusation against members of the author’s own spiritual milieu. Claiming realization of the Reality cannot abolish another person’s property rights or the duty to return what was entrusted. The two transactions are distinguished: an ordinary deposit and qirāḍ, the provision of capital for a commercial venture. The objection concerns betrayal in either setting. The later excuse about ordinary people’s possessions deliberately echoes the reported claim of exemption concerning the “unlettered” in Q3:75. Thus the passage makes fidelity to the Law a test of claimed spiritual attainment, rather than treating attainment as an exemption from accountability.","evidence":[{"source_id":"CAIRO-I-371","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 371; Q3:75–76","exact_arabic":"قد رأينا بعض الفقراء دخل بلد الحقيقة فسقطت من قلبه هيبة الشريعة","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-75-76","segment_index":2,"q":"3:75–76","source":"Cairo print · Volume I, pp. 370–371","segment_title":"Realization does not cancel the Law or people’s rights","anchor_paragraph":"We have seen some of the spiritually poor enter the land of Reality ( الحقيقة ), whereupon reverence for the religious Law ( الشريعة ) falls away from their hearts. They become careless with people’s property, and the inviolability of God’s servants loses its hold upon them, until you cannot trust them to protect either property or family. Deposit something with such a person, or entrust him with capital in a profit-sharing investment ( قِراض ), and he will not return it unless you keep standing over him. This is heresy ( زندقة ), an Israelite tendency that even the lowest of people would not accept—how much less someone claiming to be the highest! [XIV-N039]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 371; Q3:75–76","revision_status":"","word_count":100,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-75-76","segment_index":2,"q":"3:75–76","source":"Cairo print · Volume I, pp. 370–371","segment_title":"Spiritual allusion — الإشارة Realization does not cancel the Law or people’s rights","anchor_paragraph":"We have seen some of the spiritually poor enter the land of Reality ( الحقيقة ), whereupon reverence for the religious Law ( الشريعة ) falls away from their hearts. They become careless with people’s property, and the inviolability of God’s servants loses its hold upon them, until you cannot trust them to protect either property or family. Deposit something with such a person, or entrust him with capital in a profit-sharing investment ( قِراض ), and he will not return it unless you keep standing over him. This is heresy ( زندقة ), an Israelite tendency that even the lowest of people would not accept—how much less someone claiming to be the highest! [T096]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T096; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T096","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T096","original_body_sha256":"f20fb79af35548f8f1361b245b8fe4b9fe5a8e5163de4dcae63d7079e6db10f4","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":59,"print_label":"T59","linked_occurrences":[{"record_id":"q3-75-76","segment_index":2,"q":"3:75–76","source":"Cairo print · Volume I, pp. 370–371"}]},{"id":"XIV-N040","historical_note_id":"T097","title":"The paltry price of concealing a binding trust","content":"These are separate reports of an occasion for applying or revealing Q3:77. Al-Bukhārī records both the trader’s false claim about an offered price (no. 4551) and al-Ashʿath’s dispute over property, in which the opponent could be required to swear (no. 2666). Each report explicitly associates the verse with dishonest acquisition through an oath. Their juxtaposition here does not establish that the episodes happened together or that they are one narrative. The surrounding account of concealment by religious leaders is another application. Across them, the author’s common concern is exchanging a binding obligation for worldly gain.","evidence":[{"source_id":"CAIRO-I-372","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 372; Q3:77","exact_arabic":"وقيل: نزلت في رجل أقام سلعته في السوق","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-bukhari","title":"bukhari","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","locator":"Ṣaḥīḥ al-Bukhārī, no.4551","exact_arabic":"أن رجلا أقام سلعة في السوق فحلف فيها لقد أعطى بها ما لم يعطه ... فنزلت إن الذين يشترون بعهد الله وأيمانهم ثمنا قليلا","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The market episode explicitly cites Q3:77.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"16f95173b9ea1927b577ff85dc7e2a8351b8287e4ea9863782c4c5fc87ac8132"},{"source_id":"XIV-OT-bukhari","title":"bukhari","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","locator":"Ṣaḥīḥ al-Bukhārī, no.2666","exact_arabic":"قال فقال الأشعث بن قيس في والله كان ذلك ... كان بيني وبين رجل من اليهود أرض فجحدني","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"Separate al-Ashʿath property dispute; the subsequent report also cites Q3:77.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"16f95173b9ea1927b577ff85dc7e2a8351b8287e4ea9863782c4c5fc87ac8132"}],"scope":[{"record_id":"q3-77","segment_index":0,"q":"3:77","source":"Cairo print · Volume I, pp. 371–372","segment_title":"The paltry price of concealing a binding trust","anchor_paragraph":"Another account says it was revealed concerning a man who displayed his merchandise in the market and swore that he had been offered such-and-such a price for it. Another says it concerned al-Ashʿath ibn Qays, who had a dispute with a man upon whom the oath then devolved; the man intended to swear it. And God Most High knows best. [XIV-N040]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 372; Q3:77; bukhari: Ṣaḥīḥ al-Bukhārī, no.4551; bukhari: Ṣaḥīḥ al-Bukhārī, no.2666","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-77","segment_index":0,"q":"3:77","source":"Cairo print · Volume I, pp. 371–372","segment_title":"[The paltry price of concealing a binding trust]","anchor_paragraph":"Another account says it was revealed concerning a man who displayed his merchandise in the market and swore that he had been offered such-and-such a price for it. Another says it concerned al-Ashʿath ibn Qays, who had a dispute with a man upon whom the oath then devolved; the man intended to swear it. And God Most High knows best. [T097]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T097; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T097","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T097","original_body_sha256":"8351432a008fc85b25c48f5350d0e24c4b326f53d9f0029d54e28d523ffc1bd5","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":60,"print_label":"T60","linked_occurrences":[{"record_id":"q3-77","segment_index":0,"q":"3:77","source":"Cairo print · Volume I, pp. 371–372"}]},{"id":"XIV-N041","historical_note_id":"T098","title":"Worldly gain behind scholarly and spiritual appearances","content":"Al-mashhūr denotes the established predominant position within the juristic tradition under discussion; it is not simply whatever opinion happens to be socially popular. The author qualifies the conduct he condemns by its motive: a worldly benefit received in return. He pairs it with judging by desire and depending on unsound opinions. The allusion then applies the same discrepancy between speech and inward truth to spiritual pretenders who display wisdom without living it. The parallel with “twisting their tongues” in Q3:78 therefore concerns knowingly presenting a self-serving distortion as divine teaching, rather than supplying a general survey of legitimate legal disagreement.","evidence":[{"source_id":"CAIRO-I-373","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 373; Q3:78","exact_arabic":"الذين يفتون بغير المشهور، لحظ يأخذونه من الدنيا","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-78","segment_index":1,"q":"3:78","source":"Cairo print · Volume I, pp. 372–373","segment_title":"Worldly gain behind scholarly and spiritual appearances","anchor_paragraph":"This verse extends to corrupt scholars who issue rulings contrary to the established predominant position ( المشهور ) for a worldly portion they receive, and to unjust judges who judge by desire and rely on unsound opinions, saying, “It is from God,” although it is not from God. [XIV-N041]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 373; Q3:78","revision_status":"","word_count":100,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-78","segment_index":1,"q":"3:78","source":"Cairo print · Volume I, pp. 372–373","segment_title":"Spiritual allusion — الإشارة Worldly gain behind scholarly and spiritual appearances","anchor_paragraph":"This verse extends to corrupt scholars who issue rulings contrary to the established predominant position ( المشهور ) for a worldly portion they receive, and to unjust judges who judge by desire and rely on unsound opinions, saying, “It is from God,” although it is not from God. [T098]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T098; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T098","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T098","original_body_sha256":"48ce8d8197450d8f7cf1d01671bd4ca318738554e80a48488dbde1b19a3a43ef","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":61,"print_label":"T61","linked_occurrences":[{"record_id":"q3-78","segment_index":1,"q":"3:78","source":"Cairo print · Volume I, pp. 372–373"}]},{"id":"XIV-N042","historical_note_id":"T099","title":"Bashar, rabbānī and the readings of “he commands you”","content":"The explanation makes a rabbānī a formative teacher, beginning with knowledge suited to the learner before proceeding to more demanding matters. A close wording appears in al-Bukhārī’s Book of Knowledge, in the introductory comments before no. 68. There Ibn ʿAbbās is named for “forbearing, learned in the Law,” while the pedagogical definition follows “it is said.” That witness therefore confirms the saying’s circulation without independently confirming Ibn ʿAjība’s precise attribution of the latter wording to Ibn ʿAbbās. The subsequent comparison with liḥyānī and raqabānī concerns word formation and intensification; it does not add further moral characteristics to the teacher.","evidence":[{"source_id":"CAIRO-I-373","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 373; Q3:79–80","exact_arabic":"وقال ابن عباس: (هو الذي يُربي الناس بصغار العلم قبل كباره)","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-bukhari","title":"bukhari","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","locator":"Ṣaḥīḥ al-Bukhārī, Kitāb al-ʿIlm, introductory comments before no.68","exact_arabic":"وقال ابن عباس كونوا ربانيين حلماء فقهاء ويقال الرباني الذي يربي الناس بصغار العلم قبل كباره","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The attribution boundary was read: the pedagogical definition follows an anonymous “it is said.”","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"16f95173b9ea1927b577ff85dc7e2a8351b8287e4ea9863782c4c5fc87ac8132"}],"scope":[{"record_id":"q3-79-80","segment_index":0,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374","segment_title":"Bashar, rabbānī and the readings of “he commands you”","anchor_paragraph":"I say: bashar ( البشر ) is a collective expression ( اسم جمع ) with no singular form of its own; it is applied to a group and to an individual. A rabbānī is someone who nurtures people, trains their conduct and refines them through knowledge and action. Ibn ʿAbbās said: “He is one who nurtures people through the elementary matters of knowledge before its major ones.” The nūn in it conveys intensification, as in liḥyānī and raqabānī. [XIV-N042]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 373; Q3:79–80; bukhari: Ṣaḥīḥ al-Bukhārī, Kitāb al-ʿIlm, introductory comments before no.68","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-79-80","segment_index":0,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374","segment_title":"[Bashar, rabbānī and the readings of “he commands you”]","anchor_paragraph":"I say: bashar ( البشر ) is a collective expression ( اسم جمع ) with no singular form of its own; it is applied to a group and to an individual. A rabbānī is someone who nurtures people, trains their conduct and refines them through knowledge and action. Ibn ʿAbbās said: “He is one who nurtures people through the elementary matters of knowledge before its major ones.” The nūn in it conveys intensification, as in liḥyānī and raqabānī. [T099]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T099; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T099","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T099","original_body_sha256":"bdb6981e86d021593e09ed7aa822be600df4a6010faee28eddb6b00ce33e7022","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":62,"print_label":"T62","linked_occurrences":[{"record_id":"q3-79-80","segment_index":0,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374"}]},{"id":"XIV-N043","historical_note_id":"T100","title":"Teaching that directs worship to God rather than the teacher","content":"The alternatives “what you know” and “what you teach” reflect the difference between taʿlamūn and tuʿallimūn, not two unrelated descriptions of rabbānīs. Al-Bayḍāwī explicitly records both readings at Q3:79 (Anwār, II:25) and connects study and teaching with knowledge of truth and right action. Ibn ʿAjība develops that account through spiritual aspiration and state as well as acquired instruction. The opening prohibition determines their purpose: the recipient of scripture directs people towards God’s service. The reported obituary of Ibn ʿAbbās then uses rabbānī as a title of praise within this educational and devotional sense.","evidence":[{"source_id":"CAIRO-I-373","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 373; Q3:79–80","exact_arabic":"أو بِما كُنْتُمْ تُعَلِّمُونَ الناس من الخير بكتاب الله","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-baydawi","title":"baydawi","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0685NasirDinBaydawi/0685NasirDinBaydawi.AnwarTanzil/0685NasirDinBaydawi.AnwarTanzil.Shamela0023588-ara1","locator":"Anwār al-tanzīl II:25, Q3:79; PageV02P025","exact_arabic":"بسبب كونكم معلمين الكتاب ... وقرأ ابن كثير ونافع وأبو عمرو ويعقوب تعلمون بمعنى عالمين","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"Actual reading distinction between teaching and knowing, within a discussion of study and practice.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"6bc14b72dc468030f939690ce4307a3a9e617d866198b2b9d19857fba684def6"}],"scope":[{"record_id":"q3-79-80","segment_index":1,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374","segment_title":"Teaching that directs worship to God rather than the teacher","anchor_paragraph":"The Real, exalted is His majesty, says: it would not be fitting for “a human being to whom God gives scripture, judgment”—adjudication between His servants—“and prophethood”—revelation of ordinances—“then to say to people: ‘Be servants of me apart from God,’” or alongside God, or to consent to being worshipped apart from God. Rather, he tells them: “Be God-centred teachers ( ربّانيين )”: knowers of God, discerning in His religion and forbearing towards people, nurturing them through knowledge, action, spiritual aspiration ( الهمّة ) and spiritual state ( الحال ), by virtue of what you know of God’s scripture and what you study of it; or by virtue of the good you teach people through God’s scripture and what you rehearse to them. When Ibn ʿAbbās, God be pleased with him and his father, died, Muḥammad ibn al-Ḥanafiyya said: “The rabbānī of this community has died.” [XIV-N043]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 373; Q3:79–80; baydawi: Anwār al-tanzīl II:25, Q3:79; PageV02P025","revision_status":"","word_count":93,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-79-80","segment_index":1,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374","segment_title":"[Teaching that directs worship to God rather than the teacher]","anchor_paragraph":"The Real, exalted is His majesty, says: it would not be fitting for “a human being to whom God gives scripture, judgment”—adjudication between His servants—“and prophethood”—revelation of ordinances—“then to say to people: ‘Be servants of me apart from God,’” or alongside God, or to consent to being worshipped apart from God. Rather, he tells them: “Be God-centred teachers ( ربّانيين )”: knowers of God, discerning in His religion and forbearing towards people, nurturing them through knowledge, action, spiritual aspiration ( الهمّة ) and spiritual state ( الحال ), by virtue of what you know of God’s scripture and what you study of it; or by virtue of the good you teach people through God’s scripture and what you rehearse to them. When Ibn ʿAbbās, God be pleased with him and his father, died, Muḥammad ibn al-Ḥanafiyya said: “The rabbānī of this community has died.” [T100]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T100; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T100","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T100","original_body_sha256":"71c4adf441f386cc7622215c812bebd89ecfe1da73efab105312e2fb46db0d1b","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":63,"print_label":"T63","linked_occurrences":[{"record_id":"q3-79-80","segment_index":1,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374"}]},{"id":"XIV-N044","historical_note_id":"T101","title":"Honouring the guide without making the intermediary the goal","content":"The gestures named here are kissing (taqbīl) and lowering the head; the preceding reported prohibition at Cairo I:373 concerns prostration (sujūd) before someone other than God. Kissing and lowering the head are therefore distinct in his vocabulary from prostration. His defence of the disciples’ gestures rests on their intended effect within training: diminishing self-importance and preparing an opening. The short verse then expresses that effect through the “slaughter” of the lower selves and clarification of cups. It is figurative language for discipline and receptivity. The passage presents Ibn ʿAjība’s spiritual rationale; it does not supply a comparative discussion of juristic rulings on these practices.","evidence":[{"source_id":"CAIRO-I-374","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 374; Q3:79–80","exact_arabic":"حتى يُقبِّلون أرجلهم والترابَ بين أيديهم","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-79-80","segment_index":2,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374","segment_title":"Honouring the guide without making the intermediary the goal","anchor_paragraph":"The spiritually poor have always venerated their shaykhs, going so far as to kiss their feet and the ground before them, and exerting themselves in their service. When the shaykhs see them doing so, they do not forbid them, because this is the disciples’ gain and a cause of their spiritual opening ( الفتح ). Of this someone has said: [XIV-N044]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 374; Q3:79–80","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-79-80","segment_index":2,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374","segment_title":"Spiritual allusion — الإشارة Honouring the guide without making the intermediary the goal","anchor_paragraph":"The spiritually poor have always venerated their shaykhs, going so far as to kiss their feet and the ground before them, and exerting themselves in their service. When the shaykhs see them doing so, they do not forbid them, because this is the disciples’ gain and a cause of their spiritual opening ( الفتح ). Of this someone has said: [T101]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T101; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T101","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T101","original_body_sha256":"cf595249ca583f99dbdbd10fc97eacc548bdc064d1a12c4924fc08e13284e7a7","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":64,"print_label":"T64","linked_occurrences":[{"record_id":"q3-79-80","segment_index":2,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374"}]},{"id":"XIV-N045","historical_note_id":"T102","title":"Honouring the guide without making the intermediary the goal","content":"“[God]” is the object indicated by the repeated statement that veneration is ultimately for God. The quoted instruction contrasts seeing only the teacher’s sensible appearance with recognizing what points through him to the divine. “Effacement from seeing” describes the disciple’s awareness; it does not describe the teacher’s bodily disappearance. The source says only “our shaykh” at this locus, without naming him. A nearby qualification is especially relevant: at Cairo I:377 Ibn ʿAjība permits heightened reverence only while it does not take the shaykh beyond human status or diminish the honour of other saints. That explicit boundary should accompany this passage’s interpretation.","evidence":[{"source_id":"CAIRO-I-374","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 374; Q3:79–80","exact_arabic":"ولكن اعرفوا فينا، وافنوا عن رؤية حسنا","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"CAIRO-I-377","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"I:377, allusion on Q3:84","exact_arabic":"ما لم يخرجه عن طَوْر البشر، وما لم يؤد ذلك إلى إسقاط حُرمة غيره من الأولياء","inspection":"The full adjacent Cairo paragraph was directly read in the retained transcription.","finding":"The author expressly limits reverence to human status and respect for other saints."}],"scope":[{"record_id":"q3-79-80","segment_index":2,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374","segment_title":"Honouring the guide without making the intermediary the goal","anchor_paragraph":"Yet the shaykhs guide them to the Presence ( الحضرة ), until they efface them from witnessing the intermediary ( الواسطة ). Their veneration and lowering of their heads are then for God, not another. At that point they become rabbānīs: knowers of God, brought near. Our shaykh used to say: “Do not visit me on the basis that I am your shaykh. Rather, recognize [God] in us and be effaced from seeing our sensible appearance, so that the veneration is for God, our Lord.” End of the quotation. [XIV-N045]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 374; Q3:79–80; Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: I:377, allusion on Q3:84","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-79-80","segment_index":2,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374","segment_title":"Spiritual allusion — الإشارة Honouring the guide without making the intermediary the goal","anchor_paragraph":"Yet the shaykhs guide them to the Presence ( الحضرة ), until they efface them from witnessing the intermediary ( الواسطة ). Their veneration and lowering of their heads are then for God, not another. At that point they become rabbānīs: knowers of God, brought near. Our shaykh used to say: “Do not visit me on the basis that I am your shaykh. Rather, recognize [God] in us and be effaced from seeing our sensible appearance, so that the veneration is for God, our Lord.” End of the quotation. [T102]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T102; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T102","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T102","original_body_sha256":"9cb9f84900ee8382cad49f8e95450a4e9f3b4a2dab92e8bb1d7c534472692ab6","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":65,"print_label":"T65","linked_occurrences":[{"record_id":"q3-79-80","segment_index":2,"q":"3:79–80","source":"Cairo print · Volume I, pp. 373–374"}]},{"id":"XIV-N046","historical_note_id":"T103","title":"Oath, condition and the binding covenant","content":"“Response” here is a grammatical term for the clause completing an oath or condition; it does not mean a spoken reply from the prophets. On the first analysis, the opening lām signals an oath already implicit in taking the covenant, while mā introduces a condition. The emphatic “you shall surely believe” completes the oath and also supplies the consequence required by that condition. The next analyses instead treat mā as relative, or read the initial lām with kasra to express a reason. These are alternative analyses of the same binding commitment, not successive additional covenants.","evidence":[{"source_id":"CAIRO-I-374","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 374; Q3:81–82","exact_arabic":"و (لتؤمنن) : جواب القسم، سد مسد الجواب","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-81-82","segment_index":0,"q":"3:81–82","source":"Cairo print · Volume I, pp. 374–375","segment_title":"Oath, condition and the binding covenant","anchor_paragraph":"I say: the lām in la-mā ( لما ) prepares for an oath ( موطئة للقسم ), since taking the covenant has the force of exacting an oath ( الاستحلاف ). Mā may be conditional ( شرطية ); “you shall surely believe” ( لتؤمنن ) is the response to the oath ( جواب القسم ), also taking the place of the response to the condition. Thus: whatever scripture and wisdom We give you, then a messenger of God comes to you, you shall surely believe in him. [XIV-N046]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 374; Q3:81–82","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-81-82","segment_index":0,"q":"3:81–82","source":"Cairo print · Volume I, pp. 374–375","segment_title":"[Oath, condition and the binding covenant]","anchor_paragraph":"I say: the lām in la-mā ( لما ) prepares for an oath ( موطئة للقسم ), since taking the covenant has the force of exacting an oath ( الاستحلاف ). Mā may be conditional ( شرطية ); “you shall surely believe” ( لتؤمنن ) is the response to the oath ( جواب القسم ), also taking the place of the response to the condition. Thus: whatever scripture and wisdom We give you, then a messenger of God comes to you, you shall surely believe in him. [T103]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T103; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T103","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T103","original_body_sha256":"e3e8727a373d1d8657bd9cf4b5672aa984f98ca960e95323e53f7fb694c0438f","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":66,"print_label":"T66","linked_occurrences":[{"record_id":"q3-81-82","segment_index":0,"q":"3:81–82","source":"Cairo print · Volume I, pp. 374–375"}]},{"id":"XIV-N047","historical_note_id":"T104","title":"The two forms of yielding and the physician of the heart","content":"The first-person divine saying is introduced as one of the transmitted āthār. It is not a further verse of Q3:83, and this formula alone does not identify a prophetic chain or establish a hadith grade. Within the argument, “leave the shelter of My heaven” is an impossible challenge: the preceding verse already places all beings within God’s dominion. Its function is to rebuke resistance to divine decree. The author distinguishes that inward disposition from outward fulfilment of commands, then describes the spiritual teacher as a physician of the heart. The medical language continues that moral analogy; it does not identify a bodily illness.","evidence":[{"source_id":"CAIRO-I-376","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 376; Q3:83","exact_arabic":"وفي بعض الآثار يقول الله تبارك وتعالى","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-83","segment_index":2,"q":"3:83","source":"Cairo print · Volume I, pp. 375–376","segment_title":"The two forms of yielding and the physician of the heart","anchor_paragraph":"Whoever falls short in outward obedience or inwardly resents the majestic decrees ( الأحكام الجلالية ) has fallen short of the perfection of religion. He is asked: do you seek a religion other than God’s, when whoever is in the heavens and earth has yielded to Him, willingly or unwillingly? Either yield willingly or return to Him unwillingly. In certain transmitted reports, God—blessed and exalted—says: “Whoever is not content with My decree and does not patiently bear My trial, let him leave the shelter of My heaven and take a lord other than Me.” [XIV-N047]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 376; Q3:83","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-83","segment_index":2,"q":"3:83","source":"Cairo print · Volume I, pp. 375–376","segment_title":"Spiritual allusion — الإشارة The two forms of yielding and the physician of the heart","anchor_paragraph":"Whoever falls short in outward obedience or inwardly resents the majestic decrees ( الأحكام الجلالية ) has fallen short of the perfection of religion. He is asked: do you seek a religion other than God’s, when whoever is in the heavens and earth has yielded to Him, willingly or unwillingly? Either yield willingly or return to Him unwillingly. In certain transmitted reports, God—blessed and exalted—says: “Whoever is not content with My decree and does not patiently bear My trial, let him leave the shelter of My heaven and take a lord other than Me.” [T104]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T104; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T104","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T104","original_body_sha256":"7c9ee3278e591010903857e8fb687b2f727c6d1f95d86c4ed766bf257a6365a6","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":67,"print_label":"T67","linked_occurrences":[{"record_id":"q3-83","segment_index":2,"q":"3:83","source":"Cairo print · Volume I, pp. 375–376"}]},{"id":"XIV-N048","historical_note_id":"T105","title":"The source of spiritual distinction and the possibility of returning","content":"“In this matter” restricts the lineage metaphor to the special path and its claimed transmission. The language of foundling and father concerns spiritual affiliation, as the earlier analogy of bodily and spiritual offspring also does (Cairo I:350–351). The author then specifies his standard for a guide: effacement followed by subsistence, attraction joined with wayfaring, and intoxication followed by sobriety and completion. The sequence matters; extraordinary gifts alone do not qualify someone to guide others. The final exception preserves the possibility of return through renewed companionship and conduct, rather than making the exclusion unconditional or irreversible.","evidence":[{"source_id":"CAIRO-I-378","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 378; Q3:89","exact_arabic":"فكل مَن لا شيخ له في هذا الشأن فهو لقيط، لا أب له","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-89","segment_index":1,"q":"3:89","source":"Cairo print · Volume I, pp. 378–378","segment_title":"The source of spiritual distinction and the possibility of returning","anchor_paragraph":"Whoever seeks special spiritual distinction ( الخصوصية ) from those who do not possess it, or claims it without receiving it from its source, will not have it accepted from him. Among the Folk he is one of the losers in the special path. Whoever has no shaykh in this matter is a foundling without a father, a pretender without a lineage. [XIV-N048]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 378; Q3:89","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-89","segment_index":1,"q":"3:89","source":"Cairo print · Volume I, pp. 378–378","segment_title":"Spiritual allusion — الإشارة The source of spiritual distinction and the possibility of returning","anchor_paragraph":"Whoever seeks special spiritual distinction ( الخصوصية ) from those who do not possess it, or claims it without receiving it from its source, will not have it accepted from him. Among the Folk he is one of the losers in the special path. Whoever has no shaykh in this matter is a foundling without a father, a pretender without a lineage. [T105]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T105; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T105","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T105","original_body_sha256":"fc9a3c00ff8d89732c5f7cd4b0e04d678406247f9591d6f399837af23ed13a9e","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":68,"print_label":"T68","linked_occurrences":[{"record_id":"q3-89","segment_index":1,"q":"3:89","source":"Cairo print · Volume I, pp. 378–378"}]},{"id":"XIV-N049","historical_note_id":"T106","title":"Several explanations of repentance that is not accepted","content":"The refusal of repentance in Q3:90 is explained through several alternatives: no effective repentance occurs, repentance is delayed until the death-rattle, or unbelief is still being maintained. These qualifications should remain distinct. Immediately before them, Q3:89 and the account of al-Ḥārith affirm acceptance after repentance and reform; the author also says that some of the remaining group later entered Islam and were accepted. The competing reports about Jews, Christians, or both concern how the verse’s stages of unbelief are identified. They do not erase that contextual distinction between actual return and persistence, nor establish one exclusive occasion of revelation.","evidence":[{"source_id":"CAIRO-I-379","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 379; Q3:90","exact_arabic":"أو لَنْ تُقْبَلَ تَوْبَتُهُمْ ما داموا على كفرهم","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."}],"scope":[{"record_id":"q3-90","segment_index":0,"q":"3:90","source":"Cairo print · Volume I, pp. 378–379","segment_title":"Several explanations of repentance that is not accepted","anchor_paragraph":"It is also said that it was revealed concerning the Jews: they disbelieved in Jesus after believing in their prophets, then increased in unbelief by disbelieving in Muḥammad, blessings and peace be upon him. Or concerning the Christians: they disbelieved in Muḥammad, blessings and peace be upon him, after believing in Jesus, then increased in unbelief by persisting in it. Or concerning both groups together: they disbelieved in our Prophet Muḥammad, blessings and peace be upon him, after believing in him before his appearance, then increased in unbelief by obstinately rejecting him and persisting in acts of disobedience. And God Most High knows best. [XIV-N049]","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 379; Q3:90","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-90","segment_index":0,"q":"3:90","source":"Cairo print · Volume I, pp. 378–379","segment_title":"[Several explanations of repentance that is not accepted]","anchor_paragraph":"It is also said that it was revealed concerning the Jews: they disbelieved in Jesus after believing in their prophets, then increased in unbelief by disbelieving in Muḥammad, blessings and peace be upon him. Or concerning the Christians: they disbelieved in Muḥammad, blessings and peace be upon him, after believing in Jesus, then increased in unbelief by persisting in it. Or concerning both groups together: they disbelieved in our Prophet Muḥammad, blessings and peace be upon him, after believing in him before his appearance, then increased in unbelief by obstinately rejecting him and persisting in acts of disobedience. And God Most High knows best. [T106]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T106; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T106","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T106","original_body_sha256":"8bd889c3a6f1998c87e5acfc643be8e4ffd1de34003af62c562ca3a688e46048","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":69,"print_label":"T69","linked_occurrences":[{"record_id":"q3-90","segment_index":0,"q":"3:90","source":"Cairo print · Volume I, pp. 378–379"}]},{"id":"XIV-N050","historical_note_id":"T107","title":"Returning before an acquired habit becomes entrenched","content":"The quoted al-Qushayrī passage is located in Laṭāʾif I:258 on Q3:91, although Ibn ʿAjība places it in the allusion on Q3:90. The glossator’s “perhaps” then proposes a connection with Abraham’s encounter with his father; it does not identify al-Qushayrī’s stated source. Al-Bukhārī’s report no. 3350 uses dhīkh multaṭṭikh, without the gloss “pig.” That gloss belongs to the quoted commentator, while the Cairo editor explains dhīkh as a male hyena (I:379,n.1). Accordingly, “the authentic report” refers to the Abraham narrative, and must not silently authenticate the animal gloss or the proposed explanation of al-Qushayrī’s imagery.","evidence":[{"source_id":"CAIRO-I-379","title":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999","locator":"Volume I, printed p. 379; Q3:90","exact_arabic":"وما ذكره ربما ينظر إلى قضية الخليل مع أبيه","local_file":"../revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment and corresponding retained Cairo Arabic passage read. This record does not assert a new manuscript collation."},{"source_id":"XIV-OT-qushayri_tafsir","title":"qushayri_tafsir","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0465IbnHawazinQushayri/0465IbnHawazinQushayri.LataifIsharat/0465IbnHawazinQushayri.LataifIsharat.Shamela0023629-ara1","locator":"Laṭāʾif al-ishārāt I:258, Q3:91; PageV01P258","exact_arabic":"فلا يحشر فى الآخرة مع أهل هذه القصة ولو تشفع له ألف عارف ... يلقى شبهه فى الآخرة على غيره","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The earlier passage’s precise Qurʾānic location and wording were read.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"afbcaeb1209d6436504cb78b70d0b6b8a036b9be499bcc69543436feb264cd8a"},{"source_id":"XIV-OT-bukhari","title":"bukhari","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","locator":"Ṣaḥīḥ al-Bukhārī, no.3350","exact_arabic":"فإذا هو بذيخ ملتطخ فيؤخذ بقوائمه فيلقى في النار","inspection":"Relevant primary-work passage and pagination/number read directly in the supplied public electronic corpus.","finding":"The Abraham report contains dhīkh but no “pig” gloss.","witness_type":"Electronic primary-work transcription; edition metadata retained; no manuscript claim","source_sha256":"16f95173b9ea1927b577ff85dc7e2a8351b8287e4ea9863782c4c5fc87ac8132"},{"source_id":"MID-379-1","title":"Cairo editor’s footnote","locator":"Cairo I:379,n.1","exact_arabic":"الذيخ - بكسر الذال بعدها ياء ساكنة -: ذكر الضباع. والجمع: أذياخ وذيوخ وذيخة.","inspection":"Complete retained editorial-note record read separately from the authorial body.","finding":"The editor’s explicit male-hyena correction is a distinct voice."}],"scope":[{"record_id":"q3-90","segment_index":1,"q":"3:90","source":"Cairo print · Volume I, pp. 378–379","segment_title":"Returning before an acquired habit becomes entrenched","anchor_paragraph":"The glossator says: “What he mentions perhaps has in view the Friend’s encounter with his father, when he meets him covered in darkness and desires to intercede for him. His father is transformed into a filth-smeared dhīkh ( ذيخ )—that is, a pig—and he no longer recognizes him, as in the authentic report. So remember and take heed.” End of quotation. [Translator’s note: The gloss “a pig” is the quoted glossator’s; the Cairo editor defines dhīkh here as “a male hyena” (I:379, n. 1).] [XIV-N050] Success is through God, and He is the guide to the even path.","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The stated textual or interpretive distinction does not independently authenticate every report in the surrounding passage.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo Ruslān 1419/1999: Volume I, printed p. 379; Q3:90; qushayri_tafsir: Laṭāʾif al-ishārāt I:258, Q3:91; PageV01P258; bukhari: Ṣaḥīḥ al-Bukhārī, no.3350; Cairo editor’s footnote: Cairo I:379,n.1","revision_status":"","word_count":94,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-90","segment_index":1,"q":"3:90","source":"Cairo print · Volume I, pp. 378–379","segment_title":"Spiritual allusion — الإشارة Returning before an acquired habit becomes entrenched","anchor_paragraph":"The glossator says: “What he mentions perhaps has in view the Friend’s encounter with his father, when he meets him covered in darkness and desires to intercede for him. His father is transformed into a filth-smeared dhīkh ( ذيخ )—that is, a pig—and he no longer recognizes him, as in the authentic report. So remember and take heed.” End of quotation. [Translator’s note: The gloss “a pig” is the quoted glossator’s; the Cairo editor defines dhīkh here as “a male hyena” (I:379, n. 1).] [T107] Success is through God, and He is the guide to the even path."}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T107; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T107","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T107","original_body_sha256":"68152ae204ac25813ff567d58767aebed8108f495c8dbc49355c6324ecfd6693","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":70,"print_label":"T70","linked_occurrences":[{"record_id":"q3-90","segment_index":1,"q":"3:90","source":"Cairo print · Volume I, pp. 378–379"}]},{"id":"XIV-N051","historical_note_id":"T108","title":"The ransom question and its explanatory gloss","content":"The report’s counterfactual asks what the unbeliever would offer after death; it does not describe an offer that could still be accepted. Al-Bukhārī, no. 6538, preserves the earthful-of-gold question and the reply that something easier had been required. His wording ends there. Ibn ʿAjība’s identification of that easier demand with the confession of divine unity, followed by his prayer for steadfastness, belongs to the commentary’s explanatory voice. ‘He means’ introduces Ibn ʿAjība’s explanation, and the prayer is likewise his own. This distinction also preserves the verse’s contrast between present response and a belated ransom.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:380; Q3:91","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-bukhari","locator":"Ṣaḥīḥ, no.6538","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","bounded_arabic":"قد كنت سئلت ما هو أيسر من ذلك","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Core question and response; the commentary’s subsequent gloss is outside this report.","title":"Ṣaḥīḥ al-Bukhārī"}],"scope":[{"record_id":"q3-91","segment_index":1,"q":"3:91","source":"Cairo print · Volume I, pp. 379–380","segment_title":"No purchase of release after death","anchor_paragraph":"The Prophet, blessings and peace be upon him, said: “The unbeliever will be brought on the Day of Resurrection and asked: ‘Tell Me: had you possessed an earthful of gold, would you have offered it as a ransom?’ He will answer: ‘Yes, yes.’ He will be told: ‘You were asked for something easier than that.’” He means: “There is no god but God.” May God make us steadfast in this word until death, knowing its meaning. Amen. [XIV-N051]","cairo_printed_pages":[380],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The Bukhārī parallel supports the report’s core, not the added explanatory identification as quoted Prophetic speech.","source":"Cairo-Ruslan-I: I:380; Q3:91; XIV-OT-bukhari: Ṣaḥīḥ, no.6538","revision_status":"","word_count":98,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-91","segment_index":1,"q":"3:91","source":"Cairo print · Volume I, pp. 379–380","segment_title":"[No purchase of release after death]","anchor_paragraph":"The Prophet, blessings and peace be upon him, said: “The unbeliever will be brought on the Day of Resurrection and asked: ‘Tell Me: had you possessed an earthful of gold, would you have offered it as a ransom?’ He will answer: ‘Yes, yes.’ He will be told: ‘You were asked for something easier than that.’” He means: “There is no god but God.” May God make us steadfast in this word until death, knowing its meaning. Amen. [T108]","cairo_printed_pages":[380]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T108; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T108","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T108","original_body_sha256":"5f04c4b5157a08a9e1c76ad8bc4e25a6f0536026bf7f648e2dcfb42d4a6f9e55","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":71,"print_label":"T71","linked_occurrences":[{"record_id":"q3-91","segment_index":1,"q":"3:91","source":"Cairo print · Volume I, pp. 379–380"}]},{"id":"XIV-N052","historical_note_id":"T109","title":"Loss of proximity within Paradise","content":"The spiritual allusion changes the object of the unsuccessful ransom. In the outward exposition it concerns deliverance from punishment; here it concerns attaining the rank of those brought near. Ibn ʿAjība explicitly places the person being admonished among ordinary Muslims in Paradise. Consequently, ‘the grief of the veil’ and ‘the pain of separation’ describe deprivation of a higher degree of witnessing within his account of spiritual ranks. They do not denote expulsion from Paradise or an unqualified judgment of unbelief. The repeated gold image carries the warning across the two levels without making their destinies identical.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:380; Q3:91","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-91","segment_index":2,"q":"3:91","source":"Cairo print · Volume I, pp. 379–380","segment_title":"Salvation distinguished from the station of the near ones","anchor_paragraph":"Were he to purchase a station among them with an earthful of gold, it would not avail him. He remains there in the grief of the veil and the pain of separation, cut off from witnessing the beloved ones in unveiling and clarity ( الكشف والبيان ), deprived of witnessing and direct vision ( الشهود والعيان ). And success is through God. [XIV-N052]","cairo_printed_pages":[380],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"An explanation of the author’s spiritual analogy, not a separate proof of the described afterlife hierarchy.","source":"Cairo-Ruslan-I: I:380; Q3:91","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-91","segment_index":2,"q":"3:91","source":"Cairo print · Volume I, pp. 379–380","segment_title":"Spiritual allusion — الإشارة Salvation distinguished from the station of the near ones","anchor_paragraph":"Were he to purchase a station among them with an earthful of gold, it would not avail him. He remains there in the grief of the veil and the pain of separation, cut off from witnessing the beloved ones in unveiling and clarity ( الكشف والبيان ), deprived of witnessing and direct vision ( الشهود والعيان ). And success is through God. [T109]","cairo_printed_pages":[380]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T109; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T109","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T109","original_body_sha256":"dbf0616a3d8f3cf4b91b509a79120f2af7ef07077508b3074e7edba1121fe4e5","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":72,"print_label":"T72","linked_occurrences":[{"record_id":"q3-91","segment_index":2,"q":"3:91","source":"Cairo print · Volume I, pp. 379–380"}]},{"id":"XIV-N053","historical_note_id":"T110","title":"Rābiḥ and rāʾiḥ in the Bayruḥāʾ report","content":"Al-Bukhārī, no. 1461, preserves Abū Ṭalḥa’s gift and expressly records the variant rāʾiḥ alongside rābiḥ. The latter means profitable; the former belongs to the vocabulary of going or departure. These are alternative transmitted wordings, not two different properties or successive evaluations of the gift. Ibn ʿAjība’s account uses the report to show that spending what one loves can include giving to relatives. The Prophet’s direction determines the beneficiaries while Abū Ṭalḥa relinquishes the cherished property. The parenthetic identification and location of the garden are explanatory material and should not be absorbed into the quoted dialogue.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:381; Q3:92","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-bukhari","locator":"Ṣaḥīḥ, no.1461","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","bounded_arabic":"ذلك مال رابح / عن مالك رايح","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Report and explicit variant read together.","title":"Ṣaḥīḥ al-Bukhārī"}],"scope":[{"record_id":"q3-92","segment_index":1,"q":"3:92","source":"Cairo print · Volume I, pp. 380–382","segment_title":"Wealth, influence, bodily service and life itself","anchor_paragraph":"Abū Ṭalḥa came and said: “Messenger of God, the property dearest to me is Bayruḥāʾ”—a garden behind the Prophet’s mosque—“and it is a charitable gift for God. I hope for its goodness and its stored reward.” He, blessings and peace be upon him, replied: “Excellent, excellent! That is a profitable property”— rābiḥ ( رابح ), or rāʾiḥ ( رائح ), literally “going forth,” in the other wording—“and I consider that you should give it to your near relatives.” Abū Ṭalḥa therefore divided it among his relatives. [XIV-N053]","cairo_printed_pages":[381],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The primary parallel verifies the core and the recorded lexical variant; it does not validate every topographical gloss in Cairo.","source":"Cairo-Ruslan-I: I:381; Q3:92; XIV-OT-bukhari: Ṣaḥīḥ, no.1461","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-92","segment_index":1,"q":"3:92","source":"Cairo print · Volume I, pp. 380–382","segment_title":"[Wealth, influence, bodily service and life itself]","anchor_paragraph":"Abū Ṭalḥa came and said: “Messenger of God, the property dearest to me is Bayruḥāʾ”—a garden behind the Prophet’s mosque—“and it is a charitable gift for God. I hope for its goodness and its stored reward.” He, blessings and peace be upon him, replied: “Excellent, excellent! That is a profitable property”— rābiḥ ( رابح ), or rāʾiḥ ( رائح ), literally “going forth,” in the other wording—“and I consider that you should give it to your near relatives.” Abū Ṭalḥa therefore divided it among his relatives. [T110]","cairo_printed_pages":[381]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T110; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T110","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T110","original_body_sha256":"5268ea090784b3ed1282ad78d37f4f3362584281461fdc35c2ae7b285da8eacf","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":73,"print_label":"T73","linked_occurrences":[{"record_id":"q3-92","segment_index":1,"q":"3:92","source":"Cairo print · Volume I, pp. 380–382"}]},{"id":"XIV-N054","historical_note_id":"T111","title":"Personal preference as the measure of the gift","content":"The two anecdotes illustrate ‘what you love’ by identifying an attachment specific to the giver. Ibn ʿUmar’s proposed marriage is framed as something he declines because he considers it a return to a benefit already relinquished for God. The text does not say that emancipation itself prevents a subsequent marriage. Al-Rabīʿ’s explanation about sugar likewise makes the giver’s preference decisive: the example does not establish sugar as an intrinsically superior alms. Both stories extend the verse beyond the monetary value of the gift to the act of parting with something cherished. Their individual speakers and explanations should remain distinct.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:381; Q3:92","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-92","segment_index":1,"q":"3:92","source":"Cairo print · Volume I, pp. 380–382","segment_title":"Wealth, influence, bodily service and life itself","anchor_paragraph":"Ibn ʿUmar recalled this verse and found nothing he possessed dearer to him than an enslaved woman with whom he had sexual relations. He freed her and said: “Were it not that I do not take back anything I have given for God, I would marry her.” Whenever a beggar stood at al-Rabīʿ’s door, he would give him sugar. When questioned about this, he said: “Al-Rabīʿ loves sugar.” [XIV-N054]","cairo_printed_pages":[381],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The note explains the transmitted anecdotes’ argument; it does not supply independent historical authentication or a general marriage ruling.","source":"Cairo-Ruslan-I: I:381; Q3:92","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-92","segment_index":1,"q":"3:92","source":"Cairo print · Volume I, pp. 380–382","segment_title":"[Wealth, influence, bodily service and life itself]","anchor_paragraph":"Ibn ʿUmar recalled this verse and found nothing he possessed dearer to him than an enslaved woman with whom he had sexual relations. He freed her and said: “Were it not that I do not take back anything I have given for God, I would marry her.” Whenever a beggar stood at al-Rabīʿ’s door, he would give him sugar. When questioned about this, he said: “Al-Rabīʿ loves sugar.” [T111]","cairo_printed_pages":[381]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T111; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T111","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T111","original_body_sha256":"105e2927a3aba2e2ce6e5ca775608a1169248b180e112db42d533ecf320db878","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":74,"print_label":"T74","linked_occurrences":[{"record_id":"q3-92","segment_index":1,"q":"3:92","source":"Cairo print · Volume I, pp. 380–382"}]},{"id":"XIV-N055","historical_note_id":"T112","title":"Giving the self and the vocabulary of attachment","content":"Ibn ʿAjība moves from spending cherished possessions to relinquishing attachment to the self. The shifts among nafs, rūḥ and the poetry of giving one’s life carry distinct emphases. The shaykh passage gives this generosity a disciplinary form: the disciple submits personal preference to direction in spiritual training. The following love poetry and al-Qurashī’s definition then express the same relinquishment through the language of the beloved. These are related illustrations, not a single quotation. The author’s culminating argument is that whoever gives what is dearest will more readily give lesser things.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:381,382; Q3:92","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-92","segment_index":2,"q":"3:92","source":"Cairo print · Volume I, pp. 380–382","segment_title":"The self as the dearest gift","anchor_paragraph":"Giving the self to God means presenting it to a shaykh of spiritual training ( شيخ التربية ), who does with it what he wills. Whatever he directs the disciple to do, the disciple hastens to do without hesitation. Whoever does this has attained the utmost righteousness and spent the dearest thing he loves. Whoever gives his self will all the more readily give everything else, for nothing is dearer than it. [XIV-N055] Concerning this, Ibn al-Fāriḍ, may God be pleased with him, says:","cairo_printed_pages":[381,382],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Describes the argument and terminology of this passage without authenticating the attributed sayings or adding conditions absent from it.","source":"Cairo-Ruslan-I: I:381,382; Q3:92","revision_status":"","word_count":98,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-92","segment_index":2,"q":"3:92","source":"Cairo print · Volume I, pp. 380–382","segment_title":"Spiritual allusion — الإشارة The self as the dearest gift","anchor_paragraph":"Giving the self to God means presenting it to a shaykh of spiritual training ( شيخ التربية ), who does with it what he wills. Whatever he directs the disciple to do, the disciple hastens to do without hesitation. Whoever does this has attained the utmost righteousness and spent the dearest thing he loves. Whoever gives his self will all the more readily give everything else, for nothing is dearer than it. [T112] Concerning this, Ibn al-Fāriḍ, may God be pleased with him, says:","cairo_printed_pages":[381,382]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T112; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T112","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T112","original_body_sha256":"6def7d4828b70937049dc1a19d2e05ff09304b5bb94588495c85690a28000bef","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":75,"print_label":"T75","linked_occurrences":[{"record_id":"q3-92","segment_index":2,"q":"3:92","source":"Cairo print · Volume I, pp. 380–382"}]},{"id":"XIV-N056","historical_note_id":"T113","title":"Israel’s personal abstention and later prohibition","content":"‘Israel’ is Jacob in this exposition, while ‘the Children of Israel’ denotes his descendants. The distinction matters because the exception is what he forbade to himself, not a prohibition originally addressed to the whole community. Ibn ʿAjība offers two explanations of his abstention: a vow connected with recovery from illness, and dietary treatment advised by physicians. These alternatives should remain introduced as alternatives. The subsequent sentence distinguishes the descendants’ continued abstention from restrictions associated with the later revelation of the Torah. The passage’s chronological argument would be lost if personal renunciation, inherited practice and revealed prohibition were all rendered simply as ‘forbidden food.’","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:382; Q3:93–95","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-93-95","segment_index":1,"q":"3:93–95","source":"Cairo print · Volume I, pp. 382–383","segment_title":"A personal abstention is not an original universal prohibition","anchor_paragraph":"The Real, exalted is His majesty, says: “All food was lawful to the Children of Israel,” just as it was lawful to all the prophets, “except what Israel”—that is, Jacob—“forbade himself,” such as camel meat and its milk. It is said that he suffered from sciatica ( عرق النسا ) and vowed that, if God healed him, he would no longer eat the food he loved most; camel meat and milk were dearest to him. It is also said that he abstained from them as a treatment at the physicians’ direction. His children continued to abstain, although those foods were not forbidden to them in the Torah: this was something they had forbidden themselves. [XIV-N056]","cairo_printed_pages":[382],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The narrative explanations are preserved as the commentator’s alternatives; no medical or historical conclusion is inferred.","source":"Cairo-Ruslan-I: I:382; Q3:93–95","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-93-95","segment_index":1,"q":"3:93–95","source":"Cairo print · Volume I, pp. 382–383","segment_title":"[A personal abstention is not an original universal prohibition]","anchor_paragraph":"The Real, exalted is His majesty, says: “All food was lawful to the Children of Israel,” just as it was lawful to all the prophets, “except what Israel”—that is, Jacob—“forbade himself,” such as camel meat and its milk. It is said that he suffered from sciatica ( عرق النسا ) and vowed that, if God healed him, he would no longer eat the food he loved most; camel meat and milk were dearest to him. It is also said that he abstained from them as a treatment at the physicians’ direction. His children continued to abstain, although those foods were not forbidden to them in the Torah: this was something they had forbidden themselves. [T113]","cairo_printed_pages":[382]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T113; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T113","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T113","original_body_sha256":"9adb789c2a7641887f2d7e23615ba591330e60663293ab24f1a128909a284625","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":76,"print_label":"T76","linked_occurrences":[{"record_id":"q3-93-95","segment_index":1,"q":"3:93–95","source":"Cairo print · Volume I, pp. 382–383"}]},{"id":"XIV-N057","historical_note_id":"T114","title":"The challenge to produce the Torah","content":"The command to bring and recite the Torah functions here as a demand for documentary support for a particular asserted prohibition. ‘After that’ refers to the clarification and argument just presented, which explains why the following accusation concerns persistence after the claim has been challenged. Ibn ʿAjība’s report that his opponents declined the challenge is a narrative addition to the verse’s imperative, not wording contained in the Qurʾān. The scriptural challenge, the reported response and the commentator’s resulting accusation are separate voices. This also preserves the logical connection between the earlier personal abstention and the contested claim of an original universal ban.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:382,383; Q3:93–95","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-93-95","segment_index":1,"q":"3:93–95","source":"Cairo print · Volume I, pp. 382–383","segment_title":"A personal abstention is not an original universal prohibition","anchor_paragraph":"It is related that when the Prophet, blessings and peace be upon him, challenged them in this way they were confounded and dared not produce the Torah, whereupon their fabrication against God became manifest. “Whoever fabricates a lie against God” by alleging that God had forbidden camel meat and milk before the Torah was sent down, “after that”—after this explanation and the argument that has been brought home to them—“it is they who are the wrongdoers,” stubbornly maintaining falsehood after the truth has become clear. [XIV-N057]","cairo_printed_pages":[382,383],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The note analyses the argument’s structure; it does not treat the reported encounter as independently verified.","source":"Cairo-Ruslan-I: I:382,383; Q3:93–95","revision_status":"","word_count":106,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-93-95","segment_index":1,"q":"3:93–95","source":"Cairo print · Volume I, pp. 382–383","segment_title":"[A personal abstention is not an original universal prohibition]","anchor_paragraph":"It is related that when the Prophet, blessings and peace be upon him, challenged them in this way they were confounded and dared not produce the Torah, whereupon their fabrication against God became manifest. “Whoever fabricates a lie against God” by alleging that God had forbidden camel meat and milk before the Torah was sent down, “after that”—after this explanation and the argument that has been brought home to them—“it is they who are the wrongdoers,” stubbornly maintaining falsehood after the truth has become clear. [T114]","cairo_printed_pages":[382,383]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T114; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T114","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T114","original_body_sha256":"132d443124545bd255913e9341a52baeb993c695583b65e494677c6937ee3498","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":77,"print_label":"T77","linked_occurrences":[{"record_id":"q3-93-95","segment_index":1,"q":"3:93–95","source":"Cairo print · Volume I, pp. 382–383"}]},{"id":"XIV-N058","historical_note_id":"T115","title":"Reconciliation with the self remains qualified","content":"The concluding instruction to agree with the self must be read with the beginning of this same allusion: the advanced knower takes and spends ‘in conformity with the revealed Law.’ The passage distinguishes a beginner whose desires interrupt the journey from one whose self has submitted to the witnessing of its Lord. ‘What becomes manifest within it’ refers back to that transformed self, not to appetite considered without qualification. Ibn ʿAjība therefore presents opposition and reconciliation as different disciplines for different states. Keeping the earlier qualification visible prevents the final sentence from appearing to reverse the passage’s express requirement of conformity to the Law.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:383; Q3:93–95","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-93-95","segment_index":2,"q":"3:93–95","source":"Cairo print · Volume I, pp. 382–383","segment_title":"Permission, watchfulness and the differing states of the wayfarer and the knower","anchor_paragraph":"In sum: so long as the soul has not submitted and yielded to the witnessing of its Lord ( مشاهدة ربها ), it must be struggled against and opposed. Once it has submitted and yielded to its Lord, reconciliation with it is required, and one must agree with it in what becomes manifest within it ( فيما يتجلى فيها ). And God Most High knows best. [XIV-N058]","cairo_printed_pages":[383],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The qualification belongs to the immediate context of the author’s own allusion.","source":"Cairo-Ruslan-I: I:383; Q3:93–95","revision_status":"","word_count":104,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-93-95","segment_index":2,"q":"3:93–95","source":"Cairo print · Volume I, pp. 382–383","segment_title":"Spiritual allusion — الإشارة Permission, watchfulness and the differing states of the wayfarer and the knower","anchor_paragraph":"In sum: so long as the soul has not submitted and yielded to the witnessing of its Lord ( مشاهدة ربها ), it must be struggled against and opposed. Once it has submitted and yielded to its Lord, reconciliation with it is required, and one must agree with it in what becomes manifest within it ( فيما يتجلى فيها ). And God Most High knows best. [T115]","cairo_printed_pages":[383]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T115; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T115","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T115","original_body_sha256":"2329e06948d1a3bda18391c37260f0e5328deec3894280a5a3f9e1363676f44f","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":78,"print_label":"T78","linked_occurrences":[{"record_id":"q3-93-95","segment_index":2,"q":"3:93–95","source":"Cairo print · Volume I, pp. 382–383"}]},{"id":"XIV-N059","historical_note_id":"T116","title":"Two explanations of Bakkah","content":"The opening account presents two distinct approaches to the place-name. One treats Bakkah and Makkah as forms related by a consonantal interchange; the examples involving a blow and a fever illustrate that linguistic claim. The other distinguishes the name of the whole settlement from the name of the House’s location. The subsequent derivation from a verb meaning to crush explains the name through the humbling of tyrants. These are transmitted lexical and explanatory proposals, not steps in a single demonstrated etymology. ‘It is also said’ marks their alternative status and the shift from linguistic comparison to a narrative explanation.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:383; Q3:96–97","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-96-97","segment_index":0,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"Bakkah, the circumstantial accusative and the Station of Abraham","anchor_paragraph":"I say: “Bakkah” ( بكة ) is a dialectal form of “Makkah”; Arabs interchange bāʾ and mīm, as when they say ḍarba lāzim and lāzib for a decisive blow, or aghbaṭat ʿalayhi al-ḥummā and aghmaṭat, concerning a fever. It is also said that “Makkah,” with mīm, names the whole town, whereas “Bakkah” names the location of the House. It was given that name because it “breaks” ( تبك ), that is, crushes, the necks of tyrants: no tyrant has intended it evil without God breaking him. [XIV-N059]","cairo_printed_pages":[383],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The note does not independently establish the historical etymology or the universality of the associated claim about tyrants.","source":"Cairo-Ruslan-I: I:383; Q3:96–97","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-96-97","segment_index":0,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"[Bakkah, the circumstantial accusative and the Station of Abraham]","anchor_paragraph":"I say: “Bakkah” ( بكة ) is a dialectal form of “Makkah”; Arabs interchange bāʾ and mīm, as when they say ḍarba lāzim and lāzib for a decisive blow, or aghbaṭat ʿalayhi al-ḥummā and aghmaṭat, concerning a fever. It is also said that “Makkah,” with mīm, names the whole town, whereas “Bakkah” names the location of the House. It was given that name because it “breaks” ( تبك ), that is, crushes, the necks of tyrants: no tyrant has intended it evil without God breaking him. [T116]","cairo_printed_pages":[383]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T116; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T116","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T116","original_body_sha256":"21fc4c66eb0518712f13605a07f3e8872856d07d12b48c6d36c1def44d0f5ce7","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":79,"print_label":"T79","linked_occurrences":[{"record_id":"q3-96-97","segment_index":0,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385"}]},{"id":"XIV-N060","historical_note_id":"T117","title":"A singular Station among plural signs","content":"The grammatical problem is the relation of the singular ‘Station of Abraham’ to the plural ‘clear signs.’ Ibn ʿAjība records three solutions: an independent subject with an omitted predicate, a part standing for a larger set, or an explanatory apposition. The last becomes possible because several distinct wonders are understood to be contained in the one Station. The singular variant ‘a sign’ supports another way of construing the expression; it is distinct from the plural form printed here. Similarly, the analysis of mubārakan supplies an implied location or establishment as governor; the accusative marks a state of the House, not a new object.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:383,384; Q3:96–97","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-96-97","segment_index":0,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"Bakkah, the circumstantial accusative and the Station of Abraham","anchor_paragraph":"“Blessed” ( مباركاً ) is a circumstantial accusative ( حال ) referring to the pronoun in the prepositional expression, with the implied state of being established or located ( الاستقرار ) as its governor ( العامل ): that is, “the one situated in Bakkah, being blessed.” “The Station of Abraham” ( مقام إبراهيم ) may be a subject ( مبتدأ ) whose predicate ( خبر ) is suppressed: “among them is the Station of Abraham.” Or it may be a part-for-whole substitute ( بدل البعض من الكل ) for “signs” ( آيات ), or an explicative apposition ( عطف بيان ), if the signs intend the impression of his foot in the solid rock, its sinking into it as far as the ankles, the rock’s being distinguished from other rocks by this property, the preservation of this impression rather than other prophets’ traces, and its survival for thousands of years despite his many enemies. Thus the Station of Abraham, though singular, has the force of a plural. Supporting this is a variant reading with the singular “a sign” ( آية ). [XIV-N060]","cairo_printed_pages":[383,384],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-96-97","segment_index":0,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"Bakkah, the circumstantial accusative and the Station of Abraham","anchor_paragraph":"It is also said that the “signs” are the Station of Abraham and the security of whoever enters. On this explanation, “whoever enters it” is coordinated with “the Station”; on the former interpretation it begins a new sentence ( استئناف ). “Pilgrimage to the House” ( حج البيت ) is a subject ( مبتدأ ), and “belongs to God” ( لله ) is its predicate ( خبر ). The vowel fatḥa [in ḥajj] is the idiom of the Ḥijāz and kasra [ḥijj] the idiom of Najd. “Whoever is able” ( من استطاع ) is an appositional substitute ( بدل ) for “the people” ( الناس ); it is also said to be the subject/agent ( فاعل ). [XIV-N060]","cairo_printed_pages":[383,384],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"A grammatical account of the supplied analyses; the note does not authenticate the reported physical wonders or establish the status of the singular reading.","source":"Cairo-Ruslan-I: I:383,384; Q3:96–97","revision_status":"","word_count":101,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-96-97","segment_index":0,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"[Bakkah, the circumstantial accusative and the Station of Abraham]","anchor_paragraph":"“Blessed” ( مباركاً ) is a circumstantial accusative ( حال ) referring to the pronoun in the prepositional expression, with the implied state of being established or located ( الاستقرار ) as its governor ( العامل ): that is, “the one situated in Bakkah, being blessed.” “The Station of Abraham” ( مقام إبراهيم ) may be a subject ( مبتدأ ) whose predicate ( خبر ) is suppressed: “among them is the Station of Abraham.” Or it may be a part-for-whole substitute ( بدل البعض من الكل ) for “signs” ( آيات ), or an explicative apposition ( عطف بيان ), if the signs intend the impression of his foot in the solid rock, its sinking into it as far as the ankles, the rock’s being distinguished from other rocks by this property, the preservation of this impression rather than other prophets’ traces, and its survival for thousands of years despite his many enemies. Thus the Station of Abraham, though singular, has the force of a plural. Supporting this is a variant reading with the singular “a sign” ( آية ). [T117]","cairo_printed_pages":[383,384]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T117; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T117","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T117","original_body_sha256":"e8b2180c472b9597a4d6d243eecd8966ec435af547366057a74bf69e02ac9289","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":80,"print_label":"T80","linked_occurrences":[{"record_id":"q3-96-97","segment_index":0,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385"},{"record_id":"q3-96-97","segment_index":0,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385"}]},{"id":"XIV-N061","historical_note_id":"T118","title":"The forty-year interval and construction narratives","content":"Al-Bukhārī, no. 3366, records Abū Dharr’s question about the first mosque placed on earth, the answer naming the Sacred Mosque and then the Farthest Mosque, and the interval of forty years. That report does not itself name angels or Adam as their builders. Ibn ʿAjība combines the interval with further construction traditions and distinguishes an initial building from Abraham’s renewal. These layers must remain separate: confirming the interval’s hadith source does not confirm all the accompanying chronology. The later list of signs likewise gathers several explanations under the verse rather than presenting them as parts of the same Prophetic report.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:384; Q3:96–97","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-bukhari","locator":"Ṣaḥīḥ, no.3366","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","bounded_arabic":"أي مسجد وضع في الأرض أول / أربعون سنة","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Full question and answer inspected; builders are not named there.","title":"Ṣaḥīḥ al-Bukhārī"}],"scope":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"The Kaʿba, its signs and reported virtues","anchor_paragraph":"The Real, exalted is His majesty, says: “Truly the first House” placed upon the earth “for humankind” was the one established at Makkah, followed by the House of Jerusalem, with forty years between them. The angels built the first facing the Inhabited House ( البيت المعمور ), and God commanded the inhabitants of earth to circumambulate it as the dwellers of heaven circumambulate the Inhabited House; then the second was built. It is also said that Adam built both, and that Abraham later renewed the first. It is “blessed,” because good deeds are multiplied there, each one by a hundred thousand; sins are expiated there, mercies descend, and spiritual gifts ( النفحات ) arrive in succession. [Translator’s note: These are explanations and reports transmitted by the commentator, not claims independently established here about construction chronology.] [XIV-N061]","cairo_printed_pages":[384],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"The Kaʿba, its signs and reported virtues","anchor_paragraph":"“In it are clear signs,” conspicuous proofs, including the stone that is “the Station of Abraham,” upon which Abraham stood while he raised the foundations of the House. Whenever the building grew higher, the stone rose with him into the air until he completed the building, and his foot sank into it as though it were clay. Other signs are said to include birds not passing above it, the destruction of the People of the Elephant, the repelling of tyrants, the emergence of Zamzam for Hagar through Gabriel’s striking it, its later rediscovery by ʿAbd al-Muṭṭalib after it had been obscured, and the benefit of its water for whatever purpose it is drunk. [XIV-N061]","cairo_printed_pages":[384],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Only the forty-year core is matched to the inspected Bukhārī report; construction agents and the wider marvel catalogue retain their separate evidentiary status.","source":"Cairo-Ruslan-I: I:384; Q3:96–97; XIV-OT-bukhari: Ṣaḥīḥ, no.3366","revision_status":"","word_count":100,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"[The Kaʿba, its signs and reported virtues]","anchor_paragraph":"The Real, exalted is His majesty, says: “Truly the first House” placed upon the earth “for humankind” was the one established at Makkah, followed by the House of Jerusalem, with forty years between them. The angels built the first facing the Inhabited House ( البيت المعمور ), and God commanded the inhabitants of earth to circumambulate it as the dwellers of heaven circumambulate the Inhabited House; then the second was built. It is also said that Adam built both, and that Abraham later renewed the first. It is “blessed,” because good deeds are multiplied there, each one by a hundred thousand; sins are expiated there, mercies descend, and spiritual gifts ( النفحات ) arrive in succession. [Translator’s note: These are explanations and reports transmitted by the commentator, not claims independently established here about construction chronology.] [T118]","cairo_printed_pages":[384]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T118; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T118","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T118","original_body_sha256":"c0f9349e691ec676c756f81337e4e90cda5b35d705e980877274aae85993ba8c","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":81,"print_label":"T81","linked_occurrences":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385"},{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385"}]},{"id":"XIV-N062","historical_note_id":"T119","title":"Security and the competing legal readings","content":"The verse’s promise of security receives both a devotional explanation and a discussion of sanctuary law. Ibn ʿAjība first relates it to protection in the two abodes, then contrasts a position allowing the enforcement of prescribed penalties with the position he attributes to Abū Ḥanīfa. In the latter, protection within the sanctuary does not cancel the underlying liability: pressure is used to induce departure. Thus ‘safe’ cannot be rendered as a uniform immunity that all the cited jurists accept. The words ḥudūd and qiṣāṣ also remain distinct, identifying prescribed penalties and retaliation rather than two synonyms for punishment.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:384; Q3:96–97","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"The Kaʿba, its signs and reported virtues","anchor_paragraph":"“Whoever enters it is safe”: from punishment in the two abodes, through the Friend’s prayer, “My Lord, make this land secure” [14:35]. In the pre-Islamic period anyone who committed an offence and then took refuge there was neither attacked nor punished while within it. In Islam, however, the sacred precinct does not bar the prescribed penalties ( الحدود ) or retaliation ( القصاص ). Abū Ḥanīfa holds that the earlier rule remains: if someone liable to a prescribed penalty or retaliation enters the sacred precinct, he is not attacked, but pressure is applied to him—he is not fed or sold provisions—until he goes out. [XIV-N062]","cairo_printed_pages":[384],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"This is a presentation of the positions reported in the historical commentary, not a current legal determination.","source":"Cairo-Ruslan-I: I:384; Q3:96–97","revision_status":"","word_count":98,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"[The Kaʿba, its signs and reported virtues]","anchor_paragraph":"“Whoever enters it is safe”: from punishment in the two abodes, through the Friend’s prayer, “My Lord, make this land secure” [14:35]. In the pre-Islamic period anyone who committed an offence and then took refuge there was neither attacked nor punished while within it. In Islam, however, the sacred precinct does not bar the prescribed penalties ( الحدود ) or retaliation ( القصاص ). Abū Ḥanīfa holds that the earlier rule remains: if someone liable to a prescribed penalty or retaliation enters the sacred precinct, he is not attacked, but pressure is applied to him—he is not fed or sold provisions—until he goes out. [Translator’s note: The divergence of legal positions must be preserved rather than harmonized into one ruling.] [T119]","cairo_printed_pages":[384]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T119; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T119","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T119","original_body_sha256":"b1323151f52c85c30e132f6af85be488fbfb1a2754bb514681d80a6faf9d4be2","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":82,"print_label":"T82","linked_occurrences":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385"}]},{"id":"XIV-N063","historical_note_id":"T120","title":"Two reports, two evidentiary scopes","content":"The sentence about dying in either sanctuary and the sentence about a pilgrimage free of misconduct are separate reports. Al-Bukhārī, nos. 1521 and 1819, supplies a close primary parallel for the second: returning like the day one’s mother gave birth to one. That comparison expresses release from sins, not literal rebirth. Its wording should not be used to authenticate the preceding promise about burial or death in the two sanctuaries. Within the second report, rafath and fisq name distinct forms of misconduct, rather than an undifferentiated condition of ‘a good pilgrimage.’","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:384; Q3:96–97","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-bukhari","locator":"Ṣaḥīḥ, nos.1521 and1819","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","bounded_arabic":"فلم يرفث ولم يفسق رجع كيوم ولدته أمه","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Second report’s core; not the first report.","title":"Ṣaḥīḥ al-Bukhārī"}],"scope":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"The Kaʿba, its signs and reported virtues","anchor_paragraph":"The Prophet, blessings and peace be upon him, said: “Whoever dies in one of the two sanctuaries will be raised among those who are safe.” He also said: “Whoever performs pilgrimage to this House and neither commits obscenity nor transgresses comes forth from his sins like the day his mother gave birth to him.” [XIV-N063]","cairo_printed_pages":[384],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The inspected canonical parallel concerns the pilgrimage report only; the preceding sanctuary-death report is not independently authenticated by this note.","source":"Cairo-Ruslan-I: I:384; Q3:96–97; XIV-OT-bukhari: Ṣaḥīḥ, nos.1521 and1819","revision_status":"","word_count":101,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"[The Kaʿba, its signs and reported virtues]","anchor_paragraph":"The Prophet, blessings and peace be upon him, said: “Whoever dies in one of the two sanctuaries will be raised among those who are safe.” He also said: “Whoever performs pilgrimage to this House and neither commits obscenity nor transgresses comes forth from his sins like the day his mother gave birth to him.” [T120]","cairo_printed_pages":[384]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T120; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T120","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T120","original_body_sha256":"8315ac82b752e2c35c951752569e1efcfa4f8e27c8d12c3dc3affb1395438729","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":83,"print_label":"T83","linked_occurrences":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385"}]},{"id":"XIV-N064","historical_note_id":"T121","title":"Denial of obligation and intensified warning","content":"Ibn ʿAjība offers two explanations of ‘whoever disbelieves.’ One concerns rejecting pilgrimage and its obligation; the other treats the vocabulary of unbelief as an intensified warning about abandoning it. The second explanation is introduced as an alternative, not as a statement that every failure to perform pilgrimage has already been adjudged doctrinal unbelief. God’s independence then answers both readings: human refusal does not diminish Him. The account of the religious communities responding differently to the command is an occasion narrative added by the commentary. Its reported numbers should not be confused with the verse’s general address to those able to make the journey.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:384; Q3:96–97","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"The Kaʿba, its signs and reported virtues","anchor_paragraph":"“Whoever” abandons it and “disbelieves” in it—such as Jews, Christians, and anyone who denies its obligation—“God has no need” of that person, his pilgrimage, or any of the worlds; or “disbelief” is used for abandoning it as an intensification, as in the saying: “Whoever abandons prayer has disbelieved.” It is related that when the opening of the verse came down, the Prophet assembled the religious communities and said, “God has prescribed the pilgrimage for you; so perform it.” One community believed him and five denied him; so “whoever disbelieves ...” was revealed. [Translator’s note: The report is cited as a report, without independent authentication.] [XIV-N064]","cairo_printed_pages":[384],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Preserves the author’s distinction between interpretations without supplying an independent legal judgment or authentication of the occasion narrative.","source":"Cairo-Ruslan-I: I:384; Q3:96–97","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"[The Kaʿba, its signs and reported virtues]","anchor_paragraph":"“Whoever” abandons it and “disbelieves” in it—such as Jews, Christians, and anyone who denies its obligation—“God has no need” of that person, his pilgrimage, or any of the worlds; or “disbelief” is used for abandoning it as an intensification, as in the saying: “Whoever abandons prayer has disbelieved.” It is related that when the opening of the verse came down, the Prophet assembled the religious communities and said, “God has prescribed the pilgrimage for you; so perform it.” One community believed him and five denied him; so “whoever disbelieves ...” was revealed. [Translator’s note: The report is cited as a report, without independent authentication.] [T121]","cairo_printed_pages":[384]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T121; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T121","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T121","original_body_sha256":"1ce81397afeccdedb2f2016827312099177c86851593dda8715b3df16cdf27b9","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":84,"print_label":"T84","linked_occurrences":[{"record_id":"q3-96-97","segment_index":1,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385"}]},{"id":"XIV-N065","historical_note_id":"T122","title":"The heart as a house of divine remembrance","content":"The House, its inhabitant, circumambulation and visitors form an extended image of the heart filled by divine light and knowledge. The contrast is explicitly between the sensible House and an inward one. A useful earlier comparison occurs in al-Qushayrī’s Risāla, II:377, where language about God dwelling in the believer’s heart is explained as the abiding of His remembrance, with physical indwelling denied. That explanation clarifies the vocabulary’s possible spiritual use; it is not a direct gloss quoted by Ibn ʿAjība here. The present allusion’s own visitors are spiritual influxes and lights, which sustain its inward register throughout.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:385; Q3:96–97","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-qushayri_risala","locator":"Al-Risāla, II:377, chapter on remembrance","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0465IbnHawazinQushayri/0465IbnHawazinQushayri.RisalaQushayriyya/0465IbnHawazinQushayri.RisalaQushayriyya.Shamela0009953-ara1","local_file":"audit_work/revision_XIV_research/public_sources/qushayri_risala.txt","bounded_arabic":"ومعناه سكون الذكر في القلب","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Earlier contextual explanation of heart-dwelling language; no direct borrowing asserted.","title":"Al-Qushayrī, al-Risāla"}],"scope":[{"record_id":"q3-96-97","segment_index":2,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"The physical House and the heart as an inward sanctuary","anchor_paragraph":"God has established two houses for humankind. One is sensible ( حسي ), the Kaʿba; the other is intelligible or spiritual ( معنوي ), the heart, which is the House of the Lord ( بيت الرب ). As long as the house of the heart is empty of the Lord’s light, it longs to make pilgrimage to the sensible House. But when the house has been built up with the light of its Indweller, it becomes a direction of orientation ( قبلة ) for others and ceases to turn towards anything other than the light of its Lord. Rather, it becomes a Kaʿba around which spiritual visitations ( الواردات ) and lights make their circumambulations, surrounded by gnoses, sciences and secrets. Then it becomes a pole ( قطب ) of the circle of existing things, around which they turn from every side and place. How could such a person long for the sensible Kaʿba when the circle of cosmic visitors revolves around him? [XIV-N065]","cairo_printed_pages":[385],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The Risāla supplies a comparative explanation, not proof that this precise Baḥr passage derives from it or that sākin has a different reading here.","source":"Cairo-Ruslan-I: I:385; Q3:96–97; XIV-OT-qushayri_risala: Al-Risāla, II:377, chapter on remembrance","revision_status":"","word_count":97,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-96-97","segment_index":2,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385","segment_title":"Spiritual allusion — الإشارة The physical House and the heart as an inward sanctuary","anchor_paragraph":"God has established two houses for humankind. One is sensible ( حسي ), the Kaʿba; the other is intelligible or spiritual ( معنوي ), the heart, which is the House of the Lord ( بيت الرب ). As long as the house of the heart is empty of the Lord’s light, it longs to make pilgrimage to the sensible House. But when the house has been built up with the light of its Indweller, it becomes a direction of orientation ( قبلة ) for others and ceases to turn towards anything other than the light of its Lord. Rather, it becomes a Kaʿba around which spiritual visitations ( الواردات ) and lights make their circumambulations, surrounded by gnoses, sciences and secrets. Then it becomes a pole ( قطب ) of the circle of existing things, around which they turn from every side and place. How could such a person long for the sensible Kaʿba when the circle of cosmic visitors revolves around him? [T122]","cairo_printed_pages":[385]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T122; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T122","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T122","original_body_sha256":"061b5cb777f018129587158220e2f2a196ab573fe07060f4195ef7e1a0818c61","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":85,"print_label":"T85","linked_occurrences":[{"record_id":"q3-96-97","segment_index":2,"q":"3:96–97","source":"Cairo print · Volume I, pp. 383–385"}]},{"id":"XIV-N066","historical_note_id":"T123","title":"Two endings for two forms of opposition","content":"The paragraph explains why the repeated address does not simply repeat the same rebuke. The first accusation concerns disbelief openly professed; its ending emphasizes divine witnessing. The second concerns efforts to obstruct believers through concealment and contrivance; its ending denies divine heedlessness. The distinction is rhetorical, not a division between matters God knows and matters He does not yet know. Ibn ʿAjība attributes this explanation to al-Bayḍāwī. ‘Each offence is reprehensible in itself’ accordingly explains the repeated address as independent censure, while the paired endings show how each censure is fitted to the manner of conduct being described.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:386; Q3:98–99","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-98-99","segment_index":1,"q":"3:98–99","source":"Cairo print · Volume I, pp. 385–386","segment_title":"Open rejection and concealed obstruction","anchor_paragraph":"The address and question are repeated twice to heighten rebuke, remove excuse and indicate that each offence is reprehensible in itself and independently attracts punishment. Since the action denounced in the first verse is their unbelief, which they openly declare, it closes with “God is witness to what you do.” Since the second denounces the obstruction of believers from Islam, which they concealed and contrived secretly, it concludes with “God is not heedless of what you do.” Al-Bayḍāwī explains it thus. [XIV-N066]","cairo_printed_pages":[386],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The source attribution is reported by Ibn ʿAjība; this note’s argument is restricted to the quoted explanation and its immediate context.","source":"Cairo-Ruslan-I: I:386; Q3:98–99","revision_status":"","word_count":98,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-98-99","segment_index":1,"q":"3:98–99","source":"Cairo print · Volume I, pp. 385–386","segment_title":"[Open rejection and concealed obstruction]","anchor_paragraph":"The address and question are repeated twice to heighten rebuke, remove excuse and indicate that each offence is reprehensible in itself and independently attracts punishment. Since the action denounced in the first verse is their unbelief, which they openly declare, it closes with “God is witness to what you do.” Since the second denounces the obstruction of believers from Islam, which they concealed and contrived secretly, it concludes with “God is not heedless of what you do.” Al-Bayḍāwī explains it thus. [T123]","cairo_printed_pages":[386]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T123; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T123","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T123","original_body_sha256":"c4178c19062c4ecfc8a1873c64d6bd1e79c3643acad58bbeaaf21edb7d7b55a9","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":86,"print_label":"T86","linked_occurrences":[{"record_id":"q3-98-99","segment_index":1,"q":"3:98–99","source":"Cairo print · Volume I, pp. 385–386"}]},{"id":"XIV-N067","historical_note_id":"T124","title":"A particular occasion and a general address","content":"The opening sentence explicitly distinguishes the general wording of ‘O you who believe’ from the particular Aws and Khazraj group identified in the occasion narrative. The account then explains the threatened return to unbelief through renewed bloodshed and revived pre-Islamic factionalism. It should not be paraphrased as an unexplained change of abstract doctrine. The Prophet’s intervention, the abandonment of weapons and the restored embrace form the narrative reversal that prepares the next verse’s emphasis on the Messenger’s presence. Names, battlefield memories and dialogue belong to the transmitted occasion account; the general exhortation extends beyond those narrative particulars.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:386,387; Q3:100–102","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-100-102","segment_index":0,"q":"3:100–102","source":"Cairo print · Volume I, pp. 386–388","segment_title":"An attempt to revive the feud between Aws and Khazraj","anchor_paragraph":"The Messenger of God, blessings and peace be upon him, went out to them with his companions and said: “Do you call with the call of the Age of Ignorance while I am here among you, after God has honoured you with Islam, cut off from you the affair of ignorance, and brought you together?” They recognized it as an incitement from Satan and a stratagem of their enemy. They threw down their weapons, sought forgiveness, embraced one another, and returned with the Messenger, blessings and peace be upon him. Then the verse was revealed. [Translator’s note: This is the occasion-of-revelation narrative transmitted by Ibn ʿAjība; its historical details require separate assessment.] [XIV-N067]","cairo_printed_pages":[386,387],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"No chain assessment of the detailed occasion narrative is supplied; its function and quoted voices are distinguished from the verse.","source":"Cairo-Ruslan-I: I:386,387; Q3:100–102","revision_status":"","word_count":97,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-100-102","segment_index":0,"q":"3:100–102","source":"Cairo print · Volume I, pp. 386–388","segment_title":"[An attempt to revive the feud between Aws and Khazraj]","anchor_paragraph":"The Messenger of God, blessings and peace be upon him, went out to them with his companions and said: “Do you call with the call of the Age of Ignorance while I am here among you, after God has honoured you with Islam, cut off from you the affair of ignorance, and brought you together?” They recognized it as an incitement from Satan and a stratagem of their enemy. They threw down their weapons, sought forgiveness, embraced one another, and returned with the Messenger, blessings and peace be upon him. Then the verse was revealed. [Translator’s note: This is the occasion-of-revelation narrative transmitted by Ibn ʿAjība; its historical details require separate assessment.] [T124]","cairo_printed_pages":[386,387]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T124; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T124","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T124","original_body_sha256":"cbfa3e379ec52e5ae92e76770f1598243908f4027664240d58a01d4283cde76e","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":87,"print_label":"T87","linked_occurrences":[{"record_id":"q3-100-102","segment_index":0,"q":"3:100–102","source":"Cairo print · Volume I, pp. 386–388"}]},{"id":"XIV-N068","historical_note_id":"T125","title":"Two accounts of the relation to Q64:16","content":"The outward exposition reports abrogation, then gives a non-abrogating interpretation; the spiritual allusion assigns the two commands to differing capacities or inward and outward disciplines. These positions must remain distinct. The threefold explanation of ‘His true due’ also has an earlier attribution to Ibn Masʿūd in al-Ṭabarī, VII:64–66, reports 7536 onward. That Companion-level parallel does not by itself establish Cairo’s attribution of the fuller wording to the Prophet. The note therefore separates the saying’s transmission from the exegetical question of abrogation. Ibn ʿAjība’s own allusive resolution is that each command retains an appropriate field of application.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:387,388; Q3:100–102","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-tabari","locator":"Jāmiʿ al-bayān, VII:64–66, reports7536 onward","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0310Tabari/0310Tabari.JamicBayan/0310Tabari.JamicBayan.Shamela0000043-ara1","local_file":"audit_work/revision_XIV_research/public_sources/tabari.txt","bounded_arabic":"أن يطاع فلا يعصى ويذكر فلا ينسى ويشكر فلا يكفر","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Attribution to Ibn Masʿūd and surrounding exposition directly read.","title":"Al-Ṭabarī, Jāmiʿ al-bayān"}],"scope":[{"record_id":"q3-100-102","segment_index":1,"q":"3:100–102","source":"Cairo print · Volume I, pp. 386–388","segment_title":"“As He should be feared” and the question of abrogation","anchor_paragraph":"God then urged perfect Godfearingness ( التقوى الكاملة ) and constancy in submission, discouraging them from listening to anyone who would remove them from these. “O you who believe, be mindful of God as He is truly worthy of being regarded.” The Prophet, blessings and peace be upon him, is reported to have said: “His true due is that He should be obeyed and not disobeyed for the blink of an eye, remembered and not forgotten, thanked and not denied.” When the verse came down, they asked, “Messenger of God, who can bear this?” It was difficult for them; then “Be mindful of God as far as you are able” [64:16] was revealed and abrogated it, according to this explanation. [XIV-N068]","cairo_printed_pages":[387,388],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-100-102","segment_index":2,"q":"3:100–102","source":"Cairo print · Volume I, pp. 386–388","segment_title":"Holding fast through companionship and the certainty of realization","anchor_paragraph":"Then He addressed the people of spiritual excellence ( أهل الإحسان ): “O you who believe, be mindful of God as He truly deserves,” by being absent to everything other than Him; “and do not die except while you are Muslims,” yielding to the determinations of Lordship ( أحكام الربوبية ) and fulfilling the functions of servanthood ( وظائف العبودية ). This verse, then, is addressed to the people of iḥsān, while “Be mindful of God as far as you are able” [64:16] is addressed to the people of Islam and faith. Or the former is for the people of detachment ( أهل التجريد ) and the latter for those occupied with secondary causes ( أهل الأسباب ); or the former is for the inward people ( أهل الباطن ) and the latter for the outward people ( أهل الظاهر ). Each verse has its people and its proper place: there is therefore no abrogation ( نسخ ) and no contradiction ( تعارض ). [XIV-N068]","cairo_printed_pages":[387,388],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The Ṭabarī parallel is a reported Companion explanation; it neither authenticates Cairo’s Prophetic form nor proves either abrogation theory.","source":"Cairo-Ruslan-I: I:387,388; Q3:100–102; XIV-OT-tabari: Jāmiʿ al-bayān, VII:64–66, reports7536 onward","revision_status":"","word_count":96,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-100-102","segment_index":1,"q":"3:100–102","source":"Cairo print · Volume I, pp. 386–388","segment_title":"[“As He should be feared” and the question of abrogation]","anchor_paragraph":"God then urged perfect Godfearingness ( التقوى الكاملة ) and constancy in submission, discouraging them from listening to anyone who would remove them from these. “O you who believe, be mindful of God as He is truly worthy of being regarded.” The Prophet, blessings and peace be upon him, is reported to have said: “His true due is that He should be obeyed and not disobeyed for the blink of an eye, remembered and not forgotten, thanked and not denied.” When the verse came down, they asked, “Messenger of God, who can bear this?” It was difficult for them; then “Be mindful of God as far as you are able” [64:16] was revealed and abrogated it, according to this explanation. [T125]","cairo_printed_pages":[387,388]},{"record_id":"q3-100-102","segment_index":2,"q":"3:100–102","source":"Cairo print · Volume I, pp. 386–388","segment_title":"Spiritual allusion — الإشارة Holding fast through companionship and the certainty of realization","anchor_paragraph":"Then He addressed the people of spiritual excellence ( أهل الإحسان ): “O you who believe, be mindful of God as He truly deserves,” by being absent to everything other than Him; “and do not die except while you are Muslims,” yielding to the determinations of Lordship ( أحكام الربوبية ) and fulfilling the functions of servanthood ( وظائف العبودية ). This verse, then, is addressed to the people of iḥsān, while “Be mindful of God as far as you are able” [64:16] is addressed to the people of Islam and faith. Or the former is for the people of detachment ( أهل التجريد ) and the latter for those occupied with secondary causes ( أهل الأسباب ); or the former is for the inward people ( أهل الباطن ) and the latter for the outward people ( أهل الظاهر ). Each verse has its people and its proper place: there is therefore no abrogation ( نسخ ) and no contradiction ( تعارض ). [T125]","cairo_printed_pages":[387,388]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T125; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T125","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T125","original_body_sha256":"1f6d586a7876e8e5b077017f2f93042580d4b75894f068f4c4a72094a3a6bb79","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":88,"print_label":"T88","linked_occurrences":[{"record_id":"q3-100-102","segment_index":1,"q":"3:100–102","source":"Cairo print · Volume I, pp. 386–388"},{"record_id":"q3-100-102","segment_index":2,"q":"3:100–102","source":"Cairo print · Volume I, pp. 386–388"}]},{"id":"XIV-N069","historical_note_id":"T126","title":"God’s rope and the first sect report","content":"The rope image identifies a means of connection and protection, which allows the commentator to explain it through faith or the Qurʾān. ‘All together’ then specifies the manner of holding fast, while the prohibition on division states its communal consequence. Two report units occur in this passage: praise of the Qurʾān and a division-of-sects saying. The latter gives seventy-one for the Children of Israel and seventy-two for this community, with ‘the community’ as the answer. These details belong to this occurrence and must remain distinguishable from the different numbers and answer quoted at Q3:105, where Ibn ʿAjība himself compares the versions.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:388; Q3:103","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-103","segment_index":1,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389","segment_title":"God’s cord and the reversal of inherited enmity","anchor_paragraph":"The Real, exalted is His majesty, says: “Hold fast,” O company of Muslims, that is, cling “to the rope of God,” meaning faith or God’s Book, according to the Prophet’s saying: “This Qurʾān is God’s strong rope, the manifest light, the beneficial healing, and a protection for whoever holds fast to it ...” and the remainder of the report. Do so “all together,” united upon it; “and do not divide” as you were divided in the Age of Ignorance, or do not part from the truth through discord among yourselves as the People of the Book did. [XIV-N069]","cairo_printed_pages":[388],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-103","segment_index":1,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389","segment_title":"God’s cord and the reversal of inherited enmity","anchor_paragraph":"The Prophet, blessings and peace be upon him, said, as cited here: “The Children of Israel split into seventy-one sects, and my community will split into seventy-two sects, all of them in the Fire except one.” Asked, “Messenger of God, which is the one?”, he clasped his hand and said: “The community ( الجماعة ).” Then he recited: “Hold fast, all together, to the rope of God, and do not divide.” [Translator’s note: The numbers and wording here must be kept distinct from Ibn ʿAjība’s other version of the report in his very next section.] [XIV-N069]","cairo_printed_pages":[388],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Textual comparison between the two Cairo occurrences; no independent authentication of either complete report is inferred.","source":"Cairo-Ruslan-I: I:388; Q3:103","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-103","segment_index":1,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389","segment_title":"[God’s cord and the reversal of inherited enmity]","anchor_paragraph":"The Real, exalted is His majesty, says: “Hold fast,” O company of Muslims, that is, cling “to the rope of God,” meaning faith or God’s Book, according to the Prophet’s saying: “This Qurʾān is God’s strong rope, the manifest light, the beneficial healing, and a protection for whoever holds fast to it ...” and the remainder of the report. Do so “all together,” united upon it; “and do not divide” as you were divided in the Age of Ignorance, or do not part from the truth through discord among yourselves as the People of the Book did. [T126]","cairo_printed_pages":[388]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T126; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T126","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T126","original_body_sha256":"fa80e2fd2a32e59e1ae39fa09db11e146756e3261ff6b57cc1d3816ffc6676d9","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":89,"print_label":"T89","linked_occurrences":[{"record_id":"q3-103","segment_index":1,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389"},{"record_id":"q3-103","segment_index":1,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389"}]},{"id":"XIV-N070","historical_note_id":"T127","title":"Brotherhood as command and narrated transformation","content":"The prohibition of envy, hatred and abandonment supplies the ethical content of the verse’s movement from enmity to brotherhood. Muslim, no. 2564, preserves the closely corresponding sequence, including the statement that a Muslim neither wrongs nor abandons his brother. The commentary then moves to a separate historical explanation involving Aws and Khazraj, and finally to the Bedouin’s inference from rescue from the Fire. These are three different kinds of material: Prophetic exhortation, an occasion narrative and a reader’s theological inference. The canonical parallel for the first should not extend its authority automatically to the genealogy, duration of warfare or later exchange.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:388,389; Q3:103","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-muslim","locator":"Ṣaḥīḥ, no.2564","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0261Muslim/0261Muslim.Sahih/0261Muslim.Sahih.Shamela0001727-ara1.mARkdown","local_file":"audit_work/revision_XIV_research/public_sources/muslim.txt","bounded_arabic":"المسلم أخو المسلم لا يظلمه ولا يخذله","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Read within the prohibition of envy, hatred and contempt.","title":"Ṣaḥīḥ Muslim"}],"scope":[{"record_id":"q3-103","segment_index":1,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389","segment_title":"God’s cord and the reversal of inherited enmity","anchor_paragraph":"“Remember God’s blessing upon you,” one of its forms being guidance to Islam, which brings about affection and removes rancour, “when you were enemies” in the Age of Ignorance, killing one another, “and He joined your hearts” through Islam, “so that by His blessing you became brothers,” loving one another and united in brotherhood for God’s sake. The Prophet, blessings and peace be upon him, said: “Do not envy one another, hate one another or turn your backs on one another; be, servants of God, brothers. A Muslim is the brother of a Muslim; he does not wrong him or abandon him.” The remainder of the report follows. It is related that Aws and Khazraj were originally two full brothers whose descendants became enemies and warred for a hundred and twenty years, until God extinguished this through Islam and united them by His Messenger; the verse was revealed about them. [XIV-N070]","cairo_printed_pages":[388,389],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-103","segment_index":1,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389","segment_title":"God’s cord and the reversal of inherited enmity","anchor_paragraph":"He then says to them: “You were upon the brink of a pit of fire,” almost falling into Hell; had death overtaken you, you would have fallen in. “And He rescued you from it,” through His Messenger, blessings and peace be upon him. It is related that a Bedouin heard Ibn ʿAbbās reciting this verse and said: “By God, He did not rescue them from it in order to cast them into it.” Ibn ʿAbbās replied: “Take this from someone who is not a jurist.” End of report. “Thus God makes His signs clear to you,” in such a manner He explains them, “that you may be guided” to the good and increase in steadfastness upon it. [XIV-N070]","cairo_printed_pages":[388,389],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The inspected Muslim report supports the ethical saying only; the historical and exegetical additions retain separate scope.","source":"Cairo-Ruslan-I: I:388,389; Q3:103; XIV-OT-muslim: Ṣaḥīḥ, no.2564","revision_status":"","word_count":101,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-103","segment_index":1,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389","segment_title":"[God’s cord and the reversal of inherited enmity]","anchor_paragraph":"“Remember God’s blessing upon you,” one of its forms being guidance to Islam, which brings about affection and removes rancour, “when you were enemies” in the Age of Ignorance, killing one another, “and He joined your hearts” through Islam, “so that by His blessing you became brothers,” loving one another and united in brotherhood for God’s sake. The Prophet, blessings and peace be upon him, said: “Do not envy one another, hate one another or turn your backs on one another; be, servants of God, brothers. A Muslim is the brother of a Muslim; he does not wrong him or abandon him.” The remainder of the report follows. It is related that Aws and Khazraj were originally two full brothers whose descendants became enemies and warred for a hundred and twenty years, until God extinguished this through Islam and united them by His Messenger; the verse was revealed about them. [T127]","cairo_printed_pages":[388,389]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T127; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T127","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T127","original_body_sha256":"38297924c37bbbbb7aabdddbfcf72493f97cadb987aa30414e1c35ee50356658","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":90,"print_label":"T90","linked_occurrences":[{"record_id":"q3-103","segment_index":1,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389"},{"record_id":"q3-103","segment_index":1,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389"}]},{"id":"XIV-N071","historical_note_id":"T128","title":"Concord in the goal and variety in the way","content":"Ibn ʿAjība’s claim of Sufi agreement is immediately qualified by his admission of different ways of reaching the aim. The agreement he asserts therefore concerns the journey’s governing pattern and consummation, not identical practices or a complete absence of disagreement. ‘Tasting’ and ‘unveiling’ describe the mode of assurance claimed for this inward knowledge, contrasted here with probabilistic inquiry. The application of Q15:47 to a ‘Paradise of gnoses’ then turns the scriptural removal of rancour into an account of present spiritual fellowship. These are the author’s explanations of the path’s ideal unity, rather than a documented survey of all historical Sufi groups.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:389; Q3:103","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-103","segment_index":2,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389","segment_title":"Concord among the paths of realization and the healing of the heart","anchor_paragraph":"Even if they disagree over particular ways ( الطرق ) of reaching the aim, they agree concerning the end. This is unlike the people of outward inquiry ( أهل الظاهر ), whom, in Ibn ʿAjība’s characterization, one finds agreeing only on a few questions, for their method is built upon the preponderance of conjecture ( غلبة الظن ), while the method of the Folk ( القوم ) is grounded in realization through tasting and unveiling ( التحقيق ذوقاً وكشفاً ). Their hearts and spirits, likewise, are united: all are formed by compassion, tenderness, affection, harmony and purity, because they have entered Paradise—the Paradise of gnoses ( جنة المعارف )—and adopted the character traits of the inhabitants of Paradise. God says: “We shall remove whatever rancour is in their breasts, as brothers upon couches facing one another” [15:47]. [XIV-N071]","cairo_printed_pages":[389],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Explains the qualification within the author’s argument; no universal historical consensus is independently established.","source":"Cairo-Ruslan-I: I:389; Q3:103","revision_status":"","word_count":101,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-103","segment_index":2,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389","segment_title":"Spiritual allusion — الإشارة Concord among the paths of realization and the healing of the heart","anchor_paragraph":"Even if they disagree over particular ways ( الطرق ) of reaching the aim, they agree concerning the end. This is unlike the people of outward inquiry ( أهل الظاهر ), whom, in Ibn ʿAjība’s characterization, one finds agreeing only on a few questions, for their method is built upon the preponderance of conjecture ( غلبة الظن ), while the method of the Folk ( القوم ) is grounded in realization through tasting and unveiling ( التحقيق ذوقاً وكشفاً ). Their hearts and spirits, likewise, are united: all are formed by compassion, tenderness, affection, harmony and purity, because they have entered Paradise—the Paradise of gnoses ( جنة المعارف )—and adopted the character traits of the inhabitants of Paradise. God says: “We shall remove whatever rancour is in their breasts, as brothers upon couches facing one another” [15:47]. [T128]","cairo_printed_pages":[389]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T128; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T128","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T128","original_body_sha256":"fca488b29747344db693452d43b091fafd963f3c3f4ab2a260c033f52b0a5d50","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":91,"print_label":"T91","linked_occurrences":[{"record_id":"q3-103","segment_index":2,"q":"3:103","source":"Cairo print · Volume I, pp. 388–389"}]},{"id":"XIV-N072","historical_note_id":"T129","title":"Partitive min and a shared responsibility","content":"The two analyses of min produce different grammatical descriptions of the addressees: a group from within the community, or the community characterized by the following duty. The subsequent discussion connects the partitive analysis with qualifications for carrying out moral intervention. A collective obligation is still addressed to the community; performance by a sufficient qualified portion discharges the remainder. It is not merely an optional task for whoever happens to volunteer. The coordination of enjoining and forbidding after calling to good adds a second grammatical point: particular forms of the broader good are singled out for their importance, without exhausting its scope.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:389,390; Q3:104","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-104","segment_index":0,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"Whether “from among you” denotes a subset or the whole community","anchor_paragraph":"I say: “From among you” ( مِنْكُمْ )—the particle min ( مِنْ )—can be partitive ( للتبعيض ), because enjoining right and forbidding wrong is among the collective obligations ( فروض الكفاية ), not every person being suited to it. Or min can be explanatory ( للبيان ): that is, “Be a community that enjoins what is right,” as in “You are the best community brought forth for humankind: you enjoin what is right ...” [3:110]. “They enjoin what is right and forbid what is wrong” is coordinated with the predicate ( الخبر ), the mention of the particular after the general ( عطف الخاص على العام ) to show its special merit. [XIV-N072]","cairo_printed_pages":[389,390],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-104","segment_index":2,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"Capacity, knowledge and the distinction between required and recommended action","anchor_paragraph":"The person who undertakes the duty requires qualifications: knowledge of the rulings ( العلم بالأحكام ), of the degrees of moral intervention ( مراتب الاحتساب ), of how to carry it out, and the ability to discharge it. That is why the Real addresses all but requests action from some: only a portion are fitted for it. This is the nature of a collective obligation ( فرض الكفاية ), which rests on everyone in such a way that, if all neglect it, all are liable, but whose performance by some discharges the rest. [XIV-N072]","cairo_printed_pages":[389,390],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Exposition of the historical commentary’s grammatical and legal reasoning; not a determination of how the duty applies in a present case.","source":"Cairo-Ruslan-I: I:389,390; Q3:104","revision_status":"","word_count":101,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-104","segment_index":0,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"[Whether “from among you” denotes a subset or the whole community]","anchor_paragraph":"I say: “From among you” ( مِنْكُمْ )—the particle min ( مِنْ )—can be partitive ( للتبعيض ), because enjoining right and forbidding wrong is among the collective obligations ( فروض الكفاية ), not every person being suited to it. Or min can be explanatory ( للبيان ): that is, “Be a community that enjoins what is right,” as in “You are the best community brought forth for humankind: you enjoin what is right ...” [3:110]. “They enjoin what is right and forbid what is wrong” is coordinated with the predicate ( الخبر ), the mention of the particular after the general ( عطف الخاص على العام ) to show its special merit. [T129]","cairo_printed_pages":[389,390]},{"record_id":"q3-104","segment_index":2,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"[Capacity, knowledge and the distinction between required and recommended action]","anchor_paragraph":"The person who undertakes the duty requires qualifications: knowledge of the rulings ( العلم بالأحكام ), of the degrees of moral intervention ( مراتب الاحتساب ), of how to carry it out, and the ability to discharge it. That is why the Real addresses all but requests action from some: only a portion are fitted for it. This is the nature of a collective obligation ( فرض الكفاية ), which rests on everyone in such a way that, if all neglect it, all are liable, but whose performance by some discharges the rest. [T129]","cairo_printed_pages":[389,390]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T129; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T129","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T129","original_body_sha256":"f7d110f0be6b3f304622454bb7e9d7e7fa10a6090917c280db37c69db24c31f0","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":92,"print_label":"T92","linked_occurrences":[{"record_id":"q3-104","segment_index":0,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391"},{"record_id":"q3-104","segment_index":2,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391"}]},{"id":"XIV-N073","historical_note_id":"T130","title":"The voices within the moral-exhortation collection","content":"This paragraph gathers several attributed sayings rather than developing one continuous Prophetic address. The first two are introduced as words of the Prophet; the subsequent speakers are ʿAlī, Abū al-Dardāʾ and Ḥudhayfa. Their change of voice should remain explicit. The expression ‘vicegerent of His Book’ extends the preceding claim of acting in service of God and His Messenger; in this context it describes responsibility for upholding the Book’s injunctions. It does not itself narrate appointment to a political office. The sequence moves from praise of moral action to warnings about neglect and hostility toward those who undertake it.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:390; Q3:104","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-104","segment_index":1,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"Calling to every form of good that leads to religious flourishing","anchor_paragraph":"The Prophet, blessings and peace be upon him, is reported to have been asked, “Which people are best?” and to have replied: “Those who most enjoin what is right, most forbid what is wrong, are most mindful of God, and most maintain family ties.” He is also quoted as saying: “Whoever enjoins right and forbids wrong is God’s vicegerent on His earth, the vicegerent of His Messenger, and the vicegerent of His Book.” [XIV-N073]","cairo_printed_pages":[390],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-104","segment_index":1,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"Calling to every form of good that leads to religious flourishing","anchor_paragraph":"ʿAlī, may God be pleased with him, said: “The best striving ( الجهاد ) is to enjoin right, forbid wrong, and detest the transgressors”—that is, hate them. “Whoever enjoins right strengthens the believer’s back; whoever forbids wrong humiliates the hypocrite; and whoever detests the transgressors and grows angry for God, God grows angry on his behalf.” Abū al-Dardāʾ said: “You shall surely enjoin right and forbid wrong, or God will set over you an unjust ruler who will neither honour your elders nor show mercy to your young. Your best people will pray against him without being answered, seek help without receiving it, and seek forgiveness without being forgiven.” Ḥudhayfa said: “A time will come when the corpse of a donkey will be more beloved to people than a believer who enjoins them to right and forbids them from wrong.” [Translator’s note: The chains of these cited sayings have not been individually authenticated.] [XIV-N073]","cairo_printed_pages":[390],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The note identifies voice and scope, not the authenticity of the individual reports; no general authorization for coercive action is inferred.","source":"Cairo-Ruslan-I: I:390; Q3:104","revision_status":"","word_count":98,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-104","segment_index":1,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"[Calling to every form of good that leads to religious flourishing]","anchor_paragraph":"The Prophet, blessings and peace be upon him, is reported to have been asked, “Which people are best?” and to have replied: “Those who most enjoin what is right, most forbid what is wrong, are most mindful of God, and most maintain family ties.” He is also quoted as saying: “Whoever enjoins right and forbids wrong is God’s vicegerent on His earth, the vicegerent of His Messenger, and the vicegerent of His Book.” [T130]","cairo_printed_pages":[390]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T130; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T130","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T130","original_body_sha256":"1621408c6e90e109e175d7c29bede1517d60599f9c87021629da91d6a7cf2f4f","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":93,"print_label":"T93","linked_occurrences":[{"record_id":"q3-104","segment_index":1,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391"},{"record_id":"q3-104","segment_index":1,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391"}]},{"id":"XIV-N074","historical_note_id":"T131","title":"Two duties that remain logically distinct","content":"The argument rests on two obligations: refraining from the wrong oneself and opposing it in the appropriate way. Failure in the first does not logically cancel the second. Ibn ʿAjība also distinguishes forbidden conduct from what is merely disliked, so the technical term munkar should not erase that legal differentiation. Al-Ghazālī’s Iḥyāʾ, II:334, contains the corresponding exhortation to enjoin good despite incomplete practice and explains that visible wrongdoing weakens the speaker’s effect on hearts. That context distinguishes validity of the duty from effectiveness of admonition. The quotation’s occurrence in the Iḥyāʾ supplies a literary parallel, not an independent grading of its chain.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:390; Q3:104","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-ihya","locator":"Iḥyāʾ ʿulūm al-dīn, II:334","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0505Ghazali/0505Ghazali.IhyaCulumDin/0505Ghazali.IhyaCulumDin.Shamela0009472-ara1.completed","local_file":"audit_work/revision_XIV_research/public_sources/ihya.txt","bounded_arabic":"مروا بالمعروف وإن لم تعملوا به كله","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Read with the contrast between moral obligation and reduced persuasive effect.","title":"Al-Ghazālī, Iḥyāʾ ʿulūm al-dīn"}],"scope":[{"record_id":"q3-104","segment_index":2,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"Capacity, knowledge and the distinction between required and recommended action","anchor_paragraph":"Enjoining what is right can be obligatory or recommended, depending on what is being enjoined. Forbidding what is wrong is entirely obligatory, since whatever the Law condemns in this technical sense is forbidden ( حرام ). As for what is merely disliked ( المكروه ), it is not “wrong” in that sense, so encouraging one to leave it is recommended. The stronger view, he says, is that a person who himself commits a sin must nevertheless forbid that same sin to others, because he has two duties—to desist from it and to forbid it—and neglect of one does not remove the obligation of the other. The Prophet is quoted as saying: “Command right even if you do not perform all of it; and forbid wrong even if you do not desist from all of it.” [XIV-N074]","cairo_printed_pages":[390],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"No hadith authentication or present-day legal ruling follows from the literary parallel.","source":"Cairo-Ruslan-I: I:390; Q3:104; XIV-OT-ihya: Iḥyāʾ ʿulūm al-dīn, II:334","revision_status":"","word_count":102,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-104","segment_index":2,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"[Capacity, knowledge and the distinction between required and recommended action]","anchor_paragraph":"Enjoining what is right can be obligatory or recommended, depending on what is being enjoined. Forbidding what is wrong is entirely obligatory, since whatever the Law condemns in this technical sense is forbidden ( حرام ). As for what is merely disliked ( المكروه ), it is not “wrong” in that sense, so encouraging one to leave it is recommended. The stronger view, he says, is that a person who himself commits a sin must nevertheless forbid that same sin to others, because he has two duties—to desist from it and to forbid it—and neglect of one does not remove the obligation of the other. The Prophet is quoted as saying: “Command right even if you do not perform all of it; and forbid wrong even if you do not desist from all of it.” [T131]","cairo_printed_pages":[390]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T131; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T131","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T131","original_body_sha256":"941d0e246900408f5507e1c5221d08a916b54fcd9c9eb68d7746eb644efe0917","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":94,"print_label":"T94","linked_occurrences":[{"record_id":"q3-104","segment_index":2,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391"}]},{"id":"XIV-N075","historical_note_id":"T132","title":"Maʿrūf’s prayer and the narrative ending","content":"The point of Maʿrūf’s prayer is the relation between happiness in the Hereafter and repentance: he redirects a request for harm toward a request for the revellers’ ultimate good. In the Iḥyāʾ, IV:154–155, the boat anecdote ends with his explanation that making them happy in the Hereafter entails turning toward them in repentance. Ibn ʿAjība’s version states that all repented through him. These endings are related but not identical: an explanation of the prayer’s intention should not be silently treated as an eyewitness report of its outcome. The comparison helps preserve both the compassionate logic and the precise scope of the transmitted narrative.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:390,391; Q3:104","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-ihya","locator":"Iḥyāʾ ʿulūm al-dīn, IV:154–155","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0505Ghazali/0505Ghazali.IhyaCulumDin/0505Ghazali.IhyaCulumDin.Shamela0009472-ara1.completed","local_file":"audit_work/revision_XIV_research/public_sources/ihya.txt","bounded_arabic":"إذا فرحهم في الآخرة تاب عليهم","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Full anecdote and immediate explanation inspected; no explicit all-repented ending there.","title":"Al-Ghazālī, Iḥyāʾ ʿulūm al-dīn"}],"scope":[{"record_id":"q3-104","segment_index":3,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"Those whose state itself calls others to God","anchor_paragraph":"So too is the incident of Maʿrūf al-Karkhī and the people on a boat who were occupied with amusement and play. His companions told him to pray against them. He said: “O God, just as You have made them happy in this world, make them happy in the Hereafter.” All of them repented through him. Through God is success, and He is the Guide to the even way. [XIV-N075]","cairo_printed_pages":[390,391],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The literary parallel has been located; the different ending prevents using it as full confirmation of Cairo’s reported outcome.","source":"Cairo-Ruslan-I: I:390,391; Q3:104; XIV-OT-ihya: Iḥyāʾ ʿulūm al-dīn, IV:154–155","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-104","segment_index":3,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391","segment_title":"Spiritual allusion — الإشارة Those whose state itself calls others to God","anchor_paragraph":"So too is the incident of Maʿrūf al-Karkhī and the people on a boat who were occupied with amusement and play. His companions told him to pray against them. He said: “O God, just as You have made them happy in this world, make them happy in the Hereafter.” All of them repented through him. Through God is success, and He is the Guide to the even way. [T132]","cairo_printed_pages":[390,391]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T132; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T132","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T132","original_body_sha256":"edd3f249088f47ccd0a6e60f9c8826ce1550a0dbafa8e985012d558e0ccdd712","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":95,"print_label":"T95","linked_occurrences":[{"record_id":"q3-104","segment_index":3,"q":"3:104","source":"Cairo print · Volume I, pp. 389–391"}]},{"id":"XIV-N076","historical_note_id":"T133","title":"A comparative judgment about two sect traditions","content":"‘This version is sounder’ is Ibn ʿAjība’s comparative judgment, followed by his proposed explanation of the earlier wording through transmission by meaning and possible omission. It should not be rewritten as an independent modern authentication. Al-Tirmidhī, no. 2641, contains the answer ‘what I and my Companions are upon,’ with seventy-two groups for the Children of Israel and seventy-three for this community. Cairo’s fuller enumeration separately names Jews and Christians. The parallel therefore supports the distinctive answer and part of the count, while leaving a difference in formulation. Preserving both Cairo occurrences allows the reader to see the comparison that prompted the author’s remark.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:391; Q3:105–109","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-tirmidhi","locator":"Al-Jāmiʿ, no.2641, V:25–26","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0279Tirmidhi/0279Tirmidhi.Sunan/0279Tirmidhi.Sunan.Shamela0001435-ara1","local_file":"audit_work/revision_XIV_research/public_sources/tirmidhi.txt","bounded_arabic":"ما أنا عليه وأصحابي","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Read the complete wording and compiler’s following comment; partial numerical parallel.","title":"Jāmiʿ al-Tirmidhī"}],"scope":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392","segment_title":"Division in fundamentals versus plurality in derivative judgments","anchor_paragraph":"The Real, exalted is His majesty, says: “Do not be like” the Jews and Christians, “those who split apart” concerning divine unity and God’s transcendence ( التوحيد والتنزيه ), “and differed” about the states of the Hereafter. The Prophet, blessings and peace be upon him, is cited as saying: “The Jews divided into seventy-one sects, the Christians into seventy-two, and my community will divide into seventy-three; all are in the Fire except one.” Asked which one it was, he replied: “What I and my Companions are upon.” Ibn ʿAjība says that this version is sounder than the version quoted earlier, and adds that the Companions transmitted hadith according to its meaning, so perhaps the first transmitter forgot part of it. And God knows best. [XIV-N076]","cairo_printed_pages":[391],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Al-Tirmidhī’s own characterization and the detailed chains require their own assessment; the note records a textual parallel and the author’s voice.","source":"Cairo-Ruslan-I: I:391; Q3:105–109; XIV-OT-tirmidhi: Al-Jāmiʿ, no.2641, V:25–26","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392","segment_title":"[Division in fundamentals versus plurality in derivative judgments]","anchor_paragraph":"The Real, exalted is His majesty, says: “Do not be like” the Jews and Christians, “those who split apart” concerning divine unity and God’s transcendence ( التوحيد والتنزيه ), “and differed” about the states of the Hereafter. The Prophet, blessings and peace be upon him, is cited as saying: “The Jews divided into seventy-one sects, the Christians into seventy-two, and my community will divide into seventy-three; all are in the Fire except one.” Asked which one it was, he replied: “What I and my Companions are upon.” Ibn ʿAjība says that this version is sounder than the version quoted earlier, and adds that the Companions transmitted hadith according to its meaning, so perhaps the first transmitter forgot part of it. And God knows best. [T133]","cairo_printed_pages":[391]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T133; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T133","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T133","original_body_sha256":"1871fd0e821273209881883165555af3184ccc78ef943421b4bba7d9c3d5d3c9","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":96,"print_label":"T96","linked_occurrences":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392"}]},{"id":"XIV-N077","historical_note_id":"T134","title":"Disagreement and the reward for legal effort","content":"Two distinct sayings support the author’s distinction between fundamentals and derivative questions. The report of one or two rewards is independently identifiable in al-Bukhārī, no. 7352, where it concerns a judge who exercises legal effort and either errs or reaches the right judgment. Its subject is disciplined adjudication, not every disagreement or unsupported opinion. The maxim ‘Disagreement within my community is a mercy’ is a separate citation and does not acquire the other report’s source status merely by standing beside it. Keeping the two apart preserves both the author’s argument for legitimate difference and the narrower wording of the identifiable Prophetic report.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:391; Q3:105–109","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-bukhari","locator":"Ṣaḥīḥ, no.7352","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","bounded_arabic":"إذا حكم الحاكم فاجتهد ثم أصاب فله أجران","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Complete report read with its judicial context.","title":"Ṣaḥīḥ al-Bukhārī"}],"scope":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392","segment_title":"Division in fundamentals versus plurality in derivative judgments","anchor_paragraph":"He then says the prohibition concerns division over fundamentals ( الأصول ), not disagreements over derivative matters ( الفروع ), adducing the saying “Disagreement within my community is a mercy,” as well as the saying that the one who exercises legal effort ( اجتهاد ) and reaches the correct conclusion receives two rewards, while one who exercises it and errs receives one. [Translator’s note: The first saying’s status is disputed and should not be treated as an authenticated Prophetic report simply because Ibn ʿAjība quotes it.] [XIV-N077]","cairo_printed_pages":[391],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The Bukhārī reference applies to the reward report only; it does not authenticate the adjacent maxim.","source":"Cairo-Ruslan-I: I:391; Q3:105–109; XIV-OT-bukhari: Ṣaḥīḥ, no.7352","revision_status":"","word_count":102,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392","segment_title":"[Division in fundamentals versus plurality in derivative judgments]","anchor_paragraph":"He then says the prohibition concerns division over fundamentals ( الأصول ), not disagreements over derivative matters ( الفروع ), adducing the saying “Disagreement within my community is a mercy,” as well as the saying that the one who exercises legal effort ( اجتهاد ) and reaches the correct conclusion receives two rewards, while one who exercises it and errs receives one. [Translator’s note: The first saying’s status is disputed and should not be treated as an authenticated Prophetic report simply because Ibn ʿAjība quotes it.] [T134]","cairo_printed_pages":[391]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T134; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T134","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T134","original_body_sha256":"6349526e8f748aaa31243f073d3e74c24c7768b89f9396f9cded9ab63b5b5626","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":97,"print_label":"T97","linked_occurrences":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392"}]},{"id":"XIV-N078","historical_note_id":"T135","title":"Radiance, gloom and alternative readings","content":"The commentary first identifies several possible groups represented by the contrasting faces, then offers two accounts of the imagery itself. On the metonymic reading, whiteness and blackness make joy and fear visible; on the other, the people concerned receive distinguishing signs in the resurrection. These alternatives concern how the passage represents judgment, not two successive changes in a person’s complexion. These accounts differ on the relation of inward condition and outward manifestation; literal marking is introduced as another interpretation. The subsequent spiritual allusion develops yet another relative contrast between the lights of faith and spiritual excellence.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:391,392; Q3:105–109","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392","segment_title":"Division in fundamentals versus plurality in derivative judgments","anchor_paragraph":"The People of the Book divided “after clear proofs had come to them,” meaning verses and demonstrations revealing the truth and demanding agreement upon it. “For them is a mighty punishment”: this punishment shall abide for them “on the Day when some faces become white,” those of believers who were mindful of God and upheld unity; “and some faces become black,” those of unbelievers divided concerning unity. Or the whitened faces are those of the sincere ( المخلصين ), and the darkened faces those of the hypocrites ( المنافقين ); or the former are those who follow the Sunna and the latter the people of innovation. Whiteness and blackness of faces may be metonymies ( كنايتان ) for the manifest radiance of happiness and the gloom of fear. Another interpretation takes the marks literally: the people of truth are distinguished by whitened faces and records, bright complexions and light moving before them and on their right, while the people of falsehood receive the corresponding opposites. [XIV-N078]","cairo_printed_pages":[391,392],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"An account of the alternatives transmitted in the passage, not independent verification of eschatological marks.","source":"Cairo-Ruslan-I: I:391,392; Q3:105–109","revision_status":"","word_count":100,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392","segment_title":"[Division in fundamentals versus plurality in derivative judgments]","anchor_paragraph":"The People of the Book divided “after clear proofs had come to them,” meaning verses and demonstrations revealing the truth and demanding agreement upon it. “For them is a mighty punishment”: this punishment shall abide for them “on the Day when some faces become white,” those of believers who were mindful of God and upheld unity; “and some faces become black,” those of unbelievers divided concerning unity. Or the whitened faces are those of the sincere ( المخلصين ), and the darkened faces those of the hypocrites ( المنافقين ); or the former are those who follow the Sunna and the latter the people of innovation. Whiteness and blackness of faces may be metonymies ( كنايتان ) for the manifest radiance of happiness and the gloom of fear. Another interpretation takes the marks literally: the people of truth are distinguished by whitened faces and records, bright complexions and light moving before them and on their right, while the people of falsehood receive the corresponding opposites. [T135]","cairo_printed_pages":[391,392]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T135; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T135","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T135","original_body_sha256":"692e0667538f91b9b3f2f8fde85273c0f9aed86f6aa2e585cff720edb3f88ff5","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":98,"print_label":"T98","linked_occurrences":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392"}]},{"id":"XIV-N079","historical_note_id":"T136","title":"Ownership and the commentary’s account of justice","content":"The explanation moves from the denial of injustice to God’s ownership of all things and the return of all affairs to Him. Its reasoning does not merely claim that a hidden human standard of fairness has been satisfied; it rejects the premise that an obligation can be imposed upon God from outside His sovereign will. At the same time, the paragraph expressly refers to recompense according to His promise and warning. Both parts belong to the argument. The citation of Q21:23 reinforces the asymmetry between the divine disposer and the creatures who are answerable for their acts.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:392; Q3:105–109","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392","segment_title":"Division in fundamentals versus plurality in derivative judgments","anchor_paragraph":"“These are God’s signs,” concerning His promise and warning ( الوعد والوعيد ); “We recite them to you in truth,” without uncertainty. He has made the excuse impossible and given warning. “God does not desire injustice for the worlds,” since nothing is incumbent upon Him such that deprivation of it would wrong someone; and nothing is forbidden to Him such that His doing it would be unjust. He clarifies this by saying: “To God belongs whatever is in the heavens and whatever is on earth,” by ownership, creation and servitude. He recompenses each according to what He has promised or threatened. “To God all affairs are returned”: He disposes them according to His will and His prior choice. “He is not questioned about what He does, but they shall be questioned” [21:23]. [XIV-N079]","cairo_printed_pages":[392],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Explains the theological reasoning present in Cairo without claiming an independent adjudication of competing schools of theology.","source":"Cairo-Ruslan-I: I:392; Q3:105–109","revision_status":"","word_count":101,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392","segment_title":"[Division in fundamentals versus plurality in derivative judgments]","anchor_paragraph":"“These are God’s signs,” concerning His promise and warning ( الوعد والوعيد ); “We recite them to you in truth,” without uncertainty. He has made the excuse impossible and given warning. “God does not desire injustice for the worlds,” since nothing is incumbent upon Him such that deprivation of it would wrong someone; and nothing is forbidden to Him such that His doing it would be unjust. He clarifies this by saying: “To God belongs whatever is in the heavens and whatever is on earth,” by ownership, creation and servitude. He recompenses each according to what He has promised or threatened. “To God all affairs are returned”: He disposes them according to His will and His prior choice. “He is not questioned about what He does, but they shall be questioned” [21:23]. [T136]","cairo_printed_pages":[392]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T136; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T136","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T136","original_body_sha256":"0ad3f7fbf7dc36f9f7dd76e9a36255e465e00c3a95c550acfda9109ad77eac30","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":99,"print_label":"T99","linked_occurrences":[{"record_id":"q3-105-109","segment_index":1,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392"}]},{"id":"XIV-N080","historical_note_id":"T137","title":"A relative contrast between two lights","content":"The crucial qualification is that the faces described as dark may nevertheless be bright with the light of faith. Their darkness is relative to the greater light attributed to the knowers. The allusion consequently distinguishes loss of spiritual excellence from simple absence of faith. ‘Did you disbelieve in special distinction in your own time?’ also identifies the object of denial: recognition of the living people of the path. The accusation concerns this specified denial, not unbelief without qualification. The punishment of separation is likewise defined here through deprivation of continual witnessing, corresponding to the inward scale of the passage.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:392; Q3:105–109","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-105-109","segment_index":2,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392","segment_title":"The faces of realization and the pain of veiling","anchor_paragraph":"On the Day when the faces of the knowers ( العارفين ) become white, like the brilliant sun, they roam in the gardens wherever they wish. The faces of the ignorant darken with regret. Their darkness is relative to the faces of the knowers: they may be white with the light of faith ( نور الإيمان ), but they lack the light of spiritual excellence ( نور الإحسان ). It is said to them: “Did you disbelieve in special spiritual distinction ( الخصوصية ) in your own time after believing that it existed among those before you?” Taste, then, the punishment of severance ( القطيعة ) from witnessing the Beloved at every moment. [XIV-N080]","cairo_printed_pages":[392],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"A reading of the author’s explicitly relative comparison; it does not turn his spiritual polemic into an independent judgment about particular people.","source":"Cairo-Ruslan-I: I:392; Q3:105–109","revision_status":"","word_count":104,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-105-109","segment_index":2,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392","segment_title":"Spiritual allusion — الإشارة The faces of realization and the pain of veiling","anchor_paragraph":"On the Day when the faces of the knowers ( العارفين ) become white, like the brilliant sun, they roam in the gardens wherever they wish. The faces of the ignorant darken with regret. Their darkness is relative to the faces of the knowers: they may be white with the light of faith ( نور الإيمان ), but they lack the light of spiritual excellence ( نور الإحسان ). It is said to them: “Did you disbelieve in special spiritual distinction ( الخصوصية ) in your own time after believing that it existed among those before you?” Taste, then, the punishment of severance ( القطيعة ) from witnessing the Beloved at every moment. [T137]","cairo_printed_pages":[392]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T137; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T137","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T137","original_body_sha256":"d50e31854c841ef01f93814fd6b4ed70b31ed506197c0df405b41c48a1069596","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":100,"print_label":"T100","linked_occurrences":[{"record_id":"q3-105-109","segment_index":2,"q":"3:105–109","source":"Cairo print · Volume I, pp. 391–392"}]},{"id":"R07-15","content":"Cairo I:393 · The Companions’ works. Ruslān cites Ibn Ḥajar’s comparison of the Companions’ distinctive excellence with later people’s deeds in the discussion of the “best community.” This cited scholarly qualification belongs to the Cairo editor’s footnote and is distinct from the reports Ibn ʿAjība quotes in the main text. The precise Fatḥ al-Bārī passage has not been independently verified in full.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:393; Ruslān’s editorial footnote.","revision_status":"","print_number":101,"print_label":"T101","linked_occurrences":[{"record_id":"q3-110-112","segment_index":0,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396"}]},{"id":"XIV-N081","historical_note_id":"T138","title":"Entry into Paradise and the separate ransom report","content":"The paragraph contains separate reports about precedence in entering Paradise and release from the Fire. Muslim, no. 2767, provides a parallel for the latter, using fikāk, release or ransom, and specifying a Jew or Christian where Cairo’s version says another man. The opening phrase ‘a community shown mercy’ is not part of Muslim’s wording. These differences should remain visible when the report is cited. The metaphor describes deliverance in the report’s own eschatological setting; the text does not describe a payment made by the believer. Locating the ransom passage therefore supplies a bounded source for one report, not for every statement in this praise collection.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:393; Q3:110–112","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-muslim","locator":"Ṣaḥīḥ, no.2767","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0261Muslim/0261Muslim.Sahih/0261Muslim.Sahih.Shamela0001727-ara1.mARkdown","local_file":"audit_work/revision_XIV_research/public_sources/muslim.txt","bounded_arabic":"هذا فكاكك من النار","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Full report and adjacent variants inspected; wording differs from Cairo.","title":"Ṣaḥīḥ Muslim"}],"scope":[{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"The virtue of the Muhammadan community","anchor_paragraph":"Reports praising the Muhammadan community include the Prophet’s words, as cited here: “Paradise was withheld from the prophets until I enter it, and withheld from the communities until my community enters.” And: “My community is a community shown mercy. On the Day of Resurrection God gives each man of this community another man, and it is said: This is your ransom from the Fire.” [XIV-N081]","cairo_printed_pages":[393],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The source parallel is limited to the release report and differs in wording; the first report and prefatory phrase are not authenticated by this citation.","source":"Cairo-Ruslan-I: I:393; Q3:110–112; XIV-OT-muslim: Ṣaḥīḥ, no.2767","revision_status":"","word_count":106,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"[The virtue of the Muhammadan community]","anchor_paragraph":"Reports praising the Muhammadan community include the Prophet’s words, as cited here: “Paradise was withheld from the prophets until I enter it, and withheld from the communities until my community enters.” And: “My community is a community shown mercy. On the Day of Resurrection God gives each man of this community another man, and it is said: This is your ransom from the Fire.” [T138]","cairo_printed_pages":[393]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T138; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T138","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T138","original_body_sha256":"baeb04d7d9c9b98cae9a8414b47a9a78352b1b56f9944d5c986465c5701addd2","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":102,"print_label":"T102","linked_occurrences":[{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396"}]},{"id":"XIV-N082","historical_note_id":"T139","title":"Prayer toward a tree and recognition of al-Khiḍr","content":"The phrase ‘praying toward a tree’ marks the direction of the man’s prayer; it does not say that the tree is its object of worship. Recognition of the speaker as al-Khiḍr occurs through his later self-identification in the reported exchange, not through Anas’s initial observation. The repeated descriptions of Muḥammad’s community form the man’s petition and should remain within his speech. The following account about Jesus is another attributed exchange, not a continuation of the same encounter. Distinguishing those voices preserves the collection’s structure and prevents its repeated praise of the community from being mistaken for one uninterrupted Prophetic statement.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:393; Q3:110–112","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"The virtue of the Muhammadan community","anchor_paragraph":"Anas is reported as saying: “I went out with the Prophet, blessings and peace be upon him, and a voice was coming from a mountain pass. He said: ‘Anas, get up and find out what this voice is.’ I went, and there was a man praying toward a tree and saying: ‘O God, make me one of Muḥammad’s community, the community that receives mercy, is forgiven, is answered and whose repentance is accepted.’ I told the Prophet. He said: ‘Go and tell him that God’s Messenger sends his greeting and asks: Who are you?’ I conveyed the message. He said: ‘Send my greeting to God’s Messenger and say to him: Your brother al-Khiḍr asks you to pray that God make me a member of your community—the community shown mercy and forgiven.’” [XIV-N082]","cairo_printed_pages":[393],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"The virtue of the Muhammadan community","anchor_paragraph":"It was said to Jesus son of Mary: “Will there be a community after this one?” He answered: “Yes, the community of Aḥmad.” Asked about its character, he said: “They are scholars, wise ones, righteous and Godfearing, like prophets in their understanding of religion. They are content with a little provision, and God is content with a little work from them. He admits them into Paradise by their testimony that there is no god but God.” End of cited account. [XIV-N082]","cairo_printed_pages":[393],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The note resolves syntax and narrative voice; it does not establish the encounter’s historicity or the report’s chain.","source":"Cairo-Ruslan-I: I:393; Q3:110–112","revision_status":"","word_count":100,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"[The virtue of the Muhammadan community]","anchor_paragraph":"Anas is reported as saying: “I went out with the Prophet, blessings and peace be upon him, and a voice was coming from a mountain pass. He said: ‘Anas, get up and find out what this voice is.’ I went, and there was a man praying toward a tree and saying: ‘O God, make me one of Muḥammad’s community, the community that receives mercy, is forgiven, is answered and whose repentance is accepted.’ I told the Prophet. He said: ‘Go and tell him that God’s Messenger sends his greeting and asks: Who are you?’ I conveyed the message. He said: ‘Send my greeting to God’s Messenger and say to him: Your brother al-Khiḍr asks you to pray that God make me a member of your community—the community shown mercy and forgiven.’” [T139]","cairo_printed_pages":[393]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T139; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T139","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T139","original_body_sha256":"51645d7c1904eebbc45ee228f6edc6415c974ad1f5fb6151a2d9224b0c7073ad","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":103,"print_label":"T103","linked_occurrences":[{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396"},{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396"}]},{"id":"XIV-N083","historical_note_id":"T140","title":"Later believers, reward and distinct report forms","content":"Ibn ʿAjība distinguishes the reward of a deed from the performer’s overall rank in certainty and knowledge of God. That distinction governs his reconciliation of praise for later believers with the Companions’ precedence. The rain comparison occurs in al-Tirmidhī, no. 2869. The longer brotherhood passage is separately quoted with the author’s qualification ‘or words to that effect.’ A relevant reward tradition in Abū Dāwūd, no. 4341, gives fifty, not Cairo’s seventy, and has a different setting. It is a variant parallel; it does not establish Cairo’s number or authenticate the longer combination of sayings.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:393; Q3:110–112","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-tirmidhi","locator":"Al-Jāmiʿ, no.2869, V:151–152","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0279Tirmidhi/0279Tirmidhi.Sunan/0279Tirmidhi.Sunan.Shamela0001435-ara1","local_file":"audit_work/revision_XIV_research/public_sources/tirmidhi.txt","bounded_arabic":"مثل أمتي مثل المطر","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Rain comparison and following compiler comment read.","title":"Jāmiʿ al-Tirmidhī"},{"source_id":"XIV-OT-abu_dawud","locator":"Sunan, no.4341","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0275AbuDawudSijistani/0275AbuDawudSijistani.Sunan/0275AbuDawudSijistani.Sunan.Shamela0001726-ara1","local_file":"audit_work/revision_XIV_research/public_sources/abu_dawud.txt","bounded_arabic":"أجر خمسين منكم","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Complete days-of-patience report read; number and setting differ.","title":"Sunan Abī Dāwūd"}],"scope":[{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"The virtue of the Muhammadan community","anchor_paragraph":"The earliest members of the community do not have an exclusive claim to praise over its later members, in view of the saying: “My community is like rain: one does not know whether its beginning is better or its end.” Another report describes the Prophet saying: “I long for my brothers.” His companions asked: “Are we not your brothers, Messenger of God?” He replied: “You are my companions. My brothers are people who will come after me, believe in me without having seen me, and one of them would desire to see me even in exchange for everything he owns. The work of one of them is equal to the work of seventy of you.” They asked: “Of them or of us?” He said: “Of you.” “Why is that, Messenger of God?” “Because you found helpers in goodness and they found no helpers in it,” or words to that effect, as Ibn ʿAjība himself qualifies the quotation. [XIV-N083]","cairo_printed_pages":[393],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Neither the rain report nor the fifty-rewards tradition verifies Cairo’s entire longer quotation as one continuous report.","source":"Cairo-Ruslan-I: I:393; Q3:110–112; XIV-OT-tirmidhi: Al-Jāmiʿ, no.2869, V:151–152; XIV-OT-abu_dawud: Sunan, no.4341","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"[The virtue of the Muhammadan community]","anchor_paragraph":"The earliest members of the community do not have an exclusive claim to praise over its later members, in view of the saying: “My community is like rain: one does not know whether its beginning is better or its end.” Another report describes the Prophet saying: “I long for my brothers.” His companions asked: “Are we not your brothers, Messenger of God?” He replied: “You are my companions. My brothers are people who will come after me, believe in me without having seen me, and one of them would desire to see me even in exchange for everything he owns. The work of one of them is equal to the work of seventy of you.” They asked: “Of them or of us?” He said: “Of you.” “Why is that, Messenger of God?” “Because you found helpers in goodness and they found no helpers in it,” or words to that effect, as Ibn ʿAjība himself qualifies the quotation. [T140]","cairo_printed_pages":[393]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T140; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T140","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T140","original_body_sha256":"6e3f338177695da6abb51e8faac521d6af2ca2f23eb929e507baae54bbcb6ade","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":104,"print_label":"T104","linked_occurrences":[{"record_id":"q3-110-112","segment_index":1,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396"}]},{"id":"XIV-N084","historical_note_id":"T141","title":"The Iḥyāʾ ranking in its wider context","content":"Al-Ghazālī’s corresponding discussion in the Iḥyāʾ, I:52–53, ranks prophets, friends of God, firmly grounded scholars and the righteous while explaining the aims of learning. Its surrounding argument explicitly warns against despising other useful sciences merely because they stand below the highest rank. Ibn ʿAjība extracts the ranking to support the precedence of knowledge of God over knowledge of legal rulings. The wider context thus preserves a hierarchy without turning it into a dismissal of legal scholarship. The subsequent statement attributed to Ibn Rushd through al-Miʿyār is a separate cited judgment; it should not be folded into al-Ghazālī’s quotation.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:394; Q3:110–112","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-ihya","locator":"Iḥyāʾ ʿulūm al-dīn, I:52–53","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0505Ghazali/0505Ghazali.IhyaCulumDin/0505Ghazali.IhyaCulumDin.Shamela0009472-ara1.completed","local_file":"audit_work/revision_XIV_research/public_sources/ihya.txt","bounded_arabic":"فلا تظن أن ما نزل عن الرتبة القصوى ساقط القدر","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Ranking and caution against despising other sciences read in context.","title":"Al-Ghazālī, Iḥyāʾ ʿulūm al-dīn"}],"scope":[{"record_id":"q3-110-112","segment_index":2,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"The Sufis as a community calling to direct witnessing","anchor_paragraph":"In the Iḥyāʾ , when speaking of knowing God and the science of God ( معرفة الله والعلم بالله ), al-Ghazālī says: “The highest rank in that belongs to the prophets, then to the friends of God who know Him, then to scholars deeply established in knowledge, then to the righteous.” He thereby places the friends of God before the scholars. Ibn Rushd says, according to the source cited by Ibn ʿAjība, that what al-Qushayrī and al-Ghazālī say is agreed upon. He adds: “No rational person doubts that those who know God and what perfection must be attributed to Him are better than those who know God’s legal rulings.” Consult the complete discussion in al-Miʿyār . [XIV-N084]","cairo_printed_pages":[394],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The Ibn Rushd/al-Miʿyār transmission remains an attribution reported by Ibn ʿAjība; the Iḥyāʾ parallel does not verify it.","source":"Cairo-Ruslan-I: I:394; Q3:110–112; XIV-OT-ihya: Iḥyāʾ ʿulūm al-dīn, I:52–53","revision_status":"","word_count":98,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-110-112","segment_index":2,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"Spiritual allusion — الإشارة The Sufis as a community calling to direct witnessing","anchor_paragraph":"In the Iḥyāʾ , when speaking of knowing God and the science of God ( معرفة الله والعلم بالله ), al-Ghazālī says: “The highest rank in that belongs to the prophets, then to the friends of God who know Him, then to scholars deeply established in knowledge, then to the righteous.” He thereby places the friends of God before the scholars. Ibn Rushd says, according to the source cited by Ibn ʿAjība, that what al-Qushayrī and al-Ghazālī say is agreed upon. He adds: “No rational person doubts that those who know God and what perfection must be attributed to Him are better than those who know God’s legal rulings.” Consult the complete discussion in al-Miʿyār . [T141]","cairo_printed_pages":[394]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T141; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T141","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T141","original_body_sha256":"432b079ca2e0abacb6b4cb4ff2588428a146095b2c31efa46cc215ae5f44db9d","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":105,"print_label":"T105","linked_occurrences":[{"record_id":"q3-110-112","segment_index":2,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396"}]},{"id":"XIV-N085","historical_note_id":"T142","title":"The protective covenant in the verse’s imagery","content":"The two ‘cords’ are interpreted as binding covenants that secure protection. In the first, Ibn ʿAjība identifies the prescribed dhimma arrangement and explicitly states its consequence: property, life and family are protected against attack. The second extends the covenant image to protection granted by other human authorities. The preceding tent and coin comparisons explain two possible senses of something being ‘laid upon’ or ‘struck upon’ a person. They are alternative images for the persistence of the condition described. The paragraph combines historical polemic with a precise statement of covenantal protection; neither element should disappear through a loose paraphrase of the other.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:395; Q3:110–112","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-110-112","segment_index":4,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"Security, limits on harm and the cause of moral deterioration","anchor_paragraph":"Ibn ʿAjība calls this a prediction of unseen events that subsequently matched what occurred with Banū Qurayẓa, Banū al-Naḍīr, Banū Qaynuqāʿ and Khaybar. In his account, they never raised a victorious standard. Instead, “humiliation has been laid upon them,” shame and abasement surrounding them like a tent spread over its occupants—or adhering to them like the imprint of a stamped coin—“wherever they are found.” They enjoy security only “through a cord from God,” meaning a covenant or guarantee from God, expressed in the dhimma contract ( عقد الذمة ) that God prescribed. When those under it pay the poll tax ( الجزية ), this contract safeguards them: it is forbidden to attack their property, blood or families . The other is “a cord from people,” a covenant granted by other human authorities to those residing under their protection. In sum, humiliation clings to them, and they obtain security only beneath a covenant, either from Muslims or from unbelievers. [XIV-N085]","cairo_printed_pages":[395],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-110-112","segment_index":4,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"Security, limits on harm and the cause of moral deterioration","anchor_paragraph":"“They have incurred wrath from God,” that is, they have returned deserving it; “poverty has been laid upon them,” encircling them. Jews are generally poor and needy, because their hearts are empty of certainty; poverty and anxiety cling to them, even if they possess the entire world. [Translator’s note: This is the commentator’s historically situated polemic.] [XIV-N085]","cairo_printed_pages":[395],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Records the author’s historical exposition and legal vocabulary; it does not present his generalizations as independently verified facts or current legal advice.","source":"Cairo-Ruslan-I: I:395; Q3:110–112","revision_status":"","word_count":101,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-110-112","segment_index":4,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"[Security, limits on harm and the cause of moral deterioration]","anchor_paragraph":"Ibn ʿAjība calls this a prediction of unseen events that subsequently matched what occurred with Banū Qurayẓa, Banū al-Naḍīr, Banū Qaynuqāʿ and Khaybar. In his account, they never raised a victorious standard. Instead, “humiliation has been laid upon them,” shame and abasement surrounding them like a tent spread over its occupants—or adhering to them like the imprint of a stamped coin—“wherever they are found.” They enjoy security only “through a cord from God,” meaning a covenant or guarantee from God, expressed in the dhimma contract ( عقد الذمة ) that God prescribed. When those under it pay the poll tax ( الجزية ), this contract safeguards them: it is forbidden to attack their property, blood or families . The other is “a cord from people,” a covenant granted by other human authorities to those residing under their protection. In sum, humiliation clings to them, and they obtain security only beneath a covenant, either from Muslims or from unbelievers. [T142]","cairo_printed_pages":[395]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T142; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T142","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T142","original_body_sha256":"5b58e61e22b0e75eb9dc3cba4b3021c84eadac577a710b9944074eb906b28e08","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":106,"print_label":"T106","linked_occurrences":[{"record_id":"q3-110-112","segment_index":4,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396"},{"record_id":"q3-110-112","segment_index":4,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396"}]},{"id":"XIV-N086","historical_note_id":"T143","title":"First-person testimony and a differently worded divine saying","content":"The shift to ‘I say’ introduces Ibn ʿAjība’s own testimony about threats of beating, denunciation to the ruler and exile. It should not become a continuation of the Qurʾānic address or of an earlier authority’s words. The paragraph also qualifies protection by admitting that other Sufis suffered visible injury. Its concluding divine saying resembles al-Bukhārī, no. 6502, but Cairo’s adhina bi-l-ḥarb differs from Bukhārī’s first-person ādhantuhu bi-l-ḥarb. The two Arabic constructions differ; the canonical parallel does not establish a first-person verb in the Cairo text at this locus.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:396; Q3:110–112","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-bukhari","locator":"Ṣaḥīḥ, no.6502","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","bounded_arabic":"من عادى لي وليا فقد آذنته بالحرب","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Divine saying inspected with the different first-person verb.","title":"Ṣaḥīḥ al-Bukhārī"}],"scope":[{"record_id":"q3-110-112","segment_index":5,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"Hostility to the friends of God and testimony from the author’s own trials","anchor_paragraph":"I say: They threatened to beat us, report us to the ruler, and banish us to the land of the Christians, yet they accomplished none of it. Some Sufis have indeed undergone such treatment, which only increased their honour and dignity. One who censures the Sufis, says Ibn ʿAjība, remains in distress, sorrow, humiliation and need because his inward being is ruined of the light of certainty. Criticism of God’s friends is a wrongdoing, whereas belief in them brings care. If one persists in injuring them, one will meet a bad end and incur God’s anger by wronging His friends: “Whoever harms a friend of Mine is on notice of war.” [Translator’s note: Cairo I:396 prints فقد أذن بالحرب , without a first-person verb. This is read here in the attested sense of adhina bi- , “became aware of,” rather than silently supplying ādhantuhu , “I have notified him”; see Lisān al-ʿArab , s.v. أذن .] May God grant us good manners towards them and allow us to die loving them. Amen. [XIV-N086]","cairo_printed_pages":[396],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The Bukhārī source does not verify the author’s autobiographical claims or remove the local textual difference.","source":"Cairo-Ruslan-I: I:396; Q3:110–112; XIV-OT-bukhari: Ṣaḥīḥ, no.6502","revision_status":"","word_count":94,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-110-112","segment_index":5,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396","segment_title":"Spiritual allusion — الإشارة Hostility to the friends of God and testimony from the author’s own trials","anchor_paragraph":"I say: They threatened to beat us, report us to the ruler, and banish us to the land of the Christians, yet they accomplished none of it. Some Sufis have indeed undergone such treatment, which only increased their honour and dignity. One who censures the Sufis, says Ibn ʿAjība, remains in distress, sorrow, humiliation and need because his inward being is ruined of the light of certainty. Criticism of God’s friends is a wrongdoing, whereas belief in them brings care. If one persists in injuring them, one will meet a bad end and incur God’s anger by wronging His friends: “Whoever harms a friend of Mine is on notice of war.” [Translator’s note: Cairo I:396 prints فقد أذن بالحرب , without a first-person verb. This is read here in the attested sense of adhina bi- , “became aware of,” rather than silently supplying ādhantuhu , “I have notified him”; see Lisān al-ʿArab , s.v. أذن .] May God grant us good manners towards them and allow us to die loving them. Amen. [T143]","cairo_printed_pages":[396]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T143; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T143","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T143","original_body_sha256":"1dc3530173433024df4c127afb28956996abb999517e2a0648243198e7092e68","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":107,"print_label":"T107","linked_occurrences":[{"record_id":"q3-110-112","segment_index":5,"q":"3:110–112","source":"Cairo print · Volume I, pp. 392–396"}]},{"id":"XIV-N087","historical_note_id":"T144","title":"Kafara with the sense of withholding recompense","content":"The verb is explained here through semantic inclusion: kafara carries the sense of depriving or withholding and takes the construction appropriate to that meaning. The promise is consequently that good will not be denied its recompense, rather than a prediction that the people addressed will cease to disbelieve. The following exposition confirms this by pairing denial with recognition and reward. ‘You’ represents the persons concerned, while the pronoun ‘it’ points back to the good performed or its recompense. The account of the two objects concerns the underlying construction; the passive construction means ‘you shall not be deprived of it.’","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:396,397; Q3:113–115","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-113-115","segment_index":0,"q":"3:113–115","source":"Cairo print · Volume I, pp. 396–397","segment_title":"The upright community, hours of night and “denying” recompense","anchor_paragraph":"I say: “Upright” ( قائمة ) means straight or sound ( مستقيمة ), as in aqamtu al-ʿūd fa-qāma, “I set the stick straight, so it stood upright”; or it means “carrying out God’s command.” “Through the hours of the night” ( آناء الليل ) is an adverbial time expression ( ظرف ); the singular is iny ( إِنْي ), with kasra on the hamza and an unvowelled nūn, like niḥy/anḥāʾ ( نِحْي/أَنْحَاء ); or inā ( إِنًى ), like miʿā/amʿāʾ ( مِعًى/أَمْعَاء ), according to the forms transmitted here. “You shall not be denied it” ( لن تكفروه ) means “you shall not be deprived of it.” Kafara is here used with two objects ( مفعولين ) because it incorporates the meaning of “deprive” ( حرم ) or “withhold” ( منع ). [XIV-N087]","cairo_printed_pages":[396,397],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The alternative singular forms for ānāʾ are reported by the commentary; their historical derivation is not independently established.","source":"Cairo-Ruslan-I: I:396,397; Q3:113–115","revision_status":"","word_count":105,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-113-115","segment_index":0,"q":"3:113–115","source":"Cairo print · Volume I, pp. 396–397","segment_title":"[The upright community, hours of night and “denying” recompense]","anchor_paragraph":"I say: “Upright” ( قائمة ) means straight or sound ( مستقيمة ), as in aqamtu al-ʿūd fa-qāma, “I set the stick straight, so it stood upright”; or it means “carrying out God’s command.” “Through the hours of the night” ( آناء الليل ) is an adverbial time expression ( ظرف ); the singular is iny ( إِنْي ), with kasra on the hamza and an unvowelled nūn, like niḥy/anḥāʾ ( نِحْي/أَنْحَاء ); or inā ( إِنًى ), like miʿā/amʿāʾ ( مِعًى/أَمْعَاء ), according to the forms transmitted here. “You shall not be denied it” ( لن تكفروه ) means “you shall not be deprived of it.” Kafara is here used with two objects ( مفعولين ) because it incorporates the meaning of “deprive” ( حرم ) or “withhold” ( منع ). [T144]","cairo_printed_pages":[396,397]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T144; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T144","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T144","original_body_sha256":"a5dd6d065d2fb00e6d570323e1a359d8403049b0582aef2af50c2887fe2faedc","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":108,"print_label":"T108","linked_occurrences":[{"record_id":"q3-113-115","segment_index":0,"q":"3:113–115","source":"Cairo print · Volume I, pp. 396–397"}]},{"id":"XIV-N088","historical_note_id":"T145","title":"Night prayer and the scope of its supporting report","content":"The commentary gives several senses of an ‘upright’ community and then offers night prayer as a particular explanation of the nocturnal worship. Al-Bukhārī, no. 567, reports a delayed ʿishāʾ prayer and the reassurance that no one else was praying at that hour. The scene concerns a particular occasion and audience. Its wording should not be expanded into a historical claim that no other religious community ever prayed at night. Ibn ʿAjība’s broader contrast and identification of the praised group belong to his exegesis. The report supports the night-prayer illustration while remaining distinct from the commentator’s general characterization of other groups.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:397; Q3:113–115","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-bukhari","locator":"Ṣaḥīḥ, no.567","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","bounded_arabic":"ليس أحد من الناس يصلي هذه الساعة غيركم","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Complete delayed-prayer narrative inspected with the reporter’s wording variation.","title":"Ṣaḥīḥ al-Bukhārī"}],"scope":[{"record_id":"q3-113-115","segment_index":1,"q":"3:113–115","source":"Cairo print · Volume I, pp. 396–397","segment_title":"The worshippers among the People of the Book","anchor_paragraph":"The Real, exalted is His majesty, says: The People of the Book “are not all alike” in unbelief and hostility. Rather, among them is “a community,” that is, a group, “upright,” practicing justice and steadfast in religion, or rising to fulfil God’s command, or standing in prayer, “reciting God’s signs” during their night vigil “through the hours of the night,” meaning its periods, “while they prostrate” in their prayers. Or the reference is to the night prayer ( صلاة العشاء ), which the People of the Book do not perform: it is related that the Prophet, blessings and peace be upon him, once delayed that prayer, then came out while the people were waiting and said, “Rejoice, for there is no one among the inhabitants of earth praying at this hour other than you.” [XIV-N088]","cairo_printed_pages":[397],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-113-115","segment_index":1,"q":"3:113–115","source":"Cairo print · Volume I, pp. 396–397","segment_title":"The worshippers among the People of the Book","anchor_paragraph":"He then describes them through faith: “They believe in God and the Last Day, enjoin what is right, forbid what is wrong, and hasten to good deeds.” They are ʿAbd Allāh ibn Salām and his companions who accepted Islam from among the Jews. God Most High has described them with distinctive qualities not found among the Jews: the latter deviate from the truth and are not devoted to worship; they associate partners with God and deviate concerning His attributes; they describe the Last Day with qualities other than its own; they compromise in enjoining right and forbidding wrong; and they are slow to do good—unlike the description given of those among them who embraced Islam. [Translator’s note: These generalized contrasts belong to the commentator’s polemic.] “They are among the righteous”: those whose condition is sound before God, who deserve His pleasure and praise. Such is God’s practice towards His servants: when a servant draws near to Him by a handspan, He draws near by an arm’s length. [XIV-N088]","cairo_printed_pages":[397],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The Bukhārī parallel verifies the particular prayer report’s core, not the full comparative polemic or exclusive identification of the verse’s referents.","source":"Cairo-Ruslan-I: I:397; Q3:113–115; XIV-OT-bukhari: Ṣaḥīḥ, no.567","revision_status":"","word_count":100,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-113-115","segment_index":1,"q":"3:113–115","source":"Cairo print · Volume I, pp. 396–397","segment_title":"[The worshippers among the People of the Book]","anchor_paragraph":"The Real, exalted is His majesty, says: The People of the Book “are not all alike” in unbelief and hostility. Rather, among them is “a community,” that is, a group, “upright,” practicing justice and steadfast in religion, or rising to fulfil God’s command, or standing in prayer, “reciting God’s signs” during their night vigil “through the hours of the night,” meaning its periods, “while they prostrate” in their prayers. Or the reference is to the night prayer ( صلاة العشاء ), which the People of the Book do not perform: it is related that the Prophet, blessings and peace be upon him, once delayed that prayer, then came out while the people were waiting and said, “Rejoice, for there is no one among the inhabitants of earth praying at this hour other than you.” [T145]","cairo_printed_pages":[397]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T145; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T145","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T145","original_body_sha256":"2798e2ea37daf90c443220220a0bdc1048ec3ac42e6eb888f6e51af7d1ede366","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":109,"print_label":"T109","linked_occurrences":[{"record_id":"q3-113-115","segment_index":1,"q":"3:113–115","source":"Cairo print · Volume I, pp. 396–397"},{"record_id":"q3-113-115","segment_index":1,"q":"3:113–115","source":"Cairo print · Volume I, pp. 396–397"}]},{"id":"XIV-N089","historical_note_id":"T146","title":"What wealth and children cannot do","content":"The verb translated ‘avail’ concerns their inability to provide protection or benefit against the judgment described. It does not say that wealth and children have no value in every setting. The explanatory addition ‘against God’s punishment’ makes the relation expressed by min Allāh intelligible in this context. Ibn ʿAjība then explains ‘companions of the Fire’ through inseparability: companionship supplies an image of remaining constantly with something, while the following clause makes duration explicit. The preceding passage had promised that good would not be denied its reward; the contrast here turns on the stated condition of disbelief, not on possession or parenthood as such.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:397,398; Q3:116","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-116","segment_index":0,"q":"3:116","source":"Cairo print · Volume I, pp. 397–398","segment_title":"Possessions offer no exemption from divine judgment","anchor_paragraph":"The Real, exalted is His majesty, says: “Those who disbelieve,” denying what the Messenger, blessings and peace be upon him, has brought, will find that “neither their wealth nor their children will avail them anything” against God’s punishment. “They are the companions of the Fire”: they remain inseparable from it, as a man remains with his companion; “they abide therein.” [XIV-N089]","cairo_printed_pages":[397,398],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"A lexical and contextual account of the verse as expounded here; no additional judgment about individuals is supplied.","source":"Cairo-Ruslan-I: I:397,398; Q3:116","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-116","segment_index":0,"q":"3:116","source":"Cairo print · Volume I, pp. 397–398","segment_title":"[Possessions offer no exemption from divine judgment]","anchor_paragraph":"The Real, exalted is His majesty, says: “Those who disbelieve,” denying what the Messenger, blessings and peace be upon him, has brought, will find that “neither their wealth nor their children will avail them anything” against God’s punishment. “They are the companions of the Fire”: they remain inseparable from it, as a man remains with his companion; “they abide therein.” [T146]","cairo_printed_pages":[397,398]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T146; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T146","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T146","original_body_sha256":"a6c735cb67448ada90ed7707b38d70f266c9731ce04f89017a376265a472954f","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":110,"print_label":"T110","linked_occurrences":[{"record_id":"q3-116","segment_index":0,"q":"3:116","source":"Cairo print · Volume I, pp. 397–398"}]},{"id":"XIV-N090","historical_note_id":"T147","title":"Making the terms of the wind comparison explicit","content":"Without the supplied terms, the wording appears to compare expenditure directly with a wind. Ibn ʿAjība makes the parallel explicit by adding loss or destruction on both sides: the wasting of expenditure resembles the ruin produced by the wind. Al-Bayḍāwī, II:33–34, discusses the same difficulty as a composite comparison and permits an understood object destroyed by the wind. Both analyses make explicit the terms understood in the comparison. Cairo also preserves different explanations of ṣirr. Piercing cold is the one developed in the subsequent exposition; the alternatives should not be silently combined into a single meteorological description.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:398; Q3:117","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-baydawi","locator":"Anwār al-tanzīl, II:33–34, Q3:117","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0685NasirDinBaydawi/0685NasirDinBaydawi.AnwarTanzil/0685NasirDinBaydawi.AnwarTanzil.Shamela0023588-ara1","local_file":"audit_work/revision_XIV_research/public_sources/baydawi.txt","bounded_arabic":"ويجوز أن يقدر كمثل مهلك ريح وهو الحرث","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Full composite-simile explanation and continuation inspected.","title":"Al-Bayḍāwī, Anwār al-tanzīl"}],"scope":[{"record_id":"q3-117","segment_index":0,"q":"3:117","source":"Cairo print · Volume I, pp. 398–399","segment_title":"An implied verb of destruction and the meanings of ṣirr (صِرّ)","anchor_paragraph":"I say: An ellipsis ( حذف ) is present in the discourse: “The likeness of the loss of what they spend is like the destruction brought about by a wind,” and so forth. The ṣirr ( الصِّرّ ) is piercing cold. Or the phrase signifies a wind containing a sound and cold; or a scorching, poisonous hot wind ( السموم الحارة ). [XIV-N090]","cairo_printed_pages":[398],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The Bayḍāwī comparison is related but not identical to Cairo’s particular supplied wording; lexical alternatives are reported, not physically explained.","source":"Cairo-Ruslan-I: I:398; Q3:117; XIV-OT-baydawi: Anwār al-tanzīl, II:33–34, Q3:117","revision_status":"","word_count":102,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-117","segment_index":0,"q":"3:117","source":"Cairo print · Volume I, pp. 398–399","segment_title":"[An implied verb of destruction and the meanings of ṣirr (صِرّ)]","anchor_paragraph":"I say: An ellipsis ( حذف ) is present in the discourse: “The likeness of the loss of what they spend is like the destruction brought about by a wind,” and so forth. The ṣirr ( الصِّرّ ) is piercing cold. Or the phrase signifies a wind containing a sound and cold; or a scorching, poisonous hot wind ( السموم الحارة ). [T147]","cairo_printed_pages":[398]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T147; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T147","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T147","original_body_sha256":"22b20e39f5c2f3d48299aaaa6886fd2db085358753a6563987ae19aa2435a282","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":111,"print_label":"T111","linked_occurrences":[{"record_id":"q3-117","segment_index":0,"q":"3:117","source":"Cairo print · Volume I, pp. 398–399"}]},{"id":"XIV-N091","historical_note_id":"T148","title":"Expenditure, crops and the pronouns of destruction","content":"The list of expenditures supplies alternative applications of the comparison: offerings, ostentatious spending and support directed toward religious authorities. The unifying feature in the commentator’s argument is their eventual lack of benefit, not the identity of their recipients. Ḥarth denotes cultivated growth here, which explains why the wind can destroy it and leave a bare surface. The final denial of injustice refers back to the persons whose conduct, in the exposition’s account, makes their efforts fruitless. Preserving the distinction between the expenditure, the crop that illustrates it and the people responsible keeps the pronouns from turning the simile into a literal account of one particular storm.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:398; Q3:117","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-117","segment_index":1,"q":"3:117","source":"Cairo print · Volume I, pp. 398–399","segment_title":"The expenditure that yields no lasting benefit","anchor_paragraph":"The Real, exalted is His majesty, says: What the unbelievers expend, whether as a devotional offering ( قربة ) or for boasting and reputation ( مفاخرة وسمعة ); or what the lowly among the Jews expend upon their learned authorities; or what the hypocrites expend ostentatiously ( رياء ) or out of fear—is like a wind containing severe cold that strikes the cultivated land ( حَرْث ) of some people, that is, their growing crops, and ruins and destroys them. The intended comparison is between their expenditure and deeds, in their perishing, being wasted and bringing them no benefit, and the cultivation of unbelievers struck by a freezing wind that lays it waste. It becomes a smooth, bare expanse, yielding no benefit in this world or the next. God did not wrong them by letting their works go to waste without a cause: they wronged themselves by committing the unbelief that made their works fruitless. [XIV-N091]","cairo_printed_pages":[398],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The note analyses the commentator’s chosen applications; it does not authenticate a specific historical expenditure or storm.","source":"Cairo-Ruslan-I: I:398; Q3:117","revision_status":"","word_count":106,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-117","segment_index":1,"q":"3:117","source":"Cairo print · Volume I, pp. 398–399","segment_title":"[The expenditure that yields no lasting benefit]","anchor_paragraph":"The Real, exalted is His majesty, says: What the unbelievers expend, whether as a devotional offering ( قربة ) or for boasting and reputation ( مفاخرة وسمعة ); or what the lowly among the Jews expend upon their learned authorities; or what the hypocrites expend ostentatiously ( رياء ) or out of fear—is like a wind containing severe cold that strikes the cultivated land ( حَرْث ) of some people, that is, their growing crops, and ruins and destroys them. The intended comparison is between their expenditure and deeds, in their perishing, being wasted and bringing them no benefit, and the cultivation of unbelievers struck by a freezing wind that lays it waste. It becomes a smooth, bare expanse, yielding no benefit in this world or the next. God did not wrong them by letting their works go to waste without a cause: they wronged themselves by committing the unbelief that made their works fruitless. [T148]","cairo_printed_pages":[398]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T148; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T148","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T148","original_body_sha256":"ccde800dbdfee2077759761d9020c53af6cf42ed7cfb578aeb3b89f7a804a116","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":112,"print_label":"T112","linked_occurrences":[{"record_id":"q3-117","segment_index":1,"q":"3:117","source":"Cairo print · Volume I, pp. 398–399"}]},{"id":"XIV-N092","historical_note_id":"T149","title":"A jussive that retains a final vowel","content":"The conditional sequence explains why lā yaḍurrukum is analysed as jussive despite the audible final ḍamma in the assimilated form. Ibn ʿAjība derives it from the unassimilated pair of rāʾ consonants and explains the remaining vowel through phonetic agreement with the preceding ḍamma. The vowel is therefore not taken as evidence that the verb has escaped the conditional construction. This discussion should also remain distinct from the preceding statement that ḍayr and ḍurr share a meaning: lexical equivalence does not make their conjugations identical. Earlier in the paragraph, mā in mā ʿanittum converts a clause into the sense of ‘your hardship.’","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:399; Q3:118–120","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-118-120","segment_index":0,"q":"3:118–120","source":"Cairo print · Volume I, pp. 399–401","segment_title":"Biṭāna (بِطانة), alw (أَلْو), ʿanat (عَنَت), and the jussive lā yaḍurrukum","anchor_paragraph":"In “what brings you hardship” ( ما عنتم ), mā ( ما ) is a particle converting the clause to a verbal-noun sense ( مصدرية ); ʿanat ( العنت ) signifies fatigue and hardship. Anāmil ( الأنامل ) is the plural of anmula ( أنملة ), pronounced with either ḍamma or fatḥa on the mīm. Ḍayr ( الضير ) and ḍurr ( الضر ) mean much the same: their imperfect verbs are respectively yaḍīru ( يضير ) and yaḍurru ( يضر ). The latter occurs here in the jussive ( مجزوم ). Its underlying form is yaḍrurkum ( يضرُركم ); the vowel of the first rāʾ is transferred to the ḍād and the remaining rāʾ is given ḍamma to agree with the ḍād's vowel, producing a phonetic harmony ( مشاكلة ). [XIV-N092]","cairo_printed_pages":[399],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The analysis explains the morphology and syntax stated in Cairo; it does not establish a different Qurʾānic reading.","source":"Cairo-Ruslan-I: I:399; Q3:118–120","revision_status":"","word_count":101,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-118-120","segment_index":0,"q":"3:118–120","source":"Cairo print · Volume I, pp. 399–401","segment_title":"[Biṭāna (بِطانة), alw (أَلْو), ʿanat (عَنَت), and the jussive lā yaḍurrukum]","anchor_paragraph":"In “what brings you hardship” ( ما عنتم ), mā ( ما ) is a particle converting the clause to a verbal-noun sense ( مصدرية ); ʿanat ( العنت ) signifies fatigue and hardship. Anāmil ( الأنامل ) is the plural of anmula ( أنملة ), pronounced with either ḍamma or fatḥa on the mīm. Ḍayr ( الضير ) and ḍurr ( الضر ) mean much the same: their imperfect verbs are respectively yaḍīru ( يضير ) and yaḍurru ( يضر ). The latter occurs here in the jussive ( مجزوم ). Its underlying form is yaḍrurkum ( يضرُركم ); the vowel of the first rāʾ is transferred to the ḍād and the remaining rāʾ is given ḍamma to agree with the ḍād's vowel, producing a phonetic harmony ( مشاكلة ). [T149]","cairo_printed_pages":[399]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T149; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T149","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T149","original_body_sha256":"c0a2c4c3d2fbd4f18c83997a7a3d6cab2365118006fa0ba0e1211b7c218131b6","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":113,"print_label":"T113","linked_occurrences":[{"record_id":"q3-118-120","segment_index":0,"q":"3:118–120","source":"Cairo print · Volume I, pp. 399–401"}]},{"id":"XIV-N093","historical_note_id":"T150","title":"Biṭāna as privileged access to inner affairs","content":"The garment image explains why biṭāna is stronger than an unspecified acquaintance. Ibn ʿAjība defines the people concerned through access to secrets and internal vulnerabilities, and the ensuing description makes concealed hostility central to the warning. The two occasion accounts identify different possible groups and should remain alternatives. The later command about dying in rage likewise belongs to the passage’s reported rebuke, not to a change in the lexical meaning of biṭāna. ‘Intimate confidants’ expresses the connection between the inner lining, knowledge of concealed affairs and the danger of disclosing those affairs to adversaries.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:399; Q3:118–120","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-118-120","segment_index":1,"q":"3:118–120","source":"Cairo print · Volume I, pp. 399–401","segment_title":"The reported setting and exposure of concealed resentment","anchor_paragraph":"The Real, exalted is His majesty, says: “O you who believe, do not take intimate confidants ( بطانة )”—friends and chosen intimates to whom you disclose your secrets—from people outside your religious community, since “they will not spare any effort to corrupt your affairs,” striving to introduce disorder through confusion and malicious tales, and revealing your vulnerable places to unbelievers. According to one report on the occasion of revelation, it concerned Muslims who maintained close ties with certain Jewish men through kinship and friendship. According to another, it concerned hypocrites whom some Muslims associated with closely. [XIV-N093]","cairo_printed_pages":[399],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"A contextual lexical explanation; the note does not turn either occasion report into an independently established historical setting.","source":"Cairo-Ruslan-I: I:399; Q3:118–120","revision_status":"","word_count":98,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-118-120","segment_index":1,"q":"3:118–120","source":"Cairo print · Volume I, pp. 399–401","segment_title":"[The reported setting and exposure of concealed resentment]","anchor_paragraph":"The Real, exalted is His majesty, says: “O you who believe, do not take intimate confidants ( بطانة )”—friends and chosen intimates to whom you disclose your secrets—from people outside your religious community, since “they will not spare any effort to corrupt your affairs,” striving to introduce disorder through confusion and malicious tales, and revealing your vulnerable places to unbelievers. According to one report on the occasion of revelation, it concerned Muslims who maintained close ties with certain Jewish men through kinship and friendship. According to another, it concerned hypocrites whom some Muslims associated with closely. [T150]","cairo_printed_pages":[399]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T150; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T150","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T150","original_body_sha256":"abda1c3a9019120c2f9465beec12ab88dd6a8c9cc56176896c0d6415db0cb940","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":114,"print_label":"T114","linked_occurrences":[{"record_id":"q3-118-120","segment_index":1,"q":"3:118–120","source":"Cairo print · Volume I, pp. 399–401"}]},{"id":"XIV-N094","historical_note_id":"T151","title":"What the allusion asks the disciple to guard against","content":"The allusion transfers the outward warning about confidants to disclosure of spiritual secrets. Its closing instruction adds a specifically inward object to Godfearingness: witnessing ‘otherness’ in those who cause harm. This concerns how the disciple understands the encounter within divine agency, not a claim that hostility was never expressed. The paired benefits and ordeals are likewise interpreted through the vocabulary of spiritual opening, witnessing and knowledge. The conclusion combines patience toward other people with vigilance over one’s own perception. That combination should remain visible, rather than reducing the instruction to mere secrecy or to a promise that no painful event can occur.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:400,401; Q3:118–120","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-118-120","segment_index":2,"q":"3:118–120","source":"Cairo print · Volume I, pp. 399–401","segment_title":"The discipline of confidence among the spiritually realized","anchor_paragraph":"If good touches you, O spiritual poor—honour, an opening ( فتح ), witnessing ( شهود ) or knowledge of God ( معرفة )—it distresses them; if an ordeal or calamity befalls you, they rejoice. But if you patiently endure their harshness and estrangement, and guard against the perception of anything-other-than-God ( شهود السوى ) in them, their plotting will not harm you. “God encompasses all that they do.” [XIV-N094]","cairo_printed_pages":[400,401],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"An interpretation of the immediate allusive context; no unqualified immunity from physical harm is inferred.","source":"Cairo-Ruslan-I: I:400,401; Q3:118–120","revision_status":"","word_count":102,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-118-120","segment_index":2,"q":"3:118–120","source":"Cairo print · Volume I, pp. 399–401","segment_title":"Spiritual allusion — الإشارة The discipline of confidence among the spiritually realized","anchor_paragraph":"If good touches you, O spiritual poor—honour, an opening ( فتح ), witnessing ( شهود ) or knowledge of God ( معرفة )—it distresses them; if an ordeal or calamity befalls you, they rejoice. But if you patiently endure their harshness and estrangement, and guard against the perception of anything-other-than-God ( شهود السوى ) in them, their plotting will not harm you. “God encompasses all that they do.” [T151]","cairo_printed_pages":[400,401]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T151; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T151","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T151","original_body_sha256":"6afc88b4bea7f4692ace2bc533d083c9f5fe1a9fff527cbaa12819ff64ee056f","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":115,"print_label":"T115","linked_occurrences":[{"record_id":"q3-118-120","segment_index":2,"q":"3:118–120","source":"Cairo print · Volume I, pp. 399–401"}]},{"id":"XIV-N095","historical_note_id":"T152","title":"Counsel before Uḥud and the subsequent decision","content":"The argument for remaining inside Madīna is presented as counsel within the narrative, even though Ibn ʿAjība identifies Ibn Ubayy among its advocates. The Prophet’s initial approval concerns that tactical proposal. The following paragraph then supplies competing counsel and the decision to march out. The initial approval is distinct from the final decision to march; the adviser’s particular proposal is also distinct from the commentator’s assessment of his character. The conditional alternatives—enemy remaining outside, entering the town or withdrawing—are the structure of the defensive argument. They should be kept parallel, with each consequence attached to its own condition.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:401; Q3:121–122","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402","segment_title":"The dispositions at the beginning of Uḥud","anchor_paragraph":"Ibn Ubayy and most of the Helpers said: “Messenger of God, remain in Madīna; do not march out to them. By God, whenever we have gone out from it to meet an enemy, that enemy has inflicted losses on us; and whenever an enemy has entered it, we have inflicted losses on him. How much more so with you among us? Leave them! If they stay, they stay in a very bad place of confinement; if they enter, our men will fight them face-to-face, while our women and children cast stones at them; and if they retreat, they will go back humbled.” The Prophet approved this judgment. [XIV-N095]","cairo_printed_pages":[401],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Explains the transmitted consultation’s logic and voices; the detailed event chronology is not independently authenticated by this note.","source":"Cairo-Ruslan-I: I:401; Q3:121–122","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402","segment_title":"[The dispositions at the beginning of Uḥud]","anchor_paragraph":"Ibn Ubayy and most of the Helpers said: “Messenger of God, remain in Madīna; do not march out to them. By God, whenever we have gone out from it to meet an enemy, that enemy has inflicted losses on us; and whenever an enemy has entered it, we have inflicted losses on him. How much more so with you among us? Leave them! If they stay, they stay in a very bad place of confinement; if they enter, our men will fight them face-to-face, while our women and children cast stones at them; and if they retreat, they will go back humbled.” The Prophet approved this judgment. [T152]","cairo_printed_pages":[401]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T152; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T152","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T152","original_body_sha256":"c9166931cfca900ccc0a88d5e88b2018b3207ac92996d372022b11b46e0eb683","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":116,"print_label":"T116","linked_occurrences":[{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402"}]},{"id":"XIV-N096","historical_note_id":"T153","title":"The dream’s images and their interpretations","content":"The narrative alternates between images seen in a dream and the meanings assigned to them: slaughtered cattle, a damaged sword and protective armour. Dhubāb al-sayf denotes the sword’s point here, not a fly; the defect belongs to that part of the weapon. Muslim, no. 2272, contains a related dream of a sword’s broken forepart and cattle interpreted through the losses at Uḥud, but its sequence and wording differ and it does not supply this entire consultation speech. The comparison supports the dream motifs while leaving Cairo’s precise arrangement, armour image and ensuing exchange as separately transmitted material.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:401,402; Q3:121–122","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-muslim","locator":"Ṣaḥīḥ, no.2272","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0261Muslim/0261Muslim.Sahih/0261Muslim.Sahih.Shamela0001727-ara1.mARkdown","local_file":"audit_work/revision_XIV_research/public_sources/muslim.txt","bounded_arabic":"هززت سيفا فانقطع صدره","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Full related dream read; different sword description and sequence.","title":"Ṣaḥīḥ Muslim"}],"scope":[{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402","segment_title":"The dispositions at the beginning of Uḥud","anchor_paragraph":"Other Companions urged him: “Messenger of God, lead us out against those dogs, so that they do not think we have proved cowardly or weak before them.” The Prophet replied: “I saw in my dream cattle being slaughtered, and interpreted them as men from my Companions who would be killed. I saw a chip at the point of my sword, and interpreted it as defeat. I saw myself placing my hand inside a strong coat of mail, and interpreted it as Madīna. If you think it best to remain in Madīna and leave the enemy where they are, do so.” [XIV-N096]","cairo_printed_pages":[401,402],"anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402","segment_title":"The dispositions at the beginning of Uḥud","anchor_paragraph":"Some men who had missed Badr, whom God would honour with martyrdom at Uḥud, insisted upon marching out against the enemy. They pressed the case until the Prophet entered and put on his coat of armour ( لأمة ). When they saw him armed they regretted their insistence, saying: “We did badly in advising the Prophet when revelation comes to him.” They stood and apologised: “Do whatever seems best to you.” The Prophet replied: “A prophet should not put on his coat of mail and then take it off until he has fought.” [XIV-N096]","cairo_printed_pages":[401,402],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The Muslim parallel is partial; it is not full authentication of every image and sentence in Cairo’s combined narrative.","source":"Cairo-Ruslan-I: I:401,402; Q3:121–122; XIV-OT-muslim: Ṣaḥīḥ, no.2272","revision_status":"","word_count":97,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402","segment_title":"[The dispositions at the beginning of Uḥud]","anchor_paragraph":"Other Companions urged him: “Messenger of God, lead us out against those dogs, so that they do not think we have proved cowardly or weak before them.” The Prophet replied: “I saw in my dream cattle being slaughtered, and interpreted them as men from my Companions who would be killed. I saw a chip at the point of my sword, and interpreted it as defeat. I saw myself placing my hand inside a strong coat of mail, and interpreted it as Madīna. If you think it best to remain in Madīna and leave the enemy where they are, do so.” [T153]","cairo_printed_pages":[401,402]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T153; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T153","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T153","original_body_sha256":"3c7401b3802c4712dcaf73fc30af98671e60f0063bac7e9eccbb5818309c854a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":117,"print_label":"T117","linked_occurrences":[{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402"},{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402"}]},{"id":"XIV-N097","historical_note_id":"T154","title":"An intention interrupted by divine protection","content":"Hammat describes the two groups’ movement toward losing heart, while the continuation records that they remained with the Prophet. The verse’s wording therefore should not be expanded into a claim that both actually withdrew. Jābir’s apparently surprising pleasure in the verse is explained by its declaration that God was their Protector. Al-Bukhārī, no. 4558, preserves his naming of Banū Ḥāritha and Banū Salama and that very reason for welcoming the verse. The source supports this compact identification and interpretation. It does not automatically authenticate every preceding detail about the withdrawal, its location or the number who accompanied Ibn Ubayy.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:402; Q3:121–122","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."},{"source_id":"XIV-OT-bukhari","locator":"Ṣaḥīḥ, no.4558","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","bounded_arabic":"وما يسرني أنها لم تنزل لقول الله والله وليهما","inspection":"Relevant primary-work context actually read in the acquired electronic corpus.","scope":"Jābir’s complete explanation inspected.","title":"Ṣaḥīḥ al-Bukhārī"}],"scope":[{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402","segment_title":"The dispositions at the beginning of Uḥud","anchor_paragraph":"Jābir said: “We would not be pleased if the verse had not been revealed, because of the words ‘God was their Protector.’” Banū Salama belonged to the Khazraj and Banū Ḥāritha to the Aws. “In God let the believers put their trust,” and not in anything else, for there is no other true Helper. [XIV-N097]","cairo_printed_pages":[402],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The canonical parallel applies to Jābir’s comment and the two groups; the longer surrounding battle account has a wider scope.","source":"Cairo-Ruslan-I: I:402; Q3:121–122; XIV-OT-bukhari: Ṣaḥīḥ, no.4558","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402","segment_title":"[The dispositions at the beginning of Uḥud]","anchor_paragraph":"Jābir said: “We would not be pleased if the verse had not been revealed, because of the words ‘God was their Protector.’” Banū Salama belonged to the Khazraj and Banū Ḥāritha to the Aws. “In God let the believers put their trust,” and not in anything else, for there is no other true Helper. [T154]","cairo_printed_pages":[402]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T154; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T154","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T154","original_body_sha256":"b90bbbc7f8533eb07f207aa5ab970e89cf494585b6cf2948bff8e4aa09b981fa","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":118,"print_label":"T118","linked_occurrences":[{"record_id":"q3-121-122","segment_index":0,"q":"3:121–122","source":"Cairo print · Volume I, pp. 401–402"}]},{"id":"XIV-N098","historical_note_id":"T155","title":"The circumstantial force of ‘while you were humbled’","content":"The clause ‘while you were humbled’ describes the believers’ condition when help came to them; it is not the object of the verb ‘He helped you.’ The reference to the pronoun -kum identifies the people whose state the clause supplies. The subsequent exposition explains that condition through small numbers and inadequate equipment, so ‘humbled’ or ‘weak’ belongs to the contrast with the superior force faced at Badr. The place-name story is a separate explanation of the location’s name, not a grammatical premise for that contrast. Its reported derivation should not be mistaken for proof that the verse itself names an individual owner.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:403; Q3:123","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-123","segment_index":0,"q":"3:123","source":"Cairo print · Volume I, pp. 402–403","segment_title":"The well of Badr and the circumstantial clause","anchor_paragraph":"I say: Badr ( بدر ) is a well between Mecca and Madīna that belonged to a man named Badr, after whom the well was named. The expedition in which God gave His Messenger, blessings and peace be upon him, victory occurred at that place; the battle was accordingly named after its location. “While you were humbled” ( وَأَنْتُمْ أَذِلَّةٌ ) is a circumstantial clause ( جملة حال ) referring back to the object-pronoun -kum ( الكاف ) in “He helped you.” Adhilla ( أذلة ) is the plural of dhalīl ( ذليل ), just as aʿizza ( أعزة ) is the plural of ʿazīz ( عزيز ). [XIV-N098]","cairo_printed_pages":[403],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The note explains the syntax and immediate sense; the named-owner etymology is not independently established.","source":"Cairo-Ruslan-I: I:403; Q3:123","revision_status":"","word_count":102,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-123","segment_index":0,"q":"3:123","source":"Cairo print · Volume I, pp. 402–403","segment_title":"[The well of Badr and the circumstantial clause]","anchor_paragraph":"I say: Badr ( بدر ) is a well between Mecca and Madīna that belonged to a man named Badr, after whom the well was named. The expedition in which God gave His Messenger, blessings and peace be upon him, victory occurred at that place; the battle was accordingly named after its location. “While you were humbled” ( وَأَنْتُمْ أَذِلَّةٌ ) is a circumstantial clause ( جملة حال ) referring back to the object-pronoun -kum ( الكاف ) in “He helped you.” Adhilla ( أذلة ) is the plural of dhalīl ( ذليل ), just as aʿizza ( أعزة ) is the plural of ʿazīz ( عزيز ). [T155]","cairo_printed_pages":[403]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T155; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T155","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T155","original_body_sha256":"709fafd7b3bb94c6cc16eba3d84083d02008634d41d5c3915cde624d381da573","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":119,"print_label":"T119","linked_occurrences":[{"record_id":"q3-123","segment_index":0,"q":"3:123","source":"Cairo print · Volume I, pp. 402–403"}]},{"id":"XIV-N099","historical_note_id":"T156","title":"Human attributes and the corresponding divine gift","content":"The saying about realizing one’s attributes depends on the paired examples before it. The attributes to recognize are poverty, weakness, lowliness and need; the aid sought is enrichment, strength and elevation from God. The grammatical contrast is between ‘your’ attributes and ‘His’. It does not instruct the disciple to claim the divine attributes as self-sufficient possessions. In the surrounding allusion, victory at Badr supplies the scriptural example of assistance arriving amid acknowledged weakness. ‘Seeking things in their opposites’ describes that spiritual discipline, while the final command to give thanks returns the argument to reception of a gift rather than self-generated achievement.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:403; Q3:123","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-123","segment_index":2,"q":"3:123","source":"Cairo print · Volume I, pp. 402–403","segment_title":"Created things hidden within their opposites","anchor_paragraph":"God, glorified and exalted, has placed things hidden within their contraries. Therefore whoever seeks honour and victory should realize abasement and destitution ( الذل والمسكنة ); whoever seeks richness should realize poverty ( الفقر ); whoever seeks elevation should realize lowliness and the laying aside of rank; and whoever seeks strength should realize weakness. And so it continues: “Realize your own attributes, and He will assist you with His attributes” ( تحقق بأوصافك يمدك بأوصافه ). O company of disciples, be mindful of God and seek things in their opposites so that you may attain them; thank God for what He has bestowed and He will increase you from His grace and generosity. [XIV-N099]","cairo_printed_pages":[403],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"The available electronic Ḥikam text has a flawed spelling and cannot establish the Arabic wording at this point.","source":"Cairo-Ruslan-I: I:403; Q3:123","revision_status":"","word_count":103,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-123","segment_index":2,"q":"3:123","source":"Cairo print · Volume I, pp. 402–403","segment_title":"Spiritual allusion — الإشارة Created things hidden within their opposites","anchor_paragraph":"God, glorified and exalted, has placed things hidden within their contraries. Therefore whoever seeks honour and victory should realize abasement and destitution ( الذل والمسكنة ); whoever seeks richness should realize poverty ( الفقر ); whoever seeks elevation should realize lowliness and the laying aside of rank; and whoever seeks strength should realize weakness. And so it continues: “Realize your own attributes, and He will assist you with His attributes” ( تحقق بأوصافك يمدك بأوصافه ). O company of disciples, be mindful of God and seek things in their opposites so that you may attain them; thank God for what He has bestowed and He will increase you from His grace and generosity. [T156]","cairo_printed_pages":[403]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T156; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T156","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T156","original_body_sha256":"7b4597fe83d9fe4127c20a1aee797144d6e13cb1d33641762de1f1ac868375bc","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":120,"print_label":"T120","linked_occurrences":[{"record_id":"q3-123","segment_index":2,"q":"3:123","source":"Cairo print · Volume I, pp. 402–403"}]},{"id":"XIV-N100","historical_note_id":"T157","title":"The attachment of idh determines the event","content":"The two grammatical analyses correspond to two accounts of the angelic reinforcement. Attaching idh to ‘He helped you’ links the saying to Badr in the immediately preceding verse. Taking it as a substitute for the earlier ‘when you went forth’ returns the narrative to Uḥud and makes the promise conditional on patience. These are not interchangeable labels for one uncomplicated chronology: the second explanation expressly says the condition was not fulfilled. Taswīm adds a lexical question about marking or distinguishing the angels. Here taswīm concerns the visible identifying marks developed in the following exposition.","evidence":[{"source_id":"Cairo-Ruslan-I","locator":"I:403; Q3:124–125","local_file":"audit_work/revision_XIII/Cairo_Arabic_Pages_XIII.json","inspection":"Full anchored English segment read; Arabic page context checked in the preserved Cairo transcription. No new manuscript claim."}],"scope":[{"record_id":"q3-124-125","segment_index":0,"q":"3:124–125","source":"Cairo print · Volume I, pp. 403–404","segment_title":"The position of idh and the meaning of taswīm","anchor_paragraph":"I say: “When” ( إذ ) is an adverbial of time ( ظرف ) attached to “He helped you” ( نصركم ) if we consider the reinforcement to have occurred solely on the day of Badr. Alternatively, it is a substitute ( بدل ) for “when you went forth” ( إذ غدوت ) if we consider the reinforcement to have been promised at Uḥud conditional upon patience . When they failed to remain patient, it did not take place. Taswīm ( التسويم ) means marking or designating ( التعليم ). [XIV-N100]","cairo_printed_pages":[403],"anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"Records the alternatives transmitted by Ibn ʿAjība; it does not independently decide which battle received the reinforcement.","source":"Cairo-Ruslan-I: I:403; Q3:124–125","revision_status":"","word_count":97,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-124-125","segment_index":0,"q":"3:124–125","source":"Cairo print · Volume I, pp. 403–404","segment_title":"[The position of idh and the meaning of taswīm]","anchor_paragraph":"I say: “When” ( إذ ) is an adverbial of time ( ظرف ) attached to “He helped you” ( نصركم ) if we consider the reinforcement to have occurred solely on the day of Badr. Alternatively, it is a substitute ( بدل ) for “when you went forth” ( إذ غدوت ) if we consider the reinforcement to have been promised at Uḥud conditional upon patience . When they failed to remain patient, it did not take place. Taswīm ( التسويم ) means marking or designating ( التعليم ). [T157]","cairo_printed_pages":[403]}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T157; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T157","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T157","original_body_sha256":"626afdc2605f4413c056e7eac7e0bc1e9e59c8421aa22b3d704495cbc9d9586f","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":121,"print_label":"T121","linked_occurrences":[{"record_id":"q3-124-125","segment_index":0,"q":"3:124–125","source":"Cairo print · Volume I, pp. 403–404"}]},{"id":"XIV-N101","historical_note_id":"T158","title":"The three and five thousand angels","content":"The three numbers belong to a proposed reconciliation of Q3:124–125 with Q8:9: Ibn ʿAjība understands successive reinforcement, rather than three competing totals for one moment. His preceding grammatical discussion also records a different interpretation, relating the promise to Uḥud and making its fulfilment conditional upon steadfastness. The descriptions of turbans and horses are alternatives introduced in the commentary; they are not details specified by the Qurʾān. Likewise, the statement that angels fought only at Badr is presented as Ibn ʿAbbās’s report. Keeping those levels distinct preserves both the commentator’s preferred account and the alternatives he transmits.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[403,404],"quran_context":"3:124–125","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-124-125","segment_index":1,"quran_context":"3:124–125","printed_pages":[403,404],"anchor_paragraph":"The Real, exalted is His majesty, says: God certainly helped you at Badr “when you said to the believers,” after they saw the many troops of the enemy and the fewness of their own equipment and numbers: “Will it not suffice you,” in strength and numbers, “that your Lord reinforce you with three thousand angels,” sent down within clouds? “Yes,” that will suffice you as He has promised, provided that “you are patient” and stand firm, “and are mindful of God,” and the enemy comes against you “at once” ( من فورهم ), meaning swiftly and at this very time, then “your Lord will reinforce you with five thousand angels” without delay or postponement, “marked out” ( مُسَوِّمِينَ ). They were marked with white turbans, except Gabriel, whose turban was yellow. Alternatively, they marked themselves or their horses. It is said that the horses had docked tails; or that they were piebald. Translator’s note: These are differing transmitted descriptions, not a single established visual account. [XIV-N101]","segment_title":"The three and five thousand angels","anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-124-125","segment_index":1,"quran_context":"3:124–125","printed_pages":[403,404],"anchor_paragraph":"If you ask: Why is only one thousand mentioned in Sūrat al-Anfāl, whereas here there are five thousand? The response is that God initially reinforced them with one thousand; their number then reached three thousand; and finally it rose to five thousand. Ibn ʿAbbās said: “The angels fought only on the day of Badr; on other occasions they are present at the battle with us, but do not fight.” End of the cited report. [XIV-N101]","segment_title":"The three and five thousand angels","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [403, 404]","revision_status":"","word_count":96,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-124-125","segment_index":1,"quran_context":"3:124–125","printed_pages":[403,404],"anchor_paragraph":"The Real, exalted is His majesty, says: God certainly helped you at Badr “when you said to the believers,” after they saw the many troops of the enemy and the fewness of their own equipment and numbers: “Will it not suffice you,” in strength and numbers, “that your Lord reinforce you with three thousand angels,” sent down within clouds? “Yes,” that will suffice you as He has promised, provided that “you are patient” and stand firm, “and are mindful of God,” and the enemy comes against you “at once” ( من فورهم ), meaning swiftly and at this very time, then “your Lord will reinforce you with five thousand angels” without delay or postponement, “marked out” ( مُسَوِّمِينَ ). They were marked with white turbans, except Gabriel, whose turban was yellow. Alternatively, they marked themselves or their horses. It is said that the horses had docked tails; or that they were piebald. Translator’s note: These are differing transmitted descriptions, not a single established visual account. [T158]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T158; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T158","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T158","original_body_sha256":"c5d7a220613240e8a07dae8f818bebee295b998c08a58ae4ebd5204eaa2a4d94","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":122,"print_label":"T122","linked_occurrences":[{"record_id":"q3-124-125","segment_index":1,"q":"3:124–125","source":"Cairo print · Volume I, pp. 403–404"},{"record_id":"q3-124-125","segment_index":1,"q":"3:124–125","source":"Cairo print · Volume I, pp. 403–404"}]},{"id":"XIV-N102","historical_note_id":"T159","title":"Hidden lights, angelic support and an episode from the author’s circle","content":"The spiritual application distinguishes inward assistance, expressed as lights and mysteries, from outward angelic support. Fuqarāʾ here means the Sufi companions of the author’s circle, not simply economically poor people. The change to ‘we’ marks an autobiographical claim, but the reported appearance of seventy as seven hundred is expressly qualified by ‘according to what they told us.’ Ibn ʿAjība therefore claims participation in the journey and reception of others’ testimony about its appearance; he does not say that he himself counted seven hundred visible companions. The concluding Qurʾānic echo is Q3:13.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[404],"quran_context":"3:124–125","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-124-125","segment_index":2,"quran_context":"3:124–125","printed_pages":[404],"anchor_paragraph":"Whoever turns toward struggling against his own soul for the sake of God ( جهاد النفس ), and occupies himself with the remembrance of his Master ( ذكر مولاه ), receives from God, inwardly, assistance in lights and mysteries ( الأنوار والأسرار ), and outwardly, the help of noble angels ( الملائكة الأبرار ). This, Ibn ʿAjība says, has been witnessed among the spiritual poor ( الفقراء ) of his own circle: when there were three of them, the common people saw thirty; when thirty, they saw three hundred. “We were once seventy on a journey, but people saw us as seven hundred, according to what they told us.” “And God strengthens with His help whom He wills.” [XIV-N102]","segment_title":"Hidden lights, angelic support and an episode from the author’s circle","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [404]","revision_status":"","word_count":91,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-124-125","segment_index":2,"quran_context":"3:124–125","printed_pages":[404],"anchor_paragraph":"Whoever turns toward struggling against his own soul for the sake of God ( جهاد النفس ), and occupies himself with the remembrance of his Master ( ذكر مولاه ), receives from God, inwardly, assistance in lights and mysteries ( الأنوار والأسرار ), and outwardly, the help of noble angels ( الملائكة الأبرار ). This, Ibn ʿAjība says, has been witnessed among the spiritual poor ( الفقراء ) of his own circle: when there were three of them, the common people saw thirty; when thirty, they saw three hundred. “We were once seventy on a journey, but people saw us as seven hundred, according to what they told us.” “And God strengthens with His help whom He wills.” [T159]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T159; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T159","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T159","original_body_sha256":"c09edb7ef988835ce8caf2ec30f8a6eeb5d0f587e525e65ebdfdf8908ca4c35c","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":123,"print_label":"T123","linked_occurrences":[{"record_id":"q3-124-125","segment_index":2,"q":"3:124–125","source":"Cairo print · Volume I, pp. 403–404"}]},{"id":"XIV-N103","historical_note_id":"T160","title":"An inserted clause between coordinated possibilities","content":"The parenthetical analysis keeps the surrounding verbs within one coordinated account of divine purposes: defeat, frustration, acceptance of repentance, or punishment. ‘You have no part in the matter’ interrupts that sequence without becoming its grammatical governing clause. The alternative assigns aw the exceptional sense ‘unless/except that,’ with explanatory consequences supplied for the Prophet. Al-Bayḍāwī, Q3:128, actually presents both approaches. They are alternative syntactic analyses, not successive additional statements. In both, the surrounding commentary reserves the opponents’ ultimate fate to God while leaving the Prophet’s commissioned warning and struggle intact.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[404],"quran_context":"3:126–129","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-baydawi","work":"baydawi","locator":"Q3:128, between PageV02P036–037","arabic_anchor":"ليس لك من الأمر شيء اعتراض","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0685NasirDinBaydawi/0685NasirDinBaydawi.AnwarTanzil/0685NasirDinBaydawi.AnwarTanzil.Shamela0023588-ara1","local_file":"audit_work/revision_XIV_research/public_sources/baydawi.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-126-129","segment_index":0,"quran_context":"3:126–129","printed_pages":[404],"anchor_paragraph":"I say: “You have no part in the matter” ( ليس لك من الأمر شيء ) is a parenthetical clause ( جملة معترضة ) inserted between “or suppress them” ( أو يكبتهم ) and “or turn toward them” ( أو يتوب عليهم ). Alternatively, the particle aw ( أو ) may carry the force of “except” ( إلا ): “You have no part in the matter, except that if He accepts their repentance you may bring them glad tidings, or if He punishes them you may take satisfaction in their punishment.” This second grammatical account is attributed to al-Bayḍāwī. [XIV-N103]","segment_title":"An inserted clause between coordinated possibilities","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [404]; baydawi: Q3:128, between PageV02P036–037","revision_status":"","word_count":89,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-126-129","segment_index":0,"quran_context":"3:126–129","printed_pages":[404],"anchor_paragraph":"I say: “You have no part in the matter” ( ليس لك من الأمر شيء ) is a parenthetical clause ( جملة معترضة ) inserted between “or suppress them” ( أو يكبتهم ) and “or turn toward them” ( أو يتوب عليهم ). Alternatively, the particle aw ( أو ) may carry the force of “except” ( إلا ): “You have no part in the matter, except that if He accepts their repentance you may bring them glad tidings, or if He punishes them you may take satisfaction in their punishment.” This second grammatical account is attributed to al-Bayḍāwī. [T160]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T160; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T160","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T160","original_body_sha256":"27b3cbc471db49ecc84544dd650598397da463a05cf020451378b7a12735cb8b","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":124,"print_label":"T124","linked_occurrences":[{"record_id":"q3-126-129","segment_index":0,"q":"3:126–129","source":"Cairo print · Volume I, pp. 404–405"}]},{"id":"XIV-N104","historical_note_id":"T161","title":"The means of victory and the Prophet’s relation to his enemies","content":"The commentary moves from Badr’s victory to an injury at Uḥud when it explains the revelation of Q3:128. Those events should not be collapsed into a single battle. Muslim 1791 relates the damaged tooth and head wound at Uḥud, the Prophet’s question about the attackers’ prospects, and the revelation of this verse. Ibn ʿAjība’s fuller account adds the interpretation that God knew some opponents would later believe, naming Khālid. The hadith parallel establishes a source for the injury-and-verse episode; it does not independently substantiate every detail or the commentator’s general statement about how many opponents subsequently converted.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[404,405],"quran_context":"3:126–129","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-muslim","work":"muslim","locator":"Hadith1791, near PageV03P1416–1417","arabic_anchor":"فأنزل الله ... ليس لك من الأمر شيء","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0261Muslim/0261Muslim.Sahih/0261Muslim.Sahih.Shamela0001727-ara1.mARkdown","local_file":"audit_work/revision_XIV_research/public_sources/muslim.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-126-129","segment_index":1,"quran_context":"3:126–129","printed_pages":[404,405],"anchor_paragraph":"When the Prophet, blessings and peace be upon him, was wounded in the face, cut near his eyebrow and suffered a broken front tooth, he intended to pray against the unbelievers—indeed, he prayed against them. God then revealed: “You have no part in the matter.” You are only a messenger sent to them, charged with warning them and struggling against them, while their destiny rests in the hands of their Owner. If He wills, He guides them; if He wills, He punishes them. God forbade him to call down punishment on them because He knew that some of them would accept Islam and strive in God’s way. Ibn ʿAjība says that this did happen: most entered Islam and fought in its cause, including Khālid ibn al-Walīd, “God’s sword upon His earth.” [XIV-N104]","segment_title":"The means of victory and the Prophet’s relation to his enemies","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [404, 405]; muslim: Hadith1791, near PageV03P1416–1417","revision_status":"","word_count":97,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-126-129","segment_index":1,"quran_context":"3:126–129","printed_pages":[404,405],"anchor_paragraph":"When the Prophet, blessings and peace be upon him, was wounded in the face, cut near his eyebrow and suffered a broken front tooth, he intended to pray against the unbelievers—indeed, he prayed against them. God then revealed: “You have no part in the matter.” You are only a messenger sent to them, charged with warning them and struggling against them, while their destiny rests in the hands of their Owner. If He wills, He guides them; if He wills, He punishes them. God forbade him to call down punishment on them because He knew that some of them would accept Islam and strive in God’s way. Ibn ʿAjība says that this did happen: most entered Islam and fought in its cause, including Khālid ibn al-Walīd, “God’s sword upon His earth.” [T161]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T161; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T161","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T161","original_body_sha256":"910f16ec816297673115eda92a4a372432c48fc125ad7c47527d7ca72a9937ba","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":125,"print_label":"T125","linked_occurrences":[{"record_id":"q3-126-129","segment_index":1,"q":"3:126–129","source":"Cairo print · Volume I, pp. 404–405"}]},{"id":"XIV-N105","historical_note_id":"T162","title":"Affliction as preparation for freedom from dependence","content":"The wordplay links imtikān, secure establishment, to imtiḥān, testing, and miḥna, ordeal, to mikna, capacity. Ibn ʿAjība’s interpretation turns military support into a model of inward formation: opposition exposes remaining attachments, and release from them changes the seeker’s experience of divine Majesty into Beauty. ‘Residues’ are specified nearby as distractions, attachments, prestige and the self’s preferences. The subsequent instruction to set the means in motion prevents ‘you have no part’ from meaning simple inactivity. The seeker acts, while the spiritual opening remains a divine gift rather than a result he can compel.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[405],"quran_context":"3:126–129","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-126-129","segment_index":2,"quran_context":"3:126–129","printed_pages":[405],"anchor_paragraph":"This is God’s practice with His friends: at their beginnings He grants other creatures power over them and intensifies their trials until they have been purified of their residues ( البقايا ) and their merits have reached completion. Then He restrains the harm, and Majesty ( الجلال ) turns to Beauty ( الجمال ). This is His solicitude for them and His victory for them over their own souls. All victory comes from “God, the Mighty, the Wise.” [XIV-N105]","segment_title":"Affliction as preparation for freedom from dependence","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [405]","revision_status":"","word_count":92,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-126-129","segment_index":2,"quran_context":"3:126–129","printed_pages":[405],"anchor_paragraph":"This is God’s practice with His friends: at their beginnings He grants other creatures power over them and intensifies their trials until they have been purified of their residues ( البقايا ) and their merits have reached completion. Then He restrains the harm, and Majesty ( الجلال ) turns to Beauty ( الجمال ). This is His solicitude for them and His victory for them over their own souls. All victory comes from “God, the Mighty, the Wise.” [T162]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T162; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T162","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T162","original_body_sha256":"7bc7de1311744217b217b092da1a5ced558f572ded6a08d7e4315cf5655c8618","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":126,"print_label":"T126","linked_occurrences":[{"record_id":"q3-126-129","segment_index":2,"q":"3:126–129","source":"Cairo print · Volume I, pp. 404–405"}]},{"id":"XIV-N106","historical_note_id":"T163","title":"Affliction as preparation for freedom from dependence","content":"Three voices must remain distinct. Al-Qushayrī juxtaposes the agency paradox of Q8:17 with the withdrawal of control in Q3:128. A marginal commentator then names the two stations as deputyship through God and God’s acting for His servant, correlating them with baqāʾ and fanāʾ. Ibn ʿAjība’s own ‘I say’ adds the terms expansion and contraction. Laṭāʾif al-ishārāt contains the Qurʾānic juxtaposition; the subsequent terminology is not thereby authenticated as al-Qushayrī’s wording. Here fanāʾ and baqāʾ describe contrasting forms of awareness and agency within spiritual experience.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[405],"quran_context":"3:126–129","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-qushayri_tafsir","work":"qushayri_tafsir","locator":"Q3:128–129, between PageV01P275–276","arabic_anchor":"وما رميت إذ رميت ... ليس لك من الأمر شيء","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0465IbnHawazinQushayri/0465IbnHawazinQushayri.LataifIsharat/0465IbnHawazinQushayri.LataifIsharat.Shamela0023629-ara1","local_file":"audit_work/revision_XIV_research/public_sources/qushayri_tafsir.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-126-129","segment_index":2,"quran_context":"3:126–129","printed_pages":[405],"anchor_paragraph":"The glossator explains that these indicate two stations: acting as God’s deputy through God ( نيابة عن الله بالله ), and God acting in the place of His servant ( نيابة الله عن عبده ). The first is subsistence ( بقاء ), the second effacement ( فناء ), according to the gloss. I say: The first belongs to the station of expansion ( البسط ), and the second to that of contraction ( القبض ). Thus they have said: “When He expands [the heart], there is no destitution; when He contracts it, there is no power.” God Most High knows best. [XIV-N106]","segment_title":"Affliction as preparation for freedom from dependence","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [405]; qushayri_tafsir: Q3:128–129, between PageV01P275–276","revision_status":"","word_count":86,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-126-129","segment_index":2,"quran_context":"3:126–129","printed_pages":[405],"anchor_paragraph":"The glossator explains that these indicate two stations: acting as God’s deputy through God ( نيابة عن الله بالله ), and God acting in the place of His servant ( نيابة الله عن عبده ). The first is subsistence ( بقاء ), the second effacement ( فناء ), according to the gloss. I say: The first belongs to the station of expansion ( البسط ), and the second to that of contraction ( القبض ). Thus they have said: “When He expands [the heart], there is no destitution; when He contracts it, there is no power.” God Most High knows best. [T163]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T163; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T163","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T163","original_body_sha256":"7625bb124cae3db3545a41182ad08575ef6cad87d6b4bcc17d1d49fcac7fed82","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":127,"print_label":"T127","linked_occurrences":[{"record_id":"q3-126-129","segment_index":2,"q":"3:126–129","source":"Cairo print · Volume I, pp. 404–405"}]},{"id":"XIV-N107","historical_note_id":"T164","title":"Redoubled interest and the disposition of God-consciousness","content":"Ibn ʿAjība identifies the practice as an increase demanded when a debt becomes due: payment now or a larger obligation after delay. Repetition explains ‘doubled and redoubled.’ His cautious ‘perhaps the specification follows what actually occurred’ treats the multiplier as a description of a prevalent practice, not an independently stated threshold beneath which an increase becomes permissible. This is his explanation of Q3:130 in its setting. The surrounding argument connects victory with lawful sustenance and obedience, so the discussion of debt also serves the commentary’s transition back to the Uḥud narrative.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[406],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-130-134","segment_index":1,"quran_context":"3:130–134","printed_pages":[406],"anchor_paragraph":"The Real, exalted is His majesty, says: “O you who believe, do not consume usury” ( الرِّبا ) by increasing the debt when its due date arrives, “doubled and redoubled.” Perhaps this specification reflects the customary practice at the time: when a debt fell due, the creditor would tell the debtor, “Either settle it or add to it.” The creditor would grant repeated delays and repeatedly increase what was owing, until the debt swallowed all of the debtor’s property. They were forbidden this. God then commends mindfulness ( التقوى ), which is enrichment in both abodes: “Be mindful of God” regarding what I have forbidden you, “that you may prosper” in this world and the next. [XIV-N107]","segment_title":"Redoubled interest and the disposition of God-consciousness","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [406]","revision_status":"","word_count":91,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":1,"quran_context":"3:130–134","printed_pages":[406],"anchor_paragraph":"The Real, exalted is His majesty, says: “O you who believe, do not consume usury” ( الرِّبا ) by increasing the debt when its due date arrives, “doubled and redoubled.” Perhaps this specification reflects the customary practice at the time: when a debt fell due, the creditor would tell the debtor, “Either settle it or add to it.” The creditor would grant repeated delays and repeatedly increase what was owing, until the debt swallowed all of the debtor’s property. They were forbidden this. God then commends mindfulness ( التقوى ), which is enrichment in both abodes: “Be mindful of God” regarding what I have forbidden you, “that you may prosper” in this world and the next. [T164]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T164; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T164","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T164","original_body_sha256":"262d8cb299ff8976503f128c2d8702ea91e8adc27532af6211cf80213a278e35","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":128,"print_label":"T128","linked_occurrences":[{"record_id":"q3-130-134","segment_index":1,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N108","historical_note_id":"T165","title":"Redoubled interest and the disposition of God-consciousness","content":"Two related but distinct theological explanations occur here. Ibn ʿAjība infers present existence from ‘prepared’ and distinguishes the Fire’s primary preparation for unbelievers from the punishment of sinners incidentally. He then quotes al-Wartajbī’s more consolatory account of warning believers through an image of parental care. The father, lion and sword belong to that cited analogy. They do not turn the preceding distinctions into one undifferentiated doctrine, and the passage does not provide a comparative survey of theological positions. The quotation closes before the renewed command to obey God and the Messenger.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[406],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-130-134","segment_index":1,"quran_context":"3:130–134","printed_pages":[406],"anchor_paragraph":"He then makes them fear the Fire if they do not desist: “Guard against the Fire prepared for the unbelievers.” This also suggests, Ibn ʿAjība argues, that the Fire already exists, since something nonexistent cannot be prepared; that it is prepared for unbelievers primarily ( بالذات ) and for sinful people incidentally ( بالعرض ). Al-Wartajbī says the verse indicates that the Fire was not prepared or created for believers , but that God has warned them with it as a deterrent and admonition, just as a kind father may frighten his son with a lion or sword without intending to strike the child with the sword or throw him to the lion. In this interpretation the verse manifests gentleness and care toward His servants. End of quotation. [XIV-N108]","segment_title":"Redoubled interest and the disposition of God-consciousness","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [406]","revision_status":"","word_count":91,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":1,"quran_context":"3:130–134","printed_pages":[406],"anchor_paragraph":"He then makes them fear the Fire if they do not desist: “Guard against the Fire prepared for the unbelievers.” This also suggests, Ibn ʿAjība argues, that the Fire already exists, since something nonexistent cannot be prepared; that it is prepared for unbelievers primarily ( بالذات ) and for sinful people incidentally ( بالعرض ). Al-Wartajbī says the verse indicates that the Fire was not prepared or created for believers , but that God has warned them with it as a deterrent and admonition, just as a kind father may frighten his son with a lion or sword without intending to strike the child with the sword or throw him to the lion. In this interpretation the verse manifests gentleness and care toward His servants. End of quotation. [T165]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T165; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T165","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T165","original_body_sha256":"01defb7fe709c5970b0745ccddde0b4593e71b0ea9a65dd6e3045e11b071bc72","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":129,"print_label":"T129","linked_occurrences":[{"record_id":"q3-130-134","segment_index":1,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N109","historical_note_id":"T166","title":"The immensity of the Garden","content":"The interpretation offers two senses of ʿarḍ, ‘breadth.’ One uses a spatial comparison rhetorically: if even the smaller dimension is immense, its total extent is greater still. The other understands the word as extraordinary magnitude without contrasting breadth and length. These explanations are alternatives and supply no calculation of Paradise’s dimensions. The separate inference from ‘prepared’ concerns its already created existence; the conclusion that it lies beyond this world is Ibn ʿAjība’s theological inference. The recorded reading without wāw changes how ‘hasten’ joins the preceding sentence, not the object of the command.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[406],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-130-134","segment_index":2,"quran_context":"3:130–134","printed_pages":[406],"anchor_paragraph":"“Hasten” ( وسارعوا ), that is, make haste “toward forgiveness from your Lord,” such as Islam, repentance, sincerity ( الإخلاص ), and all other obedient deeds entailing forgiveness. Nāfiʿ and Ibn ʿĀmir read the command without the conjunction wāw (و), treating it as a fresh sentence ( استئناف ). And hasten toward “a Garden whose breadth is the heavens and the earth”—if the one were joined to the other. Mention of breadth, rather than length, intensifies its vastness, because breadth is less than length. Another explanation says this does not mean breadth in contrast with length, but simply extraordinary magnitude: it is as great as the seven heavens and seven earths could seem to you; its extent is beyond description. “Prepared” means made ready “for the mindful.” This, Ibn ʿAjība adds, proves that Paradise is already created and lies outside the present cosmos. [XIV-N109]","segment_title":"The immensity of the Garden","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [406]","revision_status":"","word_count":92,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":2,"quran_context":"3:130–134","printed_pages":[406],"anchor_paragraph":"“Hasten” ( وسارعوا ), that is, make haste “toward forgiveness from your Lord,” such as Islam, repentance, sincerity ( الإخلاص ), and all other obedient deeds entailing forgiveness. Nāfiʿ and Ibn ʿĀmir read the command without the conjunction wāw (و), treating it as a fresh sentence ( استئناف ). And hasten toward “a Garden whose breadth is the heavens and the earth”—if the one were joined to the other. Mention of breadth, rather than length, intensifies its vastness, because breadth is less than length. Another explanation says this does not mean breadth in contrast with length, but simply extraordinary magnitude: it is as great as the seven heavens and seven earths could seem to you; its extent is beyond description. “Prepared” means made ready “for the mindful.” This, Ibn ʿAjība adds, proves that Paradise is already created and lies outside the present cosmos. [T166]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T166; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T166","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T166","original_body_sha256":"4a938d34d2d14e572c576e5718615ea9c5997ed55ecf11354bb40472a6fcf85e","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":130,"print_label":"T130","linked_occurrences":[{"record_id":"q3-130-134","segment_index":2,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N110","historical_note_id":"T167","title":"Giving in ease and adversity","content":"The three sayings about generosity are separately introduced reports. A parallel for the middle saying is al-Tirmidhī 1961. He calls its route gharīb, records disagreement with its transmitter, and mentions a disconnected alternative through ʿĀʾisha. His wording also contrasts the generous ignorant person with a miserly worshipper, whereas Cairo has a learned miser. That partial identification should not be extended into one authentication ruling for the entire cluster, particularly the tree imagery. The Qurʾānic foundation of the paragraph is the disposition to give in both prosperity and adversity; the cited sayings elaborate it.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[407],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-tirmidhi","work":"tirmidhi","locator":"Hadith1961; PageV04P342","arabic_anchor":"هذا حديث غريب ... وقد خولف سعيد بن محمد","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0279Tirmidhi/0279Tirmidhi.Sunan/0279Tirmidhi.Sunan.Shamela0001435-ara1","local_file":"audit_work/revision_XIV_research/public_sources/tirmidhi.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-130-134","segment_index":3,"quran_context":"3:130–134","printed_pages":[407],"anchor_paragraph":"Then the Real describes the perfected attributes of those mindful people who will inhabit the Garden: “Those who spend in ease and hardship,” namely in prosperity and adversity and indeed in all circumstances, as is the way of the generous. The Prophet, blessings and peace be upon him, is cited as saying: “The Garden is the dwelling of the generous.” Also: “The generous person is close to God, close to the Garden, close to people and far from the Fire; the miser is far from God, far from the Garden, far from people and close to the Fire. An ignorant but generous person is dearer to God than a learned miser.” And again: “Generosity is a tree in Paradise whose branches are in the world. Whoever clings to one of its branches is led by it into Paradise. Miserliness is a tree in the Fire whose branches are in the world; whoever clings to one of those branches is led by it into the Fire.” Translator’s note: These are reports quoted by the author, with their individual degrees of authenticity still to be established. [XIV-N110]","segment_title":"Giving in ease and adversity","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [407]; tirmidhi: Hadith1961; PageV04P342","revision_status":"","word_count":94,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":3,"quran_context":"3:130–134","printed_pages":[407],"anchor_paragraph":"Then the Real describes the perfected attributes of those mindful people who will inhabit the Garden: “Those who spend in ease and hardship,” namely in prosperity and adversity and indeed in all circumstances, as is the way of the generous. The Prophet, blessings and peace be upon him, is cited as saying: “The Garden is the dwelling of the generous.” Also: “The generous person is close to God, close to the Garden, close to people and far from the Fire; the miser is far from God, far from the Garden, far from people and close to the Fire. An ignorant but generous person is dearer to God than a learned miser.” And again: “Generosity is a tree in Paradise whose branches are in the world. Whoever clings to one of its branches is led by it into Paradise. Miserliness is a tree in the Fire whose branches are in the world; whoever clings to one of those branches is led by it into the Fire.” Translator’s note: These are reports quoted by the author, with their individual degrees of authenticity still to be established. [T167]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T167; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T167","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T167","original_body_sha256":"4da73f1893c87da2e2e802e146bd616a42e9798dcbfb714a6b5d4a73d05026f3","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":131,"print_label":"T131","linked_occurrences":[{"record_id":"q3-130-134","segment_index":3,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N111","historical_note_id":"T168","title":"Giving in ease and adversity","content":"‘These’ refers to those who pardon the people who wrong them, immediately after the exposition of al-ʿāfīna ʿani l-nās in Q3:134. The saying concerns the rarity of that moral disposition, not a numerical census of communities. Al-Thaʿlabī, III:167, transmits the same wording through Muqātil b. Ḥayyān with the formula ‘it has reached us that the Messenger said.’ That identifies an earlier exegetical source and its indirect reporting formula; it supplies no continuous chain in that paragraph. The parallel identifies an indirect Prophetic attribution; it does not supply a continuous chain.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[407],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"work":"al-Thalabi, al-Kashf wa-l-bayan","locator":"III:167, Q3:134","local_facsimile":"audit_work/revision_XIV_research/middle/evidence/thalabi_III_pdf167.png","arabic_anchor":"وقال مقاتل بن حيان ... بلغنا أن رسول الله","assessment":"Actual page image read; the report formula is indirect."}],"scope":[{"record_id":"q3-130-134","segment_index":3,"quran_context":"3:130–134","printed_pages":[407],"anchor_paragraph":"“And those who pardon people,” meaning those who have wronged them. The Prophet is quoted as saying of such people: “In my community these are few, apart from those God has protected, though they were many among the communities that passed.” [XIV-N111]","segment_title":"Giving in ease and adversity","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [407]; al-Thalabi, al-Kashf wa-l-bayan: III:167, Q3:134","revision_status":"","word_count":92,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":3,"quran_context":"3:130–134","printed_pages":[407],"anchor_paragraph":"“And those who pardon people,” meaning those who have wronged them. The Prophet is quoted as saying of such people: “In my community these are few, apart from those God has protected, though they were many among the communities that passed.” [T168]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T168; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T168","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T168","original_body_sha256":"8ebe27fbe30f2cb9becbe3a4d3299a59a947f6b84089fe6fee6b4da11af078d4","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":132,"print_label":"T132","linked_occurrences":[{"record_id":"q3-130-134","segment_index":3,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N112","historical_note_id":"T169","title":"Giving in ease and adversity","content":"Aḥmad’s Musnad 9624 contains both the Abū Bakr episode and the ensuing three maxims, so the latter are not merely an editorial moral appended to an unrelated story. The Cairo version reverses the order of the final two maxims and slightly paraphrases them. In Aḥmad, the increase in giving is tied to maintaining a connection, while the condemned request aims at accumulating more; the clauses do not equate every request for help with greed. The point of the episode is the contrast between restraint and retaliatory exchange. Identifying this parallel does not replace a separate assessment of its chain.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[407],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-ahmad","work":"ahmad","locator":"Musnad9624; around PageV15P390, printed numbering differs within the transcription","arabic_anchor":"ثم قال يا أبا بكر ثلاث كلهن حق","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0241IbnHanbal/0241IbnHanbal.Musnad/0241IbnHanbal.Musnad.Shamela0013157-ara1","local_file":"audit_work/revision_XIV_research/public_sources/ahmad.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-130-134","segment_index":3,"quran_context":"3:130–134","printed_pages":[407],"anchor_paragraph":"Abū Hurayra related that Abū Bakr sat in the Prophet’s company when a man came and insulted Abū Bakr. While Abū Bakr kept silent, the Prophet smiled. But when Abū Bakr responded to a portion of the abuse, the Prophet became angry and stood up. Abū Bakr followed him, saying, “Messenger of God, he insulted me while you smiled; when I answered him in part, you became angry and rose.” He replied: “While you were silent, an angel was with you answering him. When you spoke, Satan came, and I would not sit in a gathering with Satan. Abū Bakr, three things are true: no servant suffers a wrong and pardons it without God thereby strengthening His support for him; no servant opens the door of begging to increase his wealth without God increasing his want; and no servant opens the door of giving or maintaining kinship without God increasing his abundance thereby.” [XIV-N112]","segment_title":"Giving in ease and adversity","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [407]; ahmad: Musnad9624; around PageV15P390, printed numbering differs within the transcription","revision_status":"","word_count":99,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":3,"quran_context":"3:130–134","printed_pages":[407],"anchor_paragraph":"Abū Hurayra related that Abū Bakr sat in the Prophet’s company when a man came and insulted Abū Bakr. While Abū Bakr kept silent, the Prophet smiled. But when Abū Bakr responded to a portion of the abuse, the Prophet became angry and stood up. Abū Bakr followed him, saying, “Messenger of God, he insulted me while you smiled; when I answered him in part, you became angry and rose.” He replied: “While you were silent, an angel was with you answering him. When you spoke, Satan came, and I would not sit in a gathering with Satan. Abū Bakr, three things are true: no servant suffers a wrong and pardons it without God thereby strengthening His support for him; no servant opens the door of begging to increase his wealth without God increasing his want; and no servant opens the door of giving or maintaining kinship without God increasing his abundance thereby.” [T169]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T169; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T169","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T169","original_body_sha256":"366b3e8b432cfdd02f1c11fcb323e5a34189385578ec45ca9c6ce88a87cfd33a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":133,"print_label":"T133","linked_occurrences":[{"record_id":"q3-130-134","segment_index":3,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N113","historical_note_id":"T170","title":"Giving in ease and adversity","content":"The two analyses concern the definite article in al-muḥsinīn. On the generic reading, the statement embraces the class of all who act with iḥsān. On the contextual reading, it points back to the people just described: those who give, restrain anger and pardon. The distinction affects reference, not whether these virtues qualify as goodness. Ibn ʿAjība also makes the term relational, covering conduct toward God and toward other people. His following spiritual interpretation develops iḥsān into the named station of worship through witnessing; that development should not erase the ethical meaning established here.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[407],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-130-134","segment_index":3,"quran_context":"3:130–134","printed_pages":[407],"anchor_paragraph":"“God loves those who do beautiful good ( الْمُحْسِنِينَ ),” who act well in their dealings with God and with God’s servants. The definite article al- ( أل ) may be generic ( للجنس ), embracing everyone who practices iḥsān, or it may refer to a known class ( للعهد ), meaning those just described. [XIV-N113]","segment_title":"Giving in ease and adversity","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [407]","revision_status":"","word_count":93,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":3,"quran_context":"3:130–134","printed_pages":[407],"anchor_paragraph":"“God loves those who do beautiful good ( الْمُحْسِنِينَ ),” who act well in their dealings with God and with God’s servants. The definite article al- ( أل ) may be generic ( للجنس ), embracing everyone who practices iḥsān, or it may refer to a known class ( للعهد ), meaning those just described. [T170]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T170; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T170","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T170","original_body_sha256":"fac8ec84e1c480518bd414a8b8af1eee122ba6eca56fda684f61ab453edd05ce","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":134,"print_label":"T134","linked_occurrences":[{"record_id":"q3-130-134","segment_index":3,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N114","historical_note_id":"T171","title":"The multiplication of sense-life as an inward form of ribā","content":"The allusion draws on the verbal association between ribā and increasing: attachment to the sensible grows by repeated engagement, thought and conversation. The three corresponding supports of inward meaning are company, reflection and remembrance. Ḥiss and maʿnā are therefore functional terms in the author’s account of attention and spiritual formation, not a claim that the material world is intrinsically unreal or that every bodily act constitutes the legal offence of ribā. The legal debt discussion remains at I:406; this passage announces a further application to the disciple’s cultivated habits.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[407,408],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-130-134","segment_index":4,"quran_context":"3:130–134","printed_pages":[407,408],"anchor_paragraph":"Whatever increases the strength of sensory existence ( مادة الحس ) is, spiritually speaking, ribā : it multiplies the sensory realm and reinforces the substance of heedlessness ( مادة الغفلة ). The disciple ( المريد ) should not augment it or practise methods that cause it to grow, but should flee its three sources: direct engagement with the sensory realm, thought occupied with it, and speech about it with those devoted to it. Three things strengthen the inward order of meaning ( مادة المعنى ): companionship with those who live by inward meaning ( أهل المعنى ), reflection upon meanings ( الفكرة في المعاني ), and remembrance of God in the heart ( ذكر الله بالقلب ). [XIV-N114]","segment_title":"The multiplication of sense-life as an inward form of ribā","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [407, 408]","revision_status":"","word_count":89,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":4,"quran_context":"3:130–134","printed_pages":[407,408],"anchor_paragraph":"Whatever increases the strength of sensory existence ( مادة الحس ) is, spiritually speaking, ribā : it multiplies the sensory realm and reinforces the substance of heedlessness ( مادة الغفلة ). The disciple ( المريد ) should not augment it or practise methods that cause it to grow, but should flee its three sources: direct engagement with the sensory realm, thought occupied with it, and speech about it with those devoted to it. Three things strengthen the inward order of meaning ( مادة المعنى ): companionship with those who live by inward meaning ( أهل المعنى ), reflection upon meanings ( الفكرة في المعاني ), and remembrance of God in the heart ( ذكر الله بالقلب ). [T171]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T171; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T171","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T171","original_body_sha256":"35ac45db9c3c89cd72b4384528643a190be45cc88a6b577663acf625444dac11","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":135,"print_label":"T135","linked_occurrences":[{"record_id":"q3-130-134","segment_index":4,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N115","historical_note_id":"T172","title":"The multiplication of sense-life as an inward form of ribā","content":"The uncompensated blood and freely available property are severe expressions of the Sufi ideal of surrendering retaliation and proprietary self-assertion. Their immediate explanation is restraint, pardon and the test of what emerges when one is angered. They are not framed here as a juristic removal of another person’s protected rights. The double imperative lā taghḍab wa-lā tughḍib balances not becoming angry with not provoking anger in others; its second member is causative. The following poem sharpens the same distinction: the desired pardon comes from self-command, rather than inability to answer an injury.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[408],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-130-134","segment_index":4,"quran_context":"3:130–134","printed_pages":[408],"anchor_paragraph":"They “restrain anger,” having mastered their selves and states, and “pardon people,” because, in the uncompromising ascetic idiom quoted here, “the Sufi’s property is freely available and his blood is without recompense” ( الصوفي ماله مباح ودمه هدر ). Some Sufis used to say: “If you wish to know the condition of a spiritual poor person ( حال الفقير ), anger him and see what emerges.” The shaykh of our shaykhs said: “The pivot of Sufism ( قطب التصوف ) is: do not grow angry and do not cause anger.” End of quotation. [XIV-N115]","segment_title":"The multiplication of sense-life as an inward form of ribā","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [408]","revision_status":"","word_count":92,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":4,"quran_context":"3:130–134","printed_pages":[408],"anchor_paragraph":"They “restrain anger,” having mastered their selves and states, and “pardon people,” because, in the uncompromising ascetic idiom quoted here, “the Sufi’s property is freely available and his blood is without recompense” ( الصوفي ماله مباح ودمه هدر ). Some Sufis used to say: “If you wish to know the condition of a spiritual poor person ( حال الفقير ), anger him and see what emerges.” The shaykh of our shaykhs said: “The pivot of Sufism ( قطب التصوف ) is: do not grow angry and do not cause anger.” End of quotation. [T172]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T172; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T172","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T172","original_body_sha256":"d1aef1bee4df2ac26614fb73aa83c7a2dbf5a9eeb8099ad0028d6ac6498b0e9a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":136,"print_label":"T136","linked_occurrences":[{"record_id":"q3-130-134","segment_index":4,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N116","historical_note_id":"T173","title":"The multiplication of sense-life as an inward form of ribā","content":"Cairo’s negative comparison with sun, wind and rain is accompanied by its own geographical explanation: favouring one land over another. The earlier al-Thaʿlabī passage, at III:167, instead gives a positive comparison, presenting those natural benefits as examples of beneficence that is general rather than exclusive. Cairo’s negative and its gloss give the comparison a different logic. Both versions support generosity, but they use nature differently. This is a real difference in the transmitted saying, whose precise entry into Ibn ʿAjība’s text remains unsettled.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[408],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"work":"al-Thalabi, al-Kashf wa-l-bayan","locator":"III:167–168, Q3:134","local_facsimiles":["audit_work/revision_XIV_research/middle/evidence/thalabi_III_pdf167.png","audit_work/revision_XIV_research/middle/evidence/thalabi_III_pdf168.png"],"arabic_anchor":"الإحسان أن يعم ولا يخص كالريح والشمس والمطر","assessment":"Both physical pages read; confirms the earlier positive comparison, not the provenance of Cairo’s negative."}],"scope":[{"record_id":"q3-130-134","segment_index":4,"quran_context":"3:130–134","printed_pages":[408],"anchor_paragraph":"“God loves those who do beautiful good”: those who have attained the station of spiritual excellence ( مقام الإحسان ) and worship God through witnessing and direct vision ( الشهود والعيان ). Their good reaches those who wrong them and those who treat them well, humankind and jinn alike. Al-Ḥasan al-Baṣrī said: “Iḥsān is for one’s beneficence to be general, not like the sun, the wind and the rain”—meaning, as Ibn ʿAjība explains, not to favour one land and exclude another. Translator’s note: Cairo transmits a negative comparison with the sun, wind and rain, followed by Ibn ʿAjība’s gloss about favouring one land over another. An earlier version attributed to al-Ḥasan in al-Thaʿlabī’s al-Kashf wa-l-bayān (Ibn ʿĀshūr ed., first edition, 1422/2002, III:167; printed page inspected) says that beneficence should be general and not exclusive, like wind, sun and rain. This is a material difference between the two texts. The translation retains Cairo’s wording and explanatory gloss; independent manuscripts are needed to determine whether the change is authorial or arose in transmission. [XIV-N116]","segment_title":"The multiplication of sense-life as an inward form of ribā","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [408]; al-Thalabi, al-Kashf wa-l-bayan: III:167–168, Q3:134","revision_status":"","word_count":92,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":4,"quran_context":"3:130–134","printed_pages":[408],"anchor_paragraph":"“God loves those who do beautiful good”: those who have attained the station of spiritual excellence ( مقام الإحسان ) and worship God through witnessing and direct vision ( الشهود والعيان ). Their good reaches those who wrong them and those who treat them well, humankind and jinn alike. Al-Ḥasan al-Baṣrī said: “Iḥsān is for one’s beneficence to be general, not like the sun, the wind and the rain”—meaning, as Ibn ʿAjība explains, not to favour one land and exclude another. Translator’s note: Cairo transmits a negative comparison with the sun, wind and rain, followed by Ibn ʿAjība’s gloss about favouring one land over another. An earlier version attributed to al-Ḥasan in al-Thaʿlabī’s al-Kashf wa-l-bayān (III:167, electronic transcription inspected) says that beneficence should be general and not exclusive, like wind, sun and rain. This is a material difference between the two texts. The translation retains Cairo’s wording and explanatory gloss; independent manuscripts are needed to determine whether the change is authorial or arose in transmission. [T173]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T173; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T173","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T173","original_body_sha256":"0bcadd81623e861e51984f31bb55983d49b960ba372fe4fb36f999a5a229e827","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":137,"print_label":"T137","linked_occurrences":[{"record_id":"q3-130-134","segment_index":4,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N117","historical_note_id":"T174","title":"The multiplication of sense-life as an inward form of ribā","content":"Al-Wartajbī’s language plays on ʿilal, the ailments or motives of creatures, and al-ʿillatayn, the two aims of pardon and Paradise. The prepositions matter: obedience is the means, while those benefits are the ends sought. The elect are then summoned to God Himself through Q51:50. The fuller ʿArāʾis passage at I:196 subsequently calls seeking forgiveness a pursuit of the self’s portion, confirming the criticism of interested motives. The later dialogue about punishing angels occurs on the same page, but its modern footnote points back to Ibn ʿAjība; that circular reference provides no independent chain.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[408,409],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"work":"Ruzbihan, Arais al-bayan","locator":"Mazidi edition1429/2008, I:196, Q3:133","url":"https://archive.org/download/rouhany_816/Bayan1.pdf","local_facsimile":"audit_work/revision_XIV_research/middle/evidence/arais_pdf196.png","arabic_anchor":"طلب المغفرة هو طلب حظ النفس","assessment":"Actual facsimile read, including the footnote referring back to Bahr1/336."}],"scope":[{"record_id":"q3-130-134","segment_index":4,"quran_context":"3:130–134","printed_pages":[408,409],"anchor_paragraph":"Al-Wartajbī said about “Hasten toward forgiveness from your Lord and a Garden ...”: the Real knows creatures’ ailments and their inclination toward what their lower selves desire, so He summoned them, through obedience to Him, toward these two aims—pardon and Paradise. He summoned the elect ( الخاصة ) to Himself, saying: “Flee to God” [Q 51:50]. He then showed that all beings lie within the ordeal of culpability. Through the verse, he attributed a fault to everyone: though some are protected from slipping, their deficiency is their inadequate recognition of the full majesty due to God. As the Prophet, blessings and peace be upon him, said: “Were God to punish the angels, He would be justified.” It was asked, “But they are protected from sin.” He replied, blessings and peace be upon him: “Because of how little they know their Lord.” Accordingly He called them to forgiveness. Translator’s note: The quotation and its attribution to the Prophet reproduce the author’s cited exposition. The dialogue also appears in Rūzbihān’s ʿArāʾis al-bayān (al-Mazīdī ed., 1429/2008, I:196; printed page inspected). Its modern footnote cites Ibn ʿAjība’s Baḥr (1/336), so that note supplies no independent authentication. The Cairo editor likewise reports that he did not locate the report. [XIV-N117]","segment_title":"The multiplication of sense-life as an inward form of ribā","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [408, 409]; Ruzbihan, Arais al-bayan: Mazidi edition1429/2008, I:196, Q3:133","revision_status":"","word_count":93,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":4,"quran_context":"3:130–134","printed_pages":[408,409],"anchor_paragraph":"Al-Wartajbī said about “Hasten toward forgiveness from your Lord and a Garden ...”: the Real knows creatures’ ailments and their inclination toward what their lower selves desire, so He summoned them, through obedience to Him, toward these two aims—pardon and Paradise. He summoned the elect ( الخاصة ) to Himself, saying: “Flee to God” [Q 51:50]. He then showed that all beings lie within the ordeal of culpability. Through the verse, he attributed a fault to everyone: though some are protected from slipping, their deficiency is their inadequate recognition of the full majesty due to God. As the Prophet, blessings and peace be upon him, said: “Were God to punish the angels, He would be justified.” It was asked, “But they are protected from sin.” He replied, blessings and peace be upon him: “Because of how little they know their Lord.” Accordingly He called them to forgiveness. Translator’s note: The quotation and its attribution to the Prophet reproduce the author’s cited exposition. This translation does not independently authenticate the report; the Cairo editor notes that he did not locate it. [T174]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T174; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T174","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T174","original_body_sha256":"b9a74cef8c674fa4826208ffde1444e3520c0435bd041e495dd64936f717067a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":138,"print_label":"T138","linked_occurrences":[{"record_id":"q3-130-134","segment_index":4,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N118","historical_note_id":"T175","title":"The multiplication of sense-life as an inward form of ribā","content":"The paragraph is explicitly a marginal commentator’s explanation of the preceding quotation. It proposes that ‘He forgives whom He wills’ at Q3:129 includes heavenly beings, and reads the summons in Q3:133 correspondingly widely. ‘Fault’ is then qualified according to the creature concerned: it can mean limited judgment or inability to comprehend divine Majesty fully, rather than the same kind of deliberate transgression in every case. The closing argument for endless growth in knowledge rests on that inexhaustibility. Neither this gloss nor its philosophical explanation supplies authentication for the preceding report attributed to the Prophet.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[409],"quran_context":"3:130–134","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-130-134","segment_index":4,"quran_context":"3:130–134","printed_pages":[409],"anchor_paragraph":"The marginal commentator explains: saying that the verse attributes a fault to all creatures refers to the inclusion, in “He forgives whom He wills,” of those in the heavens, which includes the angels. Forgiveness presupposes fault, but each creature has a deficiency appropriate to it. The summons to forgiveness is apparently taken from “Hasten toward forgiveness from your Lord,” with its address understood to include those in heaven. Even the angels may be thought of as judging by outward appearances, disagreeing and disputing, matters that allow for error and occasion forgiveness. Moreover, falling short of knowing the full measure of God’s Majesty is a shortcoming no creature can escape, for comprehending Him through knowledge is impossible. For this reason there can never, for all eternity, be a final limit to advancement in knowledge of Him ( الترقي في المعرفة ). End of marginal gloss. [XIV-N118]","segment_title":"The multiplication of sense-life as an inward form of ribā","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [409]","revision_status":"","word_count":94,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-130-134","segment_index":4,"quran_context":"3:130–134","printed_pages":[409],"anchor_paragraph":"The marginal commentator explains: saying that the verse attributes a fault to all creatures refers to the inclusion, in “He forgives whom He wills,” of those in the heavens, which includes the angels. Forgiveness presupposes fault, but each creature has a deficiency appropriate to it. The summons to forgiveness is apparently taken from “Hasten toward forgiveness from your Lord,” with its address understood to include those in heaven. Even the angels may be thought of as judging by outward appearances, disagreeing and disputing, matters that allow for error and occasion forgiveness. Moreover, falling short of knowing the full measure of God’s Majesty is a shortcoming no creature can escape, for comprehending Him through knowledge is impossible. For this reason there can never, for all eternity, be a final limit to advancement in knowledge of Him ( الترقي في المعرفة ). End of marginal gloss. [T175]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T175; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T175","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T175","original_body_sha256":"ce2b175dc5cb53c4d7860328e3b3187c6479cc1bad4cdaf430b10bbeb7130087","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":139,"print_label":"T139","linked_occurrences":[{"record_id":"q3-130-134","segment_index":4,"q":"3:130–134","source":"Cairo print · Volume I, pp. 406–409"}]},{"id":"XIV-N119","historical_note_id":"T176","title":"Indecency, wrongdoing and the refusal to persist in sin","content":"Iṣrār denotes persistence rather than an isolated recurrence. Ibn ʿAjība explicitly conditions his use of the seventy-times saying on remorse; the qualification prevents repeated verbal requests from being treated as sufficient while the person remains unrepentant. Abū Dāwūd 1514 transmits the saying, and al-Tirmidhī 3559 also records it while calling its chain ‘not strong.’ This is a concrete source judgment, distinct from the independent interpretation of Q3:135’s refusal to persist. The adjacent maxim about major and minor sins and Qatāda’s admonition are separately introduced items and should not inherit the same chain or assessment.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[409,410],"quran_context":"3:135–136","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-abu_dawud","work":"abu_dawud","locator":"Hadith1514; near PageV02P084","arabic_anchor":"ما أصر من استغفر","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0275AbuDawudSijistani/0275AbuDawudSijistani.Sunan/0275AbuDawudSijistani.Sunan.Shamela0001726-ara1","local_file":"audit_work/revision_XIV_research/public_sources/abu_dawud.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."},{"source_id":"XIV-OT-tirmidhi","work":"tirmidhi","locator":"Hadith3559; near PageV05P557–558","arabic_anchor":"وليس إسناده بالقوي","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0279Tirmidhi/0279Tirmidhi.Sunan/0279Tirmidhi.Sunan.Shamela0001435-ara1","local_file":"audit_work/revision_XIV_research/public_sources/tirmidhi.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-135-136","segment_index":0,"quran_context":"3:135–136","printed_pages":[409,410],"anchor_paragraph":"“And they do not persist in what they have done,” that is, they do not continue in it without asking forgiveness. The Prophet, blessings and peace be upon him, is quoted as saying: “One who seeks forgiveness has not persisted [in sin], even if he returns to it seventy times in a day,” provided that his seeking forgiveness is joined with remorse. Another reported saying runs: “There is no major sin in the presence of seeking forgiveness, and no minor sin in the presence of persistence.” Qatāda warned: “Beware of persistence: those who persisted before you were ruined by advancing further in disobedience to God, without repenting until death came to them.” End of quotation. [XIV-N119]","segment_title":"Indecency, wrongdoing and the refusal to persist in sin","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [409, 410]; abu_dawud: Hadith1514; near PageV02P084; tirmidhi: Hadith3559; near PageV05P557–558","revision_status":"","word_count":94,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-135-136","segment_index":0,"quran_context":"3:135–136","printed_pages":[409,410],"anchor_paragraph":"“And they do not persist in what they have done,” that is, they do not continue in it without asking forgiveness. The Prophet, blessings and peace be upon him, is quoted as saying: “One who seeks forgiveness has not persisted [in sin], even if he returns to it seventy times in a day,” provided that his seeking forgiveness is joined with remorse. Another reported saying runs: “There is no major sin in the presence of seeking forgiveness, and no minor sin in the presence of persistence.” Qatāda warned: “Beware of persistence: those who persisted before you were ruined by advancing further in disobedience to God, without repenting until death came to them.” End of quotation. [T176]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T176; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T176","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T176","original_body_sha256":"5043b775c01cb1453c173e54ac7f691d0288e36788239e0593e19276eb57c9d8","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":140,"print_label":"T140","linked_occurrences":[{"record_id":"q3-135-136","segment_index":0,"q":"3:135–136","source":"Cairo print · Volume I, pp. 409–411"}]},{"id":"XIV-N120","historical_note_id":"T177","title":"Indecency, wrongdoing and the refusal to persist in sin","content":"Three differently introduced sayings are gathered under ‘while they know.’ Their shared purpose is to connect repentance with recognition that God forgives. One close source identification is particularly useful: the final address beginning ‘Son of Adam, so long as you call upon Me and hope in Me’ occurs as a divine saying in al-Tirmidhī 3540 through Anas, where al-Tirmidhī calls it ḥasan gharīb. Cairo introduces it more generally as occurring in revealed books. That parallel clarifies the wording’s wider transmission but does not establish the separate chains or exact wording of the preceding two sayings.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[410],"quran_context":"3:135–136","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-tirmidhi","work":"tirmidhi","locator":"Hadith3540; PageV05P548","arabic_anchor":"يا ابن آدم إنك ما دعوتني ورجوتني غفرت لك","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0279Tirmidhi/0279Tirmidhi.Sunan/0279Tirmidhi.Sunan.Shamela0001435-ara1","local_file":"audit_work/revision_XIV_research/public_sources/tirmidhi.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-135-136","segment_index":0,"quran_context":"3:135–136","printed_pages":[410],"anchor_paragraph":"“While they know” that persistence injures them; or while they know they have a Lord who forgives sin. The Prophet is quoted as saying: “Whoever commits a sin and knows that he has a Lord who forgives sins is forgiven, even if he has not expressly asked forgiveness.” A divine saying ( حديث قدسي ) is also cited: “Whoever knows that I possess the power to forgive, I forgive him and do not mind.” In some revealed books there is the declaration: “Son of Adam, so long as you call upon Me and place your hope in Me, I will surely forgive you for whatever you have done, and I do not mind.” Alternatively, “while they know” refers to their recognition that repentance erases sins. Translator’s note: The reports are transcribed here as cited; the wording, attribution and transmission of each require independent hadith review. [XIV-N120]","segment_title":"Indecency, wrongdoing and the refusal to persist in sin","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [410]; tirmidhi: Hadith3540; PageV05P548","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-135-136","segment_index":0,"quran_context":"3:135–136","printed_pages":[410],"anchor_paragraph":"“While they know” that persistence injures them; or while they know they have a Lord who forgives sin. The Prophet is quoted as saying: “Whoever commits a sin and knows that he has a Lord who forgives sins is forgiven, even if he has not expressly asked forgiveness.” A divine saying ( حديث قدسي ) is also cited: “Whoever knows that I possess the power to forgive, I forgive him and do not mind.” In some revealed books there is the declaration: “Son of Adam, so long as you call upon Me and place your hope in Me, I will surely forgive you for whatever you have done, and I do not mind.” Alternatively, “while they know” refers to their recognition that repentance erases sins. Translator’s note: The reports are transcribed here as cited; the wording, attribution and transmission of each require independent hadith review. [T177]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T177; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T177","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T177","original_body_sha256":"6ab14c9f2f22fd152a7b3c3785eb5814d4a9734e72abe8e0b31e04fec59a8899","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":141,"print_label":"T141","linked_occurrences":[{"record_id":"q3-135-136","segment_index":0,"q":"3:135–136","source":"Cairo print · Volume I, pp. 409–411"}]},{"id":"XIV-N121","historical_note_id":"T178","title":"Indecency, wrongdoing and the refusal to persist in sin","content":"‘The first verse’ here points to the praise of the muḥsinūn at Q3:134; ‘this verse’ points to the reward promised at Q3:136. Ibn ʿAjība builds a hierarchy from the difference between being loved and being remunerated. The image of receiving wages from beyond the door is his exposition of distance and intimacy, not wording of the Qurʾān. Nor does he deny forgiveness or Paradise to those he assigns the lower rank: he has just affirmed both. The distinction prepares the following allusion’s contrast between reliance on works and absorption in the divine Giver.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[410],"quran_context":"3:135–136","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-135-136","segment_index":0,"quran_context":"3:135–136","printed_pages":[410],"anchor_paragraph":"Contemplate the enormous distinction between those who practice iḥsān ( المحسنون ) and the People of the Right ( أهل اليمين ). Of the former He says, “God loves the doers of beautiful good”; of the latter, “How excellent is the reward of those who work.” The people of the first verse belong among the beloved elect ( خواص الأحباب ), whereas those of the present verse receive their reward from beyond the door. God grants success, and He guides to the very heart of verification ( عين التحقيق ). [XIV-N121]","segment_title":"Indecency, wrongdoing and the refusal to persist in sin","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [410]","revision_status":"","word_count":93,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-135-136","segment_index":0,"quran_context":"3:135–136","printed_pages":[410],"anchor_paragraph":"Contemplate the enormous distinction between those who practice iḥsān ( المحسنون ) and the People of the Right ( أهل اليمين ). Of the former He says, “God loves the doers of beautiful good”; of the latter, “How excellent is the reward of those who work.” The people of the first verse belong among the beloved elect ( خواص الأحباب ), whereas those of the present verse receive their reward from beyond the door. God grants success, and He guides to the very heart of verification ( عين التحقيق ). [T178]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T178; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T178","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T178","original_body_sha256":"2fa984c5d9b7233e0b2597b157b913132fb94915513cc2107f8e822a0dd23b55","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":142,"print_label":"T142","linked_occurrences":[{"record_id":"q3-135-136","segment_index":0,"q":"3:135–136","source":"Cairo print · Volume I, pp. 409–411"}]},{"id":"XIV-N122","historical_note_id":"T179","title":"People of spiritual excellence and People of the Right","content":"The series turns on different kinds of attention to oneself, one’s works and God. ‘Absent from seeing their works’ describes the muḥsinūn’s awareness, not the nonperformance of those works: the paragraph itself identifies their generosity, pardon and self-restraint. The contrast between maḥbūbūn, beloved, and muḥibbūn, lovers, reinforces the priority given to divine initiative over the seeker’s own effort. Fanāʾ and baqāʾ likewise concern effacement of self-preoccupation and subsistence through the Lord. The statement that discursive believers are ‘the generality’ is explicitly relative to the perspective of those claiming direct witnessing.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[410],"quran_context":"3:135–136","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-135-136","segment_index":1,"quran_context":"3:135–136","printed_pages":[410],"anchor_paragraph":"The people of iḥsān are absent from contemplating their works and their separate existence ( غائبون عن رؤية أعمالهم ووجودهم ). The People of the Right rely upon their works: when they obey, hope grows; when they slip, hope diminishes. The people of iḥsān are effaced from themselves ( فانون عن أنفسهم ), subsisting through their Lord ( باقون بربهم ); the People of the Right remain conscious of their individual selves and observe their own works. The people of iḥsān are beloved ( محبوبون ), while the People of the Right are lovers ( مُحِبُّون ). For the first, formal marks and shapes ( الرسوم والأشكال ) vanish, and they behold only the existence of the Great and Exalted One ( وجود الكبير المتعال ). For the second, the created world still stands as independently present before them and the suns of gnosis ( شموس المعارف ) are absent from their hearts. The people of iḥsān worship through witnessing and direct vision ( الشهود والعيان ); the People of the Right worship from behind the veil of demonstration and discursive argument ( الدليل والبرهان ). From the viewpoint of those who witness directly, those who have only proof and argument are counted among the generality ( العموم ). [XIV-N122]","segment_title":"People of spiritual excellence and People of the Right","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [410]","revision_status":"","word_count":90,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-135-136","segment_index":1,"quran_context":"3:135–136","printed_pages":[410],"anchor_paragraph":"The people of iḥsān are absent from contemplating their works and their separate existence ( غائبون عن رؤية أعمالهم ووجودهم ). The People of the Right rely upon their works: when they obey, hope grows; when they slip, hope diminishes. The people of iḥsān are effaced from themselves ( فانون عن أنفسهم ), subsisting through their Lord ( باقون بربهم ); the People of the Right remain conscious of their individual selves and observe their own works. The people of iḥsān are beloved ( محبوبون ), while the People of the Right are lovers ( مُحِبُّون ). For the first, formal marks and shapes ( الرسوم والأشكال ) vanish, and they behold only the existence of the Great and Exalted One ( وجود الكبير المتعال ). For the second, the created world still stands as independently present before them and the suns of gnosis ( شموس المعارف ) are absent from their hearts. The people of iḥsān worship through witnessing and direct vision ( الشهود والعيان ); the People of the Right worship from behind the veil of demonstration and discursive argument ( الدليل والبرهان ). From the viewpoint of those who witness directly, those who have only proof and argument are counted among the generality ( العموم ). [T179]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T179; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T179","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T179","original_body_sha256":"4b1e6ab1671db19809135a0022f83f118a67d585130000cca4981bb7d33cad43","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":143,"print_label":"T143","linked_occurrences":[{"record_id":"q3-135-136","segment_index":1,"q":"3:135–136","source":"Cairo print · Volume I, pp. 409–411"}]},{"id":"XIV-N123","historical_note_id":"T180","title":"Fruits of knowledge through witnessing: eight of eleven are given here","content":"The enumeration announces eleven qualities but expressly gives only eight and sends the reader to Bughyat al-Sālik for the remainder. Ibn ʿAjība thus gives an abbreviated citation. The sequence distinguishes settled realization from fluctuating experience: gathering, sobriety, verification and subsistence are not interchangeable synonyms for an ecstatic state. Talbīs is specifically the concealment of inward mysteries under ordinary causes, preserving outward order. The freedom illustration contains a separate textual crux, faṣṣ/maṣṣ; the Risāla places the same manumission comparison immediately after maṣṣ.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[410,411],"quran_context":"3:135–136","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-qushayri_risala","work":"qushayri_risala","locator":"Chapter on freedom; II:372","arabic_anchor":"المكاتب عبد ما بقي عليه درهم","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0465IbnHawazinQushayri/0465IbnHawazinQushayri.RisalaQushayriyya/0465IbnHawazinQushayri.RisalaQushayriyya.Shamela0009953-ara1","local_file":"audit_work/revision_XIV_research/public_sources/qushayri_risala.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-135-136","segment_index":2,"quran_context":"3:135–136","printed_pages":[410,411],"anchor_paragraph":"Know that the knowledge of witnessing and direct vision ( معرفة الشهود والعيان ) bears fruits and consequences ( ثمرات ونتائج ). One author has enumerated eleven qualities ; Ibn ʿAjība states eight here and directs the reader to Bughyat al-Sālik ( بغية السالك ) for the rest. [XIV-N123]","segment_title":"Fruits of knowledge through witnessing: eight of eleven are given here","anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-135-136","segment_index":2,"quran_context":"3:135–136","printed_pages":[410,411],"anchor_paragraph":"Eighth: Subsistence ( البقاء ). Emerging from the effacement involved in witnessing ( فناء المشاهدة ) into the abiding permanence of knowledge ( بقاء المعرفة ), without any setting that dims the sun of witnessing and without returning to the evidences of sense. Rather, it is a carrying-forward of gathering ( استصحاب الجمع ), while the spirit takes delight in the sweetness of meanings. Thus the realized person is “separate yet near” ( كبائن دانٍ ). Consult Bughyat al-Sālik for the remaining qualities. And God grants success. [XIV-N123]","segment_title":"Fruits of knowledge through witnessing: eight of eleven are given here","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [410, 411]; qushayri_risala: Chapter on freedom; II:372","revision_status":"","word_count":96,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-135-136","segment_index":2,"quran_context":"3:135–136","printed_pages":[410,411],"anchor_paragraph":"Know that the knowledge of witnessing and direct vision ( معرفة الشهود والعيان ) bears fruits and consequences ( ثمرات ونتائج ). One author has enumerated eleven qualities ; Ibn ʿAjība states eight here and directs the reader to Bughyat al-Sālik ( بغية السالك ) for the rest. [T180]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T180; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T180","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T180","original_body_sha256":"4f6232f4811cd942a7e7fe267795dc188ee4ffd9374c2eb32274579add27a87a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":144,"print_label":"T144","linked_occurrences":[{"record_id":"q3-135-136","segment_index":2,"q":"3:135–136","source":"Cairo print · Volume I, pp. 409–411"},{"record_id":"q3-135-136","segment_index":2,"q":"3:135–136","source":"Cairo print · Volume I, pp. 409–411"}]},{"id":"XIV-N124","historical_note_id":"T181","title":"Sunan (سُنَن) as paths and recurring precedents","content":"Sunan is the plural of sunna, a way or established course. In this context ‘patterns’ or ‘precedents’ concerns the histories of earlier peoples and the recurring consequences of rejecting their messengers. The alternative ‘nations’ reads the term through the bearers of those histories rather than the paths themselves. It should remain an alternative, not be combined into the definition ‘religious traditions of nations.’ The instruction to travel and inspect the deniers’ end then gives these precedents their evidential function. Here sunan does not specifically denote the later technical corpus of Prophetic practice.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[411],"quran_context":"3:137–139","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-137-139","segment_index":0,"quran_context":"3:137–139","printed_pages":[411],"anchor_paragraph":"I say: Sunan ( السُّنَن ) means paths that have been trodden; according to another explanation, it refers to the nations themselves. [XIV-N124]","segment_title":"Sunan (سُنَن) as paths and recurring precedents","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [411]","revision_status":"","word_count":92,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-137-139","segment_index":0,"quran_context":"3:137–139","printed_pages":[411],"anchor_paragraph":"I say: Sunan ( السُّنَن ) means paths that have been trodden; according to another explanation, it refers to the nations themselves. [T181]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T181; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T181","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T181","original_body_sha256":"91c1965168b33c1a779c78ae4775e10b7faeadce5e5d385172409b6c6086a853","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":145,"print_label":"T145","linked_occurrences":[{"record_id":"q3-137-139","segment_index":0,"q":"3:137–139","source":"Cairo print · Volume I, pp. 411–412"}]},{"id":"XIV-N125","historical_note_id":"T182","title":"The fate of those who deny and the patience of those who believe","content":"The tally of seventy Helpers and five Emigrants, including the same unusual sequence of names, already appears in al-Thaʿlabī on Q3:139, III:172. Other reports differ: al-Bukhārī 3986 gives seventy casualties at Uḥud, while 4078 speaks of seventy from the Helpers. These are distinguishable transmitted formulations, not a single verified roster from which every figure can be harmonized automatically. The earlier parallel attests Ibn ʿAjība’s total of seventy-five and his names without settling the historical count or the name forms.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[412],"quran_context":"3:137–139","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-thalabi","work":"thalabi","locator":"Q3:139; between PageV03P171–172","arabic_anchor":"وكان قد قتل يومئذ خمسة من المهاجرين ... ومن الأنصار سبعون","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0427AbuIshaqThaclabi/0427AbuIshaqThaclabi.KashfWaBayan/0427AbuIshaqThaclabi.KashfWaBayan.Shamela0023578-ara1.mARkdown","local_file":"audit_work/revision_XIV_research/public_sources/thalabi.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."},{"source_id":"XIV-OT-bukhari","work":"bukhari","locator":"Hadith3986 and4078","arabic_anchor":"فأصابوا منا سبعين","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-137-139","segment_index":1,"quran_context":"3:137–139","printed_pages":[412],"anchor_paragraph":"Then He consoled the believers and gave them glad tidings: “Do not lose heart,” meaning do not become too weak to fight your enemy on account of what has happened to you; “and do not grieve” over those killed among you. Ibn ʿAjība counts seventy Helpers and five Emigrants, naming Ḥamza ibn ʿAbd al-Muṭṭalib, Muṣʿab ibn ʿUmayr (bearer of the Prophet’s standard), ʿAbd Allāh ibn Jaḥsh, ʿUthmān ibn Shammās and Saʿd, the freedman of ʿUtba, may God be pleased with them. Alternatively, “do not grieve” over lost booty. “You shall be uppermost”: the final outcome and victory will be yours, or you are already above them in rank because you stand upon the truth and fight for God, your dead enter Paradise, while they stand upon falsehood and fight for Satan and their dead enter the Fire. Do not fail in your striving “if you are believers,” for faith entails a heart strengthened by trusting and relying upon God—or if you believe what I promised of elevation and victory. God knows best. [XIV-N125]","segment_title":"The fate of those who deny and the patience of those who believe","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [412]; thalabi: Q3:139; between PageV03P171–172; bukhari: Hadith3986 and4078","revision_status":"","word_count":94,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-137-139","segment_index":1,"quran_context":"3:137–139","printed_pages":[412],"anchor_paragraph":"Then He consoled the believers and gave them glad tidings: “Do not lose heart,” meaning do not become too weak to fight your enemy on account of what has happened to you; “and do not grieve” over those killed among you. Ibn ʿAjība counts seventy Helpers and five Emigrants, naming Ḥamza ibn ʿAbd al-Muṭṭalib, Muṣʿab ibn ʿUmayr (bearer of the Prophet’s standard), ʿAbd Allāh ibn Jaḥsh, ʿUthmān ibn Shammās and Saʿd, the freedman of ʿUtba, may God be pleased with them. Alternatively, “do not grieve” over lost booty. “You shall be uppermost”: the final outcome and victory will be yours, or you are already above them in rank because you stand upon the truth and fight for God, your dead enter Paradise, while they stand upon falsehood and fight for Satan and their dead enter the Fire. Do not fail in your striving “if you are believers,” for faith entails a heart strengthened by trusting and relying upon God—or if you believe what I promised of elevation and victory. God knows best. [T182]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T182; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T182","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T182","original_body_sha256":"4b87c1f95b9e0dbd24619be5d6b7344d6979a4ed121ebeae0e9da28a5449e523","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":146,"print_label":"T146","linked_occurrences":[{"record_id":"q3-137-139","segment_index":1,"q":"3:137–139","source":"Cairo print · Volume I, pp. 411–412"}]},{"id":"XIV-N126","historical_note_id":"T183","title":"Qarḥ (قَرْح), alternation of victory and the syntax of purpose","content":"The proposed grammatical roles are paired alternatives. If al-ayyām qualifies the demonstrative, ‘We alternate them’ supplies the predicate; if ‘the days’ is already the predicate, the following clause can describe their circumstance. The omitted purpose before ‘that God may know’ allows several purposes for alternation to remain unexpressed. The final subjunctive ‘and know the patient’ is explained through an understood an after a wāw of combination. Ibn ʿAjība subsequently interprets the knowing as manifestation in events, so the syntax of purpose should not be read as an assertion that God lacked the relevant knowledge beforehand.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[412,413],"quran_context":"3:140–143","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-140-143","segment_index":0,"quran_context":"3:140–143","printed_pages":[412,413],"anchor_paragraph":"I say: Qarḥ ( القرح ), pronounced with fatḥa or ḍamma, means a wound. Alternatively, with fatḥa it is a wound and with ḍamma the pain and suffering of that wound. Mudāwala ( المداولة ) is the form expressing reciprocal action ( مفاعلة ) from dawla ( دولة ), a turn of victory or mastery. “These days” ( الأيام ) may be an adjective ( نعت ) or predicate ( خبر ), while “We cause them to alternate” ( نداولها ) may be the predicate ( خبر ) or a circumstantial clause ( حال ). “So that God may know” ( وليعلم ) is attached to an omitted expression ( محذوف ): “He did what He did in turning the fortunes of war so that He might know.” Or it may be coordinated with another omitted purpose: “We cause the days to alternate in order that such-and-such may happen, and that He might know ...,” indicating that there is more than one purpose and that believers’ sufferings involve benefits not fully known to us. “And know the patient” ( ويعلم الصابرين ) is in the subjunctive ( منصوب ) through an understood an ( أن ), the wāw (و) expressing accompaniment: the two acts of knowing occur together. [XIV-N126]","segment_title":"Qarḥ (قَرْح), alternation of victory and the syntax of purpose","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [412, 413]","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-140-143","segment_index":0,"quran_context":"3:140–143","printed_pages":[412,413],"anchor_paragraph":"I say: Qarḥ ( القرح ), pronounced with fatḥa or ḍamma, means a wound. Alternatively, with fatḥa it is a wound and with ḍamma the pain and suffering of that wound. Mudāwala ( المداولة ) is the form expressing reciprocal action ( مفاعلة ) from dawla ( دولة ), a turn of victory or mastery. “These days” ( الأيام ) may be an adjective ( نعت ) or predicate ( خبر ), while “We cause them to alternate” ( نداولها ) may be the predicate ( خبر ) or a circumstantial clause ( حال ). “So that God may know” ( وليعلم ) is attached to an omitted expression ( محذوف ): “He did what He did in turning the fortunes of war so that He might know.” Or it may be coordinated with another omitted purpose: “We cause the days to alternate in order that such-and-such may happen, and that He might know ...,” indicating that there is more than one purpose and that believers’ sufferings involve benefits not fully known to us. “And know the patient” ( ويعلم الصابرين ) is in the subjunctive ( منصوب ) through an understood an ( أن ), the wāw (و) expressing accompaniment: the two acts of knowing occur together. [T183]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T183; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T183","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T183","original_body_sha256":"512bf3fac717fade2a95fc29ea396f46e77b48d1b8fc3fa513d1d352bf53d6e9","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":147,"print_label":"T147","linked_occurrences":[{"record_id":"q3-140-143","segment_index":0,"q":"3:140–143","source":"Cairo print · Volume I, pp. 412–414"}]},{"id":"XIV-N127","historical_note_id":"T184","title":"The two battles and the alternating fortunes of nations","content":"The first explanation compares Uḥud with Badr; the second compares two phases of Uḥud itself, initial Muslim success and the subsequent reversal. The connective ‘or’ introduces that alternative chronology. ‘A similar wound’ concerns the shared experience of loss and injury, not an assertion that the listed casualty figures are mathematically identical. Al-Bukhārī 3986 independently records the Badr figures of seventy killed and seventy captured alongside seventy casualties at Uḥud. Ibn ʿAjība’s different Uḥud total has an earlier tafsīr parallel noted at I:412. Keeping the alternatives separate prevents the two-battle and one-battle explanations from becoming a confused narrative.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[413],"quran_context":"3:140–143","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-bukhari","work":"bukhari","locator":"Hadith3986","arabic_anchor":"سبعين أسيرا وسبعين قتيلا","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-140-143","segment_index":1,"quran_context":"3:140–143","printed_pages":[413],"anchor_paragraph":"The Real, exalted is His majesty, says: “If a wound touches you” at Uḥud—whether through deaths or bodily injuries—“a similar wound has touched the other people,” your opponents, at Badr. If seventy-five of you were killed at Uḥud, seventy of them had been killed and seventy captured at Badr. Or it means that a similar injury touched them during Uḥud itself: at first you struck them and put them to flight, before disobeying the Messenger’s command, just as they later struck you. [XIV-N127]","segment_title":"The two battles and the alternating fortunes of nations","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [413]; bukhari: Hadith3986","revision_status":"","word_count":97,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-140-143","segment_index":1,"quran_context":"3:140–143","printed_pages":[413],"anchor_paragraph":"The Real, exalted is His majesty, says: “If a wound touches you” at Uḥud—whether through deaths or bodily injuries—“a similar wound has touched the other people,” your opponents, at Badr. If seventy-five of you were killed at Uḥud, seventy of them had been killed and seventy captured at Badr. Or it means that a similar injury touched them during Uḥud itself: at first you struck them and put them to flight, before disobeying the Messenger’s command, just as they later struck you. [T184]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T184; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T184","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T184","original_body_sha256":"5d7d8756e2d5254e5dfacecbdc0396ef4d494ed2acaf44cc64b0729a3ccb608d","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":148,"print_label":"T148","linked_occurrences":[{"record_id":"q3-140-143","segment_index":1,"q":"3:140–143","source":"Cairo print · Volume I, pp. 412–414"}]},{"id":"XIV-N128","historical_note_id":"T185","title":"The two battles and the alternating fortunes of nations","content":"The phrase ‘so that God may know’ is explained by the commentary as the public manifestation of who truly believes. Its parallel gloss at Q3:142, ʿilm ẓuhūrihi, makes the same point: striving and patience become actual and observable. Alternating victory therefore serves discrimination and purification within the argument. It does not make success a direct sign of divine approval, for the text expressly denies that the temporary victors must be loved by God. Maḥq then supplies a different image from sudden destruction: diminution proceeding until the thing disappears.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[413],"quran_context":"3:140–143","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-140-143","segment_index":1,"quran_context":"3:140–143","printed_pages":[413],"anchor_paragraph":"The Muslims prevailed at Badr, and mastery was theirs; at Uḥud the idolaters prevailed. “Days” here may mean days of worldly life generally, or more particularly days of victory and mastery. God granted the idolaters a turn at Uḥud so that the believers might be distinguished from the hypocrites and their reality become publicly evident—“so that God may know those who believe,” in the sense of their state being manifested to people—and “take from among you witnesses” ( شهداء ), those who died in holy striving and were honoured with martyrdom ( شهادة ). The idolaters’ temporary success does not prove divine love for them: “God does not love wrongdoers.” He permitted their advantage “so that God may purify those who believe,” cleansing and refining them of sins. In turn, He grants the believers power over their opponents “so that He may wipe out the disbelievers.” Maḥq ( المحق ) means the gradual diminution of a thing until it disappears. [XIV-N128]","segment_title":"The two battles and the alternating fortunes of nations","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [413]","revision_status":"","word_count":88,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-140-143","segment_index":1,"quran_context":"3:140–143","printed_pages":[413],"anchor_paragraph":"The Muslims prevailed at Badr, and mastery was theirs; at Uḥud the idolaters prevailed. “Days” here may mean days of worldly life generally, or more particularly days of victory and mastery. God granted the idolaters a turn at Uḥud so that the believers might be distinguished from the hypocrites and their reality become publicly evident—“so that God may know those who believe,” in the sense of their state being manifested to people—and “take from among you witnesses” ( شهداء ), those who died in holy striving and were honoured with martyrdom ( شهادة ). The idolaters’ temporary success does not prove divine love for them: “God does not love wrongdoers.” He permitted their advantage “so that God may purify those who believe,” cleansing and refining them of sins. In turn, He grants the believers power over their opponents “so that He may wipe out the disbelievers.” Maḥq ( المحق ) means the gradual diminution of a thing until it disappears. [T185]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T185; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T185","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T185","original_body_sha256":"971f326eb1f64b16e8c82a952ea3a656b25066800db2ecd31c73bec5cc43529f","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":149,"print_label":"T149","linked_occurrences":[{"record_id":"q3-140-143","segment_index":1,"q":"3:140–143","source":"Cairo print · Volume I, pp. 412–414"}]},{"id":"XIV-N129","historical_note_id":"T186","title":"The testing of seekers as purification and disclosure","content":"The allusion deliberately uses two senses of shahāda: dying as a martyr under trial, and becoming a witness of the invisible Dominion through perseverance. Al-Ḥallāj is introduced as an example within Ibn ʿAjība’s first interpretation; the text does not offer a historical examination of his case. The second interpretation turns the same Qurʾānic word toward contemplative witnessing. The caves-and-snake comparison warns, within the author’s argument, against assuming that repeated impunity proves rejection of saints harmless. It is an illustrative comparison, not a separately sourced biographical event.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[413,414],"quran_context":"3:140–143","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-140-143","segment_index":2,"quran_context":"3:140–143","printed_pages":[413,414],"anchor_paragraph":"“He takes martyrs from among you” if they die in such tribulations, like al-Ḥallāj and others; or He takes witnesses of the Dominion ( شهداء الملكوت ) from those who persevere until they attain direct witnessing ( الشهود ). “God does not love wrongdoers,” those who injure His friends: rather, He detests them and sets them far away. “So that God may purify those who believe” along the path of special realization: He gives people power over them to cleanse them of the residues of sensory attachment ( بقايا الحس ). “And He may wipe out” those who reject them by reason of the wrongs they commit against them. The author compares someone who rejects the spiritually affiliated ( أهل النسبة ) to a person who thrusts his hand into successive caves. Having emerged safe from the first two, he says, “Nothing in them can harm me”; he then reaches into a third cave, where a snake bites and kills him. [XIV-N129]","segment_title":"The testing of seekers as purification and disclosure","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [413, 414]","revision_status":"","word_count":86,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-140-143","segment_index":2,"quran_context":"3:140–143","printed_pages":[413,414],"anchor_paragraph":"“He takes martyrs from among you” if they die in such tribulations, like al-Ḥallāj and others; or He takes witnesses of the Dominion ( شهداء الملكوت ) from those who persevere until they attain direct witnessing ( الشهود ). “God does not love wrongdoers,” those who injure His friends: rather, He detests them and sets them far away. “So that God may purify those who believe” along the path of special realization: He gives people power over them to cleanse them of the residues of sensory attachment ( بقايا الحس ). “And He may wipe out” those who reject them by reason of the wrongs they commit against them. The author compares someone who rejects the spiritually affiliated ( أهل النسبة ) to a person who thrusts his hand into successive caves. Having emerged safe from the first two, he says, “Nothing in them can harm me”; he then reaches into a third cave, where a snake bites and kills him. [T186]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T186; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T186","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T186","original_body_sha256":"39fffdc727a332f00988d26381035ce7d790d21f8925f9c7af91735d9f6e79a8","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":150,"print_label":"T150","linked_occurrences":[{"record_id":"q3-140-143","segment_index":2,"q":"3:140–143","source":"Cairo print · Volume I, pp. 412–414"}]},{"id":"XIV-N130","historical_note_id":"T187","title":"The testing of seekers as purification and disclosure","content":"The quoted Ḥikam aphorism distinguishes what God brings to the servant from the works the servant offers to God. Taʿarruf is God’s making Himself known, not merely the acquisition of information by the disciple. Ibn ʿAjība applies that distinction to a trial that may initially feel like rejection: reduced outward activity during it does not necessarily mean lost spiritual benefit. The source aphorism begins conditionally, ‘if He opens,’ and does not dispense generally with assigned devotions. Its argumentative force is the disproportion between divine initiative and the servant’s offering, rather than the numerical quantity of acts performed.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[414],"quran_context":"3:140–143","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-hikam","work":"hikam","locator":"Aphorism beginning idha fataha laka wijhatan; first page unit before PageV01P282","arabic_anchor":"التعرف هو موروده عليك والأعمال أنت مبديها إليه","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0709IbnCataAllahSikandari/0709IbnCataAllahSikandari.HikamCataiyya/0709IbnCataAllahSikandari.HikamCataiyya.JK009323-ara1","local_file":"audit_work/revision_XIV_research/public_sources/hikam.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-140-143","segment_index":2,"quran_context":"3:140–143","printed_pages":[414],"anchor_paragraph":"In the Ḥikam ( الحكم ) one reads: “When God opens for you a direction through which He makes Himself known ( وجهة من التعرف ), do not concern yourself if your work is slight. He opened it only because He wants to make Himself known to you through it. Do you not know that self-disclosure ( التعرف ) is what He brings to you, while works are what you offer Him? How incomparable are what you offer Him and what He brings to you!” And God grants success. [XIV-N130]","segment_title":"The testing of seekers as purification and disclosure","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [414]; hikam: Aphorism beginning idha fataha laka wijhatan; first page unit before PageV01P282","revision_status":"","word_count":97,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-140-143","segment_index":2,"quran_context":"3:140–143","printed_pages":[414],"anchor_paragraph":"In the Ḥikam ( الحكم ) one reads: “When God opens for you a direction through which He makes Himself known ( وجهة من التعرف ), do not concern yourself if your work is slight. He opened it only because He wants to make Himself known to you through it. Do you not know that self-disclosure ( التعرف ) is what He brings to you, while works are what you offer Him? How incomparable are what you offer Him and what He brings to you!” And God grants success. [T187]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T187; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T187","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T187","original_body_sha256":"349b1c8429ddd376c021d1d11596909feca04315f1535a34cc64927de47d061a","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":151,"print_label":"T151","linked_occurrences":[{"record_id":"q3-140-143","segment_index":2,"q":"3:140–143","source":"Cairo print · Volume I, pp. 412–414"}]},{"id":"XIV-N131","historical_note_id":"T188","title":"Kitāban muʾajjalan (كِتاباً مُؤَجَّلاً)","content":"Kitāban is analysed as a verbal noun belonging to an understood verb of writing or decreeing. It therefore reinforces the determination of death rather than naming a book that a person must consult. Muʾajjalan qualifies that decree as assigned a term. ‘At an appointed time’ expresses its consequence, while Ibn ʿAjība’s grammatical paraphrase makes the underlying construction explicit. The explanation belongs to Q3:145 and should remain distinct from the preceding verse’s question about how believers respond to the death or killing of a messenger.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[414],"quran_context":"3:144–145","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-144-145","segment_index":0,"quran_context":"3:144–145","printed_pages":[414],"anchor_paragraph":"I say: “In writing, at an appointed time” ( كتاباً مؤجلاً ): kitāban ( كتاباً ) is a verbal noun ( مصدر ), meaning, “He wrote or decreed death as a writing whose time has been appointed.” [XIV-N131]","segment_title":"Kitāban muʾajjalan (كِتاباً مُؤَجَّلاً)","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [414]","revision_status":"","word_count":87,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-144-145","segment_index":0,"quran_context":"3:144–145","printed_pages":[414],"anchor_paragraph":"I say: “In writing, at an appointed time” ( كتاباً مؤجلاً ): kitāban ( كتاباً ) is a verbal noun ( مصدر ), meaning, “He wrote or decreed death as a writing whose time has been appointed.” [T188]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T188; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T188","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T188","original_body_sha256":"2f14e8e8626801417c67c77af424cb0c4fb9ff87f70917964d9c8935b6b9a141","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":152,"print_label":"T152","linked_occurrences":[{"record_id":"q3-144-145","segment_index":0,"q":"3:144–145","source":"Cairo print · Volume I, pp. 414–416"}]},{"id":"XIV-N132","historical_note_id":"T189","title":"A report of death does not abolish the message","content":"The conditional ‘if he dies or is killed’ does not state that Muḥammad died at Uḥud. It exposes the inadequacy of a faith dependent upon the messenger’s continued physical presence. Ibn ʿAjība preserves two explanations of the rebuke: a hypothetical reversal, or words already spoken by hypocrites while others were silent. The expression ‘turn back upon your heels’ is consequently explained as abandonment of the established religion. The ensuing battle narrative accounts for the rumour that prompted the discussion, while the later allusion applies the distinction between messenger and message to spiritual instruction.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[414,415],"quran_context":"3:144–145","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[414,415],"anchor_paragraph":"The Real, exalted is His majesty, says: “Muḥammad is only a messenger,” susceptible to what befell the messengers before him: “Messengers have passed away before him”; he too shall pass away as they did, through death or killing. “If he dies or is killed, will you turn back upon your heels,” after his revealed Law ( شريعة ) has been established and his proofs made manifest? God rebukes them for the possibility of an actual reversal should the Prophet die or be killed—or for the remarks already made by certain hypocrites while the others remained silent. [XIV-N132]","segment_title":"A report of death does not abolish the message","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [414, 415]","revision_status":"","word_count":93,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[414,415],"anchor_paragraph":"The Real, exalted is His majesty, says: “Muḥammad is only a messenger,” susceptible to what befell the messengers before him: “Messengers have passed away before him”; he too shall pass away as they did, through death or killing. “If he dies or is killed, will you turn back upon your heels,” after his revealed Law ( شريعة ) has been established and his proofs made manifest? God rebukes them for the possibility of an actual reversal should the Prophet die or be killed—or for the remarks already made by certain hypocrites while the others remained silent. [T189]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T189; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T189","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T189","original_body_sha256":"66b88a081cd638594f99c9b42e11447e921a2bfa6cfff146b8fbfd64020659a4","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":153,"print_label":"T153","linked_occurrences":[{"record_id":"q3-144-145","segment_index":1,"q":"3:144–145","source":"Cairo print · Volume I, pp. 414–416"}]},{"id":"XIV-N133","historical_note_id":"T190","title":"A report of death does not abolish the message","content":"The heading ‘authors of the military narratives’ introduces a composite account, not one continuous hadith with a supplied chain. Its component episodes have different parallels. Al-Bukhārī 3039 records ʿAbd Allāh b. Jubayr’s fifty men, their instructions to remain and their departure toward booty. Muslim 2470 separately reports the sword offered ‘with its due right’ and Abū Dujāna accepting it. These identifications support particular episodes; they do not automatically verify the extra dialogue about bending the sword, the turban, swagger, commanders, or the full sequence of events as assembled here.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[415],"quran_context":"3:144–145","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-bukhari","work":"bukhari","locator":"Hadith3039","arabic_anchor":"وكانوا خمسين رجلا عبد الله بن جبير","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."},{"source_id":"XIV-OT-muslim","work":"muslim","locator":"Hadith2470","arabic_anchor":"فمن يأخذه بحقه","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0261Muslim/0261Muslim.Sahih/0261Muslim.Sahih.Shamela0001727-ara1.mARkdown","local_file":"audit_work/revision_XIV_research/public_sources/muslim.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[415],"anchor_paragraph":"According to the authors of the military narratives ( أصحاب المغازي ), the Prophet, blessings and peace be upon him, marched to the ravine of Uḥud with seven hundred men. He appointed ʿAbd Allāh ibn Jubayr over fifty archers and instructed them: “Drive the attackers away with arrows so that they do not come upon us from behind. Do not leave your post whether we win or lose, for we shall remain victorious as long as you stay in your positions.” The Quraysh arrived, Khālid ibn al-Walīd on their right wing and ʿIkrima on their left, with women accompanying the forces. [XIV-N133]","segment_title":"A report of death does not abolish the message","anchor_basis":"Exact active annotation call in current HTML"},{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[415],"anchor_paragraph":"When the fighting began the Prophet asked: “Who will take this sword and discharge its right?” A number of men came, but he withheld it until Abū Dujāna approached. “What is its right, Messenger of God?” he asked. He answered: “That you strike the enemy with it until it bends.” Abū Dujāna was courageous and moved proudly in battle. Taking the sword, he wrapped a red turban around his head and strode between the two armies with a swagger. The Prophet said: “God hates such a way of walking, except in this place.” [XIV-N133]","segment_title":"A report of death does not abolish the message","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [415]; bukhari: Hadith3039; muslim: Hadith2470","revision_status":"","word_count":89,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[415],"anchor_paragraph":"According to the authors of the military narratives ( أصحاب المغازي ), the Prophet, blessings and peace be upon him, marched to the ravine of Uḥud with seven hundred men. He appointed ʿAbd Allāh ibn Jubayr over fifty archers and instructed them: “Drive the attackers away with arrows so that they do not come upon us from behind. Do not leave your post whether we win or lose, for we shall remain victorious as long as you stay in your positions.” The Quraysh arrived, Khālid ibn al-Walīd on their right wing and ʿIkrima on their left, with women accompanying the forces. [T190]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T190; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T190","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T190","original_body_sha256":"9b484dba2a5b1f7fbe583b42ba4bd810b8eb13163a5b99d3ccddc2f8d203035f","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":154,"print_label":"T154","linked_occurrences":[{"record_id":"q3-144-145","segment_index":1,"q":"3:144–145","source":"Cairo print · Volume I, pp. 414–416"},{"record_id":"q3-144-145","segment_index":1,"q":"3:144–145","source":"Cairo print · Volume I, pp. 414–416"}]},{"id":"XIV-N134","historical_note_id":"T191","title":"A report of death does not abolish the message","content":"Several distinct reports have been woven into this paragraph. Muslim 1790 records the facial wound, damaged tooth and broken helmet; al-Bukhārī 3724 separately records Ṭalḥa’s paralysed hand used to protect the Prophet. Neither passage by itself supplies the entire narrative about Ibn Qamiʾa, mistaken identity, the number who rallied, or Qatāda’s restored eye. Accordingly, a citation attached to the paragraph must not be read as authenticating all of it. The Qurʾānic discussion concerns the effect of a death rumour; the medical and miraculous particulars belong to the transmitted battle narratives.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[415],"quran_context":"3:144–145","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-muslim","work":"muslim","locator":"Hadith1790","arabic_anchor":"جرح وجه ... وكسرت رباعيته وهشمت البيضة","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0261Muslim/0261Muslim.Sahih/0261Muslim.Sahih.Shamela0001727-ara1.mARkdown","local_file":"audit_work/revision_XIV_research/public_sources/muslim.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."},{"source_id":"XIV-OT-bukhari","work":"bukhari","locator":"Hadith3724","arabic_anchor":"رأيت يد طلحة ... قد شلت","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[415],"anchor_paragraph":"ʿAbd Allāh ibn Qamiʾa al-Ḥārithī struck the Prophet with a stone, breaking his nose and an incisor, wounding his face and breaking the helmet upon his head. Muṣʿab ibn ʿUmayr, who carried the standard, defended him, but Ibn Qamiʾa killed Muṣʿab believing he had killed the Prophet. He returned to his people crying, “I have killed Muḥammad.” Another cry spread: “Muḥammad has died!” Some said the cry came from Satan. The Muslim fighters fell back. The Messenger called, “Come to me, servants of God!” Thirty Companions rallied around him, formed a protective ring and drove off the idolaters. Ṭalḥa ibn ʿUbayd Allāh’s hand was wounded and became paralysed while protecting him; Qatāda ibn al-Nuʿmān’s eye was struck so that it fell upon his cheek. The source relates that the Prophet restored it to its place and it became better than before. [XIV-N134]","segment_title":"A report of death does not abolish the message","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [415]; muslim: Hadith1790; bukhari: Hadith3724","revision_status":"","word_count":91,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[415],"anchor_paragraph":"ʿAbd Allāh ibn Qamiʾa al-Ḥārithī struck the Prophet with a stone, breaking his nose and an incisor, wounding his face and breaking the helmet upon his head. Muṣʿab ibn ʿUmayr, who carried the standard, defended him, but Ibn Qamiʾa killed Muṣʿab believing he had killed the Prophet. He returned to his people crying, “I have killed Muḥammad.” Another cry spread: “Muḥammad has died!” Some said the cry came from Satan. The Muslim fighters fell back. The Messenger called, “Come to me, servants of God!” Thirty Companions rallied around him, formed a protective ring and drove off the idolaters. Ṭalḥa ibn ʿUbayd Allāh’s hand was wounded and became paralysed while protecting him; Qatāda ibn al-Nuʿmān’s eye was struck so that it fell upon his cheek. The source relates that the Prophet restored it to its place and it became better than before. [T191]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T191; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T191","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T191","original_body_sha256":"cd102ff183e678133c09342e68248994f108363d0d679f053473281fdfaadadb","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":155,"print_label":"T155","linked_occurrences":[{"record_id":"q3-144-145","segment_index":1,"q":"3:144–145","source":"Cairo print · Volume I, pp. 414–416"}]},{"id":"XIV-N135","historical_note_id":"T192","title":"A report of death does not abolish the message","content":"The quoted prayer contrasts the conduct of the withdrawing Muslims with that of the opposing polytheists: Anas seeks pardon for the former and disavows the latter. Al-Bukhārī 2805 transmits this contrast, his advance, his death and the identification of his body. It does not in that passage give every speech quoted by the commentary in response to the rumour. Anas b. al-Naḍr is the uncle of the narrator Anas b. Mālik, so the two must not be conflated. Ibn ʿAjība subsequently makes the uncle an example of thankfulness expressed as steadfastness.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[415,416],"quran_context":"3:144–145","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-bukhari","work":"bukhari","locator":"Hadith2805","arabic_anchor":"غاب عمي أنس بن النضر ... إني أعتذر إليك","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[415,416],"anchor_paragraph":"The rumour of the Prophet’s death spread. Some Muslims said, “If only Ibn Ubayy could obtain for us a guarantee of safety from Abū Sufyān.” Some hypocrites said: “Had he been a prophet, he would not have been killed. Return to your former religion.” Anas ibn al-Naḍr, the uncle of Anas ibn Mālik, replied: “If Muḥammad has been killed, the Lord of Muḥammad does not die. What would you do with life after him? Fight for what he fought for, until you die upon what he died upon.” He then prayed: “God, I offer my apology for what these”—meaning the Muslims—“have done, and I dissociate myself before You from what these”—meaning the unbelievers—“have done.” He took up his sword and fought until killed. May God show him mercy. [XIV-N135]","segment_title":"A report of death does not abolish the message","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [415, 416]; bukhari: Hadith2805","revision_status":"","word_count":91,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[415,416],"anchor_paragraph":"The rumour of the Prophet’s death spread. Some Muslims said, “If only Ibn Ubayy could obtain for us a guarantee of safety from Abū Sufyān.” Some hypocrites said: “Had he been a prophet, he would not have been killed. Return to your former religion.” Anas ibn al-Naḍr, the uncle of Anas ibn Mālik, replied: “If Muḥammad has been killed, the Lord of Muḥammad does not die. What would you do with life after him? Fight for what he fought for, until you die upon what he died upon.” He then prayed: “God, I offer my apology for what these”—meaning the Muslims—“have done, and I dissociate myself before You from what these”—meaning the unbelievers—“have done.” He took up his sword and fought until killed. May God show him mercy. [T192]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T192; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T192","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T192","original_body_sha256":"0125d0c083d64ae406cb054a43d28381e5c97d28cc69151620ae527cc485517d","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":156,"print_label":"T156","linked_occurrences":[{"record_id":"q3-144-145","segment_index":1,"q":"3:144–145","source":"Cairo print · Volume I, pp. 414–416"}]},{"id":"XIV-N136","historical_note_id":"T193","title":"A report of death does not abolish the message","content":"The two explanations of idhn are divine willing and permission to the angel who takes the soul. Both serve the claim that death has a determined term. In this local argument, fear of death should not make believers abandon the duty under discussion. The passage is theological exhortation within a battle commentary, not a calculation of an individual’s remaining lifespan. The immediately following contrast between worldly and otherworldly reward shifts attention from the time of death to intention: the archers’ pursuit of booty exemplifies seeking an immediate return at the expense of their assigned position.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[416],"quran_context":"3:144–145","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[416],"anchor_paragraph":"“No soul can die except by God’s permission”: through His will and volition, or through His permission to an angel charged with taking that soul. Every soul has a named term within God’s knowledge and decree; it cannot be delayed by an hour nor brought forward, either by holding back from battle or by plunging into it. This encourages steadfastness in fighting and promises preservation of the Messenger until his appointed term has elapsed. God has written death “as a writing with an appointed time”: its term neither advances nor retreats. [XIV-N136]","segment_title":"A report of death does not abolish the message","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [416]","revision_status":"","word_count":95,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-144-145","segment_index":1,"quran_context":"3:144–145","printed_pages":[416],"anchor_paragraph":"“No soul can die except by God’s permission”: through His will and volition, or through His permission to an angel charged with taking that soul. Every soul has a named term within God’s knowledge and decree; it cannot be delayed by an hour nor brought forward, either by holding back from battle or by plunging into it. This encourages steadfastness in fighting and promises preservation of the Messenger until his appointed term has elapsed. God has written death “as a writing with an appointed time”: its term neither advances nor retreats. [T193]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T193; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T193","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T193","original_body_sha256":"17afb9c23a5b3fcda4e5c7c8bc5c9122389234b0227849d5dd8587ed323d09c0","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":157,"print_label":"T157","linked_occurrences":[{"record_id":"q3-144-145","segment_index":1,"q":"3:144–145","source":"Cairo print · Volume I, pp. 414–416"}]},{"id":"XIV-N137","historical_note_id":"T194","title":"The death of a master and the independence of the disciple’s vision","content":"The passage distinguishes the intermediary from the One to whom the intermediary directs the seeker. Its two conditional branches are decisive: a disciple firmly established in witnessing can continue after the teacher dies; one not established seeks someone able to complete his formation. Thus sufficiency in God does not erase the text’s acknowledgment of further guidance. The later anecdote intensifies the contrast through the Living One who does not die. Ibn ʿAjība’s concluding criterion for the true teacher is precisely that his direction eventually frees the disciple from dependence upon the teacher’s own person.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[416],"quran_context":"3:144–145","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-144-145","segment_index":2,"quran_context":"3:144–145","printed_pages":[416],"anchor_paragraph":"The disciple should seek sufficiency in God ( الاستغناء بالله ), resting upon none other than Him. His spiritual insight ( بصيرة ) should penetrate so deeply that he is absent to the intermediary ( الواسطة ) through witnessing the One mediated ( الموسوط ). If his spiritual master dies, he will not turn back upon his heels. If he is firmly established in witnessing ( الشهود ), he has become independent of every created existent. If he has not attained establishment, he seeks someone who can bring him to completion. To remain fixed on the intermediaries is to remain at the gifts without witnessing the Giver ( المنعم ). He is not fully thankful to the Giver until nothing can veil Him from him. [XIV-N137]","segment_title":"The death of a master and the independence of the disciple’s vision","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [416]","revision_status":"","word_count":94,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-144-145","segment_index":2,"quran_context":"3:144–145","printed_pages":[416],"anchor_paragraph":"The disciple should seek sufficiency in God ( الاستغناء بالله ), resting upon none other than Him. His spiritual insight ( بصيرة ) should penetrate so deeply that he is absent to the intermediary ( الواسطة ) through witnessing the One mediated ( الموسوط ). If his spiritual master dies, he will not turn back upon his heels. If he is firmly established in witnessing ( الشهود ), he has become independent of every created existent. If he has not attained establishment, he seeks someone who can bring him to completion. To remain fixed on the intermediaries is to remain at the gifts without witnessing the Giver ( المنعم ). He is not fully thankful to the Giver until nothing can veil Him from him. [T194]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T194; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T194","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T194","original_body_sha256":"b4fbd9a217d3124f6bd331fe9e1d309f5e77fdc67cdd2a84aac7d1a923a4106d","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":158,"print_label":"T158","linked_occurrences":[{"record_id":"q3-144-145","segment_index":2,"q":"3:144–145","source":"Cairo print · Volume I, pp. 414–416"}]},{"id":"XIV-N138","historical_note_id":"T195","title":"The death of a master and the independence of the disciple’s vision","content":"Abū Bakr’s declaration and recitation of Q3:144 are attested together in al-Bukhārī 4454. That source also describes the listeners’ response and ʿUmar’s realization that the Prophet had died. Ibn ʿAjība supplies a further spiritual interpretation: Abū Bakr had passed from contemplating the gift to contemplating the Giver. That vocabulary belongs to the commentator’s explanation, not to the quoted declaration itself. The shift from the Uḥud rumour to the Prophet’s actual death also changes historical setting. Keeping source speech, subsequent event and spiritual interpretation distinct preserves the force of each.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[416],"quran_context":"3:144–145","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-bukhari","work":"bukhari","locator":"Hadith4454","arabic_anchor":"فإن الله حي لا يموت ... وما محمد إلا رسول","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-144-145","segment_index":2,"quran_context":"3:144–145","printed_pages":[416],"anchor_paragraph":"When the Prophet died, people were stunned and bewildered because they stood at the gift and what they had witnessed of it. The Truthful One ( الصدِّيق ), however, had passed beyond witnessing the gift to witnessing the Giver. He addressed the people, saying: “Whoever worshipped Muḥammad should know that Muḥammad has died; whoever worships God should know that God is Ever-Living and does not die.” He then recited: “Muḥammad is only a messenger ...” down to “He shall reward the thankful.” These are those who pass through to the witnessing of the Giver and do not remain with the gift. [XIV-N138]","segment_title":"The death of a master and the independence of the disciple’s vision","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [416]; bukhari: Hadith4454","revision_status":"","word_count":89,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-144-145","segment_index":2,"quran_context":"3:144–145","printed_pages":[416],"anchor_paragraph":"When the Prophet died, people were stunned and bewildered because they stood at the gift and what they had witnessed of it. The Truthful One ( الصدِّيق ), however, had passed beyond witnessing the gift to witnessing the Giver. He addressed the people, saying: “Whoever worshipped Muḥammad should know that Muḥammad has died; whoever worships God should know that God is Ever-Living and does not die.” He then recited: “Muḥammad is only a messenger ...” down to “He shall reward the thankful.” These are those who pass through to the witnessing of the Giver and do not remain with the gift. [T195]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T195; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T195","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T195","original_body_sha256":"52c9bf7d97f14210ab5af34c3d43e158040a5166b5b8b49ab51082708f507e18","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":159,"print_label":"T159","linked_occurrences":[{"record_id":"q3-144-145","segment_index":2,"q":"3:144–145","source":"Cairo print · Volume I, pp. 414–416"}]},{"id":"XIV-N139","historical_note_id":"T196","title":"Kaʾayyin (كَأَيِّن), ribbiyyūn (رِبِّيُّون), and qātala/qutila","content":"The alternatives depend on both the verbal reading and the sentence division. With qutila, ‘was killed,’ the prophet may be its subject and ‘with him were many devoted followers’ a new clause; alternatively the followers are those killed with him. With qātala, ‘fought,’ the construction describes fighting. Ribbiyyūn itself receives several lexical explanations, so ‘companies’ and ‘Godfearing scholars’ are also alternatives. Cairo’s verse block prints the passive reading and the exposition discusses both. The verbal readings and clause divisions provide distinct interpretations.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[416,417],"quran_context":"3:146–148","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-146-148","segment_index":0,"quran_context":"3:146–148","printed_pages":[416,417],"anchor_paragraph":"Ribbiyyūn ( الرِبِّيُّون ) is explained as the plural of rubba ( رُبَّة ), meaning a company or group; hence “many companies fought with him.” Other explanations make the word “devout, Godfearing scholars” ( العلماء الأتقياء ), or rulers ( الولاة ). The noun may be the subject ( مبتدأ ) of a new clause if one stops at a reading meaning “was killed” ( قُتِل ), or it may be the passive subject ( نائب فاعل ) of that form, or the agent/subject ( فاعل ) if one reads the verb in the active ( بالبناء للفاعل ). “Many” ( كثير ) qualifies ribbiyyūn , as in “and the angels, after that, are supporters” [Q 66:4]; a word on the pattern faʿīl can be predicated of singulars and plurals alike. [XIV-N139]","segment_title":"Kaʾayyin (كَأَيِّن), ribbiyyūn (رِبِّيُّون), and qātala/qutila","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [416, 417]","revision_status":"","word_count":93,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-146-148","segment_index":0,"quran_context":"3:146–148","printed_pages":[416,417],"anchor_paragraph":"Ribbiyyūn ( الرِبِّيُّون ) is explained as the plural of rubba ( رُبَّة ), meaning a company or group; hence “many companies fought with him.” Other explanations make the word “devout, Godfearing scholars” ( العلماء الأتقياء ), or rulers ( الولاة ). The noun may be the subject ( مبتدأ ) of a new clause if one stops at a reading meaning “was killed” ( قُتِل ), or it may be the passive subject ( نائب فاعل ) of that form, or the agent/subject ( فاعل ) if one reads the verb in the active ( بالبناء للفاعل ). “Many” ( كثير ) qualifies ribbiyyūn , as in “and the angels, after that, are supporters” [Q 66:4]; a word on the pattern faʿīl can be predicated of singulars and plurals alike. [T196]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T196; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T196","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T196","original_body_sha256":"77e0b778a325bcafb96d8d115857a137c73caf3bf0ae5ded2a61dd0b14e860a1","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":160,"print_label":"T160","linked_occurrences":[{"record_id":"q3-146-148","segment_index":0,"q":"3:146–148","source":"Cairo print · Volume I, pp. 416–418"}]},{"id":"XIV-N140","historical_note_id":"T197","title":"The followers of former prophets","content":"The two stated preferences support different analyses of the passive wording. The death rumour at Uḥud makes the example of a killed prophet and steadfast survivors rhetorically apt. The competing assertion that no prophet was killed in open battle favours taking the followers as those killed. Ibn ʿAjība reports both arguments before considering qātala, ‘fought.’ He does not supply a historical demonstration covering every prophet, and that universal assertion should not be treated as independently established merely because it appears here. The constant lesson across the alternatives is the survivors’ steadfastness.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[417],"quran_context":"3:146–148","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-146-148","segment_index":1,"quran_context":"3:146–148","printed_pages":[417],"anchor_paragraph":"The Real, exalted is His majesty, says: “How many a prophet was killed” in battle, with great companies or Godfearing scholars accompanying him, and they did not fail or grow weak. Rather, they stood firm in their faith and in their struggle against the enemy. Or the verse may be understood as: how many prophets had numerous devoted followers who were killed fighting alongside them? The survivors remained steadfast and did not grow languid or weak before the enemy. The first interpretation is strengthened by the cry heard at Uḥud that Muḥammad had died, for God set before them an exemplary contrast through “how many a prophet was killed”; the other is said to gain support from the assertion that no prophet was ever killed in open battle. [XIV-N140]","segment_title":"The followers of former prophets","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [417]","revision_status":"","word_count":91,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-146-148","segment_index":1,"quran_context":"3:146–148","printed_pages":[417],"anchor_paragraph":"The Real, exalted is His majesty, says: “How many a prophet was killed” in battle, with great companies or Godfearing scholars accompanying him, and they did not fail or grow weak. Rather, they stood firm in their faith and in their struggle against the enemy. Or the verse may be understood as: how many prophets had numerous devoted followers who were killed fighting alongside them? The survivors remained steadfast and did not grow languid or weak before the enemy. The first interpretation is strengthened by the cry heard at Uḥud that Muḥammad had died, for God set before them an exemplary contrast through “how many a prophet was killed”; the other is said to gain support from the assertion that no prophet was ever killed in open battle. [T197]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T197; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T197","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T197","original_body_sha256":"d8a47fc98c202a9b77d7b0e6d40d074b14667dc8d65913a9bf2278ba12fe0887","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":161,"print_label":"T161","linked_occurrences":[{"record_id":"q3-146-148","segment_index":1,"q":"3:146–148","source":"Cairo print · Volume I, pp. 416–418"}]},{"id":"XIV-N141","historical_note_id":"T198","title":"A disciple’s steadfastness after the death of a master","content":"The abbreviated reference to God becoming the servant’s hearing and sight points to the divine saying in al-Bukhārī 6502. Its fuller context places obligatory duties first and then continual drawing near through additional devotions, followed by divine love. Ibn ʿAjība invokes its language for disciples who persevere after their teacher’s death. His own paragraph also instructs those not fully guided to seek completion. The citation should therefore be read with those disciplines and conditions in view; it does not make the mere death of a teacher sufficient to establish a disciple’s spiritual attainment.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[418],"quran_context":"3:146–148","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-bukhari","work":"bukhari","locator":"Hadith6502","arabic_anchor":"وما يزال عبدي يتقرب إلي بالنوافل حتى أحبه","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0256Bukhari/0256Bukhari.Sahih/0256Bukhari.Sahih.Shamela0001681-ara1","local_file":"audit_work/revision_XIV_research/public_sources/bukhari.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-146-148","segment_index":2,"quran_context":"3:146–148","printed_pages":[418],"anchor_paragraph":"How many disciples and followers ( المريدين والأتباع ) have had their shaykh die or be killed, yet held fast to their path! They neither lost heart nor weakened nor submitted to those who would sever them from their Lord. Instead they patiently persevered in the journey toward God ( السير إلى ربهم ) or in the ascent through stations ( الترقي في المقامات ). Whoever had not yet received complete guidance sought another to complete it. “God loves the patient”; and when He loves them, He becomes their hearing and sight, as the hadith puts it. [XIV-N141]","segment_title":"A disciple’s steadfastness after the death of a master","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [418]; bukhari: Hadith6502","revision_status":"","word_count":93,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-146-148","segment_index":2,"quran_context":"3:146–148","printed_pages":[418],"anchor_paragraph":"How many disciples and followers ( المريدين والأتباع ) have had their shaykh die or be killed, yet held fast to their path! They neither lost heart nor weakened nor submitted to those who would sever them from their Lord. Instead they patiently persevered in the journey toward God ( السير إلى ربهم ) or in the ascent through stations ( الترقي في المقامات ). Whoever had not yet received complete guidance sought another to complete it. “God loves the patient”; and when He loves them, He becomes their hearing and sight, as the hadith puts it. [T198]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T198; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T198","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T198","original_body_sha256":"cd2ed9c4253e33b6394cec03210a6d8918586fdde5a677f3d386e8388f12ad73","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":162,"print_label":"T162","linked_occurrences":[{"record_id":"q3-146-148","segment_index":2,"q":"3:146–148","source":"Cairo print · Volume I, pp. 416–418"}]},{"id":"XIV-N142","historical_note_id":"T199","title":"Competing identifications of those to be obeyed","content":"Three identifications are offered: the hypocrites who urged a return to the former religion, Abū Sufyān’s followers from whom protection might be sought, and a more general pattern of religious conformity produced by prolonged dependence. The recurring ‘according to another explanation’ marks alternatives rather than one composite identification of all the parties. In the second and third, istiʾmān concerns seeking security, and the argument turns on its perceived religious consequences. ‘God is your protecting Master’ answers that dependence within the exposition. The next ‘I say’ then introduces Ibn ʿAjība’s own historical application.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[418],"quran_context":"3:149–150","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-149-150","segment_index":0,"quran_context":"3:149–150","printed_pages":[418],"anchor_paragraph":"According to another explanation: if you seek reassurance and protection from Abū Sufyān and his followers and rely upon them, they will bring you back to their religion. Or the wording is general: obeying unbelievers and submitting to their decisions leads to agreement with them in religion, particularly when the dependence extends over a long period. [XIV-N142]","segment_title":"Competing identifications of those to be obeyed","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [418]","revision_status":"","word_count":92,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-149-150","segment_index":0,"quran_context":"3:149–150","printed_pages":[418],"anchor_paragraph":"According to another explanation: if you seek reassurance and protection from Abū Sufyān and his followers and rely upon them, they will bring you back to their religion. Or the wording is general: obeying unbelievers and submitting to their decisions leads to agreement with them in religion, particularly when the dependence extends over a long period. [T199]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T199; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T199","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T199","original_body_sha256":"260e675f1709b7b3b1ee92108994a07da0e9685c63d0659b32a5998aaf1dcf28","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":163,"print_label":"T163","linked_occurrences":[{"record_id":"q3-149-150","segment_index":0,"q":"3:149–150","source":"Cairo print · Volume I, pp. 418–418"}]},{"id":"XIV-N143","historical_note_id":"T200","title":"Competing identifications of those to be obeyed","content":"The opening ‘I say’ marks Ibn ʿAjība’s extension of the preceding argument to the Muslims who remained in al-Andalus. It is neither a statement by the Qurʾānic speaker nor an account attributed to an early transmitter. The wording makes a broad causal claim about religious dependence and conversion, including descendants; it does not identify particular communities, dates or family histories. A related application occurs in his exposition of Q4:97 at Cairo I:549. The repetition clarifies the author’s concern but does not independently verify the completeness of his historical generalization.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[418],"quran_context":"3:149–150","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-149-150","segment_index":0,"quran_context":"3:149–150","printed_pages":[418],"anchor_paragraph":"I say: This is the cause of the apostasy of the Muslims who remained in al-Andalus, until they and their children became Christians. We seek refuge in God from an evil decree. Translator’s note: This reproduces the author’s historical generalization; it is not independently verified here for every surviving Andalusi Muslim or family. [XIV-N143]","segment_title":"Competing identifications of those to be obeyed","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [418]","revision_status":"","word_count":89,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-149-150","segment_index":0,"quran_context":"3:149–150","printed_pages":[418],"anchor_paragraph":"I say: This is the cause of the apostasy of the Muslims who remained in al-Andalus, until they and their children became Christians. We seek refuge in God from an evil decree. Translator’s note: This reproduces the author’s historical generalization; it is not independently verified here for every surviving Andalusi Muslim or family. [T200]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T200; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T200","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T200","original_body_sha256":"338096a95d8e8aac897a3326c67f86a8d4bffa81ba6af4e3b75293f29209c5fb","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":164,"print_label":"T164","linked_occurrences":[{"record_id":"q3-149-150","segment_index":0,"q":"3:149–150","source":"Cairo print · Volume I, pp. 418–418"}]},{"id":"XIV-N144","historical_note_id":"T201","title":"Steadfastness in tajrīd when the world calls one back","content":"The address is specifically to disciples, especially those already committed to tajrīd. It applies the reversal of Q3:149 to a retreat from their chosen spiritual discipline into preoccupation with worldly means. ‘Natures borrow’ explains the influence of companionship, followed by the saying about an intimate friend’s religion or way. The citation of Q65:2–3 supplies the language of unexpected provision. The author’s special application to the mutajarrid should remain visible: it is not presented in this paragraph as an identical vocational instruction for every reader irrespective of spiritual condition or responsibility.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[418],"quran_context":"3:149–150","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"}],"scope":[{"record_id":"q3-149-150","segment_index":1,"quran_context":"3:149–150","printed_pages":[418],"anchor_paragraph":"Rather, remain firm in detachment ( التجريد ) and in realizing divine unity ( تحقيق التوحيد ), for “God is your protecting Master, and He is the best of helpers.” He will help, honour and enrich you without dependence on external means, as He has promised: “Whoever is mindful of God, He grants him a way out and provides for him from where he did not reckon” [Q 65:2–3]. [XIV-N144]","segment_title":"Steadfastness in tajrīd when the world calls one back","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [418]","revision_status":"","word_count":90,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-149-150","segment_index":1,"quran_context":"3:149–150","printed_pages":[418],"anchor_paragraph":"Rather, remain firm in detachment ( التجريد ) and in realizing divine unity ( تحقيق التوحيد ), for “God is your protecting Master, and He is the best of helpers.” He will help, honour and enrich you without dependence on external means, as He has promised: “Whoever is mindful of God, He grants him a way out and provides for him from where he did not reckon” [Q 65:2–3]. [T201]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T201; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T201","source_id":"EARLY-Q3-150-HTML","source_locator":"HTML #note-T201","original_body_sha256":"b34744b3dafc0d269340cddfaecada7190ed723cd4ab339beb31207df539f7e8","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":165,"print_label":"T165","linked_occurrences":[{"record_id":"q3-149-150","segment_index":1,"q":"3:149–150","source":"Cairo print · Volume I, pp. 418–418"}]},{"id":"CP19","content":"Āl ʿImrān 3:152 · Cairo I:420. Ibn ʿAjība transmits “Poverty is my pride” within a quotation from al-Wartajbī. The Cairo editor treats the attribution critically; ʿAlī al-Qārī’s al-Asrār al-Marfuʿa also records the verdict “no basis / fabricated” for the expanded wording. The phrase is not an established Prophetic ḥadīth, and its spiritual interpretation does not authenticate it. The assessment attributed to Ibn Ḥajar has not been verified in his original work.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:420; Ruslān’s editorial footnote.","revision_status":"","print_number":166,"print_label":"T166","linked_occurrences":[{"record_id":"q3-152","segment_index":3,"q":"3:152","source":"Cairo print · Volume I, pp. 419–421"}]},{"id":"XIV-N145","historical_note_id":"T210","title":"The inheritance of Prophetic gentleness and the meaning of tawakkul","content":"An earlier version appears in al-Thaʿlabī on Q3:159, III:195, through Muḥammad b. Kaʿb from Ibn ʿAbbās. It has three parallel clauses: strength through trust, honour through mindfulness, and richness through greater confidence in what is with God. Cairo retains the latter two. The comparison concerns where confidence rests, rather than promising a measured increase in possessions. The surrounding definitions likewise describe freedom from fear, hope and anxious management directed toward creatures. Locating this earlier wording establishes a source parallel; it does not by itself settle the continuity or strength of that transmitted chain.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[427],"quran_context":"3:159","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-thalabi","work":"thalabi","locator":"Q3:159; between PageV03P194–195","arabic_anchor":"من سره أن يكون أغنى الناس فليكن بما في يد الله أوثق","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0427AbuIshaqThaclabi/0427AbuIshaqThaclabi.KashfWaBayan/0427AbuIshaqThaclabi.KashfWaBayan.Shamela0023578-ara1.mARkdown","local_file":"audit_work/revision_XIV_research/public_sources/thalabi.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-159","segment_index":2,"quran_context":"3:159","printed_pages":[427],"anchor_paragraph":"The Prophet is quoted as saying: “Whoever wishes to be the noblest of people should fear God; whoever wishes to be the richest should be more confident in what lies with God than in what lies in his own hand.” [XIV-N145]","segment_title":"The inheritance of Prophetic gentleness and the meaning of tawakkul","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [427]; thalabi: Q3:159; between PageV03P194–195","revision_status":"","word_count":93,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-159","segment_index":2,"quran_context":"3:159","printed_pages":[427],"anchor_paragraph":"The Prophet is quoted as saying: “Whoever wishes to be the noblest of people should fear God; whoever wishes to be the richest should be more confident in what lies with God than in what lies in his own hand.” [T210]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T210; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T210","source_id":"EARLY-Q3-200-PDF","source_locator":"PDF page455; printed page455","original_body_sha256":"f3b37e79eb5601c95a26f8fc365f7ac9296a4d64bbeb761c03f82b3dc6c488a1","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":167,"print_label":"T167","linked_occurrences":[{"record_id":"q3-159","segment_index":2,"q":"3:159","source":"Cairo print · Volume I, pp. 426–428"}]},{"id":"R07-16","content":"Cairo I:451 · The fivefold “Our Lord.” Ruslān counts the repeated invocation and cites al-Munāwī’s inability to locate the particular report elsewhere. “I have not located it” is not the same as a demonstration that it is fabricated. The statement is al-Munāwī’s reported finding, not a supplied chain or an authentication verdict for the prayer and Sufi practice.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:451; Ruslān’s editorial footnote.","revision_status":"","print_number":168,"print_label":"T168","linked_occurrences":[{"record_id":"q3-191-194","segment_index":1,"q":"3:191–194","source":"Cairo print · Volume I, pp. 450–453"}]},{"id":"XIV-N146","historical_note_id":"T239","title":"Al-Ghazālī on the realized person's wird","content":"The section combines several voices rather than one uninterrupted quotation from al-Ghazālī. The Iḥyāʾ’s Book of Litanies describes sustained presence after the obligatory prayers and expressly warns beginners against claiming the rank prematurely. Its Book of Poverty and Renunciation separately preserves the Junayd sayings about limiting distractions, including reading and writing. Ibn ʿAjība then adds his own governing qualification: a disciple with a teacher of formation should follow the particular practice assigned. This final rule limits the preceding generalizations about inward concentration. The text does not equate reduced visible activity with spiritual attainment, nor remove the obligatory prayers.","evidence":[{"work":"Ibn Ajiba, al-Bahr al-madid","edition":"Cairo Ruslan1419/1999, volumeI","printed_pages":[451,452],"quran_context":"3:191–194","local_file":"audit_work/revision_XIII/Cairo_Collated_Arabic_XIII.txt","read_scope":"Full current English segment, anchor paragraph and corresponding Cairo context read"},{"source_id":"XIV-OT-ihya","work":"ihya","locator":"Book of Litanies, I:349–350; Book of Poverty and Renunciation, IV:238–239","arabic_anchor":"بل كان ورده بعد المكتوبات واحد ... أحب للصوفي أن لا يكتب ولا يقرأ","url":"https://raw.githubusercontent.com/OpenITI/RELEASE/v2025.1.9/data/0505Ghazali/0505Ghazali.IhyaCulumDin/0505Ghazali.IhyaCulumDin.Shamela0009472-ara1.completed","local_file":"audit_work/revision_XIV_research/public_sources/ihya.txt","assessment":"Primary wording actually read; a parallel does not by itself authenticate a report or establish direct borrowing."}],"scope":[{"record_id":"q3-191-194","segment_index":3,"quran_context":"3:191–194","printed_pages":[451,452],"anchor_paragraph":"Ibn ʿAjība then cites a teaching of his teacher's teacher, Sīdī ʿAbd al-Raḥmān, on the inwardly realized performing acts that gather rather than scatter their concentration. Al-Junayd reportedly preferred that the Sufi should neither read nor write, because that better gathers his purpose, and for the disciple not to be distracted by earning or collecting hadith, lest his state change. Ibn ʿAjība adds the operative qualification: whoever has been granted a teacher of spiritual formation ( شيخ التربية ) should take as his practice whatever that teacher specifically assigns; this is his very dhikr and carries him onwards, whatever it may be. [XIV-N146]","segment_title":"Al-Ghazālī on the realized person's wird","anchor_basis":"Exact active annotation call in current HTML"}],"limitations":"","source":"Ibn Ajiba, al-Bahr al-madid: [451, 452]; ihya: Book of Litanies, I:349–350; Book of Poverty and Renunciation, IV:238–239","revision_status":"","word_count":98,"annotation_review_XIV":"Researcher read the complete anchored segment and cited contexts. Primary-editor review is recorded separately.","scope_XIV":[{"record_id":"q3-191-194","segment_index":3,"quran_context":"3:191–194","printed_pages":[451,452],"anchor_paragraph":"Ibn ʿAjība then cites a teaching of his teacher's teacher, Sīdī ʿAbd al-Raḥmān, on the inwardly realized performing acts that gather rather than scatter their concentration. Al-Junayd reportedly preferred that the Sufi should neither read nor write, because that better gathers his purpose, and for the disciple not to be distracted by earning or collecting hadith, lest his state change. Ibn ʿAjība adds the operative qualification: whoever has been granted a teacher of spiritual formation ( شيخ التربية ) should take as his practice whatever that teacher specifically assigns; this is his very dhikr and carries him onwards, whatever it may be. [T239]"}],"revision_status_XV":"New translator’s annotation in Revision XIV. Replaces the unavailable annotation route T239; historical note wording has not been recovered.","original_annotation_recovery_XVI":{"historical_note_id":"T239","source_id":"EARLY-Q3-200-PDF","source_locator":"PDF page456; printed page456","original_body_sha256":"b9e8307e72abe77b9b644d61edb6124333bb68ea4eed1eb102d427a0bc8e62bc","disposition":"Recovered original separately available; expanded current body unchanged."},"print_number":169,"print_label":"T169","linked_occurrences":[{"record_id":"q3-191-194","segment_index":3,"q":"3:191–194","source":"Cairo print · Volume I, pp. 450–453"}]},{"id":"R07-17","content":"Cairo I:453 · Labīd’s verse and the Prophet’s commendation. Abū Hurayra transmits the Prophet’s commendation of a line by Labīd in versions recorded by al-Bukhārī and Muslim. Muslim, Kitāb al-Shiʿr, no. 2256, preserves several formulations; the relevant commendation covers only the opening line. The poet’s words are distinct from the Prophetic speech praising them, and later Sufi glosses are not part of the hadith text.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:453; Ruslān’s editorial footnote.","revision_status":"","print_number":170,"print_label":"T170","linked_occurrences":[{"record_id":"q3-191-194","segment_index":4,"q":"3:191–194","source":"Cairo print · Volume I, pp. 450–453"}]},{"id":"N001","content":"Intro · The differing verse totals are historical systems of enumeration reported by Ibn ʿAjība, not discrepancies in the Qurʾānic wording. In the standard numbering, the sūrah has 176 verses.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:459.","revision_status":"","print_number":171,"print_label":"T171","linked_occurrences":[{"record_id":"intro4","segment_index":0,"q":"intro4","source":"Cairo Arabic edition I:459"}]},{"id":"N002","content":"4:1 · The genitive reading وَالْأَرْحَامِ is a recognized canonical reading attributed here to Ḥamza. The dispute concerns whether Arabic syntax permits coordination to an attached genitive pronoun without repeating the preposition. The accusative reading gives a coordinated object of اتقوا , not a different ethical rule.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:459–461.","revision_status":"","print_number":172,"print_label":"T172","linked_occurrences":[{"record_id":"q4-1","segment_index":0,"q":"4:1","source":"Cairo Arabic edition I:459–461"}]},{"id":"N003","content":"4:2 · The account of the Ghaṭafān uncle is transmitted as an occasion of revelation in the commentary. Its attribution as an authenticated Prophetic ḥadīth has not been established; the reliability of its chain remains unverified.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:461–462.","revision_status":"","print_number":173,"print_label":"T173","linked_occurrences":[{"record_id":"q4-2","segment_index":1,"q":"4:2","source":"Cairo Arabic edition I:461–462"}]},{"id":"N004","content":"4:3 · The explanation of ما as referring to women because of a supposed deficiency of intellect is Ibn ʿAjība’s historical claim, not a necessary rule of Arabic grammar. Other grammatical accounts treat mā generically, as referring to allowable classes or descriptions of wives.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:462–463.","revision_status":"","print_number":174,"print_label":"T174","linked_occurrences":[{"record_id":"q4-3","segment_index":0,"q":"4:3","source":"Cairo Arabic edition I:462–463"}]},{"id":"N005","content":"4:3 · The commentator’s juristic framework, including premodern slavery law, belongs to historical exegesis; it does not supply a contemporary legal ruling.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:462–463.","revision_status":"","print_number":175,"print_label":"T175","linked_occurrences":[{"record_id":"q4-3","segment_index":1,"q":"4:3","source":"Cairo Arabic edition I:462–463"}]},{"id":"R07-18","content":"Cairo I:464 · The readings of qiyām. The Cairo editor identifies alternative readings of the expression describing wealth as a means of support. These readings affect its morphology. The exact vowel details have not been independently verified against a specialized classical qirāʾāt source.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:464; Ruslān’s editorial footnote.","revision_status":"","print_number":176,"print_label":"T176","linked_occurrences":[{"record_id":"q4-5","segment_index":0,"q":"4:5","source":"Cairo Arabic edition I:464–466"}]},{"id":"CP21","content":"al-Nisāʾ 4:5 · Cairo I:465. Ibn ʿAjība quotes a disparaging report about women in connection with al-sufahāʾ and property guardianship. Its attribution has not been independently established. The corrective hadith cited by Ruslān is found in Ṣaḥīḥ Muslim 1469 through Abū Hurayra. Ruslān’s admonition is the Cairo editor’s annotation, not Ibn ʿAjība’s own qualification. The sound Muslim report does not establish the attribution of the separate disparaging narration.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:465; Ruslān’s editorial footnote.","revision_status":"","print_number":177,"print_label":"T177","linked_occurrences":[{"record_id":"q4-5","segment_index":1,"q":"4:5","source":"Cairo Arabic edition I:464–466"}]},{"id":"N006","content":"4:5 · The words attributed to Abū Umāma and the interpretation of النساء as السفهاء occur in the commentary. The specific Prophetic attribution is weak and cannot be treated as proof; see H004. The report from Abū Mūsā also has a contested distinction between marfūʿ and mawqūf transmission; see H005.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:464–466.","revision_status":"","print_number":178,"print_label":"T178","linked_occurrences":[{"record_id":"q4-5","segment_index":1,"q":"4:5","source":"Cairo Arabic edition I:464–466"}]},{"id":"N008","content":"4:7 · The detailed Umm Kaḥḥa/Aws ibn Thābit narrative is an asbāb al-nuzūl report transmitted in tafsīr. Its early transmission and chain remain unverified; the detailed narrative is not thereby an authenticated Prophetic report.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:467–468.","revision_status":"","print_number":179,"print_label":"T179","linked_occurrences":[{"record_id":"q4-7","segment_index":1,"q":"4:7","source":"Cairo Arabic edition I:467–468"}]},{"id":"N009","content":"4:8 · The status of the instruction to give a token share to non-heirs was contested in classical exegesis. Ibn ʿAjība reports several legal possibilities.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:468–469.","revision_status":"","print_number":180,"print_label":"T180","linked_occurrences":[{"record_id":"q4-8","segment_index":1,"q":"4:8","source":"Cairo Arabic edition I:468–469"}]},{"id":"N010","content":"4:10 · The report attributed to Abū Barza is found in Abū Yaʿlā 7440 and Ibn Ḥibbān 5566, but its chain contains Ziyād ibn al-Mundhir and has been graded very weak by critical hadith scholars. The Qurʾānic warning itself is independent of the reliability of this supplementary report; see H009.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:470–471.","revision_status":"","print_number":181,"print_label":"T181","linked_occurrences":[{"record_id":"q4-10","segment_index":1,"q":"4:10","source":"Cairo Arabic edition I:470–471"}]},{"id":"N100","content":"4:11 · Ibn Juzayy’s statements about male precedence and terminology are historically situated exegetical/legal arguments. They belong to the cited author’s legal framework, not an independent present-day judgment.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:471–475.","revision_status":"","print_number":182,"print_label":"T182","linked_occurrences":[{"record_id":"q4-11","segment_index":1,"q":"4:11","source":"Cairo Arabic edition I:471–475"}]},{"id":"N110","content":"4:15–16 · The author reports alternative claims about the chronological abrogation of Q 4:15–16, same-sex acts, and penal measures. The legal and historical status of those claims differs among jurists; the passage does not supply a present-day operational legal ruling. The associated hadith attributed to ʿUbāda b. al-Ṣāmit (“ خذوا عني ... قد جعل الله لهن سبيلاً ”) occurs in Ṣaḥīḥ Muslim 1690a; its relation to the disputed claims of naskh is a separate question.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:478–479.","revision_status":"","print_number":183,"print_label":"T183","linked_occurrences":[{"record_id":"q4-15-16","segment_index":0,"q":"4:15–16","source":"Cairo Arabic edition I:478–479"}]},{"id":"N115","content":"4:19 · This paragraph reports Ibn ʿAjība’s explanation of a historical Mālikī view on khulʿ and nushūz. It does not justify coercive control or abuse; modern legal rules and competing classical interpretations must be treated separately. The Arabic construction of the exception and the legal implications of فاحشة مبينة are contested.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:481–483.","revision_status":"","print_number":184,"print_label":"T184","linked_occurrences":[{"record_id":"q4-19","segment_index":2,"q":"4:19","source":"Cairo Arabic edition I:481–483"}]},{"id":"N116","content":"4:19 · The story of Mālik’s father and a dark-skinned wife is presented as a story, not an authenticated report or a statement about human worth. Its historical authenticity has not been verified.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:481–483.","revision_status":"","print_number":185,"print_label":"T185","linked_occurrences":[{"record_id":"q4-19","segment_index":5,"q":"4:19","source":"Cairo Arabic edition I:481–483"}]},{"id":"XV-N001","title":"Spiritual combat and witnessing: a quotation variant","content":"Cairo I:483 prints “suns of spiritual combat” (شموس المجاهدات). The corresponding passage in al-Baqlī’s ʿArāʾis al-bayān I:239 reads “suns of witnessing” (شموس المشاهدات), which also explains the Turkish rendering. This earlier-source parallel establishes a quotation variant; it does not by itself establish which wording Ibn ʿAjība wrote.","source":"Cairo I:483; primary-source comparison recorded below.","revision_status":"","scope":[{"record_id":"q4-19","segment_index":6,"quran_context":"4:19","printed_pages":[483],"anchor_text":"suns of spiritual combat and moons of unveiling","segment_title":"When the self becomes obedient, reconcile with it","anchor_paragraph":"When the self has been purified of its remnants, its virtues perfected, and it submits entirely to its Master, it becomes necessary to treat it with kindness, make peace with it and live with it in the recognized good manner. Its struggle and discipline ( مجاهدة ) are required only while it remains unbelieving; when it has submitted in Islam and become obedient, love and kindness towards it become incumbent. If, while still crooked, you dislike it and struggle to train it until it grows upright, its final state will bring much good; it will return bearing divinely bestowed knowledge ( العلوم اللدنية ), and you will behold lordly mysteries within it. Al-Wartajbī says: Every command of God which runs contrary to the self is an examination and trial. The self dislikes servanthood ( العبودية ); but if you impose upon it God’s rights through spiritual training ( الرياضة ) and struggle ( المجاهدة ), until it grows upright in His service, the first thing to dawn upon the heart is the lights of the gardens of nearness and witnessing. God says, “And forbade the self its caprice: the Garden shall be its dwelling” ( وَنَهَى النَّفْسَ عَنِ الْهَوَى فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى ) [Q 79:40–41]. In the inward depths of the darkness of struggling, the knowers behold suns of spiritual combat and moons of unveiling [XV-N001] ( المكاشفات ). Here ends the substance of his remarks.","anchor_basis":"Exact active annotation call in current HTML"}],"evidence":[{"file":"audit_work/revision_XIV_research/middle/sources/arais_I_2008.pdf","printed_page":239,"pdf_page":239,"public_url":"https://archive.org/details/rouhany_816","cairo_page":483,"turkish_II_page":361}],"provenance":{"revision":"XV","proposal_id":"XV-NISA-E002","source_proposal_file":"crux_late/Turkish_Nisa_Proposed_Operations_XV.json","adopted_edit_id":"XV-043","independent_Bahr_manuscript_evidence":false},"limitations":"Source comparison and copytext interpretation; no independent Baḥr manuscript reading is asserted.","word_count":47,"print_number":186,"print_label":"T186","linked_occurrences":[{"record_id":"q4-19","segment_index":6,"q":"4:19","source":"Cairo Arabic edition I:481–483"}]},{"id":"N121","content":"4:22 · Ibn ʿAjība’s explanation of mā referring to women because of alleged cognitive deficiency is a historically situated exegetical claim.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:484–485.","revision_status":"","print_number":187,"print_label":"T187","linked_occurrences":[{"record_id":"q4-22","segment_index":0,"q":"4:22","source":"Cairo Arabic edition I:484–485"}]},{"id":"N122","content":"4:22 · The exception concerning illicit intercourse and permanent marriage impediments is subject to disagreements between the legal schools. The Risāla cited is likely Ibn Abī Zayd al-Qayrawānī’s Mālikī text; the quotation has not been verified against a specified recension.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:484–485.","revision_status":"","print_number":188,"print_label":"T188","linked_occurrences":[{"record_id":"q4-22","segment_index":1,"q":"4:22","source":"Cairo Arabic edition I:484–485"}]},{"id":"N124","content":"4:23 · The passage concerns the commentator’s account of marriage impediments in classical jurisprudence. The unusual report attributed to ʿAlī on stepdaughters needs chain scrutiny and should not be treated as a majority view.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:485–486.","revision_status":"","print_number":189,"print_label":"T189","linked_occurrences":[{"record_id":"q4-23","segment_index":3,"q":"4:23","source":"Cairo Arabic edition I:485–486"}]},{"id":"N125","content":"4:23 · The treatment of enslaved persons in classical law is historical exegesis and does not describe a permissible contemporary practice. The reported Ẓāhirī exception has not been verified against original juristic sources.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:485–486.","revision_status":"","print_number":190,"print_label":"T190","linked_occurrences":[{"record_id":"q4-23","segment_index":4,"q":"4:23","source":"Cairo Arabic edition I:485–486"}]},{"id":"N127","content":"4:24 · The running text gives no precise bibliographical identification of ‘the Mukhtaṣar’. The material describes premodern captivity and slavery law; it is not a contemporary authorization for coercive sexual relationships. The Awṭās context is in Muslim 1456a (H021).","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:485–489.","revision_status":"","print_number":191,"print_label":"T191","linked_occurrences":[{"record_id":"q4-24","segment_index":0,"q":"4:24","source":"Cairo Arabic edition I:485–489"}]},{"id":"N128","content":"4:24, ishāra · ‘He who has not been born twice is not one of us’ is assigned to ‘one of the saints’, not to the Prophet. No reliable individual attribution or transmitted source has yet been established. The author says the saint ‘counted the first and third’ of his own three births, so those two counted births belong within the author’s threefold account.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:485–489.","revision_status":"","print_number":192,"print_label":"T192","linked_occurrences":[{"record_id":"q4-24","segment_index":1,"q":"4:24","source":"Cairo Arabic edition I:485–489"}]},{"id":"N129","content":"4:24, ishāra · The aphorism concerning love of the world and love of its Creator is ascribed to al-Shāfiʿī in the Arabic. The chain and source for that specific attribution remain unverified. The admonition is an ascetic maxim, not a juristic prohibition in itself.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:485–489.","revision_status":"","print_number":193,"print_label":"T193","linked_occurrences":[{"record_id":"q4-24","segment_index":1,"q":"4:24","source":"Cairo Arabic edition I:485–489"}]},{"id":"N142","content":"4:24, syntax · Cairo I:488 prints the active reading wa-aḥalla (“and He has made lawful”) in the printed verse heading and in the first grammatical analysis, coordinated with the tacit kataba (“He prescribed”). The author explicitly gives passive wa-uḥilla as another reading, coordinated with ḥurrimat (“were forbidden”).","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:485–489.","revision_status":"","print_number":194,"print_label":"T194","linked_occurrences":[{"record_id":"q4-24","segment_index":3,"q":"4:24","source":"Cairo Arabic edition I:485–489"}]},{"id":"N130","content":"4:24 · The ḥadīth of Sabra al-Juhanī is ṣaḥīḥ in Muslim 1406d; its full wording appears at H022. Ibn ʿAjība’s claims about three days at the conquest and Ibn ʿAbbās's later withdrawal reflect a specific Sunni reconstruction of early practice. Other schools differ in legal conclusions and in their reading of early transmission; no claim of unanimous historic interpretation is made here. Cairo I:488 prints the active reading wa-aḥalla in the verse heading; the commentary also explicitly states the passive reading as an alternative. See N142.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:485–489.","revision_status":"","print_number":195,"print_label":"T195","linked_occurrences":[{"record_id":"q4-24","segment_index":4,"q":"4:24","source":"Cairo Arabic edition I:485–489"}]},{"id":"N131","content":"4:25 · Ibn ʿAjība explicitly quotes Ibn Juzayy on Mālik, Ibn al-Qāsim, and the jurists of Iraq. The reference to dalīl al-khiṭāb concerns a technical question in uṣūl about argument from the contrary implication of a restriction. The quotation records positions of these named jurists; it does not establish a single school-wide opinion.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:489–493.","revision_status":"","print_number":196,"print_label":"T196","linked_occurrences":[{"record_id":"q4-25-28","segment_index":1,"q":"4:25–28","source":"Cairo Arabic edition I:489–493"}]},{"id":"N132","content":"4:25, ishāra · The long saying on the fruits of love is ascribed to Abū al-Ḥasan al-Shādhilī. Its specific collection, transmission and phrasing have not been independently fixed. ‘Virgins’, ‘previously married free women’, and ‘enslaved women’ are explicitly analogical rankings of modes of knowledge in Ibn ʿAjība’s spiritual allusion.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:489–493.","revision_status":"","print_number":197,"print_label":"T197","linked_occurrences":[{"record_id":"q4-25-28","segment_index":2,"q":"4:25–28","source":"Cairo Arabic edition I:489–493"}]},{"id":"N133","content":"4:25 · The division of a prescribed punishment and the statement that stoning is not halved reproduce classical exegetical/legal discourse. These historical positions do not authorize punitive action by private individuals or state current law. Ibn ʿAjība quotes Q 24:2 but does not state a fresh separate hadith at this juncture.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:489–493.","revision_status":"","print_number":198,"print_label":"T198","linked_occurrences":[{"record_id":"q4-25-28","segment_index":5,"q":"4:25–28","source":"Cairo Arabic edition I:489–493"}]},{"id":"N134","content":"4:25, ishāra · The dream story about Junayd is an edifying report, not independently authenticated historical evidence. The double-chastisement verse is Q 33:30; Ibn ʿAjība supplies a moral comparison rather than claiming that its legal ruling applies to ordinary spiritual teachers.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:489–493.","revision_status":"","print_number":199,"print_label":"T199","linked_occurrences":[{"record_id":"q4-25-28","segment_index":6,"q":"4:25–28","source":"Cairo Arabic edition I:489–493"}]},{"id":"N135","content":"4:25 · The statement about the slavery status of children born in the historical arrangement belongs to Ibn ʿAjība’s world of classical juristic institutions. It belongs to that historical juristic framework and does not describe a legitimate current practice. His distinction between fear of ʿanat and patience is material to both legal and spiritual readings.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:489–493.","revision_status":"","print_number":200,"print_label":"T200","linked_occurrences":[{"record_id":"q4-25-28","segment_index":9,"q":"4:25–28","source":"Cairo Arabic edition I:489–493"}]},{"id":"N136","content":"4:27 · The competing identifications of ‘those following desires’ as fornicators, Jews/Christians or Magians are inherited exegetical views, not an empirical claim about adherents of these religions. Ibn ʿAjība’s paraphrase ‘marry and beget’ differs from the sourced Abū Dāwūd 2050 wording quoted in H025. Figures for the concubines attributed to ʿAlī have not been verified from early chronicles.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:489–493.","revision_status":"","print_number":201,"print_label":"T201","linked_occurrences":[{"record_id":"q4-25-28","segment_index":9,"q":"4:25–28","source":"Cairo Arabic edition I:489–493"}]},{"id":"N137","content":"4:28 · The vivid personal statement is attributed to the Companion ʿUbāda b. al-Ṣāmit, not to the Prophet; an independently verified early source and isnād have not yet been located. It should be classified as an *athar*, not as ṣaḥīḥ Prophetic hadith.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:489–493.","revision_status":"","print_number":202,"print_label":"T202","linked_occurrences":[{"record_id":"q4-25-28","segment_index":9,"q":"4:25–28","source":"Cairo Arabic edition I:489–493"}]},{"id":"N138","content":"4:28 · The selection of eight verses is attributed to Ibn ʿAbbās. The attribution and exact formulation of this eight-verse selection remain unverified. This is an *athar*, not a report of Prophetic speech.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:489–493.","revision_status":"","print_number":203,"print_label":"T203","linked_occurrences":[{"record_id":"q4-25-28","segment_index":9,"q":"4:25–28","source":"Cairo Arabic edition I:489–493"}]},{"id":"N139","content":"4:29 · The distinction between verbal and bodily separation after a sale is a historically important Mālikī–Shāfiʿī juristic dispute. The ḥadīth in al-Bukhārī 2107 explicitly adds Nāfiʿ’s remark that Ibn ʿUmar would separate quickly after buying goods he wanted, a detail important to interpreting ‘separation’. The grammarians’ readings of the kāna exception are also separate from the underlying contract-law conclusion.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:493–495.","revision_status":"","print_number":204,"print_label":"T204","linked_occurrences":[{"record_id":"q4-29-30","segment_index":1,"q":"4:29–30","source":"Cairo Arabic edition I:493–495"}]},{"id":"N140","content":"4:30 · Ibn ʿAjība’s generic phrasing combines language of several sound warnings. Muslim 109a and al-Bukhārī 5778 contain the longer ‘forever’ form for three specified means; Muslim 110a/d contain shorter generic wording. His ‘threat of emphasis’ or ‘one who holds it lawful’ is a theological gloss, not a replacement for the hadith text. Warning passages must not be read as an instruction to stigmatize individuals who die by suicide; questions of knowledge, compulsion, capacity and individual judgment are distinct.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:493–495.","revision_status":"","print_number":205,"print_label":"T205","linked_occurrences":[{"record_id":"q4-29-30","segment_index":4,"q":"4:29–30","source":"Cairo Arabic edition I:493–495"}]},{"id":"N141","content":"4:31 · The caller-from-the-Throne report is transmitted with a weak chain, as classified by al-ʿIrāqī (Takhrīj al-Iḥyāʾ 3/225); see H030. Its statement about interpersonal obligations may not be cited as an authenticated doctrine that injured people’s claims evaporate without redress. Ibn ʿAjība marks it as the argument of one interpretive position, while also reporting several rival definitions of ‘major sin’.","source":"Ibn ʿAjība, al-Baḥr al-madīd; Cairo Arabic edition I:495–496.","revision_status":"","print_number":206,"print_label":"T206","linked_occurrences":[{"record_id":"q4-31","segment_index":1,"q":"4:31","source":"Cairo Arabic edition I:495–496"}]},{"id":"XV-N002","title":"The three readings of tasawwā and Cairo’s explanation","content":"Cairo I:505 confuses the explanations of the readings here. The doubled tassawwā comes from tatasawwā by assimilation of a tāʾ into the sīn; the reading tasawwā instead omits a tāʾ. The passive tusawwā is a separate form, not produced by that omission. Compare al-Bayḍāwī, Anwār al-tanzīl, at Q4:42, and al-Rāzī, Mafātīḥ al-ghayb, at Q4:42, second question. The explanations printed in Cairo therefore remain a textual difficulty.","source":"Cairo I:505; primary-source comparison recorded below.","revision_status":"","scope":[{"record_id":"q4_cont_041","segment_index":0,"quran_context":"4:41–42","printed_pages":[505],"anchor_text":"In the doubled reading tassawwā , the original is tatasawwā , with “the first assimilated into the second”; in the passive reading tusawwā , “the second has been omitted.”","segment_title":"Grammar and readings (qultu)","anchor_paragraph":"When what follows the interrogative kayfa (“how?”) forms a complete proposition, it is parsed as a circumstantial accusative ( ḥāl ), as in “How did Zayd come?” When the proposition is incomplete, it is the predicate ( khabar ), as in “How is Zayd?” It is a predicate here: “How will the matter be when ...?” Its form is indeclinable because it contains the sense of interrogation. The governing element of idhā (“when”) is the meaning implied by the subject or predicate: “How will the matter stand or occur when We bring [the witnesses]?” In the doubled reading tassawwā , the original is tatasawwā , with “the first assimilated into the second”; in the passive reading tusawwā , “the second has been omitted.” [XV-N002]","anchor_basis":"Exact active annotation call in current HTML"}],"evidence":[{"title":"Cairo Baḥr I505","evidence":"evidence/Cairo_I_505.png","status":"Printed page visually inspected"},{"title":"al-Bayḍāwī, Anwār al-tanzīl, Q4:42","url":"https://ablibrary.net/book_content/b/5961/75?lang=ar","locator":"VolII75 in this online edition, paragraph beginning وقرأ نافع وابن عامر","status":"Primary work public transcription read, not a new Baḥr witness; web diacritics are normalized incorrectly but prose explicitly distinguishes assimilation into sīn and omitted second tāʾ."},{"title":"al-Rāzī, Mafātīḥ al-ghayb, Q4:42","url":"https://www.nquran.com/ar/view/2270","locator":"المسألة الثانية","status":"Primary work excerpt read; explicitly gives passive ḍamma, active doubled sīn, and active ungeminated sīn."}],"provenance":{"revision":"XV","proposal_id":"XV-NISA-E004","source_proposal_file":"crux_late/Turkish_Nisa_Proposed_Operations_XV.json","adopted_edit_id":"XV-045","independent_Bahr_manuscript_evidence":false},"limitations":"Source comparison and copytext interpretation; no independent Baḥr manuscript reading is asserted.","word_count":67,"print_number":207,"print_label":"T207","linked_occurrences":[{"record_id":"q4_cont_041","segment_index":0,"q":"4:41–42","source":"Cairo I:505–506"}]},{"id":"R07-19","content":"Cairo I:550 · The saying about emigration. The Cairo editor identifies a mursal route for the saying encouraging emigration. Its occurrence in Ibn ʿAjība’s explanation does not establish a continuous Prophetic chain. The mursal classification is reported by Ruslān; the precise al-Ṭabarānī and al-Munāwī passages have not been independently compared for a final assessment of the report.","source":"Ibn ʿAjība, al-Baḥr al-madīd, Cairo I:550; Ruslān’s editorial footnote.","revision_status":"","print_number":208,"print_label":"T208","linked_occurrences":[{"record_id":"q4_cont_097","segment_index":0,"q":"4:97–99","source":"Cairo I:549"}]},{"id":"XV-N003","title":"The wishing subject in the angels’ testimony","content":"Cairo I:593 reads ‘the angels wish that people should know’ (أن الملائكة يودون أن يعلم الناس). Al-Bayḍāwī’s Anwār al-tanzīl, on Q 4:166 (al-Maṭbaʿa al-ʿUthmāniyya, 1305 AH, p. 137; also II:110 in the electronic edition consulted), instead reads ‘they wish to know’ (أنهم يودون أن يعلموا); in its surrounding argument, ‘they’ refers to the human opponents who seek knowledge without reflection. The Turkish translator (II:591, n. 973, citing I:249 in his edition) expressly reports correcting what he regards as surplus in the Baḥr copies available to him according to al-Bayḍāwī. His Turkish body makes the People of the Book the wishing subject, while retaining people as the knowing subject, so it is not an exact equivalent of al-Bayḍāwī’s two pronouns. No independent Baḥr manuscript has been inspected to establish at what stage this discrepancy entered the text.","source":"Cairo I:593; primary-source comparison recorded below.","revision_status":"","scope":[{"record_id":"q4_cont_166","segment_index":0,"quran_context":"4:166","printed_pages":[593],"anchor_text":"in a way that dispenses with reflection and deliberation.","segment_title":"","anchor_paragraph":"The angels’ testimony indicates that they wish people to know the truth of the claim to prophethood in a way that dispenses with reflection and deliberation. [XV-N003] This kind of knowledge is characteristic of angels. Al-Bayḍāwī says that human beings have no way to know such matters except through thought and reflection: had these opponents reasoned correctly, they would have recognized your prophethood and testified to it, as the angels recognized it and testified. Ibn ʿAjība adds that God can also create knowledge in a human heart directly, without preceding argument, through free guidance. God's testimony is enough without anyone else's assent.","anchor_basis":"Exact active annotation call in current HTML"}],"evidence":[{"title":"al-Bayḍāwī, Anwār al-tanzīl wa-asrār al-taʾwīl","locator":"Q4:166; electronic pagination II:110","url":"https://www.islamweb.com/ar/library/content/205/543/","web_ref":"turn522view0","lines":[778,788],"inspection_status":"Primary electronic text and actual early printed page inspected; early-print colophon date and printer also inspected.","printed_edition":{"publisher":"al-Maṭbaʿa al-ʿUthmāniyya","year_ah":1305,"printed_page":137,"pdf_page":160,"colophon_pdf_page":839,"edition_identification":"Wikisource catalogue identifies the marginal edition as the Ottoman press,1305; actual colophon displays1305 and printer signatures name al-Matbaa al-Uthmaniyya. No city inferred.","catalogue_url":"https://ar.wikisource.org/wiki/ملف:تفسير_البيضاوي.pdf","catalogue_web_ref":"turn524view1","pdf_url":"https://upload.wikimedia.org/wikisource/ar/1/14/تفسير_البيضاوي.pdf","local_pdf":"reference_scans/baydawi_uthmaniyya_1305.pdf","sha256":"a6210fb80956f494dbf2fd20dcbedaaf48f785bdc857b5653f98dfd879d0f953"}}],"provenance":{"revision":"XV","proposal_id":"XV-Q4-166-CAIRO-QUALIFIER","source_proposal_file":"q4_166_baydawi/Q4_166_Edit_and_Note_Proposal_XV.json","adopted_edit_id":"XV-050","independent_Bahr_manuscript_evidence":false},"limitations":"Source comparison and copytext interpretation; no independent Baḥr manuscript reading is asserted.","word_count":144,"print_number":209,"print_label":"T209","linked_occurrences":[{"record_id":"q4_cont_166","segment_index":0,"q":"4:166","source":"Cairo I:593"}]}];
